import type { QA } from "./types";

/** React.js interview — 408 প্রশ্ন (৩১৯ মূল + ৮৯ পুরনো/ক্লাস) · বাংলা + ইংরেজি */
export const reactQAs: QA[] = [
  { q: "১. React কী?", qEn: "1. What is React?", a: "React হলো ফেসবুক তৈরি করা একটি JavaScript লাইব্রেরি যা ইউজার ইন্টারফেস (UI) বানানোর জন্য ব্যবহৃত হয়। এটি কম্পোনেন্ট-ভিত্তিক এবং ডিক্লারেটিভ। অর্থাৎ, আপনি বলেন \"আমি এই UI দেখতে চাই\" আর React তা DOM-এ এনে দেয়।\n\nউদাহরণ:\nছোট component জোড়া দিয়ে UI বানানো হয়।\n\n```javascript\nfunction App() {\n  return <h1>Hello React</h1>;\n}\n```", aEn: "React (aka React.js or ReactJS) is an open-source front-end JavaScript library for building user interfaces based on components. It's used for handling the view layer in web and mobile applications, and allows developers to create reusable UI components and manage the state of those components efficiently.\n\n React was created by Jordan Walke, a software engineer at Facebook (now Meta). It was first deployed on Facebook's News Feed in 2011 and on Instagram in 2012. The library was open-sourced in May 2013 and has since become one of the most popular JavaScript libraries for building modern user interfaces." },
  { q: "২. React-এর ইতিহাস কী?", qEn: "2. What is the history behind React evolution?", a: "২০১১: ফেসবুকের নিউজফিডে FaxJS নামে প্রোটোটাইপ।\n\n২০১৩: প্রথম ওপেন সোর্স রিলিজ (JSConf US)।\n\n২০১৫: React Native আসে।\n\n২০১৭: React Fiber রি-রাইট (ভার্চুয়াল DOM-এর নতুন অ্যালগরিদম)।\n\n২০১৯: Hooks আসে (useState, useEffect)।\n\nউদাহরণ:\n২০১৩: ওপেন সোর্স → ২০১৯: Hooks (useState, useEffect)।", aEn: "The history of ReactJS started in 2010 with the creation of XHP. XHP is a PHP extension which improved the syntax of the language such that XML document fragments become valid PHP expressions and the primary purpose was used to create custom and reusable HTML elements.\n\n The main principle of this extension was to make front-end code easier to understand and to help avoid cross-site scripting attacks. The project was successful to prevent the malicious content submitted by the scrubbing user.\n\n But there was a different problem with XHP in which dynamic web applications require many roundtrips to the server, and XHP did not solve this problem. Also, the whole UI was re-rendered for small change in the application. Later, the initial prototype of React is created with the name FaxJ by Jordan inspired from XHP. Finally after sometime React has been introduced as a new library into JavaScript world.\n The evolution of React has a fascinating history that spans over a decade:\n \n 2010-2011: The Origins\n - The journey began with XHP, a PHP extension created at Facebook that allowed HTML components to be used in PHP code\n - XHP improved front-end code readability and helped prevent cross-site scripting (XSS) attacks\n - However, XHP had limitations with dynamic web applications, requiring frequent server roundtrips and complete UI re-renders for small changes\n\n 2011-2012: Early Development\n - Jordan Walke created the first prototype called FaxJS (later renamed to React), inspired by XHP's component model\n - The key innovation was bringing XHP's component model to JavaScript with performance improvements\n - React introduced the Virtual DOM concept to solve the performance issues of full page re-renders\n - First deployed internally on Facebook's News Feed in 2011 and Instagram in 2012\n\n 2013: Public Release\n - React was officially open-sourced at JSConf US in May 2013\n - Initial public reception was mixed, with some developers skeptical about the JSX syntax and the approach of mixing markup with JavaScript\n\n 2014-2015: Growing Adoption\n - React Native was announced in 2015, extending React's paradigm to mobile app development\n - The ecosystem began to grow with tools like Redux for state management\n - Companies beyond Facebook began adopting React for production applications\n\n 2016-2018: Maturation\n - React 16 (\"Fiber\") was released in 2017 with a complete rewrite of the core architecture\n - Introduction of new features like Error Boundaries, Portals, and improved server-side rendering\n - React 16.3 introduced the Context API for easier state management\n\n 2019-Present: Modern React\n - React Hooks were introduced in React 16.8 (February 2019), revolutionizing state management in functional components\n - React 17 (October 2020) focused on making React upgrades easier\n - React 18 (March 2022) introduced concurrent rendering and automatic batching\n - React continues to evolve with Server Components, the new React compiler (React Forget), and other performance improvements\n \n\n Note: JSX, React's syntax extension, was indeed inspired by XHP's approach of embedding XML-like syntax in code." },
  { q: "৩. React-এর প্রধান ফিচারগুলো কী কী?", qEn: "3. What are the major features of React?", a: "JSX (JavaScript-এ HTML লেখা)\n\nভার্চুয়াল DOM (দ্রুত রেন্ডার)\n\nকম্পোনেন্ট-ভিত্তিক (পুনঃব্যবহারযোগ্য ব্লক)\n\nওয়ান-ওয়ে ডেটা বাইন্ডিং (ডেটা শুধু উপরে থেকে নিচে যায়)\n\nReact Hooks (স্টেট ও লাইফসাইকেল ফাংশনাল কম্পোনেন্টে)\n\nউদাহরণ:\nJSX, Virtual DOM, Components, একমুখী data flow, Hooks।", aEn: "React offers a powerful set of features that have made it one of the most popular JavaScript libraries for building user interfaces:\n\n Core Features:\n\n - Component-Based Architecture: React applications are built using components - independent, reusable pieces of code that return HTML via a render function. This modular approach enables better code organization, reusability, and maintenance.\n\n - Virtual DOM: React creates an in-memory data structure cache, computes the resulting differences, and efficiently updates only the changed parts in the browser DOM. This approach significantly improves performance compared to direct DOM manipulation.\n\n - JSX (JavaScript XML): A syntax extension that allows writing HTML-like code in JavaScript. JSX makes the code more readable and expressive while providing the full power of JavaScript.\n\n - Unidirectional Data Flow: React follows a one-way data binding model where data flows from parent to child components. This makes the code more predictable and easier to debug.\n\n - Declarative UI: React allows you to describe what your UI should look like for a given state, and it handles the DOM updates when the underlying data changes.\n\n Advanced Features:\n\n - React Hooks: Introduced in React 16.8, hooks allow using state and other React features in functional components without writing classes.\n\n - Context API: Provides a way to share values between components without explicitly passing props through every level of the component tree.\n\n - Error Boundaries: Components that catch JavaScript errors anywhere in their child component tree and display fallback UI instead of crashing.\n\n - Server-Side Rendering (SSR): Enables rendering React components on the server before sending HTML to the client, improving performance and SEO.\n\n - Concurrent Mode: A set of new features (in development) that help React apps stay responsive and gracefully adjust to the user's device capabilities and network speed.\n\n - React Server Components: A new feature that allows components to be rendered entirely on the server, reducing bundle size and improving performance.\n\n - Suspense: A feature that lets your components \"wait\" for something before rendering, supporting code-splitting and data fetching with cleaner code.\n\n These features collectively make React powerful for building everything from small widgets to complex, large-scale web applications." },
  { q: "৪. JSX কী?", qEn: "4. What is JSX?", a: "JSX হলো JavaScript XML – এটি JavaScript-এর সিনট্যাক্স এক্সটেনশন যা দেখতে HTML-এর মতো। ব্রাউজার বুঝে না, বাবেল ট্রান্সপাইল করে React.createElement() কল করে।\n\nউদাহরণ:\n\n```javascript\nconst element = <h1>Hello</h1>; // JSX\n```", aEn: "_JSX_ stands for _JavaScript XML_ and it is an XML-like syntax extension to ECMAScript. Basically it just provides the syntactic sugar for the `React.createElement(type, props, ...children)` function, giving us expressiveness of JavaScript along with HTML like template syntax.\n\n In the example below, the text inside ` ` tag is returned as JavaScript function to the render function.\n\n    ```jsx harmony\n    export default function App() {\n      return <h1 className=\"greeting\">{\"Hello, this is a JSX Code!\"}</h1>;\n    }\n    \n```javascript\n\n If you don't use JSX syntax then the respective JavaScript code should be written as below,\n```javascript\n    import { createElement } from \"react\";\n\n    export default function App() {\n      return createElement(\n        \"h1\",\n        { className: \"greeting\" },\n        \"Hello, this is a JSX Code!\"\n      );\n    }\n    \n```javascript\n\n See Class\n```jsx harmony\n    class App extends React.Component {\n      render() {\n        return <h1 className=\"greeting\">{\"Hello, this is a JSX Code!\"}</h1>;\n      }\n    }\n    ```\n\n \n \n\n Note: JSX is stricter than HTML" },
  { q: "৫. Element ও Component-এর মধ্যে পার্থক্য কী?", qEn: "5. What is the difference between an Element and a Component?", a: "Element: একটি সাধারণ অবজেক্ট যা DOM নোড বা অন্য কম্পোনেন্টকে বর্ণনা করে। এটি ইমিউটেবল।\n\nComponent: একটি ফাংশন বা ক্লাস যা প্রপস নিয়ে Element রিটার্ন করে।\n\nউদাহরণ:\nElement = object descriptor; Component = function যা element return করে।", aEn: "Element:\n - A React Element is a plain JavaScript object that describes what you want to see on the UI. It represents a DOM node or a component at a specific point in time. \n - Elements are immutable: once created, you cannot change their properties. Instead, you create new elements to reflect updates.\n - Elements can be nested within other elements through their `props`.\n - Creating an element is a fast, lightweight operation—it does not create any actual DOM nodes or render anything to the screen directly.\n\n Example (without JSX):\n        \n```javascript\n        const element = React.createElement(\"button\", { id: \"login-btn\" }, \"Login\");\n```\n\n Equivalent JSX syntax:\n        \n```javascript\n        <button id=\"login-btn\">Login</button>\n```\n\n The object returned by `React.createElement`:\n        \n```javascript\n        {\n          type: 'button',\n          props: {\n            id: 'login-btn',\n            children: 'Login'\n          }\n        }\n```\n Elements are then passed to the React DOM renderer (e.g., `ReactDOM.render()`), which translates them to actual DOM nodes.\n\n ---\n\n Component:\n - A Component is a function or class that returns an element (or a tree of elements) to describe part of the UI. Components can accept inputs (called props) and manage their own state (in case of class or function components with hooks).\n - Components allow you to split the UI into independent, reusable pieces, each isolated and composable.\n - You can define a component using a function or a class:\n\n Example (Function Component with JSX):\n        \n```javascript\n        const Button = ({ handleLogin }) => (\n          <button id=\"login-btn\" onClick={handleLogin}>\n            Login\n          </button>\n        );\n```\n\n When JSX is compiled, it's transformed into a tree of `React.createElement` calls:\n\n        \n```javascript\n        const Button = ({ handleLogin }) =>\n          React.createElement(\n            \"button\",\n            { id: \"login-btn\", onClick: handleLogin },\n            \"Login\"\n          );\n```\n\n ---\n\n In summary:\n - Elements are the smallest building blocks in React—objects that describe what you want to see.\n - Components are functions or classes that return elements and encapsulate logic, structure, and behavior for parts of your UI.\n\n > Think of elements as the instructions for creating UI, and components as reusable blueprints that combine logic and structure to generate those instructions." },
  { q: "৬. React-এ কীভাবে কম্পোনেন্ট তৈরি করেন?", qEn: "6. How to create components in React?", a: "ফাংশনাল কম্পোনেন্ট:\n\nউদাহরণ:\n\n```javascript\nfunction Greeting() { return <h1>Hi</h1>; }\n```\nক্লাস কম্পোনেন্ট:\n\n```javascript\nclass Greeting extends React.Component {\n  render() { return <h1>Hi</h1>; }\n}\n```", aEn: "Components are the building blocks of creating User Interfaces(UI) in React. There are two possible ways to create a component.\n\n 1. Function Components: This is the simplest way to create a component. Those are pure JavaScript functions that accept props object as the one and only one parameter and return React elements to render the output:\n\n       ```jsx harmony\n       function Greeting({ message }) {\n         return <h1>{`Hello, ${message}`}</h1>;\n       }\n       \n```javascript\n\n 2. Class Components: You can also use ES6 class to define a component. The above function component can be written as a class component:\n```jsx harmony\n       class Greeting extends React.Component {\n         render() {\n           return <h1>{`Hello, ${this.props.message}`}</h1>;\n         }\n       }\n       ```" },
  { q: "৭. কখন ক্লাস কম্পোনেন্টের বদলে ফাংশনাল কম্পোনেন্ট ব্যবহার করবেন?", qEn: "7. When to use a Class Component over a Function Component?", a: "React 16.8-এর পর Hooks আসায় প্রায় সব ক্ষেত্রেই ফাংশনাল কম্পোনেন্ট ব্যবহার করা ভালো। ক্লাস কম্পোনেন্ট দরকার শুধুমাত্র যদি আপনি পুরনো কোডে Error Boundaries ব্যবহার করেন (কারণ Hooks দিয়ে এখনো error boundary বানানো যায় না)।\n\nউদাহরণ:\nHooks আসার পর প্রায় সব সময় functional component; Error Boundary এখনও class বা library।", aEn: "After the addition of Hooks(i.e. React 16.8 onwards) it is always recommended to use Function components over Class components in React. Because you could use state, lifecycle methods and other features that were only available in class component present in function component too.\n\n But even there are two reasons to use Class components over Function components.\n\n 1. If you need a React functionality whose Function component equivalent is not present yet, like Error Boundaries.\n 2. In older versions, If the component needs _state or lifecycle methods_ then you need to use class component.\n\n So the summary to this question is as follows:\n\n Use Function Components:\n\n - If you don't need state or lifecycle methods, and your component is purely presentational.\n - For simplicity, readability, and modern code practices, especially with the use of React Hooks for state and side effects.\n\n Use Class Components:\n\n - If you need to manage state or use lifecycle methods.\n - In scenarios where backward compatibility or integration with older code is necessary.\n\n Note: You can also use reusable react error boundary third-party component without writing any class. i.e, No need to use class components for Error boundaries.\n\n The usage of Error boundaries from the above library is quite straight forward.\n\n > _Note when using react-error-boundary:_ ErrorBoundary is a client component. You can only pass props to it that are serializable or use it in files that have a `\"use client\";` directive.\n\n    \n```javascript\n    \"use client\";\n\n    import { ErrorBoundary } from \"react-error-boundary\";\n\n    <ErrorBoundary fallback={<div>Something went wrong</div>}>\n      <ExampleApplication />\n    </ErrorBoundary>;\n```" },
  { q: "৮. Pure Components কী?", qEn: "8. What are Pure Components?", a: "Pure Components হলো সেই কম্পোনেন্ট যা shallow props/state তুলনা করে এবং যদি কোনো পরিবর্তন না থাকে তবে রি-রেন্ডার হয় না। এটি Performance Optimization-এর জন্য।\n\nউদাহরণ:\n```javascript\nconst MemoBtn = React.memo(function Button({ onClick }) {\n  return <button onClick={onClick}>Click</button>;\n});\n```", aEn: "Pure components are the components which render the same output for the same state and props. In function components, you can achieve these pure components through memoized `React.memo()` API wrapping around the component. This API prevents unnecessary re-renders by comparing the previous props and new props using shallow comparison. So it will be helpful for performance optimizations.\n\n But at the same time, it won't compare the previous state with the current state because function component itself prevents the unnecessary rendering by default when you set the same state again.\n\n The syntactic representation of memoized components looks like below,\n\n    \n```javascript\n    const MemoizedComponent = memo(SomeComponent, arePropsEqual?);\n```\n\n Below is the example of how child component(i.e., EmployeeProfile) prevents re-renders for the same props passed by parent component(i.e.,EmployeeRegForm).\n\n    \n```javascript\n    import { memo, useState } from \"react\";\n\n    const EmployeeProfile = memo(function EmployeeProfile({ name, email }) {\n      return (\n        <>\n          <p>Name:{name}</p>\n          <p>Email: {email}</p>\n        </>\n      );\n    });\n    export default function EmployeeRegForm() {\n      const [name, setName] = useState(\"\");\n      const [email, setEmail] = useState(\"\");\n      return (\n        <>\n          <label>\n            Name:{\" \"}\n            <input value={name} onChange={(e) => setName(e.target.value)} />\n          </label>\n          <label>\n            Email:{\" \"}\n            <input value={email} onChange={(e) => setEmail(e.target.value)} />\n          </label>\n          <hr />\n          <EmployeeProfile name={name} />\n        </>\n      );\n    }\n```\n\n In the above code, the email prop has not been passed to child component. So there won't be any re-renders for email prop change.\n\n In class components, the components extending _`React.PureComponent`_ instead of _`React.Component`_ become the pure components. When props or state changes, _PureComponent_ will do a shallow comparison on both props and state by invoking `shouldComponentUpdate()` lifecycle method.\n\n Note: `React.memo()` is a higher-order component." },
  { q: "৯. React-এ state কী?", qEn: "9. What is state in React?", a: "State হলো একটি কম্পোনেন্টের মালিকানাধীন ডেটা যা সময়ের সাথে পরিবর্তিত হতে পারে। এটি প্রাইভেট এবং কম্পোনেন্ট নিজেই নিয়ন্ত্রণ করে।\n\nউদাহরণ:\n\n```javascript\nconst [count, setCount] = useState(0);\n```", aEn: "_State_ of a component is an object that holds some information that may change over the lifetime of the component. The important point is whenever the state object changes, the component re-renders. It is always recommended to make our state as simple as possible and minimize the number of stateful components.\n\n !state\n\n Let's take an example of User component with `message` state. Here, useState hook has been used to add state to the User component and it returns an array with current state and function to update it.\n\n    ```jsx harmony\n    import { useState } from \"react\";\n\n    function User() {\n      const [message, setMessage] = useState(\"Welcome to React world\");\n\n      return (\n        <div>\n          <h1>{message}</h1>\n        </div>\n      );\n    }\n    \n```javascript\n\n Whenever React calls your component or access `useState` hook, it gives you a snapshot of the state for that particular render.\n\n See Class\n```jsx harmony\n    import React from \"react\";\n    class User extends React.Component {\n      constructor(props) {\n        super(props);\n\n        this.state = {\n          message: \"Welcome to React world\",\n        };\n      }\n\n      render() {\n        return (\n          <div>\n            <h1>{this.state.message}</h1>\n          </div>\n        );\n      }\n    }\n    ```\n\n \n \n\n State is similar to props, but it is private and fully controlled by the component ,i.e., it is not accessible to any other component till the owner component decides to pass it." },
  { q: "১০. props কী?", qEn: "10. What are props in React?", a: "Props (Properties) হলো ইমিউটেবল ডেটা যা প্যারেন্ট কম্পোনেন্ট থেকে চাইল্ডে পাঠানো হয়। চাইল্ড props পরিবর্তন করতে পারে না।\n\nউদাহরণ:\n```javascript\nfunction Child({ name }) { return <p>{name}</p>; }\n// <Child name=\"Rahim\" />\n```", aEn: "_Props_ are inputs to components. They are single values or objects containing a set of values that are passed to components on creation similar to HTML-tag attributes. Here, the data is passed down from a parent component to a child component.\n\n The primary purpose of props in React is to provide following component functionality:\n\n 1. Pass custom data to your component.\n 2. Trigger state changes.\n 3. Use via `this.props.reactProp` inside component's `render()` method.\n\n For example, let us create an element with `reactProp` property:\n\n    ```jsx harmony\n    <Element reactProp={\"1\"} />\n    \n```javascript\n\n This `reactProp` (or whatever you came up with) attribute name then becomes a property attached to React's native props object which originally already exists on all components created using React library.\n```jsx harmony\n    props.reactProp;\n    \n```javascript\n\n For example, the usage of props in function component looks like below:\n```jsx\n    import React from \"react\";\n    import ReactDOM from \"react-dom\";\n\n    const ChildComponent = (props) => {\n      return (\n        <div>\n          <p>{props.name}</p>\n          <p>{props.age}</p>\n          <p>{props.gender}</p>\n        </div>\n      );\n    };\n\n    const ParentComponent = () => {\n      return (\n        <div>\n          <ChildComponent name=\"John\" age=\"30\" gender=\"male\" />\n          <ChildComponent name=\"Mary\" age=\"25\" geneder=\"female\" />\n        </div>\n      );\n    };\n    \n```javascript\n\nThe properties from props object can be accessed directly using destructing feature from ES6 (ECMAScript 2015). It is also possible to fallback to default value when the prop value is not specified. The above child component can be simplified like below.\n```jsx harmony\nconst ChildComponent = ({ name, age, gender = \"male\" }) => {\n  return (\n    <div>\n      <p>{name}</p>\n      <p>{age}</p>\n      <p>{gender}</p>\n    </div>\n  );\n};\n\n```javascript\n\nNote: The default value won't be used if you pass `null` or `0` value. i.e, default value is only used if the prop value is missed or `undefined` value has been passed.\n\n See Class \n The Props accessed in Class Based Component as below\n```jsx\nimport React from \"react\";\nimport ReactDOM from \"react-dom\";\n\nclass ChildComponent extends React.Component {\n  render() {\n    return (\n      <div>\n        <p>{this.props.name}</p>\n        <p>{this.props.age}</p>\n        <p>{this.props.gender}</p>\n      </div>\n    );\n  }\n}\n\nclass ParentComponent extends React.Component {\n  render() {\n    return (\n      <div>\n        <ChildComponent name=\"John\" age=\"30\" gender=\"male\" />\n        <ChildComponent name=\"Mary\" age=\"25\" gender=\"female\" />\n      </div>\n    );\n  }\n}\n```" },
  { q: "১১. state ও props-এর মধ্যে পার্থক্য কী?", qEn: "11. What is the difference between state and props?", a: "| বৈশিষ্ট্য | state | props |\n| পরিবর্তনযোগ্য? | হ্যাঁ (setState) | না (ইমিউটেবল) |\n| কে নিয়ন্ত্রণ করে? | নিজের কম্পোনেন্ট | প্যারেন্ট কম্পোনেন্ট |\n| ব্যবহার | ইন্টারনাল ডেটা | কনফিগারেশন |\n\nউদাহরণ:\n| | state | props |\n| পরিবর্তন | হ্যাঁ (setState) | না |\n| মালিক | নিজে | parent |", aEn: "In React, both state and props are plain JavaScript objects, but they serve different purposes and have distinct behaviors:\n\n ### State\n - Definition: \n State is a data structure that is managed within a component. It represents information that can change over the lifetime of the component.\n - Mutability: \n State is mutable, meaning it can be changed using the setter function (`setState` in class components or the updater function from `useState` in functional components).\n - Scope: \n State is local to the component where it is defined. Only that component can modify its own state.\n - Usage: \n State is typically used for data that needs to change in response to user actions, network responses, or other dynamic events.\n - Re-rendering: \n Updating the state triggers a re-render of the component and its descendants.\n\n ### Props\n - Definition: \n Props (short for “properties”) are inputs to a component, provided by its parent component.\n - Mutability: \n Props are read-only. A component cannot modify its own props; they are immutable from the component’s perspective.\n - Scope: \n Props are used to pass data and event handlers down the component tree, enabling parent components to configure or communicate with their children.\n - Usage: \n Props are commonly used to make components reusable and configurable. They allow the same component to be rendered with different data or behavior.\n - Analogy: \n Think of props as arguments to a function, whereas state is like variables declared inside the function.\n\n ### Summary Table\n\n | Feature | State | Props |\n |-----------|-------------------------------------|-----------------------------------|\n | Managed by| The component itself | Parent component |\n | Mutable | Yes | No (read-only) |\n | Scope | Local to the component | Passed from parent to child |\n | Usage | Manage dynamic data and UI changes | Configure and customize component |\n | Update | Using setState/useState | Cannot be updated by the component|\n\n ---" },
  { q: "১২. HTML ও React ইভেন্ট হ্যান্ডলিং-এর পার্থক্য কী?", qEn: "12. What is the difference between HTML and React event handling?", a: "HTML-এ ইভেন্ট নাম ছোট হাতের (onclick), React-এ camelCase (onClick)। HTML-এ ফাংশন কল স্ট্রিং হিসেবে, React-এ ফাংশন রেফারেন্স। React-এ ইভেন্ট বাবলিং বন্ধ করতে preventDefault() দরকার।\n\nউদাহরণ:\nHTML: onclick=\"fn()\" → React: onClick={fn}", aEn: "Below are some of the main differences between HTML and React event handling,\n\n 1. In HTML, the event name usually represents in _lowercase_ as a convention:\n\n       \n```html\n       <button onclick=\"activateLasers()\"></button>\n```\n\n Whereas in React it follows _camelCase_ convention:\n\n       ```jsx harmony\n       <button onClick={activateLasers}>\n       \n```javascript\n\n 2. In HTML, you can return `false` to prevent default behavior:\n```html\n       <a\n         href=\"#\"\n         onclick='console.log(\"The link was clicked.\"); return false;'\n       />\n       \n```javascript\n\n Whereas in React you must call `preventDefault()` explicitly:\n```javascript\n       function handleClick(event) {\n         event.preventDefault();\n         console.log(\"The link was clicked.\");\n       }\n       ```\n\n 3. In HTML, you need to invoke the function by appending `()`\n Whereas in react you should not append `()` with the function name. (refer \"activateLasers\" function in the first point for example)" },
  { q: "১৩. Synthetic Events কী?", qEn: "13. What are synthetic events in React?", a: "Synthetic Event হলো React-এর ক্রস-ব্রাউজার র‍্যাপার যা নেটিভ ব্রাউজার ইভেন্টকে ঘিরে তৈরি। এটি সব ব্রাউজারে একই আচরণ নিশ্চিত করে।\n\nউদাহরণ:\n```javascript\nfunction handleClick(e) {\n  e.preventDefault(); // synthetic event\n}\n```", aEn: "`SyntheticEvent` is a cross-browser wrapper around the browser's native event. Its API is same as the browser's native event, including `stopPropagation()` and `preventDefault()`, except the events work identically across all browsers. The native events can be accessed directly from synthetic events using `nativeEvent` attribute.\n\n Let's take an example of `BookStore` title search component with the ability to get all native event properties\n\n    \n```javascript\n    function BookStore() {\n      function handleTitleChange(e) {\n        console.log(\"The new title is:\", e.target.value);\n        console.log('Synthetic event:', e); // React SyntheticEvent\n        console.log('Native event:', e.nativeEvent); // Browser native event\n        e.stopPropagation();\n        e.preventDefault();\n      }\n\n      return <input name=\"title\" onChange={handleTitleChange} />;\n    }\n```\n \n List of common synthetic events are:\n\n  `onClick`\n  `onChange`\n  `onSubmit`\n  `onKeyDown`, `onKeyUp`\n  `onFocus`, `onBlur`\n  `onMouseEnter`, `onMouseLeave`\n  `onTouchStart`, `onTouchEnd`\n\n *" },
  { q: "১৪. Inline Conditional Expressions কী?", qEn: "14. What are inline conditional expressions?", a: "JSX-এর ভেতর শর্ত বসানোর উপায়:\n\nTernary Operator: {isLoggedIn ? <Logout /> : <Login />}\n\nLogical &&: {isLoading && <Spinner />}\n\nউদাহরণ:\n```javascript\n{isLoggedIn ? <Logout /> : <Login />}\n{isLoading && <Spinner />}\n```", aEn: "You can use either _if statements_ or _ternary expressions_ which are available in JS(and JSX in React) to conditionally execute or render expressions. Apart from these approaches, you can also embed any expressions in JSX by wrapping them in curly braces and then followed by JS logical operator `&&`. It is helpful to render elements conditionally within a single line and commonly used for concise logic, especially in JSX rendering.\n\n    ```jsx harmony\n    <h1>Hello!</h1>;\n    {\n      messages.length > 0 && !isLogin ? (\n        <h2>You have {messages.length} unread messages.</h2>\n      ) : (\n        <h2>You don't have unread messages.</h2>\n      );\n    }\n    ```" },
  { q: "১৫. \"key\" prop কী এবং অ্যারের এলিমেন্টে এর সুবিধা কী?", qEn: "15. What is \"key\" prop and what is the benefit of using it in arrays of elements?", a: "Key React কে বলে দেয় কোন এলিমেন্ট পরিবর্তিত, যোগ বা সরানো হয়েছে। এটি পুনঃব্যবহার ও রি-অর্ডারিং দ্রুত করে। ইনডেক্স কী ব্যবহার না করে ইউনিক আইডি ব্যবহার করবেন।\n\nউদাহরণ:\n```javascript\n{items.map(item => (\n  <li key={item.id}>{item.name}</li>\n))}\n```", aEn: "A `key` is a special attribute you should include when mapping over arrays to render data. _Key_ prop helps React identify which items have changed, are added, or are removed.\n\n Keys should be unique among its siblings. Most often we use ID from our data as _key_:\n\n    ```jsx harmony\n    const todoItems = todos.map((todo) => <li key={todo.id}>{todo.text}</li>);\n    \n```javascript\n\n When you don't have stable IDs for rendered items, you may use the item _index_ as a _key_ as a last resort:\n```jsx harmony\n    const todoItems = todos.map((todo, index) => (\n      <li key={index}>{todo.text}</li>\n    ));\n    ```\n Benefits of key:\n  Enables React to efficiently update and re-render components.\n  Prevents unnecessary re-renders by reusing components when possible.\n  Helps maintain internal state of list items correctly.\n\n Note:\n\n 1. Using _indexes_ for _keys_ is not recommended if the order of items may change. This can negatively impact performance and may cause issues with component state.\n 2. If you extract list item as separate component then apply _keys_ on list component instead of `li` tag.\n 3. There will be a warning message in the console if the `key` prop is not present on list items.\n 4. The key attribute accepts either string or number and internally convert it as string type.\n 5. Don't generate the key on the fly something like `key={Math.random()}`. Because the keys will never match up between re-renders and DOM created everytime.\n\n *" },
  { q: "১৬. Virtual DOM কী?", qEn: "16. What is Virtual DOM?", a: "Virtual DOM হলো রিয়েল DOM-এর একটি লাইটওয়েট JavaScript অবজেক্ট রেপ্লিকা। এটি মেমোরিতে থাকে এবং পরিবর্তনগুলো হিসাব করে, তারপর শুধু প্রয়োজনীয় অংশ রিয়েল DOM-এ আপডেট করে।\n\nউদাহরণ:\nMemory-তে lightweight tree; change হলে diff করে real DOM update।", aEn: "The _Virtual DOM_ (VDOM) is a lightweight, in-memory representation of _Real DOM_ used by libraries like React to optimize UI rendering. The representation of a UI is kept in memory and synced with the \"real\" DOM. It's a step that happens between the render function being called and the displaying of elements on the screen. This entire process is called _reconciliation_." },
  { q: "১৭. Virtual DOM কীভাবে কাজ করে?", qEn: "17. How Virtual DOM works?", a: "UI-তে কোনো পরিবর্তন হলে নতুন ভার্চুয়াল DOM তৈরি হয়।\n\nপুরনো ভার্চুয়াল DOM-এর সাথে নতুন ভার্চুয়াল DOM-এর তুলনা (diffing) হয়।\n\nশুধু পরিবর্তিত অংশ রিয়েল DOM-এ আপডেট হয় (reconciliation)।\n\nউদাহরণ:\nChange → new VDOM → diff → patch real DOM (reconciliation)।", aEn: "The _Virtual DOM_ works in five simple steps.\n\n 1. Initial Render \n When a UI component renders for the first time, it returns JSX. React uses this structure to create a Virtual DOM tree, which is a lightweight copy of the actual DOM. This Virtual DOM is then used to build and render the Real DOM in the browser.\n\n 2. State or Props Change \n When the component's state or props change, React creates a new Virtual DOM reflecting the updated UI. However, it doesn't immediately update the Real DOM; instead, it works in memory to prepare for an efficient update.\n \n !vdom\n\n 3. Diffing Algorithm \n React then compares the new Virtual DOM with the previous one using a process called diffing. It determines what has changed between the two versions and identifies the minimal set of updates needed.\n \n !vdom2 \n\n 4. Reconciliation \n Based on the diffing results, React decides which parts of the Real DOM should be updated. It avoids re-rendering the entire DOM and instead updates only the elements that actually changed.\n \n !vdom3\n\n 5. Efficient DOM Updates \n This entire process—working with the Virtual DOM, diffing, and selective updating—makes the UI rendering much faster and more efficient than manipulating the Real DOM directly." },
  { q: "১৮. Shadow DOM ও Virtual DOM-এর পার্থক্য কী?", qEn: "18. What is the difference between Shadow DOM and Virtual DOM?", a: "| Shadow DOM | Virtual DOM |\n| ব্রাউজার ফিচার (Web Components) | React-এর ম্যানেজড কপি |\n| CSS ও মার্কপ এনক্যাপসুলেট করে | শুধু পারফরম্যান্সের জন্য ডিফিং |\n\nউদাহরণ:\n| Shadow DOM | Virtual DOM |\n| Browser encapsulation | React performance |", aEn: "The _Shadow DOM_ is a browser technology designed primarily for scoping variables and CSS in _web components_. The _Virtual DOM_ is a concept implemented by libraries in JavaScript on top of browser APIs.\n\n The key differences in a table format shown below:\n\n | Feature | Shadow DOM | Virtual DOM |\n | --- | --- | --- |\n | Purpose | Encapsulation for Web Components | Efficient UI rendering |\n | Managed by | Browser | JS frameworks (e.g., React) |\n | DOM Type | Part of real DOM (scoped) | In-memory representation |\n | Encapsulation | Yes | No |\n | Use Case | Web Components, scoped styling | UI diffing and minimal DOM updates |" },
  { q: "১৯. React Fiber কী?", qEn: "19. What is React Fiber?", a: "React Fiber হলো React v16-তে আসা কোর অ্যালগরিদমের পুনর্লিখন। এটি রেন্ডারিং কাজকে ছোট ইউনিটে ভাগ করে এবং উচ্চ-প্রাধান্যের কাজ আগে করে (যেমন অ্যানিমেশন)।\n\nউদাহরণ:\nRender কাজ ছোট unit-এ ভাগ; interrupt ও priority support।", aEn: "React Fiber is the new reconciliation engine in React, introduced in React 16. It’s a complete rewrite of React’s core algorithm(old stack-based algorithm) for rendering and updating the UI. Fiber enhances React’s ability to handle asynchronous rendering, prioritized updates(assign priority to different types of updates), and interruption(ability to pause, abort, or reuse work) of rendering work, enabling smoother and more responsive user interfaces." },
  { q: "২০. React Fiber-এর প্রধান লক্ষ্য কী?", qEn: "20. What is the main goal of React Fiber?", a: "ইন্টারাপ্টেবল রেন্ডারিং (অন্যান্য কাজের জন্য থামানো যাবে)\n\nপ্রাধান্য ভিত্তিক আপডেট\n\nকনকারেন্ট রেন্ডারিং সম্ভব করা\n\nউদাহরণ:\nInterruptible rendering, priority updates, concurrent features।", aEn: "The goal of _React Fiber_ is to increase its suitability for areas like animation, layout, and gestures. Its headline feature is incremental rendering: the ability to split rendering work into chunks and spread it out over multiple frames.\n\n Its main goals are:\n\n  Incremental Rendering – Breaks work into chunks for smoother updates.\n  Interruptible Rendering – Pauses and resumes rendering to keep the UI responsive.\n  Prioritization – Handles high-priority updates (e.g. animations) before low-priority ones.\n  Concurrency Support – Enables working on multiple UI versions simultaneously.\n  Better Error Handling – Supports component-level error boundaries.\n  Suspense Support – Allows waiting for async data before rendering.\n  Improved DevTools – Enables better debugging and performance tracking.\n\n *" },
  { q: "২১. Controlled Components কী?", qEn: "21. What are controlled components?", a: "যেখানে ফর্ম এলিমেন্টের মান React state দ্বারা নিয়ন্ত্রিত হয়। প্রতিটি টাইপে onChange ইভেন্টে state আপডেট হয়।\n\nউদাহরণ:\n\n```javascript\n<input value={name} onChange={e => setName(e.target.value)} />\n```", aEn: "A controlled component is a React component that fully manages the form element's state(e.g, elements like ` `, ` `, or ` `)) using React's internal state mechanism. i.e, The component does not manage its own internal state — instead, React acts as the single source of truth for form data.\n\n The controlled components will be implemented using the below steps,\n\n 1. Initialize the state using `useState` hooks in function components or inside constructor for class components.\n 2. Set the value of the form element to the respective state variable.\n 3. Create an event handler(`onChange`) to handle the user input changes through `useState`'s updater function or `setState` from class component.\n 4. Attach the above event handler to form element's change or click events\n\n Note: React re-renders the component every time the input value changes.\n\n For example, the name input field updates the username using `handleChange` event handler as below,\n\n   \n```javascript\n   import React, { useState } from \"react\";\n\n   function UserProfile() {\n     const [username, setUsername] = useState(\"\");\n\n     const handleChange = (e) => {\n       setUsername(e.target.value);\n     };\n\n     return (\n       <form>\n         <label>\n           Name:\n           <input type=\"text\" value={username} onChange={handleChange} />\n         </label>\n       </form>\n     );\n   }\n```\n In these components, DOM does not hold the actual data instead React does.\n \n Benefits:\n\n  Easy to implement validation, conditional formatting, or live feedback.\n  Full control over form data.\n  Easier to test and debug because the data is centralized in the component’s state.\n\n *" },
  { q: "২২. Uncontrolled Components কী?", qEn: "22. What are uncontrolled components?", a: "যেখানে ফর্ম এলিমেন্ট তার নিজের internal state রাখে (DOM-এর মতো)। মান পেতে ref ব্যবহার করি।\n\nউদাহরণ:\n\n```javascript\n<input ref={inputRef} />\n```", aEn: "The Uncontrolled components are form elements (like ` `, ` `, or ` `) that manage their own state internally via the DOM, rather than through React state.\n You can query the DOM using a `ref` to find its current value when you need it. This is a bit more like traditional HTML.\n\n The uncontrolled components will be implemented using the below steps,\n\n 1. Create a ref using `useRef` react hook in function component or `React.createRef()` in class based component.\n 2. Attach this `ref` to the form element.\n 3. The form element value can be accessed directly through `ref` in event handlers or `componentDidMount` for class components\n\n In the below UserProfile component, the `username` input is accessed using ref.\n\n    ```jsx harmony\n    import React, { useRef } from \"react\";\n\n    function UserProfile() {\n      const usernameRef = useRef(null);\n\n      const handleSubmit = (event) => {\n        event.preventDefault();\n        console.log(\"The submitted username is: \" + usernameRef.current.value);\n      };\n\n      return (\n        <form onSubmit={handleSubmit}>\n          <label>\n            Username:\n            <input type=\"text\" ref={usernameRef} />\n          </label>\n          <button type=\"submit\">Submit</button>\n        </form>\n      );\n    }\n    \n```javascript\n Note: Here, DOM is in charge of the value. React only accesses the value when needed (via `ref`).\n\n Benefits:\n  Less boilerplate — no need for `useState` and `onChange`.\n  Useful for quick form setups or when integrating with non-React code.\n  Slightly better performance in very large forms (fewer re-renders).\n\n In most cases, it's recommend to use controlled components to implement forms. In a controlled component, form data is handled by a React component. The alternative is uncontrolled components, where form data is handled by the DOM itself.\n\n See Class\n```jsx harmony\n    class UserProfile extends React.Component {\n      constructor(props) {\n        super(props);\n        this.handleSubmit = this.handleSubmit.bind(this);\n        this.input = React.createRef();\n      }\n\n      handleSubmit(event) {\n        alert(\"A name was submitted: \" + this.input.current.value);\n        event.preventDefault();\n      }\n\n      render() {\n        return (\n          <form onSubmit={this.handleSubmit}>\n            <label>\n              {\"Name:\"}\n              <input type=\"text\" ref={this.input} />\n            </label>\n            <input type=\"submit\" value=\"Submit\" />\n          </form>\n        );\n      }\n    }\n    ```" },
  { q: "২৩. createElement ও cloneElement-এর পার্থক্য কী?", qEn: "23. What is the difference between createElement and cloneElement?", a: "createElement(type, props, ...children) → নতুন React এলিমেন্ট তৈরি করে।\n\ncloneElement(element, newProps, ...children) → বিদ্যমান এলিমেন্ট কপি করে নতুন props মার্জ করে।\n\nউদাহরণ:\n```javascript\nReact.createElement('h1', null, 'Hi');\nReact.cloneElement(el, { className: 'active' });\n```", aEn: "Both `React.createElement` and `React.cloneElement` are used to work with React elements, but they serve different purposes.\n\n #### createElement: \n Creates a new React element from scratch. JSX elements will be transpiled to `React.createElement()` functions to create React elements which are going to be used for the object representation of UI.\n Syntax:\n    \n```javascript\n    React.createElement(type, props, ...children)\n```\n Example:\n    \n```javascript\n    React.createElement('button', { className: 'btn' }, 'Click Me')\n```\n #### cloneElement:\n The `cloneElement` method is used to clone an existing React element and optionally adds or overrides props.\n\n Syntax:\n    \n```javascript\n    React.cloneElement(element, newProps, ...children)\n```\n Example:\n    \n```javascript\n    const button = <button className=\"btn\">Click Me</button>;\n    const cloned = React.cloneElement(button, { className: 'btn-primary' });\n    // Result: <button className=\"btn-primary\">Click Me</button>\n```" },
  { q: "২৪. Lifting State Up কী?", qEn: "24. What is Lifting State Up in React?", a: "যখন একাধিক চাইল্ড কম্পোনেন্টের একই ডেটার প্রয়োজন হয়, তখন সেই ডেটা কমন প্যারেন্টে রেখে প্রপস আকারে পাঠানো। একে \"স্টেট উত্তোলন\" বলে।\n\nউদাহরণ:\n```javascript\n// Parent\nconst [user, setUser] = useState(null);\n<Profile user={user} />\n<Settings user={user} />\n```", aEn: "When several components need to share the same changing data then it is recommended to _lift the shared state up_ to their closest common ancestor. That means if two child components share the same data from its parent, then move the state to parent instead of maintaining local state in both of the child components." },
  { q: "২৫. Higher-Order Components (HOC) কী?", qEn: "25. What are Higher-Order Components?", a: "HOC হলো একটি ফাংশন যা একটি কম্পোনেন্ট নিয়ে একটি নতুন কম্পোনেন্ট রিটার্ন করে। এটি লজিক রিইউজের জন্য।\n\nউদাহরণ:\n\n```javascript\nconst EnhancedComponent = higherOrderComponent(WrappedComponent);\n```", aEn: "A _higher-order component_ (_HOC_) is a function that takes a component and returns a new enhanced component with additional props, behavior, or data. It’s a design pattern based on React’s compositional nature, allowing you to reuse logic across multiple components without modifying their internals.\n\n We consider HOCs pure components because they don’t mutate or copy behavior from the original component—they simply wrap it, enhance it, and pass through the necessary props. The wrapped component remains decoupled and reusable.\n\n    \n```javascript\n    const EnhancedComponent = higherOrderComponent(WrappedComponent);\n```\n Let's take an example of a `withAuth` higher-order component (HOC) in React. This HOC will check if a user is authenticated and either render the wrapped component if authenticated or redirect (or show a message) if not.\n\n withAuth HOC Example:\n    \n```javascript\n    import React from 'react';\n    import { Navigate } from 'react-router-dom'; // For redirection (assuming React Router v6)\n\n    const isAuthenticated = () => {\n      // e.g., check for a valid token in localStorage or context\n      return !!localStorage.getItem('authToken');\n    };\n\n    function withAuth(WrappedComponent) {\n      return function AuthenticatedComponent(props) {\n        if (!isAuthenticated()) {\n          // User is NOT authenticated, redirect to login page\n          return <Navigate to=\"/login\" replace />;\n        }\n\n        // User is authenticated, render the wrapped component\n        return <WrappedComponent {...props} />;\n      };\n    }\n\n    export default withAuth;\n```\n Usage\n    \n```javascript\n    import React from 'react';\n    import withAuth from './withAuth';\n\n    function Dashboard() {\n      return <h1>Welcome to the Dashboard!</h1>;\n    }\n\n    // Wrap Dashboard with withAuth HOC\n    export default withAuth(Dashboard);\n```\n\n HOC can be used for many use cases:\n\n 1. Code reuse, logic and bootstrap abstraction (e.g., fetching data, permissions, theming).\n 2. Render hijacking (e.g., conditional rendering or layout changes).\n 3. State abstraction and manipulation(e.g., handling form logic).\n 4. Props manipulation(e.g., injecting additional props or filtering them).\n \n Some of the real-world examples of HOCs in react eco-system:\n 1. connect() from react-redux\n 2. withRouter() from React Router v5\n 3. withTranslation() from react-i18next\n 4. withApollo() from Apollo client\n 5. withFormik from Formik library\n 6. withTheme from styled components" },
  { q: "২৬. children prop কী?", qEn: "26. What is children prop?", a: "children হলো একটি বিশেষ prop যা কম্পোনেন্টের ওপেনিং ও ক্লোজিং ট্যাগের মধ্যের সবকিছু ধারণ করে।\n\nউদাহরণ:\n\n```javascript\n<Card> <h1>Title</h1> </Card> // এখানে <h1> হলো children\n```", aEn: "The `children` prop is a special prop in React used to pass elements between the opening and closing tags of a component. It is commonly used in layout and wrapper componnents. \n\n A simple usage of children prop looks as below,\n\n    ```jsx harmony\n    function MyDiv({ children }){\n        return (\n          <div>\n            {children}\n          </div>;\n        );\n    }\n\n    export default function Greeting() {\n      return (\n        <MyDiv>\n          <span>{\"Hello\"}</span>\n          <span>{\"World\"}</span>\n        </MyDiv>\n      );\n    }\n    \n```javascript\n Here, everything inside `... ` is passed as children to the custom div component.\n\n The children can be text, JSX elements, fragments, arrays and functions(for advance use case like render props).\n\n See Class\n```jsx harmony\n    const MyDiv = React.createClass({\n      render: function () {\n        return <div>{this.props.children}</div>;\n      },\n    });\n\n    ReactDOM.render(\n      <MyDiv>\n        <span>{\"Hello\"}</span>\n        <span>{\"World\"}</span>\n      </MyDiv>,\n      node\n    );\n    ```\n\n \n \n\n Note: There are several methods available in the legacy React API to work with this prop. These include `React.Children.map`, `React.Children.forEach`, `React.Children.count`, `React.Children.only`, `React.Children.toArray`." },
  { q: "২৭. React-এ মন্তব্য কীভাবে লিখেন?", qEn: "27. How to write comments in React?", a: "JSX-এর বাইরে: // comment বা /* comment */\n\nJSX-এর ভেতর: {/* comment */}\n\nউদাহরণ:\n```javascript\n{/* JSX comment */}\n// normal JS comment outside JSX\n```", aEn: "The comments in React/JSX are similar to JavaScript Multiline comments but are wrapped in curly braces.\n\n Single-line comments:\n\n    ```jsx harmony\n    <div>\n      {/ Single-line comments(In vanilla JavaScript, the single-line comments are represented by double slash(//)) /}\n      {`Welcome ${user}, let's play React`}\n    </div>\n    \n```javascript\n\n Multi-line comments:\n```jsx harmony\n    <div>\n      {/ Multi-line comments for more than\n       one line /}\n      {`Welcome ${user}, let's play React`}\n    </div>\n    ```\n\n You can use `//` and `/ /` in JS logic, hooks, and functions." },
  { q: "২৮. Reconciliation কী?", qEn: "28. What is reconciliation?", a: "Reconciliation হলো React-এর ডিফিং অ্যালগরিদম যা দুইটি ট্রির তুলনা করে কোন নোড পরিবর্তিত হয়েছে তা বের করে এবং শুধু সেই অংশ রিয়েল DOM-এ আপডেট করে।\n\nউদাহরণ:\nপুরনো vs নতুন VDOM tree compare → minimal DOM update।", aEn: "`Reconciliation` is the process through which React updates the Browser DOM and makes React work faster. React use a `diffing algorithm` so that component updates are predictable and faster. React would first calculate the difference between the `real DOM` and the copy of DOM `(Virtual DOM)` when there's an update of components.\n React stores a copy of Browser DOM which is called `Virtual DOM`. When we make changes or add data, React creates a new Virtual DOM and compares it with the previous one. This comparison is done by `Diffing Algorithm`.\n Now React compares the Virtual DOM with Real DOM. It finds out the changed nodes and updates only the changed nodes in Real DOM leaving the rest nodes as it is. This process is called _Reconciliation_." },
  { q: "২৯. lazy ফাংশন কি named exports সমর্থন করে?", qEn: "29. Does the lazy function support named exports?", a: "না। React.lazy() শুধু default export সমর্থন করে। named export দরকার হলে মিডলম্যান মডিউল তৈরি করুন।\n\nউদাহরণ:\n```javascript\nconst Lazy = React.lazy(() => import('./Heavy'));\n// named export: .then(m => ({ default: m.Named }))\n```", aEn: "No, currently `React.lazy` function supports default exports only. If you would like to import modules which are named exports, you can create an intermediate module that reexports it as the default. It also ensures that tree shaking keeps working and don’t pull unused components.\n Let's take a component file which exports multiple named components,\n\n    \n```javascript\n    // MoreComponents.js\n    export const SomeComponent = / ... /;\n    export const UnusedComponent = / ... /;\n```\n\n and reexport `MoreComponents.js` components in an intermediate file `IntermediateComponent.js`\n\n    \n```javascript\n    // IntermediateComponent.js\n    export { SomeComponent as default } from \"./MoreComponents.js\";\n```\n\n Now you can import the module using lazy function as below,\n\n    \n```javascript\n    import React, { lazy } from \"react\";\n    const SomeComponent = lazy(() => import(\"./IntermediateComponent.js\"));\n```" },
  { q: "৩০. React কেন class অ্যাট্রিবিউটের বদলে className ব্যবহার করে?", qEn: "30. Why React uses `className` over `class` attribute?", a: "কারণ class JavaScript-এ রিজার্ভড কীওয়ার্ড। JSX বাবেল ট্রান্সপাইলের সময় className-কে class-এ রূপান্তর করে।\n\nউদাহরণ:\nclass রিজার্ভড → JSX-এ className, htmlFor।", aEn: "React uses className instead of class because of a JavaScript naming conflict with the class keyword.\n\n 1. `class` is a reserved keyword in JavaScript\n In JavaScript, class is used to define ES6 classes:\n \n        \n```javascript\n        class Person {\n          constructor(name) {\n            this.name = name;\n          }\n        }\n```\n If you try to use class as a variable or property name, it will throw a syntax error. Since JSX is just JavaScript with XML-like syntax, using class directly in JSX would break the parser.\n\n 2. JSX Is JavaScript\n \n When you write JSX like this:\n        \n```javascript\n        <div class=\"btn\">Click</div>\n```\n It will be compiled to:\n        \n```javascript\n        React.createElement('div', { class: 'btn' }, 'Click');\n```\n But `class` is invalid in this object literal context (since it clashes with the JS keyword), hence React instead uses className.\n        \n```javascript\n        <div className=\"btn\">Click</div>\n```\n which compiles to:\n        \n```javascript\n        React.createElement('div', { className: 'btn' }, 'Click');\n```\n React then translates `className` to` class` in the final HTML DOM.\n\n 3. Aligns with DOM APIs\n In vanilla JavaScript, you interact with element classes using:\n        \n```javascript\n        element.className = 'my-class';\n```\n React follows this convention, staying consistent with the DOM API's property name rather than HTML’s attribute." },
  { q: "৩১. Fragments কী?", qEn: "31. What are fragments?", a: "Fragments (<></> বা <React.Fragment>) একটি গ্রুপিং এলিমেন্ট যা অতিরিক্ত DOM নোড ছাড়াই একাধিক এলিমেন্ট রিটার্ন করতে দেয়।\n\nউদাহরণ:\n```javascript\n<>\n  <h1>Title</h1>\n  <p>Text</p>\n</>\n```", aEn: "It's a common pattern or practice in React for a component to return multiple elements. _Fragments_ let you group a list of children without adding extra nodes to the DOM.\n You need to use either ` ` or a shorter syntax having empty tag (`<> `).\n\n Below is the example of how to use fragment inside _Story_ component.\n\n    ```jsx harmony\n    function Story({ title, description, date }) {\n      return (\n        <Fragment>\n          <h2>{title}</h2>\n          <p>{description}</p>\n          <p>{date}</p>\n        </Fragment>\n      );\n    }\n    \n```javascript\n\n It is also possible to render list of fragments inside a loop with the mandatory key attribute supplied.\n```jsx harmony\n    function StoryBook() {\n      return stories.map((story) => (\n        <Fragment key={story.id}>\n          <h2>{story.title}</h2>\n          <p>{story.description}</p>\n          <p>{story.date}</p>\n        </Fragment>\n      ));\n    }\n    \n```javascript\n\n Usually, you don't need to use ` ` until there is a need of _key_ attribute. The usage of shorter syntax looks like below.\n```jsx harmony\n    function Story({ title, description, date }) {\n      return (\n        <>\n          <h2>{title}</h2>\n          <p>{description}</p>\n          <p>{date}</p>\n        </>\n      );\n    }\n    ```" },
  { q: "৩২. Fragments কেন container div-এর চেয়ে ভালো?", qEn: "32. Why fragments are better than container divs?", a: "কম DOM নোড → দ্রুত রেন্ডার\n\nCSS ফ্লেক্স/গ্রিড লেআউট ভাঙে না\n\nডেভ টুলস পরিষ্কার থাকে\n\nউদাহরণ:\nঅতিরিক্ত <div> wrapper লাগে না — flex/grid ভাঙে না।", aEn: "Below are the list of reasons to prefer fragments over container DOM elements,\n\n 1. Fragments are a bit faster and use less memory by not creating an extra DOM node. This only has a real benefit on very large and deep trees.\n 2. Some CSS mechanisms like _Flexbox_ and _CSS Grid_ have a special parent-child relationships, and adding divs in the middle makes it hard to keep the desired layout.\n 3. The DOM Inspector is less cluttered." },
  { q: "৩৩. Portals কী?", qEn: "33. What are portals in React?", a: "Portals একটি কম্পোনেন্টের JSX-কে প্যারেন্ট ট্রির বাইরে অন্য DOM নোডে রেন্ডার করার উপায় দেয়। মোডাল, টুলটিপের জন্য দারুণ।\n\nউদাহরণ:\n\n```javascript\nReactDOM.createPortal(child, domNode)\n```", aEn: "A Portal is a React feature that enables rendering children into a DOM node that exists outside the parent component's DOM hierarchy, while still preserving the React component hierarchy. Portals help avoid CSS stacking issues—for example, elements with position: fixed may not behave as expected inside a parent with transform. Portals solve this by rendering content (like modals or tooltips) outside such constrained DOM contexts.\n\n    \n```javascript\n    ReactDOM.createPortal(child, container);\n```\n  `child`: Any valid React node (e.g., JSX, string, fragment).\n  `container`: A real DOM node (e.g., `document.getElementById('modal-root')`).\n\n Even though the content renders elsewhere in the DOM, it still behaves like a normal child in React. It has access to context, state, and event handling.\n\n Example:- Modal:\n    \n```javascript\n    function Modal({ children }) {\n      return ReactDOM.createPortal(\n        <div className=\"modal\">{children}</div>,\n        document.body)\n      );\n    }\n```\n The above code will render the modal content into the body element in the HTML, not inside the component's usual location." },
  { q: "৩৪. Stateless Components কী?", qEn: "34. What are stateless components?", a: "যেসব কম্পোনেন্টের কোনো state নেই, শুধু props নিয়ে UI রেন্ডার করে। এরা প্রায়ই Presentational Components।\n\nউদাহরণ:\n```javascript\nfunction Badge({ label }) { return <span>{label}</span>; }\n```", aEn: "If the behaviour of a component is independent of its state then it can be a stateless component. You can use either a function or a class for creating stateless components. But unless you need to use a lifecycle hook in your components, you should go for function components. There are a lot of benefits if you decide to use function components here; they are easy to write, understand, and test, a little faster, and you can avoid the `this` keyword altogether." },
  { q: "৩৫. Stateful Components কী?", qEn: "35. What are stateful components?", a: "যেসব কম্পোনেন্টের state আছে এবং তারা ডেটা পরিবর্তন করে বা লজিক ধারণ করে। এরা Container Components বা স্মার্ট কম্পোনেন্ট।\n\nউদাহরণ:\n```javascript\nfunction Counter() {\n  const [n, setN] = useState(0);\n  return <button onClick={() => setN(n + 1)}>{n}</button>;\n}\n```", aEn: "If the behaviour of a component is dependent on the _state_ of the component then it can be termed as stateful component. These _stateful components_ are either function components with hooks or _class components_.\n\n Let's take an example of function stateful component which update the state based on click event,\n\n    \n```javascript\n    import React, {useState} from 'react';\n\n    const App = (props) => {\n    const [count, setCount] = useState(0);\n    handleIncrement() {\n      setCount(count+1);\n    }\n\n    return (\n      <>\n        <button onClick={handleIncrement}>Increment</button>\n        <span>Counter: {count}</span>\n      </>\n      )\n    }\n```\n\n See Class \n \n The equivalent class stateful component with a state that gets initialized in the `constructor`.\n\n    ```jsx harmony\n    class App extends Component {\n      constructor(props) {\n        super(props);\n        this.state = { count: 0 };\n      }\n\n      handleIncrement() {\n        setState({ count: this.state.count + 1 });\n      }\n\n      render() {\n        <>\n          <button onClick={() => this.handleIncrement}>Increment</button>\n          <span>Count: {count}</span>\n        </>;\n      }\n    }\n    ```" },
  { q: "৩৬. React-এ props-এ কীভাবে ভ্যালিডেশন প্রয়োগ করবেন?", qEn: "36. How to apply validation on props in React?", a: "prop-types প্যাকেজ ব্যবহার করে:\n\nউদাহরণ:\n\n```javascript\nMyComponent.propTypes = {\n  name: PropTypes.string.isRequired\n}\n```", aEn: "When the application is running in _development mode_, React will automatically check all props that we set on components to make sure they have _correct type_. If the type is incorrect, React will generate warning messages in the console. It's disabled in _production mode_ due to performance impact. The mandatory props are defined with `isRequired`.\n\n The set of predefined prop types:\n\n 1. `PropTypes.number`\n 2. `PropTypes.string`\n 3. `PropTypes.array`\n 4. `PropTypes.object`\n 5. `PropTypes.func`\n 6. `PropTypes.node`\n 7. `PropTypes.element`\n 8. `PropTypes.bool`\n 9. `PropTypes.symbol`\n 10. `PropTypes.any`\n\n We can define `propTypes` for `User` component as below:\n\n    ```jsx harmony\n    import React from \"react\";\n    import PropTypes from \"prop-types\";\n\n    class User extends React.Component {\n      static propTypes = {\n        name: PropTypes.string.isRequired,\n        age: PropTypes.number.isRequired,\n      };\n\n      render() {\n        return (\n          <>\n            <h1>{`Welcome, ${this.props.name}`}</h1>\n            <h2>{`Age, ${this.props.age}`}</h2>\n          </>\n        );\n      }\n    }\n    \n```javascript\n\n Note: In React v15.5 _PropTypes_ were moved from `React.PropTypes` to `prop-types` library.\n\n _The Equivalent Functional Component_\n```jsx harmony\n    import React from \"react\";\n    import PropTypes from \"prop-types\";\n\n    function User({ name, age }) {\n      return (\n        <>\n          <h1>{`Welcome, ${name}`}</h1>\n          <h2>{`Age, ${age}`}</h2>\n        </>\n      );\n    }\n\n    User.propTypes = {\n      name: PropTypes.string.isRequired,\n      age: PropTypes.number.isRequired,\n    };\n    ```" },
  { q: "৩৭. React-এর সুবিধাগুলো কী কী?", qEn: "37. What are the advantages of React?", a: "দ্রুত: ভার্চুয়াল DOM-এর জন্য\n\nমডুলার: ছোট ছোট কম্পোনেন্ট\n\nসহজ ডিবাগ (ওয়ান-ওয়ে ডেটা ফ্লো)\n\nমোবাইল অ্যাপ (React Native)\n\nবড় কমিউনিটি\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "Below are the list of main advantages of React,\n\n 1. Increases the application's performance with _Virtual DOM_.\n 2. JSX makes code easy to read and write.\n 3. It renders both on client and server side (_SSR_).\n 4. Easy to integrate with frameworks (Angular, Backbone) since it is only a view library.\n 5. Easy to write unit and integration tests with tools such as Jest." },
  { q: "৩৮. React-এর সীমাবদ্ধতা কী কী?", qEn: "38. What are the limitations of React?", a: "শুধু UI (পূর্ণাঙ্গ ফ্রেমওয়ার্ক নয়, রাউটিং/স্টেট ম্যানেজমেন্ট আলাদা লাগে)\n\nJSX শিখতে হবে\n\nদ্রুত পরিবর্তনশীল ইকোসিস্টেম\n\nSEO ফ্রেন্ডলি না (SSR লাগে, যেমন Next.js)\n\nউদাহরণ:\n```javascript\nconst el = <div className=\"box\">Hi</div>;\n```", aEn: "Apart from the advantages, there are few limitations of React too,\n\n 1. React is just a view library, not a full framework.\n 2. There is a learning curve for beginners who are new to web development.\n 3. Integrating React into a traditional MVC framework requires some additional configuration.\n 4. The code complexity increases with inline templating and JSX.\n 5. Too many smaller components leading to over engineering or boilerplate." },
  { q: "৩৯. স্ট্যাটিক টাইপ চেকিংয়ের জন্য প্রস্তাবিত উপায়গুলো কী?", qEn: "39. What are the recommended ways for static type checking?", a: "TypeScript (মাইক্রোসফট)\n\nFlow (ফেসবুক)\n\nউদাহরণ:\n```typescript\ninterface Props { name: string }\nfunction Hello({ name }: Props) { return <h1>{name}</h1>; }\n```", aEn: "Normally we use _PropTypes library_ (`React.PropTypes` moved to a `prop-types` package since React v15.5) for _type checking_ in the React applications. For large code bases, it is recommended to use _static type checkers_ such as Flow or TypeScript, that perform type checking at compile time and provide auto-completion features." },
  { q: "৪০. react-dom প্যাকেজের ব্যবহার কী?", qEn: "40. What is the use of `react-dom` package?", a: "react-dom React কম্পোনেন্টকে ব্রাউজারের DOM-এ রেন্ডার করার জন্য পদ্ধতি দেয়। যেমন:\n\nrender()\n\nhydrate() (SSR-এর জন্য)\n\ncreatePortal()\n\nউদাহরণ:\n```javascript\ncreatePortal(children, document.body)\n```", aEn: "The `react-dom` package provides _DOM-specific methods_ that can be used at the top level of your app. Most of the components are not required to use this module. Some of the methods of this package are:\n\n 1. `render()`\n 2. `hydrate()`\n 3. `unmountComponentAtNode()`\n 4. `findDOMNode()`\n 5. `createPortal()`" },
  { q: "৪১. ReactDOMServer কী?", qEn: "41. What is ReactDOMServer?", a: "এটি সার্ভার-সাইডে React কম্পোনেন্টকে HTML স্ট্রিং বা স্ট্রিম এ রূপান্তর করে (SSR-এর জন্য)।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "The `ReactDOMServer` object enables you to render components to static markup (typically used on node server). This object is mainly used for _server-side rendering_ (SSR). The following methods can be used in both the server and browser environments:\n\n 1. `renderToString()`\n 2. `renderToStaticMarkup()`\n\n For example, you generally run a Node-based web server like Express, Hapi, or Koa, and you call `renderToString` to render your root component to a string, which you then send as response.\n\n    \n```javascript\n    // using Express\n    import { renderToString } from \"react-dom/server\";\n    import MyPage from \"./MyPage\";\n\n    app.get(\"/\", (req, res) => {\n      res.write(\n        \"<!DOCTYPE html><html><head><title>My Page</title></head><body>\"\n      );\n      res.write('<div id=\"content\">');\n      res.write(renderToString(<MyPage />));\n      res.write(\"</div></body></html>\");\n      res.end();\n    });\n```" },
  { q: "৪২. React-এ innerHTML কীভাবে ব্যবহার করবেন?", qEn: "42. How to use innerHTML in React?", a: "dangerouslySetInnerHTML prop ব্যবহার করে, কিন্তু সতর্ক থাকবেন (XSS আক্রমণ হতে পারে)।\n\nউদাহরণ:\n\n```javascript\n<div dangerouslySetInnerHTML={{__html: htmlString}} />\n```", aEn: "The `dangerouslySetInnerHTML` attribute is React's replacement for using `innerHTML` in the browser DOM. Just like `innerHTML`, it is risky to use this attribute considering cross-site scripting (XSS) attacks. You just need to pass a `html` object as key and HTML text as value.\n\n In this example MyComponent uses `dangerouslySetInnerHTML` attribute for setting HTML markup:\n\n    ```jsx harmony\n    function createMarkup() {\n      return { html: \"First · Second\" };\n    }\n\n    function MyComponent() {\n      return <div dangerouslySetInnerHTML={createMarkup()} />;\n    }\n    ```" },
  { q: "৪৩. React-এ কীভাবে স্টাইল প্রয়োগ করবেন?", qEn: "43. How to use styles in React?", a: "ইনলাইন স্টাইল: style={{color: 'red'}}\n\nCSS ক্লাস: className=\"btn\"\n\nCSS-in-JS (styled-components)\n\nউদাহরণ:\n```javascript\nconst Btn = styled.button`padding: 8px;`;\n```", aEn: "The `style` attribute accepts a JavaScript object with camelCased properties rather than a CSS string. This is consistent with the DOM style JavaScript property, is more efficient, and prevents XSS security holes.\n\n    ```jsx harmony\n    const divStyle = {\n      color: \"blue\",\n      backgroundImage: \"url(\" + imgUrl + \")\",\n    };\n\n    function HelloWorldComponent() {\n      return <div style={divStyle}>Hello World!</div>;\n    }\n    ```\n\n Style keys are camelCased in order to be consistent with accessing the properties on DOM nodes in JavaScript (e.g. `node.style.backgroundImage`)." },
  { q: "৪৪. React-এ ইভেন্টগুলি কীভাবে আলাদা?", qEn: "44. How events are different in React?", a: "camelCase (onClick)\n\nস্ট্রিং না হয়ে ফাংশন পাস\n\nreturn false কাজ করে না, preventDefault() দিতে হবে\n\nউদাহরণ:\n```javascript\nreturn false কাজ করে না, preventDefault() দিতে হবে\n```", aEn: "Handling events in React elements has some syntactic differences:\n\n 1. React event handlers are named using camelCase, rather than lowercase.\n 2. With JSX you pass a function as the event handler, rather than a string." },
  { q: "৪৫. কী হিসেবে ইনডেক্স ব্যবহারের প্রভাব কী?", qEn: "45. What is the impact of indexes as keys?", a: "ইনডেক্স কী ব্যবহার করলে:\n\nআইটেমের ক্রম পরিবর্তনে ভুল ম্যাচিং\n\nকম পারফরম্যান্স\n\nঅ্যানিমেশন ভাঙা\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "Keys should be stable, predictable, and unique so that React can keep track of elements.\n\n In the below code snippet each element's key will be based on ordering, rather than tied to the data that is being represented. This limits the optimizations that React can do and creates confusing bugs in the application.\n\n    ```jsx harmony\n    {\n      todos.map((todo, index) => <Todo {...todo} key={index} />);\n    }\n    \n```javascript\n\n If you use element data for unique key, assuming `todo.id` is unique to this list and stable, React would be able to reorder elements without needing to reevaluate them as much.\n```jsx harmony\n    {\n      todos.map((todo) => <Todo {...todo} key={todo.id} />);\n    }\n    ```\n\n Note: If you don't specify `key` prop at all, React will use index as a key's value while iterating over an array of data." },
  { q: "৪৬. কীভাবে শর্তসাপেক্ষে কম্পোনেন্ট রেন্ডার করবেন?", qEn: "46. How do you conditionally render components?", a: "if/else (JSX-এর বাইরে)\n\nTernary Operator\n\nLogical &&\n\nImmediately Invoked Function Expression (IIFE)\n\nউদাহরণ:\n```javascript\nconst el = <div className=\"box\">Hi</div>;\n```", aEn: "In some cases you want to render different components depending on some state. JSX does not render `false` or `undefined`, so you can use conditional _short-circuiting_ to render a given part of your component only if a certain condition is true.\n\n    ```jsx harmony\n    const MyComponent = ({ name, address }) => (\n      <div>\n        <h2>{name}</h2>\n        {address && <p>{address}</p>}\n      </div>\n    );\n    \n```javascript\n\n If you need an `if-else` condition then use _ternary operator_.\n```jsx harmony\n    const MyComponent = ({ name, address }) => (\n      <div>\n        <h2>{name}</h2>\n        {address ? <p>{address}</p> : <p>{\"Address is not available\"}</p>}\n      </div>\n    );\n    ```" },
  { q: "৪৭. DOM এলিমেন্টে props ছড়িয়ে দিতে কেন সতর্ক থাকবেন?", qEn: "47. Why we need to be careful when spreading props on DOM elements?", a: "কাস্টম props (যেমন isActive) DOM এলিমেন্টে গেলে React unknown prop warning দেয়। শুধু বৈধ HTML অ্যাট্রিবিউট যেতে পারে।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "When we _spread props_ we run into the risk of adding unknown HTML attributes, which is a bad practice. Instead we can use prop destructuring with `...rest` operator, so it will add only required props.\n\n For example,\n\n    ```jsx harmony\n    const ComponentA = () => (\n      <ComponentB isDisplay={true} className={\"componentStyle\"} />\n    );\n\n    const ComponentB = ({ isDisplay, ...domProps }) => (\n      <div {...domProps}>{\"ComponentB\"}</div>\n    );\n    ```" },
  { q: "৪৮. কীভাবে একটি কম্পোনেন্ট মেমোয়েজ করবেন?", qEn: "48. How do you memoize a component?", a: "ফাংশনাল কম্পোনেন্ট: React.memo()\n\nক্লাস কম্পোনেন্ট: PureComponent বা shouldComponentUpdate\n\nউদাহরণ:\n```javascript\nexport default React.memo(ExpensiveList);\n```", aEn: "There are memoize libraries available which can be used on function components.\n\n For example `moize` library can memoize the component in another component.\n\n    ```jsx harmony\n    import moize from \"moize\";\n    import Component from \"./components/Component\"; // this module exports a non-memoized component\n\n    const MemoizedFoo = moize.react(Component);\n\n    const Consumer = () => {\n      <div>\n        {\"I will memoize the following entry:\"}\n        <MemoizedFoo />\n      </div>;\n    };\n    \n```javascript\n\n Update: Since React v16.6.0, we have a `React.memo`. It provides a higher order component which memoizes component unless the props change. To use it, simply wrap the component using React.memo before you use it.\n```js\n    const MemoComponent = React.memo(function MemoComponent(props) {\n      / render using props /\n    });\n    OR;\n    export default React.memo(MyFunctionComponent);\n    ```" },
  { q: "৪৯. কীভাবে Server-Side Rendering (SSR) ইমপ্লিমেন্ট করবেন?", qEn: "49. How you implement Server Side Rendering or SSR?", a: "ReactDOMServer.renderToString() ব্যবহার করে HTML বানিয়ে ক্লায়েন্টে পাঠান। ক্লায়েন্টে hydrate() অ্যাটাচ করেন। ফ্রেমওয়ার্ক: Next.js, Gatsby।\n\nউদাহরণ:\n```javascript\n// Server\nconst html = renderToString(<App />);\n// Client\ncreateRoot(el).render(<App />);\n```", aEn: "React is already equipped to handle rendering on Node servers. A special version of the DOM renderer is available, which follows the same pattern as on the client side.\n\n    ```jsx harmony\n    import ReactDOMServer from \"react-dom/server\";\n    import App from \"./App\";\n\n    ReactDOMServer.renderToString(<App />);\n    ```\n\n This method will output the regular HTML as a string, which can be then placed inside a page body as part of the server response. On the client side, React detects the pre-rendered content and seamlessly picks up where it left off." },
  { q: "৫০. React-এ প্রোডাকশন মোড কীভাবে এনাবল করবেন?", qEn: "50. How to enable production mode in React?", a: "Create React App: npm run build\n\nWebpack: mode: 'production' (ডিবাগ লগ, হট রিলোড বন্ধ করে, মিনিফাই করে)\n\nপরবর্তী অংশের (React Router, Redux, Hooks ইত্যাদি) উত্তর চাইলে জানাবেন।\n\nউদাহরণ:\nCRA: npm run build | Vite: vite build", aEn: "You should use Webpack's `DefinePlugin` method to set `NODE_ENV` to `production`, by which it strip out things like propType validation and extra warnings. Apart from this, if you minify the code, for example, Uglify's dead-code elimination to strip out development only code and comments, it will drastically reduce the size of your bundle." },
  { q: "৫১. হুকস কি রেন্ডার প্রপস এবং HOC প্রতিস্থাপন করে?", qEn: "51. Do Hooks replace render props and higher order components?", a: "বেশিরভাগ ক্ষেত্রেই হাঁ, কিন্তু কিছু জটিল প্যাটার্নে এখনও এদের দরকার হতে পারে।\n\nউদাহরণ:\nHooks বেশিরভাগ HOC/render props replace করে; জটিল reuse-এ এখনও pattern দরকার হতে পারে।", aEn: "Both render props and higher-order components render only a single child but in most of the cases Hooks are a simpler way to serve this by reducing nesting in your tree." },
  { q: "৫২. সুইচিং কম্পোনেন্ট কী?", qEn: "52. What is a switching component?", a: "কম্পোনেন্ট যা একাধিক কম্পোনেন্টের মধ্যে শর্তসাপেক্ষে রেন্ডার করে।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "A _switching component_ is a component that renders one of many components. We need to use object to map prop values to components.\n\n For example, a switching component to display different pages based on `page` prop:\n\n    ```jsx harmony\n    import HomePage from \"./HomePage\";\n    import AboutPage from \"./AboutPage\";\n    import ServicesPage from \"./ServicesPage\";\n    import ContactPage from \"./ContactPage\";\n\n    const PAGES = {\n      home: HomePage,\n      about: AboutPage,\n      services: ServicesPage,\n      contact: ContactPage,\n    };\n\n    const Page = (props) => {\n      const Handler = PAGES[props.page] || ContactPage;\n\n      return <Handler {...props} />;\n    };\n\n    // The keys of the PAGES object can be used in the prop types to catch dev-time errors.\n    Page.propTypes = {\n      page: PropTypes.oneOf(Object.keys(PAGES)).isRequired,\n    };\n    ```" },
  { q: "৫৩. রিয়্যাক্ট মিক্সিনস কী?", qEn: "53. What are React Mixins?", a: "পুরনো পদ্ধতি (React.createClass)-তে লজিক রিইউজের উপায়। এখন বাতিল।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "_Mixins_ are a way to totally separate components to have a common functionality. Mixins should not be used and can be replaced with _higher-order components_ or _decorators_.\n\n One of the most commonly used mixins is `PureRenderMixin`. You might be using it in some components to prevent unnecessary re-renders when the props and state are shallowly equal to the previous props and state:\n\n    \n```javascript\n    const PureRenderMixin = require(\"react-addons-pure-render-mixin\");\n\n    const Button = React.createClass({\n      mixins: [PureRenderMixin],\n      // ...\n    });\n```" },
  { q: "৫৪. রিয়্যাক্টে সমর্থিত পয়েন্টার ইভেন্টগুলো কী কী?", qEn: "54. What are the Pointer Events supported in React?", a: "onPointerDown, onPointerMove, onPointerUp, onPointerCancel ইত্যাদি।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "_Pointer Events_ provide a unified way of handling all input events. In the old days we had a mouse and respective event listeners to handle them but nowadays we have many devices which don't correlate to having a mouse, like phones with touch surface or pens. We need to remember that these events will only work in browsers that support the _Pointer Events_ specification.\n\n The following event types are now available in _React DOM_:\n\n 1. `onPointerDown`\n 2. `onPointerMove`\n 3. `onPointerUp`\n 4. `onPointerCancel`\n 5. `onGotPointerCapture`\n 6. `onLostPointerCapture`\n 7. `onPointerEnter`\n 8. `onPointerLeave`\n 9. `onPointerOver`\n 10. `onPointerOut`" },
  { q: "৫৫. কম্পোনেন্টের নাম কেন বড় হাতের অক্ষর দিয়ে শুরু হওয়া উচিত?", qEn: "55. Why should component names start with capital letter?", a: "JSX ছোট হাতের ট্যাগকে HTML এলিমেন্ট ধরে, বড় হাতেরকে কম্পোনেন্ট ধরে।\n\nউদাহরণ:\n```javascript\nconst el = <div className=\"box\">Hi</div>;\n```", aEn: "If you are rendering your component using JSX, the name of that component has to begin with a capital letter otherwise React will throw an error as an unrecognized tag. This convention is because only HTML elements and SVG tags can begin with a lowercase letter.\n\n    ```jsx harmony\n    function SomeComponent {\n      // Code goes here\n    }\n    \n```javascript\n\n You can define function component whose name starts with lowercase letter, but when it's imported it should have a capital letter. Here lowercase is fine:\n```jsx harmony\n    function myComponent {\n      render() {\n        return <div />;\n      }\n    }\n\n    export default myComponent;\n    \n```javascript\n\n While when imported in another file it should start with capital letter:\n```jsx harmony\n    import MyComponent from \"./myComponent\";\n    ```" },
  { q: "৫৬. রিয়্যাক্ট v16-এ কি কাস্টম DOM অ্যাট্রিবিউট সমর্থিত?", qEn: "56. Are custom DOM attributes supported in React v16?", a: "হাঁ। অজানা অ্যাট্রিবিউট DOM-এ যায় (কিছু রিজার্ভড ছাড়া)।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "Yes. In the past, React used to ignore unknown DOM attributes. If you wrote JSX with an attribute that React doesn't recognize, React would just skip it.\n\n For example, let's take a look at the below attribute:\n\n    ```jsx harmony\n    <div mycustomattribute={\"something\"} />\n    \n```javascript\n\n Would render an empty div to the DOM with React v15:\n```html\n    <div />\n    \n```javascript\n\n In React v16 any unknown attributes will end up in the DOM:\n```html\n    <div mycustomattribute=\"something\" />\n    ```\n\n This is useful for supplying browser-specific non-standard attributes, trying new DOM APIs, and integrating with opinionated third-party libraries." },
  { q: "৫৭. JSX-এর ভেতর কীভাবে লুপ করবেন?", qEn: "57. How to loop inside JSX?", a: "map() ফাংশন ব্যবহার করে: {items.map(item => <div key={item.id}>{item.name}</div>)}\n\nউদাহরণ:\n```javascript\n{users.map(u => <li key={u.id}>{u.name}</li>)}\n```", aEn: "You can simply use `Array.prototype.map` with ES6 _arrow function_ syntax.\n\n For example, the `items` array of objects is mapped into an array of components:\n\n    ```jsx harmony\n    <tbody>\n      {items.map((item) => (\n        <SomeComponent key={item.id} name={item.name} />\n      ))}\n    </tbody>\n    \n```javascript\n\n But you can't iterate using `for` loop:\n```jsx harmony\n    <tbody>\n      for (let i = 0; i < items.length; i++) {\n        <SomeComponent key={items[i].id} name={items[i].name} />\n      }\n    </tbody>\n    ```\n\n This is because JSX tags are transpiled into _function calls_, and you can't use statements inside expressions. This may change thanks to `do` expressions which are _stage 1 proposal_." },
  { q: "৫৮. অ্যাট্রিবিউট কোটেশনের ভেতর কীভাবে প্রপস অ্যাক্সেস করবেন?", qEn: "58. How do you access props in attribute quotes?", a: "টেমপ্লেট লিটারেল: className={btn-${type}}\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "React (or JSX) doesn't support variable interpolation inside an attribute value. The below representation won't work:\n\n    ```jsx harmony\n    <img className=\"image\" src=\"images/{this.props.image}\" />\n    \n```javascript\n\n But you can put any JS expression inside curly braces as the entire attribute value. So the below expression works:\n```jsx harmony\n    <img className=\"image\" src={\"images/\" + this.props.image} />\n    \n```javascript\n\n Using _template strings_ will also work:\n```jsx harmony\n    <img className=\"image\" src={`images/${this.props.image}`} />\n    ```" },
  { q: "৫৯. রিয়্যাক্ট প্রপটাইপ অ্যারে উইথ শেপ কী?", qEn: "59. What is React proptype array with shape?", a: "PropTypes.arrayOf(PropTypes.shape({...})) - নির্দিষ্ট আকৃতির অবজেক্টের অ্যারে ভ্যালিডেট করে।\n\nউদাহরণ:\n```javascript\nname: PropTypes.string.isRequired\n```", aEn: "If you want to pass an array of objects to a component with a particular shape then use `React.PropTypes.shape()` as an argument to `React.PropTypes.arrayOf()`.\n\n    \n```javascript\n    ReactComponent.propTypes = {\n      arrayWithShape: React.PropTypes.arrayOf(\n        React.PropTypes.shape({\n          color: React.PropTypes.string.isRequired,\n          fontSize: React.PropTypes.number.isRequired,\n        })\n      ).isRequired,\n    };\n```" },
  { q: "৬০. কীভাবে শর্তসাপেক্ষে ক্লাস অ্যাট্রিবিউট প্রয়োগ করবেন?", qEn: "60. How to conditionally apply class attributes?", a: "className={condition ? 'active' : 'inactive'} অথবা classnames লাইব্রেরি।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "You shouldn't use curly braces inside quotes because it is going to be evaluated as a string.\n\n    ```jsx harmony\n    <div className=\"btn-panel {this.props.visible ? 'show' : 'hidden'}\">\n    \n```javascript\n\n Instead you need to move curly braces outside (don't forget to include spaces between class names):\n```jsx harmony\n    <div className={'btn-panel ' + (this.props.visible ? 'show' : 'hidden')}>\n    \n```javascript\n\n _Template strings_ will also work:\n```jsx harmony\n    <div className={`btn-panel ${this.props.visible ? 'show' : 'hidden'}`}>\n    ```" },
  { q: "৬১. রিয়্যাক্ট ও ReactDOM-এর মধ্যে পার্থক্য কী?", qEn: "61. What is the difference between React and ReactDOM?", a: "রিয়্যাক্ট হল কোর লাইব্রেরি (কম্পোনেন্ট, স্টেট), ReactDOM হল DOM-এ রেন্ডার করার টুল।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "The `react` package contains `React.createElement()`, `React.Component`, `React.Children`, and other helpers related to elements and component classes. You can think of these as the isomorphic or universal helpers that you need to build components. The `react-dom` package contains `ReactDOM.render()`, and in `react-dom/server` we have _server-side rendering_ support with `ReactDOMServer.renderToString()` and `ReactDOMServer.renderToStaticMarkup()`." },
  { q: "৬২. ReactDOM কেন রিয়্যাক্ট থেকে আলাদা?", qEn: "62. Why ReactDOM is separated from React?", a: "যাতে রিয়্যাক্টকে অন্যান্য প্ল্যাটফর্মে (React Native, VR) ব্যবহার করা যায়।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "The React team worked on extracting all DOM-related features into a separate library called _ReactDOM_. React v0.14 is the first release in which the libraries are split. By looking at some of the packages, `react-native`, `react-art`, `react-canvas`, and `react-three`, it has become clear that the beauty and essence of React has nothing to do with browsers or the DOM.\n\n To build more environments that React can render to, React team planned to split the main React package into two: `react` and `react-dom`. This paves the way to writing components that can be shared between the web version of React and React Native." },
  { q: "৬৩. রিয়্যাক্টে label এলিমেন্ট কীভাবে ব্যবহার করবেন?", qEn: "63. How to use React label element?", a: "স্বাভাবিক HTML-এর মতো, তবে htmlFor অ্যাট্রিবিউট ব্যবহার করবেন (কারণ for রিজার্ভড কীওয়ার্ড)।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "If you try to render a ` ` element bound to a text input using the standard `for` attribute, then it produces HTML missing that attribute and prints a warning to the console.\n\n    ```jsx harmony\n    <label for={'user'}>{'User'}</label>\n    <input type={'text'} id={'user'} />\n    \n```javascript\n\n Since `for` is a reserved keyword in JavaScript, use `htmlFor` instead.\n```jsx harmony\n    <label htmlFor={'user'}>{'User'}</label>\n    <input type={'text'} id={'user'} />\n    ```" },
  { q: "৬৪. কীভাবে একাধিক ইনলাইন স্টাইল অবজেক্ট একত্রিত করবেন?", qEn: "64. How to combine multiple inline style objects?", a: "style={{...style1, ...style2}} (স্প্রেড অপারেটর) বা Object.assign() দিয়ে।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "You can use _spread operator_ in regular React:\n\n    ```jsx harmony\n    <button style={{ ...styles.panel.button, ...styles.panel.submitButton }}>\n      {\"Submit\"}\n    </button>\n    \n```javascript\n\n If you're using React Native then you can use the array notation:\n```jsx harmony\n    <button style={[styles.panel.button, styles.panel.submitButton]}>\n      {\"Submit\"}\n    </button>\n    ```" },
  { q: "৬৫. ব্রাউজার রিসাইজ হলে কীভাবে ভিউ রি-রেন্ডার করবেন?", qEn: "65. How to re-render the view when the browser is resized?", a: "window.addEventListener('resize') ইভেন্ট লিসেনার বসান, স্টেট আপডেট করলে রি-রেন্ডার হবে।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "You can use the `useState` hook to manage the width and height state variables, and the `useEffect` hook to add and remove the `resize` event listener. The `[]` dependency array passed to useEffect ensures that the effect only runs once (on mount) and not on every re-render.\n\n    \n```javascript\n    import React, { useState, useEffect } from \"react\";\n    function WindowDimensions() {\n      const [dimensions, setDimensions] = useState({\n        width: window.innerWidth,\n        height: window.innerHeight,\n      });\n\n      useEffect(() => {\n        function handleResize() {\n          setDimensions({\n            width: window.innerWidth,\n            height: window.innerHeight,\n          });\n        }\n        window.addEventListener(\"resize\", handleResize);\n        return () => window.removeEventListener(\"resize\", handleResize);\n      }, []);\n\n      return (\n        <span>\n          {dimensions.width} x {dimensions.height}\n        </span>\n      );\n    }\n```\n\n \n Using Class Component \n\n You can listen to the `resize` event in `componentDidMount()` and then update the dimensions (`width` and `height`). You should remove the listener in `componentWillUnmount()` method.\n\n    \n```javascript\n    class WindowDimensions extends React.Component {\n      constructor(props) {\n        super(props);\n        this.updateDimensions = this.updateDimensions.bind(this);\n      }\n\n      componentWillMount() {\n        this.updateDimensions();\n      }\n\n      componentDidMount() {\n        window.addEventListener(\"resize\", this.updateDimensions);\n      }\n\n      componentWillUnmount() {\n        window.removeEventListener(\"resize\", this.updateDimensions);\n      }\n\n      updateDimensions() {\n        this.setState({\n          width: window.innerWidth,\n          height: window.innerHeight,\n        });\n      }\n\n      render() {\n        return (\n          <span>\n            {this.state.width} x {this.state.height}\n          </span>\n        );\n      }\n    }\n```" },
  { q: "৬৬. রিয়্যাক্ট দিয়ে কীভাবে JSON প্রিটি-প্রিন্ট করবেন?", qEn: "66. How to pretty print JSON with React?", a: "<pre>{JSON.stringify(data, null, 2)}</pre>\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "We can use ` ` tag so that the formatting of the `JSON.stringify()` is retained:\n\n    ```jsx harmony\n    const data = { name: \"John\", age: 42 };\n\n    function User {\n        return <pre>{JSON.stringify(data, null, 2)}</pre>;\n    }\n\n    const container = createRoot(document.getElementById(\"container\"));\n\n    container.render(<User />);\n    \n```javascript\n\n See Class\n```jsx harmony\n    const data = { name: \"John\", age: 42 };\n\n    class User extends React.Component {\n      render() {\n        return <pre>{JSON.stringify(data, null, 2)}</pre>;\n      }\n    }\n\n    React.render(<User />, document.getElementById(\"container\"));\n    ```" },
  { q: "৬৭. রিয়্যাক্টে কেন প্রপস আপডেট করতে পারেন না?", qEn: "67. Why can't you update props in React?", a: "প্রপস ইমিউটেবল - এটি প্যারেন্ট থেকে সন্তানের দিকে শুধু পঠনযোগ্য ডেটা।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "The React philosophy is that props should be _immutable_(read only) and _top-down_. This means that a parent can send any prop values to a child, but the child can't modify received props." },
  { q: "৬৮. পেজ লোডে কীভাবে ইনপুট এলিমেন্টে ফোকাস করবেন?", qEn: "68. How to focus an input element on page load?", a: "useRef হুক ব্যবহার করে inputRef.current.focus() (useEffect-এর ভেতর)।\n\nউদাহরণ:\n```javascript\nconst inputRef = useRef();\nuseEffect(() => { inputRef.current?.focus(); }, []);\nreturn <input ref={inputRef} />;\n```", aEn: "You need to use `useEffect` hook to set focus on input field during page load time for functional component.\n\n    ```jsx harmony\n    import React, { useEffect, useRef } from \"react\";\n\n    const App = () => {\n      const inputElRef = useRef(null);\n\n      useEffect(() => {\n        inputElRef.current.focus();\n      }, []);\n\n      return (\n        <div>\n          <input defaultValue={\"Won't focus\"} />\n          <input ref={inputElRef} defaultValue={\"Will focus\"} />\n        </div>\n      );\n    };\n\n    ReactDOM.render(<App />, document.getElementById(\"app\"));\n    \n```javascript\n\n See Class \n \n You can do it by creating _ref_ for `input` element and using it in `componentDidMount()`:\n```jsx harmony\n    class App extends React.Component {\n      componentDidMount() {\n        this.nameInput.focus();\n      }\n\n      render() {\n        return (\n          <div>\n            <input defaultValue={\"Won't focus\"} />\n            <input\n              ref={(input) => (this.nameInput = input)}\n              defaultValue={\"Will focus\"}\n            />\n          </div>\n        );\n      }\n    }\n\n    ReactDOM.render(<App />, document.getElementById(\"app\"));\n    ```" },
  { q: "৬৯. ব্রাউজারে রানটাইমে কীভাবে রিয়্যাক্টের ভার্সন খুঁজবেন?", qEn: "69. How can we find the version of React at runtime in the browser?", a: "কনসোলে টাইপ করুন: React.version (যেখানে React গ্লোবালে আছে) বা DevTools-এ দেখুন।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "You can use `React.version` to get the version.\n\n    ```jsx harmony\n    const REACT_VERSION = React.version;\n\n    ReactDOM.render(\n      <div>{`React version: ${REACT_VERSION}`}</div>,\n      document.getElementById(\"app\")\n    );\n    ```" },
  { q: "৭০. রিয়্যাক্ট রাউটারের জন্য কীভাবে গুগল অ্যানালিটিক্স যোগ করবেন?", qEn: "70. How to add Google Analytics for React Router?", a: "useEffect দিয়ে লোকেশন পরিবর্তন ট্র্যাক করে GA ইভেন্ট পাঠান।\n\nউদাহরণ:\n```javascript\nuseEffect(() => {\n  // side effect\n  return () => cleanup();\n}, [deps]);\n```", aEn: "Add a listener on the `history` object to record each page view:\n\n    \n```javascript\n    history.listen(function (location) {\n      window.ga(\"set\", \"page\", location.pathname + location.search);\n      window.ga(\"send\", \"pageview\", location.pathname + location.search);\n    });\n```" },
  { q: "৭১. রিয়্যাক্টে ইনলাইন স্টাইলে কীভাবে ভেন্ডর প্রিফিক্স প্রয়োগ করবেন?", qEn: "71. How do you apply vendor prefixes to inline styles in React?", a: "রিয়্যাক্ট স্বয়ংক্রিয়ভাবে কিছু প্রিফিক্স করে, বাকিগুলো ম্যানুয়ালি দিতে হবে (যেমন WebkitTransition)।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "React _does not_ apply _vendor prefixes_ automatically. You need to add vendor prefixes manually.\n\n    ```jsx harmony\n    <div\n      style={{\n        transform: \"rotate(90deg)\",\n        WebkitTransform: \"rotate(90deg)\", // note the capital 'W' here\n        msTransform: \"rotate(90deg)\", // 'ms' is the only lowercase vendor prefix\n      }}\n    />\n    ```" },
  { q: "৭২. রিয়্যাক্ট ও ES6 ব্যবহার করে কীভাবে কম্পোনেন্ট ইম্পোর্ট ও এক্সপোর্ট করবেন?", qEn: "72. How to import and export components using React and ES6?", a: "export default MyComponent;\nimport MyComponent from './MyComponent';\n\nউদাহরণ:\n```javascript\nexport default function Button() { return <button>OK</button>; }\nimport Button from './Button';\n```", aEn: "You should use default for exporting the components\n\n    ```jsx harmony\n    import User from \"user\";\n\n    export default function MyProfile {\n        return <User type=\"customer\">//...</User>;\n    }\n    \n```javascript\n\n See Class\n```jsx harmony\n     import React from \"react\";\n     import User from \"user\";\n\n    export default class MyProfile extends React.Component {\n    render() {\n    return <User type=\"customer\">//...</User>;\n    }\n    }\n\n    \n```javascript\n \n \n\n With the export specifier, the MyProfile is going to be the member and exported to this module and the same can be imported without mentioning the name in other components.\n```" },
  { q: "৭৩. রিয়্যাক্ট কম্পোনেন্ট নামকরণের ব্যতিক্রমগুলো কী কী?", qEn: "73. What are the exceptions on React component naming?", a: "DOM ট্যাগ (div, span) ছোট হাতের, কম্পোনেন্ট বড় হাতের। ডট নোটেশন (MyComponent.Sub) ব্যবহার করা যায়।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "The component names should start with an uppercase letter but there are few exceptions to this convention. The lowercase tag names with a dot (property accessors) are still considered as valid component names.\n    For example, the below tag can be compiled to a valid component,\n\n    ```jsx harmony\n         render() {\n              return (\n                <obj.component/> // `React.createElement(obj.component)`\n              )\n        }\n    ```" },
  { q: "৭৪. প্লেইন রিয়্যাক্টে কি async/await ব্যবহার করা সম্ভব?", qEn: "74. Is it possible to use async/await in plain React?", a: "হাঁ। এটি জাভাস্ক্রিপ্ট ফিচার, রিয়্যাক্টের সাথে সম্পর্কিত নয়। useEffect-এর ভেতর ব্যবহার করতে পারেন।\n\nউদাহরণ:\n```javascript\nuseEffect(() => {\n  // side effect\n  return () => cleanup();\n}, [deps]);\n```", aEn: "Yes, you can use `async/await` in plain React, as long as your JavaScript environment supports ES2017+. Nowadays most modern browsers and build tools support ES2017+ version. If you're using Create React App, Next.js, Remix, or any modern React setup, `async/await` is supported out of the box through Babel.\n\n ### Example Usage\n\n    \n```javascript\n    import { useEffect, useState } from 'react';\n\n    function UserProfile() {\n      const [user, setUser] = useState(null);\n\n      useEffect(() => {\n        const fetchUser = async () => {\n          const response = await fetch('/api/user');\n          const data = await response.json();\n          setUser(data);\n        };\n\n        fetchUser();\n      }, []);\n\n      return user ? <div>Hello, {user.name}</div> : <div>Loading...</div>;\n    }\n```\n But If you're not using a bundler like Webpack or Babel, you will need _Babel_ and transform-async-to-generator plugin. However, React Native ships with Babel and a set of transforms." },
  { q: "৭৫. সাধারণ ফোল্ডার কাঠামো কী কী?", qEn: "75. What are the common folder structures for React?", a: "কম্পোনেন্ট-ভিত্তিক: src/components/Button/Button.js\n\nফিচার-ভিত্তিক: src/features/auth/Login.js\n\nটাইপ-ভিত্তিক: src/containers/, src/components/, src/hooks/\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "There are two common practices for React project file structure.\n\n 1. Grouping by features or routes:\n\n One common way to structure projects is locate CSS, JS, and tests together, grouped by feature or route.\n\n        \n```javascript\n        common/\n        ├─ Avatar.js\n        ├─ Avatar.css\n        ├─ APIUtils.js\n        └─ APIUtils.test.js\n        feed/\n        ├─ index.js\n        ├─ Feed.js\n        ├─ Feed.css\n        ├─ FeedStory.js\n        ├─ FeedStory.test.js\n        └─ FeedAPI.js\n        profile/\n        ├─ index.js\n        ├─ Profile.js\n        ├─ ProfileHeader.js\n        ├─ ProfileHeader.css\n        └─ ProfileAPI.js\n```\n\n 2. Grouping by file type:\n\n Another popular way to structure projects is to group similar files together.\n\n        \n```javascript\n        api/\n        ├─ APIUtils.js\n        ├─ APIUtils.test.js\n        ├─ ProfileAPI.js\n        └─ UserAPI.js\n        components/\n        ├─ Avatar.js\n        ├─ Avatar.css\n        ├─ Feed.js\n        ├─ Feed.css\n        ├─ FeedStory.js\n        ├─ FeedStory.test.js\n        ├─ Profile.js\n        ├─ ProfileHeader.js\n        └─ ProfileHeader.css\n```" },
  { q: "৭৬. অ্যানিমেশনের জন্য জনপ্রিয় প্যাকেজগুলো কী কী?", qEn: "76. What are the popular packages for animation?", a: "Framer Motion\n\nReact Spring\n\nReact Transition Group\n\nGSAP (GreenSock)\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "_React Transition Group_ and _React Motion_ are popular animation packages in React ecosystem." },
  { q: "৭৭. স্টাইল মডিউলের সুবিধাগুলো কী কী?", qEn: "77. What is the benefit of styles modules?", a: "লোকাল স্কোপড CSS (ক্ল্যাশ হয় না)\n\nকম্পোনেন্ট-ভিত্তিক স্টাইলিং\n\nকোনো রানটাইম ওভারহেড নেই\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "It is recommended to avoid hard coding style values in components. Any values that are likely to be used across different UI components should be extracted into their own modules.\n\n For example, these styles could be extracted into a separate component:\n\n    \n```javascript\n    export const colors = {\n      white,\n      black,\n      blue,\n    };\n\n    export const space = [0, 8, 16, 32, 64];\n```\n\n And then imported individually in other components:\n\n    \n```javascript\n    import { space, colors } from \"./styles\";\n```" },
  { q: "৭৮. জনপ্রিয় রিয়্যাক্ট-স্পেসিফিক লিন্টারগুলো কী কী?", qEn: "78. What are the popular React-specific linters?", a: "eslint-plugin-react\n\neslint-plugin-react-hooks\n\neslint-plugin-jsx-a11y (অ্যাক্সেসিবিলিটি)\n\nউদাহরণ:\n```javascript\nconst el = <div className=\"box\">Hi</div>;\n```", aEn: "ESLint is a popular JavaScript linter. There are plugins available that analyse specific code styles. One of the most common for React is an npm package called `eslint-plugin-react`. By default, it will check a number of best practices, with rules checking things from keys in iterators to a complete set of prop types.\n\n Another popular plugin is `eslint-plugin-jsx-a11y`, which will help fix common issues with accessibility. As JSX offers slightly different syntax to regular HTML, issues with `alt` text and `tabindex`, for example, will not be picked up by regular plugins." },
  { q: "৭৯. রিয়্যাক্ট রাউটার কী?", qEn: "79. What is React Router?", a: "রিয়্যাক্ট অ্যাপ্লিকেশনে ক্লায়েন্ট-সাইড রাউটিং করার জন্য জনপ্রিয় লাইব্রেরি। SPA-তে পৃষ্ঠা রিলোড ছাড়া URL পরিবর্তন করে।\n\nউদাহরণ:\n```javascript\n<BrowserRouter>\n  <Routes>\n    <Route path=\"/\" element={<Home />} />\n  </Routes>\n</BrowserRouter>\n```", aEn: "React Router is a powerful routing library built on top of React that helps you add new screens and flows to your application incredibly quickly, all while keeping the URL in sync with what's being displayed on the page." },
  { q: "৮০. রিয়্যাক্ট রাউটার কীভাবে হিস্ট্রি লাইব্রেরি থেকে আলাদা?", qEn: "80. How React Router is different from history library?", a: "হিস্ট্রি লাইব্রেরি নিচের স্তরে URL ম্যানেজ করে, রিয়্যাক্ট রাউটার এটি ব্যবহার করে তৈরি হয়েছে।\n\nউদাহরণ:\n```javascript\n<Link to=\"/about\">About</Link>\n```", aEn: "React Router is a wrapper around the `history` library which handles interaction with the browser's `window.history` with its browser and hash histories. It also provides memory history which is useful for environments that don't have global history, such as mobile app development (React Native) and unit testing with Node." },
  { q: "৮১. রিয়্যাক্ট রাউটার v6-এর কম্পোনেন্টগুলো কী কী?", qEn: "81. What are the ` ` components of React Router v6?", a: "<BrowserRouter>, <Routes>, <Route>, <Link>, <NavLink>, <Navigate>, <Outlet>\n\nউদাহরণ:\n```javascript\n<Link to=\"/about\">About</Link>\n```", aEn: "React Router v6 provides below 4 ` ` components:\n\n 1. ` `:Uses the HTML5 history API for standard web apps.\n 2. ` `:Uses hash-based routing for static servers.\n 3. ` `:Uses in-memory routing for testing and non-browser environments.\n 4. ` `:Provides static routing for server-side rendering (SSR).\n\n The above components will create _browser_, _hash_, _memory_ and _static_ history instances. React Router v6 makes the properties and methods of the `history` instance associated with your router available through the context in the `router` object." },
  { q: "৮২. history-র push ও replace মেথডের উদ্দেশ্য কী?", qEn: "82. What is the purpose of `push()` and `replace()` methods of `history`?", a: "push: নতুন এন্ট্রি যোগ করে\n\nreplace: বর্তমান এন্ট্রি প্রতিস্থাপন করে\n\nউদাহরণ:\n```javascript\n<Route path=\"/users/:id\" element={<User />} />\n```", aEn: "A history instance has two methods for navigation purpose.\n\n 1. `push()`\n 2. `replace()`\n\n If you think of the history as an array of visited locations, `push()` will add a new location to the array and `replace()` will replace the current location in the array with the new one." },
  { q: "৮৩. রিয়্যাক্ট রাউটার v4-এ কীভাবে প্রোগ্রামেটিক্যালি নেভিগেট করবেন?", qEn: "83. How do you programmatically navigate using React Router v4?", a: "useNavigate() হুক ব্যবহার করে: const navigate = useNavigate(); navigate('/home');\n\nউদাহরণ:\n```javascript\nconst navigate = useNavigate();\nnavigate('/dashboard');\n```", aEn: "There are three different ways to achieve programmatic routing/navigation within components.\n\n 1. Using the `withRouter()` higher-order function:\n\n The `withRouter()` higher-order function will inject the history object as a prop of the component. This object provides `push()` and `replace()` methods to avoid the usage of context.\n\n        ```jsx harmony\n        import { withRouter } from \"react-router-dom\"; // this also works with 'react-router-native'\n\n        const Button = withRouter(({ history }) => (\n          <button\n            type=\"button\"\n            onClick={() => {\n              history.push(\"/new-location\");\n            }}\n          >\n            {\"Click Me!\"}\n          </button>\n        ));\n        \n```javascript\n\n 2. Using ` ` component and render props pattern:\n\n The ` ` component passes the same props as `withRouter()`, so you will be able to access the history methods through the history prop.\n```jsx harmony\n        import { Route } from \"react-router-dom\";\n\n        const Button = () => (\n          <Route\n            render={({ history }) => (\n              <button\n                type=\"button\"\n                onClick={() => {\n                  history.push(\"/new-location\");\n                }}\n              >\n                {\"Click Me!\"}\n              </button>\n            )}\n          />\n        );\n        \n```javascript\n\n 3. Using context:\n\n This option is not recommended and treated as unstable API.\n```jsx harmony\n        const Button = (props, context) => (\n          <button\n            type=\"button\"\n            onClick={() => {\n              context.history.push(\"/new-location\");\n            }}\n          >\n            {\"Click Me!\"}\n          </button>\n        );\n\n        Button.contextTypes = {\n          history: React.PropTypes.shape({\n            push: React.PropTypes.func.isRequired,\n          }),\n        };\n        ```" },
  { q: "৮৪. রিয়্যাক্ট রাউটার v4-এ কীভাবে কোয়েরি প্যারামিটার পাবেন?", qEn: "84. How to get query parameters in React Router v4?", a: "useLocation() হুক এবং new URLSearchParams(location.search) ব্যবহার করে।\n\nউদাহরণ:\n```javascript\n<Link to=\"/about\">About</Link>\n```", aEn: "The ability to parse query strings was taken out of React Router v4 because there have been user requests over the years to support different implementation. So the decision has been given to users to choose the implementation they like. The recommended approach is to use query strings library.\n\n    \n```javascript\n    const queryString = require(\"query-string\");\n    const parsed = queryString.parse(props.location.search);\n```\n\n You can also use `URLSearchParams` if you want something native:\n\n    \n```javascript\n    const params = new URLSearchParams(props.location.search);\n    const foo = params.get(\"name\");\n```\n\n You should use a _polyfill_ for IE11." },
  { q: "৮৫. \"Router may have only one child element\" ওয়ার্নিং কেন পান?", qEn: "85. Why you get \"Router may have only one child element\" warning?", a: "<BrowserRouter>-এর সরাসরি ভেতরে একাধিক এলিমেন্ট থাকলে। সবকিছু <Routes> বা <div> দিয়ে র‍্যাপ করুন।\n\nউদাহরণ:\n```javascript\n<Link to=\"/about\">About</Link>\n```", aEn: "You have to wrap your Route's in a ` ` block because ` ` is unique in that it renders a route exclusively.\n\n At first you need to add `Switch` to your imports:\n\n    \n```javascript\n    import { Switch, Router, Route } from \"react-router\";\n```\n\n Then define the routes within ` ` block:\n\n    ```jsx harmony\n    <Router>\n      <Switch>\n        <Route {/ ... /} />\n        <Route {/ ... /} />\n      </Switch>\n    </Router>\n    ```" },
  { q: "৮৬. রিয়্যাক্ট রাউটার v4-এ কীভাবে history.push-এ প্যারাম পাস করবেন?", qEn: "86. How to pass params to `history.push` method in React Router v4?", a: "navigate('/user/123', { state: { from: 'home' } }) অথবা পাথ প্যারামিটার।\n\nউদাহরণ:\n```javascript\n<Link to=\"/about\">About</Link>\n```", aEn: "While navigating you can pass props to the `history` object:\n\n    \n```javascript\n    this.props.history.push({\n      pathname: \"/template\",\n      search: \"?name=sudheer\",\n      state: { detail: response.data },\n    });\n```\n\n The `search` property is used to pass query params in `push()` method." },
  { q: "৮৭. কীভাবে ডিফল্ট বা নটফাউন্ড পেজ ইমপ্লিমেন্ট করবেন?", qEn: "87. How to implement _default_ or _NotFound_ page?", a: "পাথ * দিয়ে শেষ Route বানান: <Route path=\"*\" element={<NotFound />} />\n\nউদাহরণ:\n```javascript\n<Route path=\"*\" element={<NotFound />} />\n```", aEn: "A ` ` renders the first child ` ` that matches. A ` ` with no path always matches. So you just need to simply drop path attribute as below\n\n    ```jsx harmony\n    <Switch>\n      <Route exact path=\"/\" component={Home} />\n      <Route path=\"/user\" component={User} />\n      <Route component={NotFound} />\n    </Switch>\n    ```" },
  { q: "৮৮. রিয়্যাক্ট রাউটার v4-এ কীভাবে হিস্ট্রি পাবেন?", qEn: "88. How to get history on React Router v4?", a: "useNavigate() (v6) বা পুরনো ভার্সনে useHistory()।\n\nউদাহরণ:\n```javascript\n<Link to=\"/about\">About</Link>\n```", aEn: "Below are the list of steps to get history object on React Router v4,\n\n 1. Create a module that exports a `history` object and import this module across the project.\n\n For example, create `history.js` file:\n\n        \n```javascript\n        import { createBrowserHistory } from \"history\";\n\n        export default createBrowserHistory({\n          / pass a configuration object here if needed /\n        });\n```\n\n 2. You should use the ` ` component instead of built-in routers. Import the above `history.js` inside `index.js` file:\n\n        ```jsx harmony\n        import { Router } from \"react-router-dom\";\n        import history from \"./history\";\n        import App from \"./App\";\n\n        ReactDOM.render(\n          <Router history={history}>\n            <App />\n          </Router>,\n          holder\n        );\n        \n```javascript\n\n 3. You can also use push method of `history` object similar to built-in history object:\n```javascript\n        // some-other-file.js\n        import history from \"./history\";\n\n        history.push(\"/go-here\");\n        ```" },
  { q: "৮৯. লগইনের পর কীভাবে অটোমেটিক রিডাইরেক্ট করবেন?", qEn: "89. How to perform automatic redirect after login?", a: "navigate('/dashboard', { replace: true }) ব্যবহার করে।\n\nউদাহরণ:\n```javascript\n<Route path=\"/users/:id\" element={<User />} />\n```", aEn: "The `react-router` package provides ` ` component in React Router. Rendering a ` ` will navigate to a new location. Like server-side redirects, the new location will override the current location in the history stack.\n\n    \n```javascript\n    import { Redirect } from \"react-router\";\n\n    export default function Login {\n        if (this.state.isLoggedIn === true) {\n          return <Redirect to=\"/your/redirect/page\" />;\n        } else {\n          return <div>{\"Login Please\"}</div>;\n        }\n    }\n```\n\n See Class \n \n\n    \n```javascript\n    import React, { Component } from \"react\";\n    import { Redirect } from \"react-router\";\n\n    export default class LoginComponent extends Component {\n      render() {\n        if (this.state.isLoggedIn === true) {\n          return <Redirect to=\"/your/redirect/page\" />;\n        } else {\n          return <div>{\"Login Please\"}</div>;\n        }\n      }\n    }\n```" },
  { q: "৯০. রিয়্যাক্ট ইন্টেল কী?", qEn: "90. What is React Intl?", a: "ফরম্যাটজেএসের রিয়্যাক্টের জন্য ইন্টারন্যাশনালাইজেশন (i18n) লাইব্রেরি। একাধিক ভাষা সাপোর্ট করে।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "The _React Intl_ library makes internationalization in React straightforward, with off-the-shelf components and an API that can handle everything from formatting strings, dates, and numbers, to pluralization. React Intl is part of _FormatJS_ which provides bindings to React via its components and API." },
  { q: "৯১. রিয়্যাক্ট ইন্টেলের প্রধান বৈশিষ্ট্যগুলো কী কী?", qEn: "91. What are the main features of React Intl?", a: "তারিখ/সময় ফরম্যাটিং\n\nসংখ্যা ফরম্যাটিং\n\nপ্লুরালাইজেশন\n\nHTML মেসেজে প্লেসহোল্ডার\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "Below are the main features of React Intl,\n\n 1. Display numbers with separators.\n 2. Display dates and times correctly.\n 3. Display dates relative to \"now\".\n 4. Pluralize labels in strings.\n 5. Support for 150+ languages.\n 6. Runs in the browser and Node.\n 7. Built on standards." },
  { q: "৯২. রিয়্যাক্ট ইন্টেলে ফরম্যাটিংয়ের দুটি উপায় কী কী?", qEn: "92. What are the two ways of formatting in React Intl?", a: "কম্পোনেন্ট ভিত্তিক: <FormattedMessage />\n\nহুক ভিত্তিক: useIntl()\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "The library provides two ways to format strings, numbers, and dates:\n\n 1. Using react components:\n\n        ```jsx harmony\n        <FormattedMessage\n          id={\"account\"}\n          defaultMessage={\"The amount is less than minimum balance.\"}\n        />\n        \n```javascript\n\n 2. Using an API:\n```javascript\n        const messages = defineMessages({\n          accountMessage: {\n            id: \"account\",\n            defaultMessage: \"The amount is less than minimum balance.\",\n          },\n        });\n\n        formatMessage(messages.accountMessage);\n        ```" },
  { q: "৯৩. প্লেসহোল্ডার হিসেবে কীভাবে FormattedMessage ব্যবহার করবেন?", qEn: "93. How to use ` ` as placeholder using React Intl?", a: "উদাহরণ:\n\n```javascript\n<input placeholder={intl.formatMessage({ id: 'name' })} />\n```", aEn: "The ` ` components from `react-intl` return elements, not plain text, so they can't be used for placeholders, alt text, etc. In that case, you should use lower level API `formatMessage()`. You can inject the `intl` object into your component using `injectIntl()` higher-order component and then format the message using `formatMessage()` available on that object.\n\n    ```jsx harmony\n    import React from \"react\";\n    import { injectIntl, intlShape } from \"react-intl\";\n\n    const MyComponent = ({ intl }) => {\n      const placeholder = intl.formatMessage({ id: \"messageId\" });\n      return <input placeholder={placeholder} />;\n    };\n\n    MyComponent.propTypes = {\n      intl: intlShape.isRequired,\n    };\n\n    export default injectIntl(MyComponent);\n    ```" },
  { q: "৯৪. রিয়্যাক্ট ইন্টেলে কীভাবে বর্তমান লোকেল অ্যাক্সেস করবেন?", qEn: "94. How to access current locale with React Intl?", a: "useIntl() হুক থেকে locale প্রপ: const { locale } = useIntl();\n\nউদাহরণ:\n```javascript\nconst { locale } = useIntl();\nconsole.log(locale); // 'bn' | 'en'\n```", aEn: "You can get the current locale in any component of your application using `injectIntl()`:\n\n    ```jsx harmony\n    import { injectIntl, intlShape } from \"react-intl\";\n\n    const MyComponent = ({ intl }) => (\n      <div>{`The current locale is ${intl.locale}`}</div>\n    );\n\n    MyComponent.propTypes = {\n      intl: intlShape.isRequired,\n    };\n\n    export default injectIntl(MyComponent);\n    ```" },
  { q: "৯৫. রিয়্যাক্ট ইন্টেলে কীভাবে তারিখ ফরম্যাট করবেন?", qEn: "95. How to format date using React Intl?", a: "<FormattedDate value={date} year=\"numeric\" month=\"long\" day=\"numeric\" />\n\nউদাহরণ:\n```javascript\n<FormattedDate value={new Date()} year=\"numeric\" month=\"long\" day=\"numeric\" />\n```", aEn: "The `injectIntl()` higher-order component will give you access to the `formatDate()` method via the props in your component. The method is used internally by instances of `FormattedDate` and it returns the string representation of the formatted date.\n\n     ```jsx harmony\n     import { injectIntl, intlShape } from \"react-intl\";\n\n     const stringDate = this.props.intl.formatDate(date, {\n       year: \"numeric\",\n       month: \"numeric\",\n       day: \"numeric\",\n     });\n\n     const MyComponent = ({ intl }) => (\n       <div>{`The formatted date is ${stringDate}`}</div>\n     );\n\n     MyComponent.propTypes = {\n       intl: intlShape.isRequired,\n     };\n\n     export default injectIntl(MyComponent);\n     ```" },
  { q: "৯৬. রিয়্যাক্ট টেস্টিংয়ে শ্যালো রেন্ডারার কী?", qEn: "96. What is Shallow Renderer in React testing?", a: "একটি কম্পোনেন্টকে গভীরতা ছাড়া রেন্ডার করে (চাইল্ড কম্পোনেন্ট রেন্ডার হয় না)। ইউনিট টেস্টের জন্য।\n\nউদাহরণ:\n```javascript\nimport { shallow } from 'enzyme';\nconst wrapper = shallow(<MyComponent />);\n```", aEn: "_Shallow rendering_ is useful for writing unit test cases in React. It lets you render a component _one level deep_ and assert facts about what its render method returns, without worrying about the behavior of child components, which are not instantiated or rendered.\n\n For example, if you have the following component:\n\n    \n```javascript\n    function MyComponent() {\n      return (\n        <div>\n          <span className={\"heading\"}>{\"Title\"}</span>\n          <span className={\"description\"}>{\"Description\"}</span>\n        </div>\n      );\n    }\n```\n\n Then you can assert as follows:\n\n    ```jsx harmony\n    import ShallowRenderer from \"react-test-renderer/shallow\";\n\n    // in your test\n    const renderer = new ShallowRenderer();\n    renderer.render(<MyComponent />);\n\n    const result = renderer.getRenderOutput();\n\n    expect(result.type).toBe(\"div\");\n    expect(result.props.children).toEqual([\n      <span className={\"heading\"}>{\"Title\"}</span>,\n      <span className={\"description\"}>{\"Description\"}</span>,\n    ]);\n    ```" },
  { q: "৯৭. টেস্টরেন্ডারার প্যাকেজ কী?", qEn: "97. What is `TestRenderer` package in React?", a: "react-test-renderer – রিয়্যাক্ট কম্পোনেন্টকে পিওর জাভাস্ক্রিপ্ট অবজেক্টে রেন্ডার করে (DOM ছাড়া)। স্ন্যাপশট টেস্টিংয়ে ব্যবহার হয়।\n\nউদাহরণ:\n```javascript\nimport TestRenderer from 'react-test-renderer';\nconst tree = TestRenderer.create(<App />).toJSON();\n```", aEn: "This package provides a renderer that can be used to render components to pure JavaScript objects, without depending on the DOM or a native mobile environment. This package makes it easy to grab a snapshot of the platform view hierarchy (similar to a DOM tree) rendered by a ReactDOM or React Native without using a browser or `jsdom`.\n\n    ```jsx harmony\n    import TestRenderer from \"react-test-renderer\";\n\n    const Link = ({ page, children }) => <a href={page}>{children}</a>;\n\n    const testRenderer = TestRenderer.create(\n      <Link page={\"https://www.facebook.com/\"}>{\"Facebook\"}</Link>\n    );\n\n    console.log(testRenderer.toJSON());\n    // {\n    //   type: 'a',\n    //   props: { href: 'https://www.facebook.com/' },\n    //   children: [ 'Facebook' ]\n    // }\n    ```" },
  { q: "৯৮. ReactTestUtils প্যাকেজের উদ্দেশ্য কী?", qEn: "98. What is the purpose of ReactTestUtils package?", a: "রিয়্যাক্ট কম্পোনেন্ট টেস্টিংয়ের জন্য হেল্পার ফাংশন দেয় (যেমন Simulate.click, scryRenderedDOMComponentsWithTag)।\n\nউদাহরণ:\n```javascript\nimport { render, screen } from '@testing-library/react';\nrender(<App />);\n```", aEn: "_ReactTestUtils_ are provided in the `with-addons` package and allow you to perform actions against a simulated DOM for the purpose of unit testing." },
  { q: "৯৯. জেস্ট কী?", qEn: "99. What is Jest?", a: "ফেসবুক তৈরিকৃত জাভাস্ক্রিপ্ট টেস্টিং ফ্রেমওয়ার্ক। রিয়্যাক্টের সাথে ডিফল্ট হিসেবে আসে (CRA)।\n\nউদাহরণ:\n```javascript\nexpect(result).toBe(expected);\n```", aEn: "_Jest_ is a JavaScript unit testing framework created by Facebook based on Jasmine and provides automated mock creation and a `jsdom` environment. It's often used for testing components." },
  { q: "১০০. জেসমিনের তুলনায় জেস্টের সুবিধাগুলো কী কী?", qEn: "100. What are the advantages of Jest over Jasmine?", a: "দ্রুত (প্যারালাল টেস্ট)\n\nস্ন্যাপশট টেস্টিং\n\nবিল্ট-ইন মকিং\n\nজিরো কনফিগ (CRA-তে)\n\nউদাহরণ:\n```javascript\nexpect(result).toBe(expected);\n```", aEn: "There are couple of advantages compared to Jasmine:\n\n - Automatically finds tests to execute in your source code.\n - Automatically mocks dependencies when running your tests.\n - Allows you to test asynchronous code synchronously.\n - Runs your tests with a fake DOM implementation (via `jsdom`) so that your tests can be run on the command line.\n - Runs tests in parallel processes so that they finish sooner." },
  { q: "১০১. জেস্ট টেস্ট কেসের একটি সহজ উদাহরণ দিন?", qEn: "101. Give a simple example of Jest test case", a: "উদাহরণ:\n\n```javascript\ntest('adds 1 + 2 to equal 3', () => {\n  expect(1 + 2).toBe(3);\n});\n```", aEn: "Let's write a test for a function that adds two numbers in `sum.js` file:\n\n     \n```javascript\n     const sum = (a, b) => a + b;\n\n     export default sum;\n```\n\n Create a file named `sum.test.js` which contains actual test:\n\n     \n```javascript\n     import sum from \"./sum\";\n\n     test(\"adds 1 + 2 to equal 3\", () => {\n       expect(sum(1, 2)).toBe(3);\n     });\n```\n\n And then add the following section to your `package.json`:\n\n     \n```json\n     {\n       \"scripts\": {\n         \"test\": \"jest\"\n       }\n     }\n```\n\n Finally, run `yarn test` or `npm test` and Jest will print a result:\n\n     \n```console\n     $ yarn test\n     PASS ./sum.test.js\n     ✓ adds 1 + 2 to equal 3 (2ms)\n```\n\nReact Redux" },
  { q: "১০২. ফ্লাক্স কী?", qEn: "102. What is flux?", a: "ফেসবুকের তৈরি অ্যাপ্লিকেশন আর্কিটেকচার প্যাটার্ন। একমুখী ডেটা প্রবাহ: Action → Dispatcher → Store → View।\n\nউদাহরণ:\nAction → Dispatcher → Store → View (one-way)", aEn: "Flux is an application architecture (not a framework or library) designed by Facebook to manage data flow in React applications. It was created as an alternative to the traditional MVC (Model-View-Controller) pattern, and it emphasizes a unidirectional data flow to make state changes more predictable and easier to debug.\n\n Flux complements React by organizing the way data moves through your application, especially in large-scale or complex projects.\n\n #### Core Concepts of Flux\n\n Flux operates using four key components, each with a specific responsibility:\n  Actions\n  Plain JavaScript objects or functions that describe _what happened_ (e.g., user interactions or API responses).\n  Example: `{ type: 'ADD_TODO', payload: 'Buy milk' }`\n  Dispatcher\n  A central hub that receives actions and dispatches them to the appropriate stores.\n  There is only one dispatcher in a Flux application.\n  Stores\n  Hold the application state and business logic.\n  Respond to actions from the dispatcher and update themselves accordingly.\n  They emit change events that views can listen to.\n  Views (React Components)\n  Subscribe to stores and re-render when the data changes.\n  They can also trigger new actions (e.g., on user input).\n\n The workflow between dispatcher, stores and views components with distinct inputs and outputs as follows:\n\n !flux" },
  { q: "১০৩. রিডাক্স কী?", qEn: "103. What is Redux?", a: "জাভাস্ক্রিপ্ট অ্যাপের জন্য প্রেডিক্টেবল স্টেট কন্টেইনার। ফ্লাক্স দ্বারা অনুপ্রাণিত।\n\nউদাহরণ:\n```javascript\nconst store = createStore(reducer);\nstore.dispatch({ type: 'INCREMENT' });\n```", aEn: "Redux is a predictable state container for JavaScript applications, most commonly used with React. It helps you manage and centralize your application’s state in a single source of truth, enabling easier debugging, testing, and maintenance—especially in large or complex applications. Redux core is tiny library(about 2.5kB gzipped) and has no dependencies." },
  { q: "১০৪. রিডাক্সের মূল নীতিগুলো কী কী?", qEn: "104. What are the core principles of Redux?", a: "একক সোর্স অফ ট্রুথ (একটি স্টোর)\n\nস্টেট ইমিউটেবল (শুধু অ্যাকশনের মাধ্যমে পরিবর্তন)\n\nরিডিউসার বিশুদ্ধ ফাংশন\n\nউদাহরণ:\n```javascript\ndispatch({ type: 'ACTION', payload: data });\n```", aEn: "Redux follows three fundamental principles:\n\n 1. Single source of truth: The state of your whole application is stored in an object tree within a single store. The single state tree makes it easier to keep track of changes over time and debug or inspect the application.\n \n      \n```javascript\n      const store = createStore(reducer);\n```\n 2. State is read-only: The only way to change the state is to emit an action, an object describing what happened. This ensures that neither the views nor the network callbacks will ever write directly to the state.\n      \n```javascript\n      const action = { type: 'INCREMENT' };\n      store.dispatch(action);\n```\n 3. Changes are made with pure functions(Reducers): To specify how the state tree is transformed by actions, you write reducers. Reducers are just pure functions that take the previous state and an action as parameters, and return the next state.\n \n      \n```javascript\n      function counter(state = 0, action) {\n        switch (action.type) {\n          case 'INCREMENT':\n            return state + 1;\n          case 'DECREMENT':\n            return state - 1;\n          default:\n            return state;\n        }\n      }\n```" },
  { q: "১০৫. ফ্লাক্সের তুলনায় রিডাক্সের অসুবিধাগুলো কী কী?", qEn: "105. What are the downsides of Redux compared to Flux?", a: "বয়লারপ্লেট কোড বেশি\n\nছোট অ্যাপের জন্য ওভারকিল\n\nঅ্যাসিঙ্ক্রোনাস অ্যাকশন ম্যানেজ করতে মিডলওয়্যার দরকার\n\nউদাহরণ:\n```javascript\ndispatch({ type: 'ACTION', payload: data });\n```", aEn: "While Redux offers a powerful and predictable state management solution, it comes with a few trade-offs when compared to Flux. These include:\n\n 1. Immutability is essential \n Redux enforces a strict immutability model for state updates, which differs from Flux’s more relaxed approach. This means you must avoid mutating state directly. Many Redux-related libraries assume immutability, so your team must be disciplined in writing pure update logic. You can use tools like `redux-immutable-state-invariant`, `Immer`, or `Immutable.js` to help enforce this practice, especially during development.\n 2. Careful selection of complementary packages \n Redux is more minimal by design and provides extension points such as middleware and store enhancers. This has led to a large ecosystem, but it also means you must thoughtfully choose and configure additional packages for features like undo/redo, persistence, or form handling—something Flux explicitly leaves out but may be simpler to manage in smaller setups.\n 3. Limited static type integration \n While Flux has mature support for static type checking with tools like Flow, Redux’s type integration is less seamless. Although TypeScript is commonly used with Redux now, early Flow support was limited, and more boilerplate was required for static type safety. This may affect teams that rely heavily on type systems for large codebases." },
  { q: "১০৬. mapStateToProps ও mapDispatchToProps-এর মধ্যে পার্থক্য কী?", qEn: "106. What is the difference between `mapStateToProps()` and `mapDispatchToProps()`?", a: "| mapStateToProps | mapDispatchToProps |\n| স্টেট থেকে প্রপস বানায় | ডিস্প্যাচ ফাংশন প্রপস বানায় |\n| স্টোর সাবস্ক্রাইব করে | অ্যাকশন ডিস্প্যাচ করে |\n\nউদাহরণ:\n```javascript\n// Redux flow: dispatch → reducer → new state\n```", aEn: "`mapStateToProps()` is a utility which helps your component get updated state (which is updated by some other components):\n\n     \n```javascript\n     const mapStateToProps = (state) => {\n       return {\n         todos: getVisibleTodos(state.todos, state.visibilityFilter),\n       };\n     };\n```\n\n `mapDispatchToProps()` is a utility which will help your component to fire an action event (dispatching action which may cause change of application state):\n\n     \n```javascript\n     const mapDispatchToProps = (dispatch) => {\n       return {\n         onTodoClick: (id) => {\n           dispatch(toggleTodo(id));\n         },\n       };\n     };\n```\n\n It is recommended to always use the “object shorthand” form for the `mapDispatchToProps`.\n\n Redux wraps it in another function that looks like (…args) => dispatch(onTodoClick(…args)), and pass that wrapper function as a prop to your component.\n\n     \n```javascript\n     const mapDispatchToProps = {\n       onTodoClick,\n     };\n```" },
  { q: "১০৭. রিডিউসারে কি অ্যাকশন ডিস্প্যাচ করতে পারেন?", qEn: "107. Can I dispatch an action in reducer?", a: "না। এটি বিশুদ্ধ ফাংশন হওয়া উচিত। ডিস্প্যাচ করলে পার্শ্বপ্রতিক্রিয়া হয়।\n\nউদাহরণ:\n```javascript\n// Redux flow: dispatch → reducer → new state\n```", aEn: "Dispatching an action within a reducer is an anti-pattern. Your reducer should be _without side effects_, simply digesting the action payload and returning a new state object. Adding listeners and dispatching actions within the reducer can lead to chained actions and other side effects." },
  { q: "১০৮. কম্পোনেন্টের বাইরে কীভাবে রিডাক্স স্টোর অ্যাক্সেস করবেন?", qEn: "108. How to access Redux store outside a component?", a: "স্টোর ফাইল থেকে store এক্সপোর্ট করে store.getState(), store.dispatch() ব্যবহার করুন।\n\nউদাহরণ:\n```javascript\ndispatch({ type: 'ACTION', payload: data });\n```", aEn: "You just need to export the store from the module where it created with `createStore()`. Also, it shouldn't pollute the global window object.\n\n     \n```javascript\n     store = createStore(myReducer);\n\n     export default store;\n```" },
  { q: "১০৯. MVW প্যাটার্নের অসুবিধাগুলো কী কী?", qEn: "109. What are the drawbacks of MVW pattern?", a: "দ্বিমুখী ডেটা বাইন্ডিং বড় অ্যাপ্লিকেশনে ডিবাগ কঠিন করে তোলে। রিডাক্স এটি সমাধান করে।\n\nউদাহরণ:\n```javascript\ndispatch({ type: 'ACTION', payload: data });\n```", aEn: "1. DOM manipulation is very expensive which causes applications to behave slow and inefficient.\n 2. Due to circular dependencies, a complicated model was created around models and views.\n 3. Lot of data changes happens for collaborative applications(like Google Docs).\n 4. No way to do undo (travel back in time) easily without adding so much extra code." },
  { q: "১১০. রিডাক্স ও RxJS-এর মধ্যে কি কোনো মিল আছে?", qEn: "110. Are there any similarities between Redux and RxJS?", a: "না। রিডাক্স স্টেট ম্যানেজমেন্ট, RxJS রিঅ্যাকটিভ প্রোগ্রামিং (অ্যাসিঙ্ক ডেটা স্ট্রিম)।\n\nউদাহরণ:\n```javascript\ndispatch({ type: 'ACTION', payload: data });\n```", aEn: "These libraries are very different for very different purposes, but there are some vague similarities.\n\n Redux is a tool for managing state throughout the application. It is usually used as an architecture for UIs. Think of it as an alternative to (half of) Angular. RxJS is a reactive programming library. It is usually used as a tool to accomplish asynchronous tasks in JavaScript. Think of it as an alternative to Promises. Redux uses the Reactive paradigm because the Store is reactive. The Store observes actions from a distance, and changes itself. RxJS also uses the Reactive paradigm, but instead of being an architecture, it gives you basic building blocks, Observables, to accomplish this pattern." },
  { q: "১১১. রিডাক্সে কীভাবে স্টেট রিসেট করবেন?", qEn: "111. How to reset state in Redux?", a: "রুট রিডিউসারে একটি স্পেশাল অ্যাকশন (যেমন RESET_STATE) হ্যান্ডেল করুন বা replaceReducer ব্যবহার করুন।\n\nউদাহরণ:\n```javascript\ndispatch({ type: 'ACTION', payload: data });\n```", aEn: "You need to write a _root reducer_ in your application which delegate handling the action to the reducer generated by `combineReducers()`.\n\n For example, let us take `rootReducer()` to return the initial state after `USER_LOGOUT` action. As we know, reducers are supposed to return the initial state when they are called with `undefined` as the first argument, no matter the action.\n\n     \n```javascript\n     const appReducer = combineReducers({\n       / your app's top-level reducers /\n     });\n\n     const rootReducer = (state, action) => {\n       if (action.type === \"USER_LOGOUT\") {\n         state = undefined;\n       }\n\n       return appReducer(state, action);\n     };\n```\n\n In case of using `redux-persist`, you may also need to clean your storage. `redux-persist` keeps a copy of your state in a storage engine. First, you need to import the appropriate storage engine and then, to parse the state before setting it to undefined and clean each storage state key.\n\n     \n```javascript\n     const appReducer = combineReducers({\n       / your app's top-level reducers /\n     });\n\n     const rootReducer = (state, action) => {\n       if (action.type === \"USER_LOGOUT\") {\n         Object.keys(state).forEach((key) => {\n           storage.removeItem(`persist:${key}`);\n         });\n\n         state = undefined;\n       }\n\n       return appReducer(state, action);\n     };\n```" },
  { q: "১১২. রিয়্যাক্ট কনটেক্সট ও রিয়্যাক্স রিডাক্সের মধ্যে পার্থক্য কী?", qEn: "112. What is the difference between React context and React Redux?", a: "| কনটেক্সট | রিডাক্স |\n| হালকা, ছোট অ্যাপের জন্য | ভারী, বড় অ্যাপের জন্য |\n| কোনো টাইম ট্রাভেল নেই | ডেভ টুলস আছে |\n| ডিফল্ট রিয়্যাক্ট ফিচার | আলাদা লাইব্রেরি |\n\nউদাহরণ:\n```javascript\ndispatch({ type: 'ACTION', payload: data });\n```", aEn: "You can use Context in your application directly and is going to be great for passing down data to deeply nested components which what it was designed for.\n\n Whereas Redux is much more powerful and provides a large number of features that the Context API doesn't provide. Also, React Redux uses context internally but it doesn't expose this fact in the public API." },
  { q: "১১৩. রিডাক্স স্টেট ফাংশনগুলোকে \"রিডিউসার\" কেন বলা হয়?", qEn: "113. Why are Redux state functions called reducers?", a: "জাভাস্ক্রিপ্টের Array.reduce() পদ্ধতির মতো: পূর্ববর্তী স্টেট + অ্যাকশন → নতুন স্টেট।\n\nউদাহরণ:\n```javascript\ndispatch({ type: 'ACTION', payload: data });\n```", aEn: "Reducers always return the accumulation of the state (based on all previous and current actions). Therefore, they act as a reducer of state. Each time a Redux reducer is called, the state and action are passed as parameters. This state is then reduced (or accumulated) based on the action, and then the next state is returned. You could _reduce_ a collection of actions and an initial state (of the store) on which to perform these actions to get the resulting final state." },
  { q: "১১৪. রিডাক্সে কীভাবে AJAX রিকোয়েস্ট করবেন?", qEn: "114. How to make AJAX request in Redux?", a: "রিডাক্স থাঙ্ক বা রিডাক্স সাগা মিডলওয়্যার ব্যবহার করে। অ্যাকশন ক্রিয়েটরে অ্যাসিঙ্ক কোড লেখেন।\n\nউদাহরণ:\n```javascript\n// thunk\nexport const fetchUser = () => async (dispatch) => {\n  const data = await api.getUser();\n  dispatch({ type: 'SET_USER', payload: data });\n};\n```", aEn: "You can use `redux-thunk` middleware which allows you to define async actions.\n\n Let's take an example of fetching specific account as an AJAX call using _fetch API_:\n\n     \n```javascript\n     export function fetchAccount(id) {\n       return (dispatch) => {\n         dispatch(setLoadingAccountState()); // Show a loading spinner\n         fetch(`/account/${id}`, (response) => {\n           dispatch(doneFetchingAccount()); // Hide loading spinner\n           if (response.status === 200) {\n             dispatch(setAccount(response.json)); // Use a normal function to set the received state\n           } else {\n             dispatch(someError);\n           }\n         });\n       };\n     }\n\n     function setAccount(data) {\n       return { type: \"SET_Account\", data: data };\n     }\n```" },
  { q: "১১৫. সব কম্পোনেন্ট স্টেট কি রিডাক্স স্টোরে রাখা উচিত?", qEn: "115. Should I keep all component's state in Redux store?", a: "না। লোকাল স্টেট (যেমন ফর্ম ইনপুট টগল) রিয়্যাক্ট স্টেটে রাখুন। গ্লোবাল ডেটা (ইউজার, থিম) রিডাক্সে রাখুন।\n\nউদাহরণ:\n```javascript\ndispatch({ type: 'ACTION', payload: data });\n```", aEn: "Keep your data in the Redux store, and the UI related state internally in the component." },
  { q: "১১৬. রিডাক্স স্টোর অ্যাক্সেস করার সঠিক উপায় কী?", qEn: "116. What is the proper way to access Redux store?", a: "<Provider> দিয়ে অ্যাপ র‍্যাপ করুন, তারপর useSelector() হুক বা connect() দিয়ে অ্যাক্সেস করুন।\n\nউদাহরণ:\n```javascript\nconst count = useSelector(s => s.counter.value);\nconst dispatch = useDispatch();\n```", aEn: "The best way to access your store in a component is to use the `connect()` function, that creates a new component that wraps around your existing one. This pattern is called _Higher-Order Components_, and is generally the preferred way of extending a component's functionality in React. This allows you to map state and action creators to your component, and have them passed in automatically as your store updates.\n\n Let's take an example of ` ` component using connect:\n\n     \n```javascript\n     import { connect } from \"react-redux\";\n     import { setVisibilityFilter } from \"../actions\";\n     import Link from \"../components/Link\";\n\n     const mapStateToProps = (state, ownProps) => ({\n       active: ownProps.filter === state.visibilityFilter,\n     });\n\n     const mapDispatchToProps = (dispatch, ownProps) => ({\n       onClick: () => dispatch(setVisibilityFilter(ownProps.filter)),\n     });\n\n     const FilterLink = connect(mapStateToProps, mapDispatchToProps)(Link);\n\n     export default FilterLink;\n```\n\n Due to it having quite a few performance optimizations and generally being less likely to cause bugs, the Redux developers almost always recommend using `connect()` over accessing the store directly (using context API).\n\n     \n```javascript\n     function MyComponent {\n       someMethod() {\n         doSomethingWith(this.context.store);\n       }\n     }\n```" },
  { q: "১১৭. রিয়্যাক্ট রিডাক্সে কম্পোনেন্ট ও কন্টেইনারের মধ্যে পার্থক্য কী?", qEn: "117. What is the difference between component and container in React Redux?", a: "| কম্পোনেন্ট | কন্টেইনার |\n| UI ফোকাসড | লজিক ফোকাসড |\n| রিডাক্স জানে না | রিডাক্সের সাথে সংযুক্ত |\n| প্রপস পায় | স্টোর থেকে ডেটা নেয় |\n\nউদাহরণ:\n```javascript\ndispatch({ type: 'ACTION', payload: data });\n```", aEn: "Component is a class or function component that describes the presentational part of your application.\n\n Container is an informal term for a component that is connected to a Redux store. Containers _subscribe_ to Redux state updates and _dispatch_ actions, and they usually don't render DOM elements; they delegate rendering to presentational child components." },
  { q: "১১৮. রিডাক্সে কনস্ট্যান্টের উদ্দেশ্য কী?", qEn: "118. What is the purpose of the constants in Redux?", a: "অ্যাকশন টাইপের নাম স্ট্রিং হিসেবে এক জায়গায় রাখে। টাইপো এড়ায় এবং অটোকমপ্লিট সুবিধা দেয়।\n\nউদাহরণ:\n```javascript\ndispatch({ type: 'ACTION', payload: data });\n```", aEn: "Constants allows you to easily find all usages of that specific functionality across the project when you use an IDE. It also prevents you from introducing silly bugs caused by typos – in which case, you will get a `ReferenceError` immediately.\n\n Normally we will save them in a single file (`constants.js` or `actionTypes.js`).\n\n     \n```javascript\n     export const ADD_TODO = \"ADD_TODO\";\n     export const DELETE_TODO = \"DELETE_TODO\";\n     export const EDIT_TODO = \"EDIT_TODO\";\n     export const COMPLETE_TODO = \"COMPLETE_TODO\";\n     export const COMPLETE_ALL = \"COMPLETE_ALL\";\n     export const CLEAR_COMPLETED = \"CLEAR_COMPLETED\";\n```\n\n In Redux, you use them in two places:\n\n 1. During action creation:\n\n Let's take `actions.js`:\n\n        \n```javascript\n        import { ADD_TODO } from \"./actionTypes\";\n\n        export function addTodo(text) {\n          return { type: ADD_TODO, text };\n        }\n```\n\n 2. In reducers:\n\n Let's create `reducer.js`:\n\n        \n```javascript\n        import { ADD_TODO } from \"./actionTypes\";\n\n        export default (state = [], action) => {\n          switch (action.type) {\n            case ADD_TODO:\n              return [\n                ...state,\n                {\n                  text: action.text,\n                  completed: false,\n                },\n              ];\n            default:\n              return state;\n          }\n        };\n```" },
  { q: "১১৯. mapDispatchToProps লেখার বিভিন্ন উপায় কী কী?", qEn: "119. What are the different ways to write `mapDispatchToProps()`?", a: "অবজেক্ট ফর্ম: { addTodo }\n\nফাংশন ফর্ম: (dispatch) => ({ addTodo: () => dispatch(addTodo()) })\n\nউদাহরণ:\n```javascript\nফাংশন ফর্ম: (dispatch) => ({ addTodo: () => dispatch(addTodo()) })\n```", aEn: "There are a few ways of binding _action creators_ to `dispatch()` in `mapDispatchToProps()`.\n\n Below are the possible options:\n\n     \n```javascript\n     const mapDispatchToProps = (dispatch) => ({\n       action: () => dispatch(action()),\n     });\n```\n\n     \n```javascript\n     const mapDispatchToProps = (dispatch) => ({\n       action: bindActionCreators(action, dispatch),\n     });\n```\n\n     \n```javascript\n     const mapDispatchToProps = { action };\n```\n\n The third option is just a shorthand for the first one." },
  { q: "১২০. mapStateToProps ও mapDispatchToProps-এ ownProps প্যারামিটারের ব্যবহার কী?", qEn: "120. What is the use of the `ownProps` parameter in `mapStateToProps()` and `mapDispatchToProps()`?", a: "কম্পোনেন্টের নিজের প্রপস অ্যাক্সেস করতে। যেমন, একটি আইডি প্রপস থেকে নিয়ে স্টেট ফিল্টার করা।\n\nউদাহরণ:\n```javascript\n// Redux flow: dispatch → reducer → new state\n```", aEn: "If the `ownProps` parameter is specified, React Redux will pass the props that were passed to the component into your _connect_ functions. So, if you use a connected component:\n\n     ```jsx harmony\n     import ConnectedComponent from \"./containers/ConnectedComponent\";\n\n     <ConnectedComponent user={\"john\"} />;\n     \n```javascript\n\n The `ownProps` inside your `mapStateToProps()` and `mapDispatchToProps()` functions will be an object:\n```javascript\n     {\n       user: \"john\";\n     }\n     ```\n\n You can use this object to decide what to return from those functions." },
  { q: "১২১. রিডাক্স টপ-লেভেল ডিরেক্টরি কীভাবে স্ট্রাকচার করবেন?", qEn: "121. How to structure Redux top level directories?", a: "actions/\n\nreducers/\n\nstore/\n\nconstants/\n\nselectors/\n\nউদাহরণ:\n```javascript\ndispatch({ type: 'ACTION', payload: data });\n```", aEn: "Most of the applications has several top-level directories as below:\n\n 1. Components: Used for _dumb_ components unaware of Redux.\n 2. Containers: Used for _smart_ components connected to Redux.\n 3. Actions: Used for all action creators, where file names correspond to part of the app.\n 4. Reducers: Used for all reducers, where files name correspond to state key.\n 5. Store: Used for store initialization.\n\n This structure works well for small and medium size apps." },
  { q: "১২২. রিডাক্স সাগা কী?", qEn: "122. What is redux-saga?", a: "রিডাক্সের জন্য মিডলওয়্যার যা সাইড ইফেক্ট (API কল) জেনারেটর ফাংশন দিয়ে ম্যানেজ করে।\n\nউদাহরণ:\n```javascript\nuseEffect(() => {\n  // side effect\n  return () => cleanup();\n}, [deps]);\n```", aEn: "`redux-saga` is a library that aims to make side effects (asynchronous things like data fetching and impure things like accessing the browser cache) in React/Redux applications easier and better.\n\n It is available in NPM:\n\n     \n```console\n     $ npm install --save redux-saga\n```" },
  { q: "১২৩. রিডাক্স সাগার মানসিক মডেল কী?", qEn: "123. What is the mental model of redux-saga?", a: "একটি আলাদা থ্রেড (সাগা) যা অ্যাকশন দেখে, অ্যাসিঙ্ক কাজ করে এবং নতুন অ্যাকশন ডিস্প্যাচ করে।\n\nউদাহরণ:\n```javascript\ndispatch({ type: 'ACTION', payload: data });\n```", aEn: "_Saga_ is like a separate thread in your application, that's solely responsible for side effects. `redux-saga` is a redux _middleware_, which means this thread can be started, paused and cancelled from the main application with normal Redux actions, it has access to the full Redux application state and it can dispatch Redux actions as well." },
  { q: "১২৪. রিডাক্স সাগায় call ও put-এর মধ্যে পার্থক্য কী?", qEn: "124. What are the differences between `call()` and `put()` in redux-saga?", a: "call: ফাংশন কল করে (প্রোমিস রিটার্ন করে)\n\nput: একটি অ্যাকশন ডিস্প্যাচ করে\n\nউদাহরণ:\n```javascript\ndispatch({ type: 'ACTION', payload: data });\n```", aEn: "Both `call()` and `put()` are effect creator functions. `call()` function is used to create effect description, which instructs middleware to call the promise. `put()` function creates an effect, which instructs middleware to dispatch an action to the store.\n\n Let's take example of how these effects work for fetching particular user data.\n\n     \n```javascript\n     function fetchUserSaga(action) {\n       // `call` function accepts rest arguments, which will be passed to `api.fetchUser` function.\n       // Instructing middleware to call promise, it resolved value will be assigned to `userData` variable\n       const userData = yield call(api.fetchUser, action.userId);\n\n       // Instructing middleware to dispatch corresponding action.\n       yield put({\n         type: \"FETCH_USER_SUCCESS\",\n         userData,\n       });\n     }\n```" },
  { q: "১২৫. রিডাক্স থাঙ্ক কী?", qEn: "125. What is Redux Thunk?", a: "রিডাক্সের মিডলওয়্যার যা অ্যাকশন ক্রিয়েটরকে ফাংশন রিটার্ন করতে দেয় (অ্যাসিঙ্ক অপারেশনের জন্য)।\n\nউদাহরণ:\n```javascript\nconst thunk = () => (dispatch) => {\n  dispatch({ type: 'LOADING' });\n};\n```", aEn: "_Redux Thunk_ middleware allows you to write action creators that return a function instead of an action. The thunk can be used to delay the dispatch of an action, or to dispatch only if a certain condition is met. The inner function receives the store methods `dispatch()` and `getState()` as parameters." },
  { q: "১২৬. রিডাক্স সাগা ও রিডাক্স থাঙ্কের মধ্যে পার্থক্য কী?", qEn: "126. What are the differences between `redux-saga` and `redux-thunk`?", a: "| থাঙ্ক | সাগা |\n| সহজ, ছোট প্রকল্প | জটিল, বড় প্রকল্প |\n| প্রমিসベース | জেনারেটরベース |\n| টেস্ট করা কঠিন | টেস্ট করা সহজ |\n\nউদাহরণ:\n```javascript\ndispatch({ type: 'ACTION', payload: data });\n```", aEn: "Both _Redux Thunk_ and _Redux Saga_ take care of dealing with side effects. In most of the scenarios, Thunk uses _Promises_ to deal with them, whereas Saga uses _Generators_. Thunk is simple to use and Promises are familiar to many developers, Sagas/Generators are more powerful but you will need to learn them. But both middleware can coexist, so you can start with Thunks and introduce Sagas when/if you need them." },
  { q: "১২৭. রিডাক্স ডেভটুলস কী?", qEn: "127. What is Redux DevTools?", a: "ব্রাউজার এক্সটেনশন যা রিডাক্স স্টোরের প্রতিটি অ্যাকশন ও স্টেট পরিবর্তন দেখায়।\n\nউদাহরণ:\nRedux DevTools extension → time-travel, action log।", aEn: "_Redux DevTools_ is a live-editing time travel environment for Redux with hot reloading, action replay, and customizable UI. If you don't want to bother with installing Redux DevTools and integrating it into your project, consider using Redux DevTools Extension for Chrome and Firefox." },
  { q: "১২৮. রিডাক্স ডেভটুলসের বৈশিষ্ট্যগুলো কী কী?", qEn: "128. What are the features of Redux DevTools?", a: "টাইম ট্রাভেল ডিবাগিং\n\nঅ্যাকশন ইনস্পেক্টর\n\nস্টেট ডিফ\n\nএক্সপোর্ট/ইম্পোর্ট\n\nউদাহরণ:\n```javascript\ndispatch({ type: 'ACTION', payload: data });\n```", aEn: "Some of the main features of Redux DevTools are below,\n\n 1. Lets you inspect every state and action payload.\n 2. Lets you go back in time by _cancelling_ actions.\n 3. If you change the reducer code, each _staged_ action will be re-evaluated.\n 4. If the reducers throw, you will see during which action this happened, and what the error was.\n 5. With `persistState()` store enhancer, you can persist debug sessions across page reloads." },
  { q: "১২৯. রিডাক্স সিলেক্টর কী এবং কেন ব্যবহার করবেন?", qEn: "129. What are Redux selectors and why use them?", a: "সিলেক্টর হল ফাংশন যা স্টোর থেকে নির্দিষ্ট অংশের ডেটা বের করে এবং দরকার হলে ট্রান্সফর্ম করে। রি-কম্পিউটেশন এড়ায়।\n\nউদাহরণ:\n```javascript\ndispatch({ type: 'ACTION', payload: data });\n```", aEn: "_Selectors_ are functions that take Redux state as an argument and return some data to pass to the component.\n\n For example, to get user details from the state:\n\n     \n```javascript\n     const getUserData = (state) => state.user.data;\n```\n\n These selectors have two main benefits,\n\n 1. The selector can compute derived data, allowing Redux to store the minimal possible state\n 2. The selector is not recomputed unless one of its arguments changes" },
  { q: "১৩০. রিডাক্স ফর্ম কী?", qEn: "130. What is Redux Form?", a: "ফর্ম স্টেট ম্যানেজমেন্টের জন্য রিডাক্সের সাথে সংহত লাইব্রেরি।\n\nউদাহরণ:\n```javascript\ndispatch({ type: 'ACTION', payload: data });\n```", aEn: "_Redux Form_ works with React and Redux to enable a form in React to use Redux to store all of its state. Redux Form can be used with raw HTML5 inputs, but it also works very well with common UI frameworks like Material UI, React Widgets and React Bootstrap." },
  { q: "১৩১. রিডাক্স ফর্মের প্রধান বৈশিষ্ট্যগুলো কী কী?", qEn: "131. What are the main features of Redux Form?", a: "ফর্ম স্টেট অটোমেটিক ট্র্যাকিং\n\nভ্যালিডেশন\n\nসাবমিট হ্যান্ডলিং\n\nডাটা নরমালাইজেশন\n\nউদাহরণ:\n```javascript\ndispatch({ type: 'ACTION', payload: data });\n```", aEn: "Some of the main features of Redux Form are:\n\n 1. Field values persistence via Redux store.\n 2. Validation (sync/async) and submission.\n 3. Formatting, parsing and normalization of field values." },
  { q: "১৩২. রিডাক্সে কীভাবে একাধিক মিডলওয়্যার যোগ করবেন?", qEn: "132. How to add multiple middlewares to Redux?", a: "applyMiddleware(thunk, saga, logger) ব্যবহার করে।\n\nউদাহরণ:\n```javascript\ndispatch({ type: 'ACTION', payload: data });\n```", aEn: "You can use `applyMiddleware()`.\n\n For example, you can add `redux-thunk` and `logger` passing them as arguments to `applyMiddleware()`:\n\n     \n```javascript\n     import { createStore, applyMiddleware } from \"redux\";\n     const createStoreWithMiddleware = applyMiddleware(\n       ReduxThunk,\n       logger\n     )(createStore);\n```" },
  { q: "১৩৩. রিডাক্সে কীভাবে ইনিশিয়াল স্টেট সেট করবেন?", qEn: "133. How to set initial state in Redux?", a: "রিডিউসারে ডিফল্ট প্যারামিটার হিসেবে: const reducer = (state = initialState, action)\n\nউদাহরণ:\n```javascript\ndispatch({ type: 'ACTION', payload: data });\n```", aEn: "You need to pass initial state as second argument to createStore:\n\n     \n```javascript\n     const rootReducer = combineReducers({\n       todos: todos,\n       visibilityFilter: visibilityFilter,\n     });\n\n     const initialState = {\n       todos: [{ id: 123, name: \"example\", completed: false }],\n     };\n\n     const store = createStore(rootReducer, initialState);\n```" },
  { q: "১৩৪. রিলে কীভাবে রিডাক্স থেকে আলাদা?", qEn: "134. How Relay is different from Redux?", a: "| রিলে | রিডাক্স |\n| গ্রাফকিউএল এর জন্য | যেকোনো ডেটার জন্য |\n| ফেসবুকের | ওপেন সোর্স |\n| ডিক্লারেটিভ ডেটা ফেচিং | ইম্পেরেটিভ |\n\nউদাহরণ:\n```javascript\ndispatch({ type: 'ACTION', payload: data });\n```", aEn: "Relay is similar to Redux in that they both use a single store. The main difference is that relay only manages state originated from the server, and all access to the state is used via _GraphQL_ queries (for reading data) and mutations (for changing data). Relay caches the data for you and optimizes data fetching for you, by fetching only changed data and nothing more." },
  { q: "১৩৫. রিডাক্সে অ্যাকশন কী?", qEn: "135. What is an action in Redux?", a: "অ্যাকশন হল একটি প্লেইন জাভাস্ক্রিপ্ট অবজেক্ট যার type প্রপার্টি থাকে। এটি স্টোরে \"কী ঘটেছে\" তা বলে।\n\nউদাহরণ:\n```javascript\ndispatch({ type: 'ACTION', payload: data });\n```", aEn: "_Actions_ are plain JavaScript objects or payloads of information that send data from your application to your store. They are the only source of information for the store. Actions must have a type property that indicates the type of action being performed.\n\n For example, let's take an action which represents adding a new todo item:\n\n     \n```javascript\n     {\n       type: ADD_TODO,\n       text: 'Add todo item'\n     }\n```" },
  { q: "১৩৬. রিয়্যাক্ট নেটিভ ও রিয়্যাক্টের মধ্যে পার্থক্য কী?", qEn: "136. What is the difference between React Native and React?", a: "| রিয়্যাক্ট | রিয়্যাক্ট নেটিভ |\n| ওয়েব অ্যাপ | মোবাইল অ্যাপ (iOS/Android) |\n| DOM এলিমেন্ট (div, span) | নেটিভ কম্পোনেন্ট (View, Text) |\n| CSS | স্টাইলশিট অবজেক্ট |\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "React is a JavaScript library, supporting both front end web and being run on the server, for building user interfaces and web applications.\n\n React Native is a mobile framework that compiles to native app components, allowing you to build native mobile applications (iOS, Android, and Windows) in JavaScript that allows you to use React to build your components, and implements React under the hood." },
  { q: "১৩৭. কীভাবে রিয়্যাক্ট নেটিভ অ্যাপ টেস্ট করবেন?", qEn: "137. How to test React Native apps?", a: "Jest (ইউনিট টেস্ট)\n\nReact Native Testing Library\n\nDetox (E2E টেস্ট)\n\nউদাহরণ:\n```javascript\nexpect(result).toBe(expected);\n```", aEn: "React Native can be tested only in mobile simulators like iOS and Android. You can run the app in your mobile using expo app (https://expo.io) Where it syncs using QR code, your mobile and computer should be in same wireless network." },
  { q: "১৩৮. রিয়্যাক্ট নেটিভে কীভাবে লগ করবেন?", qEn: "138. How to do logging in React Native?", a: "console.log() কাজ করে। অ্যান্ড্রয়েডে adb logcat, iOS-এ npx react-native log-ios দিয়ে দেখুন।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "You can use `console.log`, `console.warn`, etc. As of React Native v0.29 you can simply run the following to see logs in the console:\n\n     \n```javascript\n     $ react-native log-ios\n     $ react-native log-android\n```" },
  { q: "১৩৯. কীভাবে রিয়্যাক্ট নেটিভ অ্যাপ ডিবাগ করবেন?", qEn: "139. How to debug your React Native?", a: "রিমোট ডিবাগিং (Chrome DevTools)\n\nReact Native Debugger (Electron অ্যাপ)\n\nFlipper (মেটার অফিসিয়াল টুল)\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "Follow the below steps to debug React Native app:\n\n 1. Run your application in the iOS simulator.\n 2. Press `Command + D` and a webpage should open up at `http://localhost:8081/debugger-ui`.\n 3. Enable _Pause On Caught Exceptions_ for a better debugging experience.\n 4. Press `Command + Option + I` to open the Chrome Developer tools, or open it via `View` -> `Developer` -> `Developer Tools`.\n 5. You should now be able to debug as you normally would.\n\nReact supported libraries & Integration" },
  { q: "১৪০. রিসিলেক্ট কী এবং এটি কীভাবে কাজ করে?", qEn: "140. What is reselect and how it works?", a: "রিডাক্সের জন্য মেমোয়াজড সিলেক্টর লাইব্রেরি। এটি createSelector দিয়ে সিলেক্টর তৈরি করে যা ইনপুট পরিবর্তন না হলে পূর্বের ফলাফল রিটার্ন করে।\n\nউদাহরণ:\n```javascript\ndispatch({ type: 'ACTION', payload: data });\n```", aEn: "_Reselect_ is a selector library (for Redux) which uses _memoization_ concept. It was originally written to compute derived data from Redux-like applications state, but it can't be tied to any architecture or library.\n\n Reselect keeps a copy of the last inputs/outputs of the last call, and recomputes the result only if one of the inputs changes. If the same inputs are provided twice in a row, Reselect returns the cached output. It's memoization and cache are fully customizable." },
  { q: "১৪১. ফ্লো কী?", qEn: "141. What is Flow?", a: "ফেসবুকের তৈরি স্ট্যাটিক টাইপ চেকার যা জাভাস্ক্রিপ্টের জন্য।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "_Flow_ is a _static type checker_ designed to find type errors in JavaScript. Flow types can express much more fine-grained distinctions than traditional type systems. For example, Flow helps you catch errors involving `null`, unlike most type systems." },
  { q: "১৪২. ফ্লো ও প্রপটাইপসের মধ্যে পার্থক্য কী?", qEn: "142. What is the difference between Flow and PropTypes?", a: "| ফ্লো | প্রপটাইপস |\n| স্ট্যাটিক টাইপ চেকিং (ডেভেলপমেন্ট সময়) | রানটাইম টাইপ চেকিং |\n| সমগ্র কোডবেসের জন্য | শুধু প্রপসের জন্য |\n\nউদাহরণ:\n```javascript\nname: PropTypes.string.isRequired\n```", aEn: "Flow is a _static analysis tool_ (static checker) which uses a superset of the language, allowing you to add type annotations to all of your code and catch an entire class of bugs at compile time.\n\n PropTypes is a _basic type checker_ (runtime checker) which has been patched onto React. It can't check anything other than the types of the props being passed to a given component. If you want more flexible typechecking for your entire project Flow/TypeScript are appropriate choices." },
  { q: "১৪৩. রিয়্যাক্টে কীভাবে ফন্ট অ্যাওসাম আইকন ব্যবহার করবেন?", qEn: "143. How to use Font Awesome icons in React?", a: "@fortawesome/react-fontawesome প্যাকেজ ব্যবহার করে।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "The below steps followed to include Font Awesome in React:\n\n 1. Install `font-awesome`:\n\n        \n```console\n        $ npm install --save font-awesome\n```\n\n 2. Import `font-awesome` in your `index.js` file:\n\n        \n```javascript\n        import \"font-awesome/css/font-awesome.min.css\";\n```\n\n 3. Add Font Awesome classes in `className`:\n\n        \n```javascript\n        function MyComponent {\n          return <div><i className={'fa fa-spinner'} /></div>\n        }\n```" },
  { q: "১৪৪. রিয়্যাক্ট ডেভটুলস কী?", qEn: "144. What is React Dev Tools?", a: "ব্রাউজার এক্সটেনশন যা রিয়্যাক্ট কম্পোনেন্ট ট্রি, প্রপস, স্টেট দেখতে দেয়।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "_React Developer Tools_ let you inspect the component hierarchy, including component props and state. It exists both as a browser extension (for Chrome and Firefox), and as a standalone app (works with other environments including Safari, IE, and React Native).\n\n The official extensions available for different browsers or environments.\n\n 1. Chrome extension\n 2. Firefox extension\n 3. Standalone app (Safari, React Native, etc)" },
  { q: "১৪৫. ক্রোমে লোকাল ফাইলের জন্য ডেভটুলস কেন লোড হয় না?", qEn: "145. Why is DevTools not loading in Chrome for local files?", a: "ব্রাউজার সিকিউরিটি কারণে file:// প্রোটোকলে এক্সটেনশন কাজ করে না। HTTP সার্ভার (যেমন http-server) ব্যবহার করুন।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "If you opened a local HTML file in your browser (`file://...`) then you must first open _Chrome Extensions_ and check `Allow access to file URLs`." },
  { q: "১৪৬. রিয়্যাক্টে পলিমার কীভাবে ব্যবহার করবেন?", qEn: "146. How to use Polymer in React?", a: "পলিমার এলিমেন্ট কাস্টম এলিমেন্ট; রিয়্যাক্টে ref দিয়ে অ্যাক্সেস করুন।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "You need to follow below steps to use Polymer in React,\n\n 1. Create a Polymer element:\n\n        ```jsx harmony\n        <link\n          rel=\"import\"\n          href=\"../../bower_components/polymer/polymer.html\"\n        />;\n        Polymer({\n          is: \"calendar-element\",\n          ready: function () {\n            this.textContent = \"I am a calendar\";\n          },\n        });\n        \n```javascript\n\n 2. Create the Polymer component HTML tag by importing it in a HTML document, e.g. import it in the `index.html` of your React application:\n```html\n        <link\n          rel=\"import\"\n          href=\"./src/polymer-components/calendar-element.html\"\n        />\n        \n```javascript\n\n 3. Use that element in the JSX file:\n```javascript\n        export default function MyComponent {\n          return <calendar-element />;\n        }\n        ```" },
  { q: "১৪৭. ভিউজেএস-এর তুলনায় রিয়্যাক্টের সুবিধাগুলো কী কী?", qEn: "147. What are the advantages of React over Vue.js?", a: "বড় কমিউনিটি ও ইকোসিস্টেম\n\nকর্পোরেট ব্যাকিং (ফেসবুক)\n\nআরও ফ্লেক্সিবল (শুধু ভিউ)\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "React has the following advantages over Vue.js:\n\n 1. Gives more flexibility in large apps developing.\n 2. Easier to test.\n 3. Suitable for mobile apps creating.\n 4. More information and solutions available.\n\nNote: The above list of advantages are purely opinionated and it vary based on the professional experience. But they are helpful as base parameters." },
  { q: "১৪৮. রিয়্যাক্ট ও অ্যাঙ্গুলারের মধ্যে পার্থক্য কী?", qEn: "148. What is the difference between React and Angular?", a: "| রিয়্যাক্ট | অ্যাঙ্গুলার |\n| লাইব্রেরি | পূর্ণ ফ্রেমওয়ার্ক |\n| ভার্চুয়াল DOM | রিয়েল DOM |\n| JSX | টাইপস্ক্রিপ্ট + HTML টেমপ্লেট |\n| ওয়ান-ওয়ে ডেটা বাইন্ডিং | টু-ওয়ে ডেটা বাইন্ডিং |\n\nউদাহরণ:\n```javascript\nconst el = <div className=\"box\">Hi</div>;\n```", aEn: "Let's see the difference between React and Angular in a table format.\n\n | React | Angular |\n | ------------------------------------------------------------------------------------------- | ---------------------------------------------------------------------------------------------------------------------------------- |\n | React is a library and has only the View layer | Angular is a framework and has complete MVC functionality |\n | React handles rendering on the server side | AngularJS renders only on the client side but Angular 2 and above renders on the server side |\n | React uses JSX that looks like HTML in JS which can be confusing | Angular follows the template approach for HTML, which makes code shorter and easy to understand |\n | React Native, which is a React type to build mobile applications are faster and more stable | Ionic, Angular's mobile native app is relatively less stable and slower |\n | In React, data flows only in one way and hence debugging is easy | In Angular, data flows both way i.e it has two-way data binding between children and parent and hence debugging is often difficult |\n\nNote: The above list of differences are purely opinionated and it vary based on the professional experience. But they are helpful as base parameters." },
  { q: "১৪৯. ডেভটুলসে রিয়্যাক্ট ট্যাব কেন দেখা যাচ্ছে না?", qEn: "149. Why React tab is not showing up in DevTools?", a: "ওয়েবসাইটটি প্রোডাকশন বিল্ড ব্যবহার করছে। ডেভটুলস শুধু ডেভেলপমেন্ট বিল্ডে কাজ করে।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "When the page loads, _React DevTools_ sets a global named `__REACT_DEVTOOLS_GLOBAL_HOOK__`, then React communicates with that hook during initialization. If the website is not using React or if React fails to communicate with DevTools then it won't show up the tab." },
  { q: "১৫০. স্টাইলড-কম্পোনেন্ট কী?", qEn: "150. What are Styled Components?", a: "CSS-in-JS লাইব্রেরি যা কম্পোনেন্টের সাথে স্টাইল এনক্যাপসুলেট করে।\n\nউদাহরণ:\n```javascript\nconst Btn = styled.button`padding: 8px;`;\n```", aEn: "`styled-components` is a JavaScript library for styling React applications. It removes the mapping between styles and components, and lets you write actual CSS augmented with JavaScript." },
  { q: "১৫১. স্টাইলড-কম্পোনেন্টের উদাহরণ দিন?", qEn: "151. Give an example of Styled Components?", a: "উদাহরণ:\n\n```javascript\nconst Button = styled.button`\n  background: blue;\n  color: white;\n`;\n```", aEn: "Lets create ` ` and ` ` components with specific styles for each.\n\n     \n```javascript\n     import React from \"react\";\n     import styled from \"styled-components\";\n\n     // Create a <Title> component that renders an <h1> which is centered, red and sized at 1.5em\n     const Title = styled.h1`\n       font-size: 1.5em;\n       text-align: center;\n       color: palevioletred;\n     `;\n\n     // Create a <Wrapper> component that renders a <section> with some padding and a papayawhip background\n     const Wrapper = styled.section`\n       padding: 4em;\n       background: papayawhip;\n     `;\n```\n\n These two variables, `Title` and `Wrapper`, are now components that you can render just like any other react component.\n\n     ```jsx harmony\n     <Wrapper>\n       <Title>{\"Lets start first styled component!\"}</Title>\n     </Wrapper>\n     ```" },
  { q: "১৫২. রিলে কী?", qEn: "152. What is Relay?", a: "ফেসবুকের গ্রাফকিউএল ক্লায়েন্ট যা রিয়্যাক্টের সাথে ডেটা ফেচিং ইন্টিগ্রেট করে।\n\nউদাহরণ:\n```graphql\nquery AppQuery { viewer { name } }\n```", aEn: "Relay is a JavaScript framework for providing a data layer and client-server communication to web applications using the React view layer." },
  { q: "১৫৩. রিসিলেক্ট লাইব্রেরির প্রধান বৈশিষ্ট্যগুলো কী কী?", qEn: "153. What are the main features of Reselect library?", a: "মেমোাইজেশন\n\nকম্পোজেবল সিলেক্টর\n\nরি-রেন্ডার কমায়\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "Let's see the main features of Reselect library,\n\n 1. Selectors can compute derived data, allowing Redux to store the minimal possible state.\n 2. Selectors are efficient. A selector is not recomputed unless one of its arguments changes.\n 3. Selectors are composable. They can be used as input to other selectors." },
  { q: "১৫৪. রিসিলেক্ট ব্যবহারের একটি উদাহরণ দিন?", qEn: "154. Give an example of Reselect usage?", a: "উদাহরণ:\n\n```javascript\nconst getVisibleTodos = createSelector(\n  [getTodos, getFilter],\n  (todos, filter) => todos.filter(t => t.status === filter)\n);\n```", aEn: "Let's take calculations and different amounts of a shipment order with the simplified usage of Reselect:\n\n     \n```javascript\n     import { createSelector } from \"reselect\";\n\n     const shopItemsSelector = (state) => state.shop.items;\n     const taxPercentSelector = (state) => state.shop.taxPercent;\n\n     const subtotalSelector = createSelector(shopItemsSelector, (items) =>\n       items.reduce((acc, item) => acc + item.value, 0)\n     );\n\n     const taxSelector = createSelector(\n       subtotalSelector,\n       taxPercentSelector,\n       (subtotal, taxPercent) => subtotal  (taxPercent / 100)\n     );\n\n     export const totalSelector = createSelector(\n       subtotalSelector,\n       taxSelector,\n       (subtotal, tax) => ({ total: subtotal + tax })\n     );\n\n     let exampleState = {\n       shop: {\n         taxPercent: 8,\n         items: [\n           { name: \"apple\", value: 1.2 },\n           { name: \"orange\", value: 0.95 },\n         ],\n       },\n     };\n\n     console.log(subtotalSelector(exampleState)); // 2.15\n     console.log(taxSelector(exampleState)); // 0.172\n     console.log(totalSelector(exampleState)); // { total: 2.322 }\n```" },
  { q: "১৫৫. রিডাক্স কি শুধু রিয়্যাক্টের সাথে ব্যবহার করা যায়?", qEn: "155. Can Redux only be used with React?", a: "না। এটি যেকোনো জাভাস্ক্রিপ্ট ফ্রেমওয়ার্কের সাথে (Angular, Vue, Vanilla JS) ব্যবহার করা যায়।\n\nউদাহরণ:\n```javascript\ndispatch({ type: 'ACTION', payload: data });\n```", aEn: "Redux can be used as a data store for any UI layer. The most common usage is with React and React Native, but there are bindings available for Angular, Angular 2, Vue, Mithril, and more. Redux simply provides a subscription mechanism which can be used by any other code." },
  { q: "১৫৬. রিডাক্স ব্যবহারের জন্য কী নির্দিষ্ট বিল্ড টুল প্রয়োজন?", qEn: "156. Do you need to have a particular build tool to use Redux?", a: "না। প্লেইন জাভাস্ক্রিপ্টেও ব্যবহার করা যায়।\n\nউদাহরণ:\n```javascript\ndispatch({ type: 'ACTION', payload: data });\n```", aEn: "Redux is originally written in ES6 and transpiled for production into ES5 with Webpack and Babel. You should be able to use it regardless of your JavaScript build process. Redux also offers a UMD build that can be used directly without any build process at all." },
  { q: "১৫৭. রিডাক্স ফর্মের ইনিশিয়াল ভ্যালু কীভাবে স্টেট থেকে আপডেট হয়?", qEn: "157. How Redux Form `initialValues` get updated from state?", a: "initialValues প্রপে ফাংশন পাস করে: initialValues={() => ({ name: store.name })}\n\nউদাহরণ:\n```javascript\ndispatch({ type: 'ACTION', payload: data });\n```", aEn: "You need to add `enableReinitialize : true` setting.\n\n     \n```javascript\n     const InitializeFromStateForm = reduxForm({\n       form: \"initializeFromState\",\n       enableReinitialize: true,\n     })(UserEdit);\n```\n\n If your `initialValues` prop gets updated, your form will update too." },
  { q: "১৫৮. রিয়্যাক্ট প্রপটাইপস কীভাবে এক প্রপের জন্য ভিন্ন ধরন অনুমতি দেয়?", qEn: "158. How React PropTypes allow different types for one prop?", a: "PropTypes.oneOfType([PropTypes.string, PropTypes.number])\n\nউদাহরণ:\n```javascript\nname: PropTypes.string.isRequired\n```", aEn: "You can use `oneOfType()` method of `PropTypes`.\n\n For example, the height property can be defined with either `string` or `number` type as below:\n\n     \n```javascript\n     Component.propTypes = {\n       size: PropTypes.oneOfType([PropTypes.string, PropTypes.number]),\n     };\n```" },
  { q: "১৫৯. SVG ফাইল কি রিয়্যাক্ট কম্পোনেন্ট হিসেবে ইম্পোর্ট করতে পারবেন?", qEn: "159. Can I import an SVG file as react component?", a: "হাঁ। CRA-তে ডিফল্ট সাপোর্ট: import { ReactComponent as Logo } from './logo.svg'\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "You can import SVG directly as component instead of loading it as a file. This feature is available with `react-scripts@2.0.0` and higher.\n\n     ```jsx harmony\n     import { ReactComponent as Logo } from \"./logo.svg\";\n\n     const App = () => (\n       <div>\n         {/ Logo is an actual react component /}\n         <Logo />\n       </div>\n     );\n     ```\n\n Note: Don't forget about the curly braces in the import." },
  { q: "১৬০. রেন্ডার হাইজ্যাকিং কী?", qEn: "160. What is render hijacking in react?", a: "HOC বা রেন্ডার প্রপস দিয়ে কম্পোনেন্টের রেন্ডার আউটপুট ইন্টারসেপ্ট ও মডিফাই করা।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "The concept of render hijacking is the ability to control what a component will output from another component. It means that you decorate your component by wrapping it into a Higher-Order component. By wrapping, you can inject additional props or make other changes, which can cause changing logic of rendering. It does not actually enable hijacking, but by using HOC you make your component behave differently." },
  { q: "১৬১. কীভাবে রিয়্যাক্ট কম্পোনেন্টে সংখ্যা পাঠাবেন?", qEn: "161. How to pass numbers to React component?", a: "<MyComponent count={5} /> (কার্লি ব্রেসে সংখ্যা) অথবা count=\"5\" দিলে স্ট্রিং যায়।\n\nউদাহরণ:\n```javascript\n<MyComponent count={5} /> (কার্লি ব্রেসে সংখ্যা) অথবা count=\"5\" দিলে স্ট্রিং যায়।\n```", aEn: "We can pass `numbers` as `props` to React component using curly braces `{}` where as `strings` in double quotes `\"\"` or single quotes `''`\n\n     \n```javascript\n     import React from \"react\";\n\n     const ChildComponent = ({ name, age }) => {\n       return (\n         <>\n           My Name is {name} and Age is {age}\n         </>\n       );\n     };\n\n     const ParentComponent = () => {\n       return (\n         <>\n           <ChildComponent name=\"Chetan\" age={30} />\n         </>\n       );\n     };\n\n     export default ParentComponent;\n```" },
  { q: "১৬২. সব স্টেট কি রিডাক্সে রাখা উচিত? কি কি রিয়্যাক্টের ইন্টারনাল স্টেটে রাখবেন?", qEn: "162. Do I need to keep all my state into Redux? Should I ever use react internal state?", a: "শুধু গ্লোবাল ডেটা রিডাক্সে। লোকাল UI স্টেট (যেমন মোডাল খোলা/বন্ধ) রিয়্যাক্ট স্টেটে রাখুন।\n\nউদাহরণ:\n```javascript\ndispatch({ type: 'ACTION', payload: data });\n```", aEn: "It is up to the developer's decision, i.e., it is developer's job to determine what kinds of state make up your application, and where each piece of state should live. Some users prefer to keep every single piece of data in Redux, to maintain a fully serializable and controlled version of their application at all times. Others prefer to keep non-critical or UI state, such as “is this dropdown currently open”, inside a component's internal state.\n\n Below are the rules of thumb to determine what kind of data should be put into Redux\n\n 1. Do other parts of the application care about this data?\n 2. Do you need to be able to create further derived data based on this original data?\n 3. Is the same data being used to drive multiple components?\n 4. Is there value to you in being able to restore this state to a given point in time (ie, time travel debugging)?\n 5. Do you want to cache the data (i.e, use what's in state if it's already there instead of re-requesting it)?" },
  { q: "১৬৩. registerServiceWorker-এর উদ্দেশ্য কী?", qEn: "163. What is the purpose of registerServiceWorker in React?", a: "CRA-তে প্রগ্রেসিভ ওয়েব অ্যাপ (PWA) ফিচার দেয় – অফলাইন সাপোর্ট ও ক্যাশিং।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "React creates a service worker for you without any configuration by default. The service worker is a web API that helps you cache your assets and other files so that when the user is offline or on a slow network, he/she can still see results on the screen, as such, it helps you build a better user experience, that's what you should know about service worker for now. It's all about adding offline capabilities to your site.\n\n     \n```javascript\n     import React from \"react\";\n     import ReactDOM from \"react-dom\";\n     import App from \"./App\";\n     import registerServiceWorker from \"./registerServiceWorker\";\n\n     ReactDOM.render(<App />, document.getElementById(\"root\"));\n     registerServiceWorker();\n```" },
  { q: "১৬৪. React.memo ফাংশন কী?", qEn: "164. What is React memo function?", a: "ফাংশনাল কম্পোনেন্ট মেমোইজেশন করে। প্রপস পরিবর্তন না হলে রি-রেন্ডার বাধা দেয়।\n\nউদাহরণ:\n```javascript\nconst MemoChild = React.memo(Child);\n```", aEn: "Class components can be restricted from re-rendering when their input props are the same using PureComponent or shouldComponentUpdate. Now you can do the same with function components by wrapping them in React.memo.\n\n     \n```javascript\n     const MyComponent = React.memo(function MyComponent(props) {\n       / only rerenders if props change /\n     });\n```" },
  { q: "১৬৫. React.lazy ফাংশন কী?", qEn: "165. What is React lazy function?", a: "কম্পোনেন্ট ডাইনামিক ইম্পোর্ট করে (কোড স্প্লিটিং)। Suspense-এর সাথে ব্যবহার হয়।\n\nউদাহরণ:\n```javascript\nconst LazyPage = React.lazy(() => import('./Page'));\n<Suspense fallback={<Spinner />}><LazyPage /></Suspense>\n```", aEn: "The `React.lazy` function lets you render a dynamic import as a regular component. It will automatically load the bundle containing the `OtherComponent` when the component gets rendered. This must return a Promise which resolves to a module with a default export containing a React component.\n\n     \n```javascript\n     const OtherComponent = React.lazy(() => import(\"./OtherComponent\"));\n\n     function MyComponent() {\n       return (\n         <div>\n           <OtherComponent />\n         </div>\n       );\n     }\n```\n\n Note:\n `React.lazy` and `Suspense` is not yet available for server-side rendering. If you want to do code-splitting in a server rendered app, we still recommend React Loadable." },
  { q: "১৬৬. কীভাবে setState ব্যবহার করে অপ্রয়োজনীয় আপডেট প্রতিরোধ করবেন?", qEn: "166. How to prevent unnecessary updates using setState?", a: "shouldComponentUpdate বা React.memo ব্যবহার করুন, অথবা useMemo/useCallback দিয়ে প্রপস স্থিতিশীল রাখুন।\n\nউদাহরণ:\n```javascript\nconst v = useMemo(() => heavy(a), [a]);\n```", aEn: "You can compare the current value of the state with an existing state value and decide whether to rerender the page or not. If the values are the same then you need to return null to stop re-rendering otherwise return the latest state value.\n\n For example, the user profile information is conditionally rendered as follows,\n\n     \n```javascript\n     getUserProfile = (user) => {\n       const latestAddress = user.address;\n       this.setState((state) => {\n         if (state.address === latestAddress) {\n           return null;\n         } else {\n           return { title: latestAddress };\n         }\n       });\n     };\n```" },
  { q: "১৬৭. রিয়্যাক্ট ১৬-এ কীভাবে অ্যারে, স্ট্রিং ও নাম্বার রেন্ডার করবেন?", qEn: "167. How do you render Array, Strings and Numbers in React 16 Version?", a: "সরাসরি রেন্ডার হয়:\n\nউদাহরণ:\n\n```javascript\n<div>{['হ্যালো', 'ওয়ার্ল্ড']}</div> {/* হ্যালোওয়ার্ল্ড */}\n<div>{42}</div>\n```", aEn: "Arrays: Unlike older releases, you don't need to make sure render method return a single element in React16. You are able to return multiple sibling elements without a wrapping element by returning an array.\n\n For example, let us take the below list of developers,\n\n     \n```javascript\n     const ReactJSDevs = () => {\n       return [\n         <li key=\"1\">John</li>,\n         <li key=\"2\">Jackie</li>,\n         <li key=\"3\">Jordan</li>,\n       ];\n     };\n```\n\n You can also merge this array of items in another array component.\n\n     \n```javascript\n     const JSDevs = () => {\n       return (\n         <ul>\n           <li>Brad</li>\n           <li>Brodge</li>\n           <ReactJSDevs />\n           <li>Brandon</li>\n         </ul>\n       );\n     };\n```\n\n Strings and Numbers: You can also return string and number type from the render method.\n\n     \n```javascript\n     render() {\n      return 'Welcome to ReactJS questions';\n     }\n     // Number\n     render() {\n      return 2018;\n     }\n```" },
  { q: "১৬৮. হুকস কী?", qEn: "168. What are hooks?", a: "ফাংশনাল কম্পোনেন্টে স্টেট ও লাইফসাইকেল ফিচার ব্যবহারের উপায় (useState, useEffect, etc)।\n\nউদাহরণ:\nuseState, useEffect, useContext… — functional component-এ state/lifecycle।", aEn: "Hooks is a special JavaScript function that allows you use state and other React features without writing a class. This pattern has been introduced as a new feature in React 16.8 and helped to isolate the stateful logic from the components.\n\n Let's see an example of useState hook:\n\n     \n```javascript\n     import { useState } from \"react\";\n\n     function Example() {\n       // Declare a new state variable, which we'll call \"count\"\n       const [count, setCount] = useState(0);\n\n       return (\n         <>\n           <p>You clicked {count} times</p>\n           <button onClick={() => setCount(count + 1)}>Click me</button>\n         </>\n       );\n     }\n```\n\n Note: Hooks can be used inside an existing function component without rewriting the component." },
  { q: "১৬৯. হুকসের জন্য কী কী নিয়ম মেনে চলতে হবে?", qEn: "169. What rules need to be followed for hooks?", a: "শুধুমাত্র টপ-লেভেলে কল করুন (লুপ/শর্ত/নেস্টেড ফাংশনে নয়)\n\nশুধুমাত্র রিয়্যাক্ট ফাংশনে কল করুন\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "You need to follow two rules in order to use hooks,\n\n 1. Call Hooks only at the top level of your react functions: You should always use hooks at the top level of react function before any early returns. i.e, You shouldn’t call Hooks inside loops, conditions, or nested functions. This will ensure that Hooks are called in the same order each time a component renders and it preserves the state of Hooks between multiple re-renders due to `useState` and `useEffect` calls.\n\n Let's see the difference using an example,\n Correct usage::\n     \n```javascript\n     function UserProfile() {\n      // Correct: Hooks called at the top level\n      const [name, setName] = useState('John');\n      const [country, setCountry] = useState('US');\n\n      return (\n        <div>\n          <h1>Name: {name}</h1>\n          <p>Country: {country}</p>\n        </div>\n      );\n     }\n```\n Incorrect usage::\n     \n```javascript\n     function UserProfile() {\n      const [name, setName] = useState('John');\n\n      if (name === 'John') {\n        // Incorrect: useState is called inside a conditional\n        const [country, setCountry] = useState('US'); \n      }\n\n      return (\n        <div>\n          <h1>Name: {name}</h1>\n          <p>Country: {country}</p> {/ This will throw an error if the name condition isn't met /}\n        </div>\n      );\n     }\n```\n The `useState` hook for the country field is being called conditionally within an `if` block. This can lead to inconsistent state behavior and may cause hooks to be called in a different order on each re-render.\n\n 2. Call Hooks from React Functions only: You shouldn’t call Hooks from regular JavaScript functions or class components. Instead, you should call them from either function components or custom hooks.\n\n Let's find the difference of correct and incorrect usage with below examples,\n\n Correct usage::\n     \n```javascript\n     //Example1:\n     function Counter() {\n      // Correct: useState is used inside a functional component\n      const [count, setCount] = useState(0);\n\n      return <div>Counter: {count}</div>;\n     }\n     //Example2:\n     function useFetchData(url) {\n      const [data, setData] = useState(null);\n\n      useEffect(() => {\n        fetch(url)\n          .then((response) => response.json())\n          .then((data) => setData(data));\n      }, [url]);\n\n      return data;\n     }\n\n     function UserProfile() {\n      // Correct: Using a custom hook here\n      const user = useFetchData('https://some-api.com/user');\n\n      return (\n        <div>\n          <h1>{user ? user.name : 'Loading profile...'}</h1>\n        </div>\n      );\n     }\n```\n Incorrect usage::\n     \n```javascript\n      //Example1\n      function normalFunction() {\n        // Incorrect: Can't call hooks in normal functions\n        const [count, setCount] = useState(0); \n      }\n\n      //Example2\n      function fetchData(url) {\n        // Incorrect: Hooks can't be used in non-React functions\n        const [data, setData] = useState(null);\n\n        useEffect(() => {\n          fetch(url)\n            .then((response) => response.json())\n            .then((data) => setData(data));\n        }, [url]);\n\n        return data;\n      }\n```\n In the above incorrect usage example, both `useState` and `useEffect` are used in non-React functions(`normalFunction` and `fetchData`), which is not allowed." },
  { q: "১৭০. কীভাবে নিশ্চিত করবেন যে আপনার প্রকল্পে হুকসের নিয়ম অনুসরণ হয়?", qEn: "170. How to ensure hooks followed the rules in your project?", a: "eslint-plugin-react-hooks প্লাগইন ব্যবহার করুন।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "React team released an ESLint plugin called eslint-plugin-react-hooks that enforces Hook's two rules. It is part of Hooks API. You can add this plugin to your project using the below command,\n\n        \n```javascript\n        npm install eslint-plugin-react-hooks --save-dev\n```\n\n And apply the below config in your ESLint config file,\n\n        \n```javascript\n        // Your ESLint configuration\n        {\n          \"plugins\": [\n            // ...\n            \"react-hooks\"\n          ],\n          \"rules\": {\n            // ...\n            \"react-hooks/rules-of-hooks\": \"error\"\n          }\n        }\n```\n\n This plugin also provide another important rule through `react-hooks/exhaustive-deps`. It ensures that the dependencies of useEffect, useCallback, and useMemo hooks are correctly listed to avoid potential bugs.\n\n        \n```javascript\n        useEffect(() => {\n          // Forgetting `message` will result in incorrect behavior\n          console.log(message);\n        }, []); // Here `message` should be a dependency\n```\n The recommended `eslint-config-react-app` preset already includes the hooks rules of this plugin.\n For example, the linter enforce proper naming convention for hooks. If you rename your custom hooks which as prefix \"use\" to something else then linter won't allow you to call built-in hooks such as useState, useEffect etc inside of your custom hook anymore.\n\n Note: This plugin is intended to use in Create React App by default." },
  { q: "১৭১. ফ্লাক্স ও রিডাক্সের মধ্যে পার্থক্যগুলো কী কী?", qEn: "171. What are the differences between Flux and Redux?", a: "| ফ্লাক্স | রিডাক্স |\n| একাধিক স্টোর থাকতে পারে | একক স্টোর |\n| ডিস্প্যাচার আছে | নেই (রিডিউসার ডিস্প্যাচ করে) |\n| স্টোর ইমিউটেবল নয় | স্টেট ইমিউটেবল |\n\nউদাহরণ:\n```javascript\ndispatch({ type: 'ACTION', payload: data });\n```", aEn: "Below are the major differences between Flux and Redux\n\n | Flux | Redux |\n | ---------------------------------------------- | ------------------------------------------ |\n | State is mutable | State is immutable |\n | The Store contains both state and change logic | The Store and change logic are separate |\n | There are multiple stores exist | There is only one store exist |\n | All the stores are disconnected and flat | Single store with hierarchical reducers |\n | It has a singleton dispatcher | There is no concept of dispatcher |\n | React components subscribe to the store | Container components uses connect function |" },
  { q: "১৭২. রিয়্যাক্ট রাউটার v4-এর সুবিধাগুলো কী কী?", qEn: "172. What are the benefits of React Router V4?", a: "ডিক্লারেটিভ রাউটিং\n\nডায়নামিক রাউট ম্যাচিং\n\nছোট সাইজ\n\nউদাহরণ:\n```javascript\n<Link to=\"/about\">About</Link>\n```", aEn: "Below are the main benefits of React Router V4 module,\n\n 1. In React Router v4(version 4), the API is completely about components. A router can be visualized as a single component(` `) which wraps specific child router components(` `).\n 2. You don't need to manually set history. The router module will take care history by wrapping routes with ` ` component.\n 3. The application size is reduced by adding only the specific router module(Web, core, or native)" },
  { q: "১৭৩. componentDidCatch লাইফসাইকেল মেথডের সিগনেচার বর্ণনা করতে পারেন?", qEn: "173. Can you describe about componentDidCatch lifecycle method signature?", a: "componentDidCatch(error, info)\n\nerror: ধরা পড়া এরর\n\ninfo: কম্পোনেন্ট স্ট্যাক ট্রেস থাকা অবজেক্ট\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "The componentDidCatch lifecycle method is invoked after an error has been thrown by a descendant component. The method receives two parameters,\n\n 1. error: - The error object which was thrown\n 2. info: - An object with a componentStack key contains the information about which component threw the error.\n\n The method structure would be as follows\n\n     \n```javascript\n     componentDidCatch(error, info);\n```" },
  { q: "১৭৪. কোন কোন ক্ষেত্রে এরর বাউন্ডারি এরর ধরে না?", qEn: "174. In which scenarios do error boundaries not catch errors?", a: "ইভেন্ট হ্যান্ডলার\n\nঅ্যাসিঙ্ক কোড (setTimeout)\n\nসার্ভার-সাইড রেন্ডারিং\n\nএরর বাউন্ডারির নিজের ভেতরের এরর\n\nউদাহরণ:\n```javascript\nclass ErrorBoundary extends React.Component {\n  state = { hasError: false };\n  static getDerivedStateFromError() { return { hasError: true }; }\n  render() { return this.state.hasError ? <h1>Oops</h1> : this.props.children; }\n}\n```", aEn: "Below are the cases in which error boundaries don't work,\n\n 1. Inside Event handlers\n 2. Asynchronous code using setTimeout or requestAnimationFrame callbacks\n 3. During Server side rendering\n 4. When errors thrown in the error boundary code itself" },
  { q: "১৭৫. রিয়্যাক্ট ১৬-এ আন্ডকট এররগুলোর আচরণ কী?", qEn: "175. What is the behavior of uncaught errors in react 16?", a: "সম্পূর্ণ কম্পোনেন্ট ট্রি আনমাউন্ট হয়।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "In React 16, errors that were not caught by any error boundary will result in unmounting of the whole React component tree. The reason behind this decision is that it is worse to leave corrupted UI in place than to completely remove it. For example, it is worse for a payments app to display a wrong amount than to render nothing." },
  { q: "১৭৬. এরর বাউন্ডারির সঠিক স্থান কোথায়?", qEn: "176. What is the proper placement for error boundaries?", a: "প্রতিটি ফিচার বা ইউআই সেকশনের উপরে, পুরো অ্যাপের একদম উপরে একটি রুট এরর বাউন্ডারি।\n\nউদাহরণ:\n```javascript\nclass ErrorBoundary extends React.Component {\n  state = { hasError: false };\n  static getDerivedStateFromError() { return { hasError: true }; }\n  render() { return this.state.hasError ? <h1>Oops</h1> : this.props.children; }\n}\n```", aEn: "The granularity of error boundaries usage is up to the developer based on project needs. You can follow either of these approaches,\n 1. You can wrap top-level route components to display a generic error message for the entire application.\n 2. You can also wrap individual components in an error boundary to protect them from crashing the rest of the application." },
  { q: "১৭৭. এরর বাউন্ডারি থেকে কম্পোনেন্ট স্ট্যাক ট্রেসের সুবিধা কী?", qEn: "177. What is the benefit of component stack trace from error boundary?", a: "কোন কম্পোনেন্টে এরর হয়েছে তা দ্রুত চিহ্নিত করা যায়। প্রোডাকশনে ডিবাগ সহজ করে।\n\nউদাহরণ:\n```javascript\nclass ErrorBoundary extends React.Component {\n  state = { hasError: false };\n  static getDerivedStateFromError() { return { hasError: true }; }\n  render() { return this.state.hasError ? <h1>Oops</h1> : this.props.children; }\n}\n```", aEn: "Apart from error messages and javascript stack, React16 will display the component stack trace with file names and line numbers using error boundary concept.\n\n For example, BuggyCounter component displays the component stack trace as below,\n\n !stacktrace" },
  { q: "১৭৮. ডিফল্ট প্রপস কী?", qEn: "178. What are default props?", a: "কম্পোনেন্টে প্রপস পাঠানো না হলে ব্যবহৃত হয়:\n\nউদাহরণ:\n\n```javascript\nMyComponent.defaultProps = { name: 'অতিথি' };\n```", aEn: "The _defaultProps_ can be defined as a property on the component to set the default values for the props. These default props are used when props not supplied(i.e., undefined props), but not for `null` or `0` as props. That means, If you provide null value then it remains null value. It's the same behavior with 0 as well.\n\n For example, let us create color default prop for the button component,\n\n     \n```javascript\n     function MyButton {\n       // ...\n     }\n\n     MyButton.defaultProps = {\n       color: \"red\",\n     };\n```\n\n If `props.color` is not provided then it will set the default value to 'red'. i.e, Whenever you try to access the color prop it uses the default value\n\n     \n```javascript\n     function MyButton() {\n       return <MyButton />; // props.color will contain red value\n     }\n```" },
  { q: "১৭৯. displayName ক্লাস প্রপার্টির উদ্দেশ্য কী?", qEn: "179. What is the purpose of displayName class property?", a: "ডেভ টুলসে কম্পোনেন্টের নাম দেখায়।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "The displayName string is used in debugging messages. Usually, you don’t need to set it explicitly because it’s inferred from the name of the function or class that defines the component. You might want to set it explicitly if you want to display a different name for debugging purposes or when you create a higher-order component.\n\n For example, To ease debugging, choose a display name that communicates that it’s the result of a withSubscription HOC.\n\n     \n```javascript\n     function withSubscription(WrappedComponent) {\n       class WithSubscription extends React.Component {\n         / ... /\n       }\n       WithSubscription.displayName = `WithSubscription(${getDisplayName(\n         WrappedComponent\n       )})`;\n       return WithSubscription;\n     }\n     function getDisplayName(WrappedComponent) {\n       return (\n         WrappedComponent.displayName || WrappedComponent.name || \"Component\"\n       );\n     }\n```" },
  { q: "১৮০. রিয়্যাক্ট অ্যাপ্লিকেশনের জন্য ব্রাউজার সাপোর্ট কী?", qEn: "180. What is the browser support for react applications?", a: "রিয়্যাক্ট ১৮+: IE নয়। আধুনিক ব্রাউজার (Chrome, Firefox, Safari, Edge)।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "React supports all popular browsers, including Internet Explorer 9 and above, although some polyfills are required for older browsers such as IE 9 and IE 10. If you use es5-shim and es5-sham polyfill then it even support old browsers that doesn't support ES5 methods." },
  { q: "১৮১. কোড স্প্লিটিং কী?", qEn: "181. What is code-splitting?", a: "বড় বান্ডলকে ছোট ছোট চাঙ্কে ভাগ করা যা প্রয়োজনে লোড হয়। React.lazy() + Suspense ব্যবহার করুন।\n\nউদাহরণ:\n```javascript\nconst LazyHome = React.lazy(() => import('./Home'));\n```", aEn: "Code-Splitting is a feature supported by bundlers like Webpack and Browserify which can create multiple bundles that can be dynamically loaded at runtime. The react project supports code splitting via dynamic import() feature.\n\n For example, in the below code snippets, it will make moduleA.js and all its unique dependencies as a separate chunk that only loads after the user clicks the 'Load' button.\n\n moduleA.js\n\n     \n```javascript\n     const moduleA = \"Hello\";\n\n     export { moduleA };\n```\n\n App.js\n\n     \n```javascript\n     export default function App {\n       function handleClick() {\n         import(\"./moduleA\")\n           .then(({ moduleA }) => {\n             // Use moduleA\n           })\n           .catch((err) => {\n             // Handle failure\n           });\n       };\n\n      return (\n        <div>\n          <button onClick={this.handleClick}>Load</button>\n        </div>\n      );\n     }\n```\n\n See Class \n \n\n  \n```javascript\n    import React, { Component } from \"react\";\n\n     class App extends Component {\n       handleClick = () => {\n         import(\"./moduleA\")\n           .then(({ moduleA }) => {\n             // Use moduleA\n           })\n           .catch((err) => {\n             // Handle failure\n           });\n       };\n\n       render() {\n         return (\n           <div>\n             <button onClick={this.handleClick}>Load</button>\n           </div>\n         );\n       }\n     }\n\n     export default App;\n```" },
  { q: "১৮২. কীড ফ্র্যাগমেন্টস কী?", qEn: "182. What are Keyed Fragments?", a: "ফ্র্যাগমেন্টে কী অ্যাট্রিবিউট দিতে চাইলে <Fragment key={id}> ব্যবহার করুন।\n\nউদাহরণ:\n```javascript\n<>...</>\n```", aEn: "The Fragments declared with the explicit syntax may have keys. The general use case is mapping a collection to an array of fragments as below,\n\n     \n```javascript\n     function Glossary(props) {\n       return (\n         <dl>\n           {props.items.map((item) => (\n             // Without the `key`, React will fire a key warning\n             <React.Fragment key={item.id}>\n               <dt>{item.term}</dt>\n               <dd>{item.description}</dd>\n             </React.Fragment>\n           ))}\n         </dl>\n       );\n     }\n```\n\n Note: key is the only attribute that can be passed to Fragment. In the future, there might be a support for additional attributes, such as event handlers." },
  { q: "১৮৩. রিয়্যাক্ট কি সব HTML অ্যাট্রিবিউট সাপোর্ট করে?", qEn: "183. Does React support all HTML attributes?", a: "বেশিরভাগ সাপোর্ট করে, তবে কিছু আলাদা (className, htmlFor)।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "As of React 16, both standard or custom DOM attributes are fully supported. Since React components often take both custom and DOM-related props, React uses the camelCase convention just like the DOM APIs.\n\n Let us take few props with respect to standard HTML attributes,\n\n     \n```javascript\n     <div tabIndex=\"-1\" />      // Just like node.tabIndex DOM API\n     <div className=\"Button\" /> // Just like node.className DOM API\n     <input readOnly={true} />  // Just like node.readOnly DOM API\n```\n\n These props work similarly to the corresponding HTML attributes, with the exception of the special cases. It also support all SVG attributes." },
  { q: "১৮৪. কম্পোনেন্ট প্রপস কখন ডিফল্ট true হয়?", qEn: "184. When component props defaults to true?", a: "প্রপস নাম লিখলে কিন্তু মান না দিলে: <MyComponent disabled /> -> disabled={true}\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "If you pass no value for a prop, it defaults to true. This behavior is available so that it matches the behavior of HTML.\n\n For example, below expressions are equivalent,\n\n     \n```javascript\n     <MyInput autocomplete />\n\n     <MyInput autocomplete={true} />\n```\n\n Note: It is not recommended to use this approach because it can be confused with the ES6 object shorthand (example, `{name}` which is short for `{name: name}`)" },
  { q: "১৮৫. নেক্সট.জেএস কী এবং এর প্রধান বৈশিষ্ট্যগুলো কী কী?", qEn: "185. What is NextJS and major features of it?", a: "রিয়্যাক্টের জন্য ফুল-স্ট্যাক ফ্রেমওয়ার্ক। বৈশিষ্ট্য: SSR, স্ট্যাটিক সাইট জেনারেশন, ফাইল-ভিত্তিক রাউটিং, API রাউট।\n\nউদাহরণ:\n```javascript\n// app/page.tsx — Server Component by default\nexport default function Page() { return <main />; }\n```", aEn: "Next.js is a popular and lightweight framework for static and server‑rendered applications built with React. It also provides styling and routing solutions. Below are the major features provided by NextJS,\n\n 1. Server-rendered by default\n 2. Automatic code splitting for faster page loads\n 3. Simple client-side routing (page based)\n 4. Webpack-based dev environment which supports (HMR)\n 5. Able to implement with Express or any other Node.js HTTP server\n 6. Customizable with your own Babel and Webpack configurations" },
  { q: "১৮৬. কীভাবে একটি কম্পোনেন্টে ইভেন্ট হ্যান্ডলার পাস করবেন?", qEn: "186. How do you pass an event handler to a component?", a: "প্রপস আকারে: <Button onClick={handleClick} />\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "You can pass event handlers and other functions as props to child components. The functions can be passed to child component as below,\n\n     \n```javascript\n     function Button({ onClick }) {\n       return <button onClick={onClick}>Download</button>;\n     }\n\n     export default function downloadExcel() {\n       function handleClick() {\n         alert(\"Downloaded\");\n       }\n\n       return <Button onClick={handleClick}></Button>;\n     }\n```" },
  { q: "১৮৭. কীভাবে একটি ফাংশনকে একাধিকবার কল হওয়া থেকে রক্ষা করবেন?", qEn: "187. How to prevent a function from being called multiple times?", a: "debounce (থ্রটল) বা useCallback + AbortController ব্যবহার করুন।\n\nউদাহরণ:\n```javascript\nconst fn = useCallback(() => action(), [dep]);\n```", aEn: "If you use an event handler such as onClick or onScroll and want to prevent the callback from being fired too quickly, then you can limit the rate at which callback is executed. This can be achieved in the below possible ways,\n\n 1. Throttling: Changes based on a time based frequency. For example, it can be used using \\_.throttle lodash function\n 2. Debouncing: Publish changes after a period of inactivity. For example, it can be used using \\_.debounce lodash function\n 3. RequestAnimationFrame throttling: Changes based on requestAnimationFrame. For example, it can be used using raf-schd lodash function" },
  { q: "১৮৮. JSX কীভাবে ইনজেকশন আক্রমণ প্রতিরোধ করে?", qEn: "188. How JSX prevents Injection Attacks?", a: "JSX সব মান এস্কেপ করে রেন্ডার করার আগে। তাই XSS আক্রমণ প্রতিরোধ করে।\n\nউদাহরণ:\n```javascript\nconst el = <div className=\"box\">Hi</div>;\n```", aEn: "React DOM escapes any values embedded in JSX before rendering them. Thus it ensures that you can never inject anything that’s not explicitly written in your application. Everything is converted to a string before being rendered.\n\n For example, you can embed user input as below,\n\n     \n```javascript\n     const name = response.potentiallyMaliciousInput;\n     const element = <h1>{name}</h1>;\n```\n\n This way you can prevent XSS(Cross-site-scripting) attacks in the application." },
  { q: "১৮৯. কীভাবে রেন্ডার করা এলিমেন্ট আপডেট করবেন?", qEn: "189. How do you update rendered elements?", a: "স্টেট পরিবর্তন করুন। রিয়্যাক্ট স্বয়ংক্রিয়ভাবে রি-রেন্ডার করবে।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "You can update UI(represented by rendered element) by passing the newly created element to ReactDOM's render method.\n\n For example, lets take a ticking clock example, where it updates the time by calling render method multiple times,\n\n     \n```javascript\n     function tick() {\n       const element = (\n         <div>\n           <h1>Hello, world!</h1>\n           <h2>It is {new Date().toLocaleTimeString()}.</h2>\n         </div>\n       );\n       ReactDOM.render(element, document.getElementById(\"root\"));\n     }\n\n     setInterval(tick, 1000);\n```" },
  { q: "১৯০. প্রপস রিড-অনলি তা কীভাবে নির্দেশ করবেন?", qEn: "190. How do you say that props are readonly?", a: "কম্পোনেন্টের ভেতর প্রপসের মান পরিবর্তন করার চেষ্টা করবেন না। এটি রিয়্যাক্টের মৌলিক নীতি।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "When you declare a component as a function or a class, it must never modify its own props.\n\n Let us take a below capital function,\n\n     \n```javascript\n     function capital(amount, interest) {\n       return amount + interest;\n     }\n```\n\n The above function is called “pure” because it does not attempt to change their inputs, and always return the same result for the same inputs. Hence, React has a single rule saying \"All React components must act like pure functions with respect to their props.\"" },
  { q: "১৯১. কী হিসেবে ইনডেক্স নিরাপদে ব্যবহারের শর্তগুলো কী কী?", qEn: "191. What are the conditions to safely use the index as a key?", a: "লিস্ট স্ট্যাটিক (কখনো পরিবর্তন হয় না)\n\nলিস্টে রি-অর্ডার, ফিল্টার, অ্যাড, ডিলিট নেই\n\nলিস্ট ছোট এবং কর্মক্ষমতা সমস্যা নেই\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "There are three conditions to make sure, it is safe use the index as a key.\n\n 1. The list and items are static– they are not computed and do not change\n 2. The items in the list have no ids\n 3. The list is never reordered or filtered." },
  { q: "১৯২. কী কি গ্লোবালি ইউনিক হতে হবে?", qEn: "192. Should keys be globally unique?", a: "না। শুধু সিবলিংদের মধ্যে ইউনিক হলেই যথেষ্ট।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "The keys used within arrays should be unique among their siblings but they don’t need to be globally unique. i.e, You can use the same keys with two different arrays.\n\n For example, the below `Book` component uses two arrays with different arrays,\n\n     \n```javascript\n     function Book(props) {\n       const index = (\n         <ul>\n           {props.pages.map((page) => (\n             <li key={page.id}>{page.title}</li>\n           ))}\n         </ul>\n       );\n       const content = props.pages.map((page) => (\n         <div key={page.id}>\n           <h3>{page.title}</h3>\n           <p>{page.content}</p>\n           <p>{page.pageNumber}</p>\n         </div>\n       ));\n       return (\n         <div>\n           {index}\n           <hr />\n           {content}\n         </div>\n       );\n     }\n```" },
  { q: "১৯৩. ফর্ম হ্যান্ডলিংয়ের জন্য জনপ্রিয় পছন্দ কী কী?", qEn: "193. What is the popular choice for form handling?", a: "React Hook Form (বর্তমানে সবচেয়ে জনপ্রিয়)\n\nFormik\n\nReact Final Form\n\nউদাহরণ:\n```javascript\nconst { register, handleSubmit } = useForm();\n```", aEn: "`Formik` is a form library for react which provides solutions such as validation, keeping track of the visited fields, and handling form submission.\n\n In detail, You can categorize them as follows,\n\n 1. Getting values in and out of form state\n 2. Validation and error messages\n 3. Handling form submission\n\n It is used to create a scalable, performant, form helper with a minimal API to solve annoying stuff." },
  { q: "১৯৪. রিডাক্স ফর্ম লাইব্রেরির তুলনায় ফরমিকের সুবিধাগুলো কী কী?", qEn: "194. What are the advantages of formik over redux form library?", a: "কম বয়লারপ্লেট\n\nফাস্ট (কম রি-রেন্ডার)\n\nরিডাক্স নির্ভর নয়\n\nউদাহরণ:\n```javascript\ndispatch({ type: 'ACTION', payload: data });\n```", aEn: "Below are the main reasons to recommend formik over redux form library,\n\n 1. The form state is inherently short-term and local, so tracking it in Redux (or any kind of Flux library) is unnecessary.\n 2. Redux-Form calls your entire top-level Redux reducer multiple times ON EVERY SINGLE KEYSTROKE. This way it increases input latency for large apps.\n 3. Redux-Form is 22.5 kB minified gzipped whereas Formik is 12.7 kB" },
  { q: "১৯৫. উত্তরাধিকার (ইনহেরিট্যান্স) ব্যবহার করতে বলা হয় না কেন?", qEn: "195. Why are you not required to use inheritance?", a: "রিয়্যাক্টের কম্পোজিশন মডেল (HOC, রেন্ডার প্রপস, হুকস) উত্তরাধিকারের চেয়ে বেশি নমনীয়।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "In React, it is recommended to use composition over inheritance to reuse code between components. Both Props and composition give you all the flexibility you need to customize a component’s look and behavior explicitly and safely.\n Whereas, If you want to reuse non-UI functionality between components, it is suggested to extract it into a separate JavaScript module. Later components import it and use that function, object, or class, without extending it." },
  { q: "১৯৬. রিয়্যাক্ট অ্যাপ্লিকেশনে ওয়েব কম্পোনেন্ট ব্যবহার করতে পারেন?", qEn: "196. Can I use web components in react application?", a: "হাঁ। রেফ দিয়ে ওয়েব কম্পোনেন্ট অ্যাক্সেস করুন এবং ইভেন্ট হ্যান্ডেল করুন।\n\nউদাহরণ:\n```javascript\nconst ref = useRef(null);\n```", aEn: "Yes, you can use web components in a react application. Even though many developers won't use this combination, it may require especially if you are using third-party UI components that are written using Web Components.\n\n For example, let us use `Vaadin` date picker web component as below,\n\n     \n```javascript\n     import \"./App.css\";\n     import \"@vaadin/vaadin-date-picker\";\n     export default function App() {\n       return (\n         <div className=\"App\">\n           <vaadin-date-picker label=\"When were you born?\"></vaadin-date-picker>\n         </div>\n       );\n     }\n```" },
  { q: "১৯৭. ডাইনামিক ইম্পোর্ট কী?", qEn: "197. What is dynamic import?", a: "import('./module').then(module => ...) – রানটাইমে মডিউল লোড করে।\n\nউদাহরণ:\n```javascript\nimport('./module').then(module => ...) – রানটাইমে মডিউল লোড করে।\n```", aEn: "You can achieve code-splitting in your app using dynamic import.\n\n Let's take an example of addition,\n\n 1. Normal Import\n\n     \n```javascript\n     import { add } from \"./math\";\n     console.log(add(10, 20));\n```\n\n 2. Dynamic Import\n\n     \n```javascript\n     import(\"./math\").then((math) => {\n       console.log(math.add(10, 20));\n     });\n```" },
  { q: "১৯৮. লোডেবল কম্পোনেন্ট কী?", qEn: "198. What are loadable components?", a: "@loadable/component – React.lazy-র বিকল্প যা সার্ভার-সাইড রেন্ডারিং সাপোর্ট করে।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "With the release of React 18, React.lazy and Suspense are now available for server-side rendering. However, prior to React 18, it was recommended to use Loadable Components for code-splitting in a server-side rendered app because React.lazy and Suspense were not available for server-side rendering. Loadable Components lets you render a dynamic import as a regular component. For example, you can use Loadable Components to load the OtherComponent in a separate bundle like this:\n\n     \n```javascript\n     import loadable from \"@loadable/component\";\n\n     const OtherComponent = loadable(() => import(\"./OtherComponent\"));\n\n     function MyComponent() {\n       return (\n         <div>\n           <OtherComponent />\n         </div>\n       );\n     }\n```\n\n Now OtherComponent will be loaded in a separated bundle\n Loadable Components provides additional benefits beyond just code-splitting, such as automatic code reloading, error handling, and preloading. By using Loadable Components, you can ensure that your application loads quickly and efficiently, providing a better user experience for your users." },
  { q: "১৯৯. সাসপেন্স কম্পোনেন্ট কী?", qEn: "199. What is suspense component?", a: "কম্পোনেন্ট লোড হওয়া পর্যন্ত ফলব্যাক UI দেখায়: <Suspense fallback={<Spinner />}>...\n\nউদাহরণ:\n```javascript\n<Suspense fallback={<div>Loading…</div>}>\n  <LazyComponent />\n</Suspense>\n```", aEn: "React Suspense is a built-in feature that lets you defer rendering part of your component tree until some condition(asynchronous operation) is met—usually, data or code has finished loading. While waiting, Suspense lets you display a fallback UI like a spinner or placeholder.\n\n 1. Lazy loading components uses suspense feature,\n\n If the module containing the dynamic import is not yet loaded by the time parent component renders, you must show some fallback content while you’re waiting for it to load using a loading indicator. This can be done using Suspense component.\n \n        \n```javascript\n        const OtherComponent = React.lazy(() => import(\"./OtherComponent\"));\n\n        function MyComponent() {\n          return (\n            <div>\n              <Suspense fallback={<div>Loading...</div>}>\n                <OtherComponent />\n              </Suspense>\n            </div>\n          );\n        }\n```\n The above component shows fallback UI instead real component until `OtherComponent` is fully loaded.\n\n 2. As an another example, suspend until async data(data fetching) is ready\n      \n```javascript\n        function UserProfile() {\n          const user = use(fetchUser()); // throws a promise internally\n          return <div>{user.name}</div>;\n        }\n\n        function App() {\n          return (\n            <Suspense fallback={<div>Loading user...</div>}>\n              <UserProfile />\n            </Suspense>\n          );\n        }\n```" },
  { q: "২০০. রুট-ভিত্তিক কোড স্প্লিটিং কী?", qEn: "200. What is route based code splitting?", a: "প্রতিটি রুটের জন্য আলাদা চাঙ্ক তৈরি করে শুধু ঐ রুট ভিজিট করলে লোড হয়।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "One of the best place to do code splitting is with routes. The entire page is going to re-render at once so users are unlikely to interact with other elements in the page at the same time. Due to this, the user experience won't be disturbed.\n\n Let us take an example of route based website using libraries like React Router with React.lazy,\n\n     \n```javascript\n     import { BrowserRouter as Router, Route, Switch } from \"react-router-dom\";\n     import React, { Suspense, lazy } from \"react\";\n\n     const Home = lazy(() => import(\"./routes/Home\"));\n     const About = lazy(() => import(\"./routes/About\"));\n\n     const App = () => (\n       <Router>\n         <Suspense fallback={<div>Loading...</div>}>\n           <Switch>\n             <Route exact path=\"/\" component={Home} />\n             <Route path=\"/about\" component={About} />\n           </Switch>\n         </Suspense>\n       </Router>\n     );\n```\n\n In the above code, the code splitting will happen at each route level." },
  { q: "২০১. কনটেক্সটে ডিফল্ট ভ্যালুর উদ্দেশ্য কী?", qEn: "201. What is the purpose of default value in context?", a: "প্রোভাইডার উপরে না থাকলে এই মান ব্যবহার হবে।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "The defaultValue argument is only used when a component does not have a matching Provider above it in the tree. This can be helpful for testing components in isolation without wrapping them.\n\n Below code snippet provides default theme value as Luna.\n\n     \n```javascript\n     const MyContext = React.createContext(defaultValue);\n```" },
  { q: "২০২. ডিফিং অ্যালগরিদম কী?", qEn: "202. What is diffing algorithm?", a: "দুটি ট্রি তুলনা করার অ্যালগরিদম। O(n³) না হয়ে O(n) জটিলতায় কাজ করে।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "React needs to use algorithms to find out how to efficiently update the UI to match the most recent tree. The diffing algorithms is generating the minimum number of operations to transform one tree into another. However, the algorithms have a complexity in the order of O(n³) where n is the number of elements in the tree.\n\n In this case, displaying 1000 elements would require in the order of one billion comparisons. This is far too expensive. Instead, React implements a heuristic O(n) algorithm based on two assumptions:\n\n 1. Two elements of different types will produce different trees.\n 2. The developer can hint at which child elements may be stable across different renders with a key prop." },
  { q: "২০৩. ডিফিং অ্যালগরিদম কী কী নিয়ম কভার করে?", qEn: "203. What are the rules covered by diffing algorithm?", a: "ভিন্ন টাইপের এলিমেন্ট → পুরো ট্রি ধ্বংস\n\nএকই টাইপের DOM এলিমেন্ট → অ্যাট্রিবিউট তুলনা\n\nএকই টাইপের কম্পোনেন্ট এলিমেন্ট → প্রপস তুলনা\n\nচাইল্ডের তালিকা → কী দিয়ে ম্যাচ\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "When diffing two trees, React first compares the two root elements. The behavior is different depending on the types of the root elements. It covers the below rules during reconciliation algorithm,\n\n 1. Elements Of Different Types:\n Whenever the root elements have different types, React will tear down the old tree and build the new tree from scratch. For example, elements to, or from to of different types lead a full rebuild.\n 2. DOM Elements Of The Same Type:\n When comparing two React DOM elements of the same type, React looks at the attributes of both, keeps the same underlying DOM node, and only updates the changed attributes. Lets take an example with same DOM elements except className attribute,\n\n        \n```javascript\n        <div className=\"show\" title=\"ReactJS\" />\n\n        <div className=\"hide\" title=\"ReactJS\" />\n```\n\n 3. Component Elements Of The Same Type:\n When a component updates, the instance stays the same, so that state is maintained across renders. React updates the props of the underlying component instance to match the new element, and calls componentWillReceiveProps() and componentWillUpdate() on the underlying instance. After that, the render() method is called and the diff algorithm recurses on the previous result and the new result.\n 4. Recursing On Children:\n when recursing on the children of a DOM node, React just iterates over both lists of children at the same time and generates a mutation whenever there’s a difference. For example, when adding an element at the end of the children, converting between these two trees works well.\n\n        \n```javascript\n        <ul>\n          <li>first</li>\n          <li>second</li>\n        </ul>\n\n        <ul>\n          <li>first</li>\n          <li>second</li>\n          <li>third</li>\n        </ul>\n```\n\n 5. Handling keys:\n React supports a key attribute. When children have keys, React uses the key to match children in the original tree with children in the subsequent tree. For example, adding a key can make the tree conversion efficient,\n\n     \n```javascript\n     <ul>\n       <li key=\"2015\">Duke</li>\n       <li key=\"2016\">Villanova</li>\n     </ul>\n\n     <ul>\n       <li key=\"2014\">Connecticut</li>\n       <li key=\"2015\">Duke</li>\n       <li key=\"2016\">Villanova</li>\n     </ul>\n```" },
  { q: "২০৪. কখন রেফ ব্যবহার করবেন?", qEn: "204. When do you need to use refs?", a: "DOM এলিমেন্টে ফোকাস/টেক্সট সিলেক্ট\n\nথার্ড-পার্টি DOM লাইব্রেরি ইন্টিগ্রেশন\n\nঅ্যানিমেশন ট্রিগার\n\nউদাহরণ:\n```javascript\nconst ref = useRef(null);\n```", aEn: "There are few use cases to go for refs,\n\n 1. Managing focus, text selection, or media playback.\n 2. Triggering imperative animations.\n 3. Integrating with third-party DOM libraries." },
  { q: "২০৫. রেন্ডার প্রপসের জন্য কি প্রপের নাম \"render\" হতে বাধ্য?", qEn: "205. Must prop be named as render for render props?", a: "না। যেকোনো নাম হতে পারে, শুধু এটি একটি ফাংশন প্রপ।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "Even though the pattern named render props, you don’t have to use a prop named render to use this pattern. i.e, Any prop that is a function that a component uses to know what to render is technically a “render prop”. Lets take an example with the children prop for render props,\n\n     \n```javascript\n     <Mouse\n       children={(mouse) => (\n         <p>\n           The mouse position is {mouse.x}, {mouse.y}\n         </p>\n       )}\n     />\n```\n\n Actually children prop doesn’t need to be named in the list of “attributes” in JSX element. Instead, you can keep it directly inside element,\n\n     \n```javascript\n     <Mouse>\n       {(mouse) => (\n         <p>\n           The mouse position is {mouse.x}, {mouse.y}\n         </p>\n       )}\n     </Mouse>\n```\n\n While using this above technique(without any name), explicitly state that children should be a function in your propTypes.\n\n     \n```javascript\n     Mouse.propTypes = {\n       children: PropTypes.func.isRequired,\n     };\n```" },
  { q: "২০৬. পিওর কম্পোনেন্টের সাথে রেন্ডার প্রপসের সমস্যাগুলো কী কী?", qEn: "206. What are the problems of using render props with pure components?", a: "রেন্ডার প্রপস প্রতিবার নতুন ফাংশন তৈরি করে, যা পিওর কম্পোনেন্টকে রি-রেন্ডার করতে বাধ্য করে।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "If you create a function inside a render method, it negates the purpose of pure component. Because the shallow prop comparison will always return false for new props, and each render in this case will generate a new value for the render prop. You can solve this issue by defining the render function as instance method." },
  { q: "২০৭. উইন্ডোয়িং টেকনিক কী?", qEn: "207. What is windowing technique?", a: "শুধু দৃশ্যমান আইটেমগুলো রেন্ডার করা (ভার্চুয়াল স্ক্রল)। লাইব্রেরি: react-window, react-virtualized।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "Windowing is a technique that only renders a small subset of your rows at any given time, and can dramatically reduce the time it takes to re-render the components as well as the number of DOM nodes created. If your application renders long lists of data then this technique is recommended. Both react-window and react-virtualized are popular windowing libraries which provides several reusable components for displaying lists, grids, and tabular data." },
  { q: "২০৮. JSX-এ কীভাবে ফলসি মান প্রিন্ট করবেন?", qEn: "208. How do you print falsy values in JSX?", a: "স্ট্রিংয়ে কনভার্ট করে: {String(false)} অথবা {false.toString()}\n\nউদাহরণ:\n```javascript\nconst el = <div className=\"box\">Hi</div>;\n```", aEn: "The falsy values such as false, null, undefined, and true are valid children but they don't render anything. If you still want to display them then you need to convert it to string. Let's take an example on how to convert to a string,\n\n     \n```javascript\n     <div>My JavaScript variable is {String(myVariable)}.</div>\n```" },
  { q: "২০৯. পোর্টালের সাধারণ ব্যবহারের ক্ষেত্র কী কী?", qEn: "209. What is the typical use case of portals?", a: "মোডাল\n\nটুলটিপ\n\nড্রপডাউন মেনু\n\nটোস্ট নোটিফিকেশন\n\nউদাহরণ:\n```javascript\ncreatePortal(children, document.body)\n```", aEn: "React Portals are primarily used to render UI components such as modals, tooltips, dropdowns, hovercards, and notifications outside of their parent component's DOM tree. This helps avoid common CSS issues caused by parent elements, such as:\n\n  `overflow: hidden` on parent elements clipping or hiding child elements like modals or tooltips,\n  stacking context and `z-index` conflicts created by parent containers that prevent child elements from appearing above other content.\n\n That means, you need to visually “break out” of its container. By rendering these UI elements into a separate DOM node (often directly under ` `), portals ensure they appear above all other content and are not restricted by the parent’s CSS or layout constraints, resulting in correct positioning and visibility regardless of the parent’s styling." },
  { q: "২১০. আনকন্ট্রোল্ড কম্পোনেন্টের ডিফল্ট ভ্যালু কীভাবে সেট করবেন?", qEn: "210. How do you set default value for uncontrolled component?", a: "defaultValue (ইনপুটের জন্য) বা defaultChecked (চেকবক্সের জন্য) ব্যবহার করুন।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "In React, the value attribute on form elements will override the value in the DOM. With an uncontrolled component, you might want React to specify the initial value, but leave subsequent updates uncontrolled. To handle this case, you can specify a defaultValue attribute instead of value.\n\n     \n```javascript\n     render() {\n       return (\n         <form onSubmit={this.handleSubmit}>\n           <label>\n             User Name:\n             <input\n               defaultValue=\"John\"\n               type=\"text\"\n               ref={this.input} />\n           </label>\n           <input type=\"submit\" value=\"Submit\" />\n         </form>\n       );\n     }\n```\n\n The same applies for `select` and `textArea` inputs. But you need to use defaultChecked for `checkbox` and `radio` inputs." },
  { q: "২১১. আপনার প্রিয় রিয়্যাক্ট স্ট্যাক কী?", qEn: "211. What is your favorite React stack?", a: "উদাহরণ: React + TypeScript + Redux Toolkit + React Router + Tailwind CSS + Vite\n\n```javascript\ndispatch({ type: 'ACTION', payload: data });\n```", aEn: "Even though the tech stack varies from developer to developer, the most popular stack is used in react boilerplate project code. It mainly uses Redux and redux-saga for state management and asynchronous side-effects, react-router for routing purpose, styled-components for styling react components, axios for invoking REST api, and other supported stack such as webpack, reselect, ESNext, Babel.\n You can clone the project https://github.com/react-boilerplate/react-boilerplate and start working on any new react project." },
  { q: "২১২. রিয়েল DOM ও ভার্চুয়াল DOM-এর পার্থক্য কী?", qEn: "212. What is the difference between Real DOM and Virtual DOM?", a: "| রিয়েল DOM | ভার্চুয়াল DOM |\n| ধীর (রি-ফ্লো, রি-পেইন্ট) | দ্রুত (মেমোরিতে) |\n| সরাসরি ম্যানিপুলেশন | ডিফিং ও বATCH আপডেট |\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "Below are the main differences between Real DOM and Virtual DOM,\n\n | Real DOM | Virtual DOM |\n | ------------------------------------ | ------------------------------------ |\n | Updates are slow | Updates are fast |\n | DOM manipulation is very expensive. | DOM manipulation is very easy |\n | You can update HTML directly. | You Can’t directly update HTML |\n | It causes too much of memory wastage | There is no memory wastage |\n | Creates a new DOM if element updates | It updates the JSX if element update |" },
  { q: "২১৩. রিয়্যাক্ট অ্যাপ্লিকেশনে কীভাবে বুটস্ট্র্যাপ যোগ করবেন?", qEn: "213. How to add Bootstrap to a react application?", a: "CDN লিংক দিয়ে অথবা react-bootstrap প্যাকেজ ইন্সটল করে।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "Bootstrap can be added to your React app in a three possible ways,\n\n 1. Using the Bootstrap CDN:\n This is the easiest way to add bootstrap. Add both bootstrap CSS and JS resources in a head tag.\n 2. Bootstrap as Dependency:\n If you are using a build tool or a module bundler such as Webpack, then this is the preferred option for adding Bootstrap to your React application\n        \n```javascript\n        npm install bootstrap\n```\n 3. React Bootstrap Package:\n In this case, you can add Bootstrap to our React app is by using a package that has rebuilt Bootstrap components to work particularly as React components. Below packages are popular in this category,\n 1. react-bootstrap\n 2. reactstrap" },
  { q: "২১৪. শীর্ষ ওয়েবসাইট বা অ্যাপ্লিকেশনের তালিকা দিন যা রিয়্যাক্ট ব্যবহার করে?", qEn: "214. Can you list down top websites or applications using react as front end framework?", a: "ফেসবুক, ইনস্টাগ্রাম, হোয়াটসঅ্যাপ ওয়েব, নেটফ্লিক্স, আয়ারবিএনবি, ইউবার, ড্রপবক্স।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "Below are the `top 10 websites` using React as their front-end framework,\n\n 1. Facebook\n 2. Uber\n 3. Instagram\n 4. WhatsApp\n 5. Khan Academy\n 6. Airbnb\n 7. Dropbox\n 8. Flipboard\n 9. Netflix\n 10. PayPal" },
  { q: "২১৫. রিয়্যাক্টে CSS-in-JS টেকনিক ব্যবহার করার পরামর্শ দেওয়া হয় কি?", qEn: "215. Is it recommended to use CSS In JS technique in React?", a: "ছোট-মাঝারি প্রকল্পে হ্যাঁ। বড় প্রকল্পে কিছুটা পারফরম্যান্স ওভারহেড থাকতে পারে।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "React does not have any opinion about how styles are defined but if you are a beginner then good starting point is to define your styles in a separate \\.css file as usual and refer to them using className. This functionality is not part of React but came from third-party libraries. But If you want to try a different approach(CSS-In-JS) then styled-components library is a good option." },
  { q: "২১৬. সব ক্লাস কম্পোনেন্ট কি হুকস দিয়ে রি-রাইট করা দরকার?", qEn: "216. Do I need to rewrite all my class components with hooks?", a: "না। পুরানো কোড কাজ করতে থাকবে। নতুন কোডে হুকস ব্যবহার করুন।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "No. But you can try Hooks in a few components(or new components) without rewriting any existing code. Because there are no plans to remove classes in ReactJS." },
  { q: "২১৭. রিয়্যাক্ট হুকস দিয়ে কীভাবে ডেটা ফেচ করবেন?", qEn: "217. What is useEffect hook? How to fetch data with React Hooks?", a: "useEffect-এর ভেতর ফেচ করুন:\n\nউদাহরণ:\n\n```javascript\nuseEffect(() => { fetchData().then(setData); }, []);\n```", aEn: "The `useEffect` hook is a React Hook that lets you perform side effects in function components. Side effects are operations that interact with the outside world or system and aren't directly related to rendering UI — such as fetching data, setting up subscriptions, timers, manually manipulating the DOM, etc.\n\n In function components, useEffect replaces the class component lifecycle methods(`componentDidMount`, `componentDidUpdate` and `componentWillUnmount`) with a single, unified API. \n\n Syntax\n     \n```javascript\n     useEffect(() => {\n        // Side effect logic here\n\n        return () => {\n        // Cleanup logic (optional)\n        };\n        }, [dependencies]);\n```\n This effect hook can be used to fetch data from an API and to set the data in the local state of the component with the useState hook’s update function.\n\n Here is an example of fetching a list of ReactJS articles from an API using fetch.\n\n     \n```javascript\n     import React from \"react\";\n\n     function App() {\n       const [data, setData] = React.useState({ hits: [] });\n\n       React.useEffect(() => {\n         fetch(\"http://hn.algolia.com/api/v1/search?query=react\")\n           .then((response) => response.json())\n           .then((data) => setData(data));\n       }, []);\n\n       return (\n         <ul>\n           {data.hits.map((item) => (\n             <li key={item.objectID}>\n               <a href={item.url}>{item.title}</a>\n             </li>\n           ))}\n         </ul>\n       );\n     }\n\n     export default App;\n```\n\n A popular way to simplify this is by using the library axios.\n\n We provided an empty array as second argument to the useEffect hook to avoid activating it on component updates. This way, it only fetches on component mount." },
  { q: "২১৮. হুকস কি ক্লাসের সব ব্যবহারের ক্ষেত্র কভার করে?", qEn: "218. Is Hooks cover all use cases for classes?", a: "প্রায় সব, তবে getSnapshotBeforeUpdate ও componentDidCatch এর সরাসরি হুকস বিকল্প নেই।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "Hooks doesn't cover all use cases of classes but there is a plan to add them soon. Currently there are no Hook equivalents to the uncommon getSnapshotBeforeUpdate and componentDidCatch lifecycles yet." },
  { q: "২১৯. হুকস সাপোর্টের জন্য স্টেবল রিলিজ কোনটি?", qEn: "219. What is the stable release for hooks support?", a: "রিয়্যাক্ট ১৬.৮ (ফেব্রুয়ারি ২০১৯)।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "React includes a stable implementation of React Hooks in 16.8 release for below packages\n\n 1. React DOM\n 2. React DOM Server\n 3. React Test Renderer\n 4. React Shallow Renderer" },
  { q: "২২০. useState-এ কেন অ্যারে ডিস্ট্রাকচারিং (স্কয়ার ব্র্যাকেট) ব্যবহার করি?", qEn: "220. Why do we use array destructuring (square brackets notation) in `useState`?", a: "যাতে ভেরিয়েবলের নাম নিজের মতো করে দেওয়া যায়। অবজেক্ট ডিস্ট্রাকচারিং করলে প্রপার্টির নাম ঠিক করে দিতে হয়।\n\nউদাহরণ:\n```javascript\nconst [value, setValue] = useState(initial);\n```", aEn: "When we declare a state variable with `useState`, it returns a pair — an array with two items. The first item is the current value, and the second is a function that updates the value. Using [0] and [1] to access them is a bit confusing because they have a specific meaning. This is why we use array destructuring instead.\n\n For example, the array index access would look as follows:\n\n     \n```javascript\n     var userStateVariable = useState(\"userProfile\"); // Returns an array pair\n     var user = userStateVariable[0]; // Access first item\n     var setUser = userStateVariable[1]; // Access second item\n```\n\n Whereas with array destructuring the variables can be accessed as follows:\n\n     \n```javascript\n     const [user, setUser] = useState(\"userProfile\");\n```" },
  { q: "২২১. হুকস প্রবর্তনের জন্য কোন সোর্সগুলো ব্যবহার করা হয়েছিল?", qEn: "221. What are the sources used for introducing hooks?", a: "ক্লাসের জটিলতা (this বাইন্ডিং)\n\nলজিক রিইউজের কঠিনতা (HOCs, রেন্ডার প্রপস)\n\nপারফরম্যান্স ইস্যু\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "Hooks got the ideas from several different sources. Below are some of them,\n\n 1. Previous experiments with functional APIs in the react-future repository\n 2. Community experiments with render prop APIs such as Reactions Component\n 3. State variables and state cells in DisplayScript.\n 4. Subscriptions in Rx.\n 5. Reducer components in ReasonReact." },
  { q: "২২২. কীভাবে ওয়েব কম্পোনেন্টের ইম্পেরেটিভ API অ্যাক্সেস করবেন?", qEn: "222. How do you access imperative API of web components?", a: "ref ব্যবহার করে: <my-element ref={el => el?.doSomething()} />\n\nউদাহরণ:\n```javascript\nref ব্যবহার করে: <my-element ref={el => el?.doSomething()} />\n```", aEn: "Web Components often expose an imperative API to implement its functions. You will need to use a ref to interact with the DOM node directly if you want to access imperative API of a web component. But if you are using third-party Web Components, the best solution is to write a React component that behaves as a wrapper for your Web Component." },
  { q: "২২৩. ফরমিক কী?", qEn: "223. What is formik?", a: "ফর্ম বিল্ডিং, ভ্যালিডেশন, সাবমিট হ্যান্ডলিং সহজ করার রিয়্যাক্ট লাইব্রেরি।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "Formik is a small react form library that helps you with the three major problems,\n\n 1. Getting values in and out of form state\n 2. Validation and error messages\n 3. Handling form submission" },
  { q: "২২৪. অ্যাসিঙ্ক্রোনাস কল হ্যান্ডলিংয়ের জন্য সাধারণ মিডলওয়্যার পছন্দগুলো কী কী?", qEn: "224. What are typical middleware choices for handling asynchronous calls in Redux?", a: "Redux Thunk (সহজ)\n\nRedux Saga (জটিল)\n\nRedux Observable (RxJS)\n\nRedux Toolkit Query\n\nউদাহরণ:\n```javascript\ndispatch({ type: 'ACTION', payload: data });\n```", aEn: "Some of the popular middleware choices for handling asynchronous calls in Redux eco system are `Redux Thunk, Redux Promise, Redux Saga`." },
  { q: "২২৫. ব্রাউজার কি JSX কোড বোঝে?", qEn: "225. Do browsers understand JSX code?", a: "না। বাবেল বা অন্য ট্রান্সপাইলার JSX-কে রিয়্যাক্ট.createElement()-এ রূপান্তর করে।\n\nউদাহরণ:\n```javascript\nconst el = <div className=\"box\">Hi</div>;\n```", aEn: "No, browsers can't understand JSX code. You need a transpiler to convert your JSX to regular Javascript that browsers can understand. The most widely used transpiler right now is Babel." },
  { q: "২২৬. রিয়্যাক্টে ডেটা ফ্লো বর্ণনা করতে পারেন?", qEn: "226. Describe about data flow in react?", a: "ওয়ান-ওয়ে ডাউনওয়ার্ড ডেটা ফ্লো: প্যারেন্ট → প্রপস → চাইল্ড। চাইল্ড ইভেন্ট প্যারেন্টে পাঠালে স্টেট আপডেট হয়।\n\nউদাহরণ:\nParent → props → child; child event → parent state update।", aEn: "React implements one-way reactive data flow using props which reduce boilerplate and is easier to understand than traditional two-way data binding." },
  { q: "২২৭. মবিএক্স কী?", qEn: "227. What is MobX?", a: "একটি সিম্পল, স্কেলেবল স্টেট ম্যানেজমেন্ট লাইব্রেরি যা রিঅ্যাকটিভ প্রোগ্রামিং ব্যবহার করে।\n\nউদাহরণ:\n```javascript\n// observable state + autorun\n```", aEn: "MobX is a simple, scalable and battle tested state management solution for applying functional reactive programming (TFRP). For ReactJS application, you need to install below packages,\n     \n```bash\n     npm install mobx --save\n     npm install mobx-react --save\n```" },
  { q: "২২৮. রিডাক্স ও মবিএক্সের মধ্যে পার্থক্যগুলো কী কী?", qEn: "228. What are the differences between Redux and MobX?", a: "| রিডাক্স | মবিএক্স |\n| ইমিউটেবল | মিউটেবল |\n| অনেক বয়লারপ্লেট | কম বয়লারপ্লেট |\n| ডেভ টুলস চমৎকার | ডেভ টুলস ভালো |\n\nউদাহরণ:\n```javascript\ndispatch({ type: 'ACTION', payload: data });\n```", aEn: "Below are the main differences between Redux and MobX,\n\n | Topic | Redux | MobX |\n | ------------- | ------------------------------------------------------------- | ---------------------------------------------------------------------- |\n | Definition | It is a javascript library for managing the application state | It is a library for reactively managing the state of your applications |\n | Programming | It is mainly written in ES6 | It is written in JavaScript(ES5) |\n | Data Store | There is only one large store exist for data storage | There is more than one store for storage |\n | Usage | Mainly used for large and complex applications | Used for simple applications |\n | Performance | Need to be improved | Provides better performance |\n | How it stores | Uses JS Object to store | Uses observable to store the data |" },
  { q: "২২৯. রিয়্যাক্টজেএস শেখার আগে কি ES6 শেখা উচিত?", qEn: "229. Should I learn ES6 before learning ReactJS?", a: "হাঁ। ক্লাস, অ্যারো ফাংশন, ডিস্ট্রাকচারিং, স্প্রেড অপারেটর – এগুলো রিয়্যাক্টে ব্যাপক ব্যবহৃত।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "No, you don’t have to learn es2015/es6 to learn react. But you may find many resources or React ecosystem uses ES6 extensively. Let's see some of the frequently used ES6 features,\n\n 1. Destructuring: To get props and use them in a component\n\n        \n```javascript\n        // in es 5\n        var someData = this.props.someData;\n        var dispatch = this.props.dispatch;\n\n        // in es6\n        const { someData, dispatch } = this.props;\n```\n\n 2. Spread operator: Helps in passing props down into a component\n\n        \n```javascript\n        // in es 5\n        <SomeComponent someData={this.props.someData} dispatch={this.props.dispatch} />\n\n        // in es6\n        <SomeComponent {...this.props} />\n```\n\n 3. Arrow functions: Makes compact syntax\n        \n```javascript\n        // es 5\n        var users = usersList.map(function (user) {\n          return <li>{user.name}</li>;\n        });\n        // es 6\n        const users = usersList.map((user) => <li>{user.name}</li>);\n```" },
  { q: "২৩০. কনকারেন্ট রেন্ডারিং কী?", qEn: "230. What is Concurrent Rendering?", a: "রিয়্যাক্টের একটি মোড যা রেন্ডারিং কাজ ইন্টারাপ্টেবল করে। উচ্চ-প্রাধান্যের আপডেটকে আগে সুযোগ দেয়।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "The Concurrent rendering makes React apps to be more responsive by rendering component trees without blocking the main UI thread. It allows React to interrupt a long-running render to handle a high-priority event. i.e, When you enabled concurrent Mode, React will keep an eye on other tasks that need to be done, and if there's something with a higher priority it will pause what it is currently rendering and let the other task finish first. You can enable this in two ways,\n\n     \n```javascript\n     // 1. Part of an app by wrapping with ConcurrentMode\n     <React.unstable_ConcurrentMode>\n       <Something />\n     </React.unstable_ConcurrentMode>;\n\n     // 2. Whole app using createRoot\n     ReactDOM.unstable_createRoot(domNode).render(<App />);\n```" },
  { q: "২৩১. অ্যাসিঙ্ক মোড ও কনকারেন্ট মোডের পার্থক্য কী?", qEn: "231. What is the difference between async mode and concurrent mode?", a: "অ্যাসিঙ্ক মোড ছিল পুরোনো নাম, কনকারেন্ট মোড নতুন নাম। উভয়ই একই জিনিস।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "Both refers the same thing. Previously concurrent Mode being referred to as \"Async Mode\" by React team. The name has been changed to highlight React’s ability to perform work on different priority levels. So it avoids the confusion from other approaches to Async Rendering." },
  { q: "২৩২. রিয়্যাক্ট ১৬.৯-এ জাভাস্ক্রিপ্ট URL ব্যবহার করা যাবে?", qEn: "232. Can I use javascript urls in react16.9?", a: "না। javascript: URL ডিফল্টভাবে ব্লক করা হয় (নিরাপত্তা কারণে)।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "Yes, you can use javascript: URLs but it will log a warning in the console. Because URLs starting with javascript: are dangerous by including unsanitized output in a tag like ` ` and create a security hole.\n\n     \n```javascript\n     const companyProfile = {\n       website: \"javascript: alert('Your website is hacked')\",\n     };\n     // It will log a warning\n     <a href={companyProfile.website}>More details</a>;\n```\n\n Remember that the future versions will throw an error for javascript URLs." },
  { q: "২৩৩. হুকসের জন্য ESLint প্লাগইনের উদ্দেশ্য কী?", qEn: "233. What is the purpose of eslint plugin for hooks?", a: "হুকসের নিয়ম (শুধু টপ-লেভেল, ডিপেন্ডেন্সি অ্যারে) স্বয়ংক্রিয়ভাবে চেক ও ফিক্স করে।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "The ESLint plugin enforces rules of Hooks to avoid bugs. It assumes that any function starting with ”use” and a capital letter right after it is a Hook. In particular, the rule enforces that,\n\n 1. Calls to Hooks are either inside a PascalCase function (assumed to be a component) or another useSomething function (assumed to be a custom Hook).\n 2. Hooks are called in the same order on every render." },
  { q: "২৩৪. রিয়্যাক্টে ইম্পেরেটিভ ও ডিক্লারেটিভ প্রোগ্রামিংয়ের পার্থক্য কী?", qEn: "234. What is the difference between Imperative and Declarative in React?", a: "ইম্পেরেটিভ: কীভাবে করতে হবে তা বলেন (DOM ম্যানিপুলেশন)\n\nডিক্লারেটিভ: কী দেখতে চান তা বলেন (JSX)\n\nউদাহরণ:\n```javascript\nconst el = <div className=\"box\">Hi</div>;\n```", aEn: "Imagine a simple UI component, such as a \"Like\" button. When you tap it, it turns blue if it was previously grey, and grey if it was previously blue.\n\n The imperative way of doing this would be:\n\n     \n```javascript\n     if (user.likes()) {\n       if (hasBlue()) {\n         removeBlue();\n         addGrey();\n       } else {\n         removeGrey();\n         addBlue();\n       }\n     }\n```\n\n Basically, you have to check what is currently on the screen and handle all the changes necessary to redraw it with the current state, including undoing the changes from the previous state. You can imagine how complex this could be in a real-world scenario.\n\n In contrast, the declarative approach would be:\n\n     \n```javascript\n     if (this.state.liked) {\n       return <blueLike />;\n     } else {\n       return <greyLike />;\n     }\n```\n\n Because the declarative approach separates concerns, this part of it only needs to handle how the UI should look in a specific state, and is therefore much simpler to understand." },
  { q: "২৩৫. রিয়্যাক্টজেএস-এর সাথে টাইপস্ক্রিপ্ট ব্যবহারের সুবিধাগুলো কী কী?", qEn: "235. What are the benefits of using TypeScript with ReactJS?", a: "টাইপ সেফটি\n\nঅটোকমপ্লিট\n\nরিফ্যাক্টরিং সহজ\n\nরানটাইম এরর কমে\n\nউদাহরণ:\n```typescript\ninterface Props { name: string }\nfunction Hello({ name }: Props) { return <h1>{name}</h1>; }\n```", aEn: "Below are some of the benefits of using TypeScript with ReactJS,\n\n 1. It is possible to use latest JavaScript features\n 2. Use of interfaces for complex type definitions\n 3. IDEs such as VS Code was made for TypeScript\n 4. Avoid bugs with the ease of readability and Validation" },
  { q: "২৩৬. কনটেক্সট API স্টেট ম্যানেজমেন্ট ব্যবহার করে পৃষ্ঠা রিফ্রেশে কীভাবে ব্যবহারকারী লগইন রাখবেন?", qEn: "236. How do you make sure that user remains authenticated on page refresh while using Context API State Management?", a: "লোকালস্টোরেজ/কুকিতে টোকেন সংরক্ষণ করুন। অ্যাপ লোড হলে টোকেন যাচাই করে স্টেট সেট করুন।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "When a user logs in and reload, to persist the state generally we add the load user action in the useEffect hooks in the main App.js. While using Redux, loadUser action can be easily accessed.\n\n App.js\n\n     \n```javascript\n     import { loadUser } from \"../actions/auth\";\n     store.dispatch(loadUser());\n```\n\n - But while using Context API, to access context in App.js, wrap the AuthState in index.js so that App.js can access the auth context. Now whenever the page reloads, no matter what route you are on, the user will be authenticated as loadUser action will be triggered on each re-render.\n\n index.js\n\n     \n```javascript\n     import React from \"react\";\n     import ReactDOM from \"react-dom\";\n     import App from \"./App\";\n     import AuthState from \"./context/auth/AuthState\";\n\n     ReactDOM.render(\n       <React.StrictMode>\n         <AuthState>\n           <App />\n         </AuthState>\n       </React.StrictMode>,\n       document.getElementById(\"root\")\n     );\n```\n\n App.js\n\n     \n```javascript\n     const authContext = useContext(AuthContext);\n\n     const { loadUser } = authContext;\n\n     useEffect(() => {\n       loadUser();\n     }, []);\n```\n\n loadUser\n\n     \n```javascript\n     const loadUser = async () => {\n       const token = sessionStorage.getItem(\"token\");\n\n       if (!token) {\n         dispatch({\n           type: ERROR,\n         });\n       }\n       setAuthToken(token);\n\n       try {\n         const res = await axios(\"/api/auth\");\n\n         dispatch({\n           type: USER_LOADED,\n           payload: res.data.data,\n         });\n       } catch (err) {\n         console.error(err);\n       }\n     };\n```" },
  { q: "২৩৭. নতুন JSX ট্রান্সফর্মের সুবিধাগুলো কী কী?", qEn: "237. What are the benefits of new JSX transform?", a: "import React from 'react' লাগে না\n\nসামান্য ছোট বান্ডল\n\nভবিষ্যতের ফিচার সাপোর্ট\n\nউদাহরণ:\n```javascript\nconst el = <div className=\"box\">Hi</div>;\n```", aEn: "There are three major benefits of new JSX transform,\n\n 1. It is possible to use JSX without importing React packages\n 2. The compiled output might improve the bundle size in a small amount\n 3. The future improvements provides the flexibility to reduce the number of concepts to learn React." },
  { q: "২৩৮. নতুন JSX ট্রান্সফর্ম কীভাবে পুরোনো থেকে আলাদা?", qEn: "238. How is the new JSX transform different from old transform??", a: "পুরোনো: React.createElement → নতুন: _jsx ফাংশন (স্বয়ংক্রিয় ইম্পোর্ট হয়)।\n\nউদাহরণ:\n```javascript\nconst el = <div className=\"box\">Hi</div>;\n```", aEn: "The new JSX transform doesn’t require React to be in scope. i.e, You don't need to import React package for simple scenarios.\n\n Let's take an example to look at the main differences between the old and the new transform,\n\n Old Transform:\n\n     \n```javascript\n     import React from \"react\";\n\n     function App() {\n       return <h1>Good morning!!</h1>;\n     }\n```\n\n Now JSX transform convert the above code into regular JavaScript as below,\n\n     \n```javascript\n     import React from \"react\";\n\n     function App() {\n       return React.createElement(\"h1\", null, \"Good morning!!\");\n     }\n```\n\n New Transform:\n\n The new JSX transform doesn't require any React imports\n\n     \n```javascript\n     function App() {\n       return <h1>Good morning!!</h1>;\n     }\n```\n\n Under the hood JSX transform compiles to below code\n\n     \n```javascript\n     import { jsx as _jsx } from \"react/jsx-runtime\";\n\n     function App() {\n       return _jsx(\"h1\", { children: \"Good morning!!\" });\n     }\n```\n\n Note: You still need to import React to use Hooks." },
  { q: "২৩৯. রিয়্যাক্ট সার্ভার কম্পোনেন্ট কী?", qEn: "239. What are React Server components?", a: "সার্ভারে এক্সিকিউট হয়, HTML উৎপন্ন করে, ক্লায়েন্টে JS বান্ডলে যায় না। জিরো বান্ডল সাইজ।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "React Server Component is a way to write React component that gets rendered in the server-side with the purpose of improving React app performance. These components allow us to load components from the backend.\n\n Note: React Server Components is still under development and not recommended for production yet." },
  { q: "২৪০. প্রপ ড্রিলিং কী?", qEn: "240. What is prop drilling?", a: "প্রপসকে অনেক স্তরের মধ্যে দিয়ে পাস করা, যেখানে মধ্যবর্তী কম্পোনেন্টগুলির ঐ প্রপসের প্রয়োজন নেই। কনটেক্সট বা রিডাক্স সমাধান।\n\nউদাহরণ:\n```javascript\ndispatch({ type: 'ACTION', payload: data });\n```", aEn: "Prop Drilling is the process by which you pass data from one component of the React Component tree to another by going through other components that do not need the data but only help in passing it around." },
  { q: "২৪১. useState ও useRef হুকের মধ্যে পার্থক্য কী?", qEn: "241. What is the difference between useState and useRef hook?", a: "| useState | useRef |\n| মান পরিবর্তনে রি-রেন্ডার করে | মান পরিবর্তনে রি-রেন্ডার করে না |\n| অ্যাসিঙ্ক আপডেট | সিঙ্ক্রোনাস আপডেট |\n\nউদাহরণ:\n| useState | useRef |\n| change → re-render | change → no re-render |", aEn: "1. useState causes components to re-render after state updates whereas useRef doesn’t cause a component to re-render when the value or state changes.\n Essentially, useRef is like a “box” that can hold a mutable value in its (`.current`) property.\n 2. useState allows us to update the state inside components. While useRef allows referencing DOM elements and tracking values." },
  { q: "২৪২. র‍্যাপার কম্পোনেন্ট কী?", qEn: "242. What is a wrapper component?", a: "একটি কম্পোনেন্ট যা অন্যান্য কম্পোনেন্টকে ঘিরে রাখে (লেআউট, কন্ডিশনাল রেন্ডারিং, ডেটা প্রোভাইডার)।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "A wrapper in React is a component that wraps or surrounds another component or group of components. It can be used for a variety of purposes such as adding additional functionality, styling, or layout to the wrapped components.\n\n For example, consider a simple component that displays a message:\n\n     \n```javascript\n     const Message = ({ text }) => {\n       return <p>{text}</p>;\n     };\n```\n\n We can create a wrapper component that will add a border to the message component:\n\n     \n```javascript\n     const MessageWrapper = (props) => {\n       return (\n         <div style={{ border: \"1px solid black\" }}>\n           <Message {...props} />\n         </div>\n       );\n     };\n```\n\n Now we can use the MessageWrapper component instead of the Message component and the message will be displayed with a border:\n\n     \n```javascript\n     <MessageWrapper text=\"Hello World\" />\n```\n\n Wrapper component can also accept its own props and pass them down to the wrapped component, for example, we can create a wrapper component that will add a title to the message component:\n\n     \n```javascript\n     const MessageWrapperWithTitle = ({ title, ...props }) => {\n       return (\n         <div>\n           <h3>{title}</h3>\n           <Message {...props} />\n         </div>\n       );\n     };\n```\n\n Now we can use the MessageWrapperWithTitle component and pass title props:\n\n     \n```javascript\n     <MessageWrapperWithTitle title=\"My Message\" text=\"Hello World\" />\n```\n\n This way, the wrapper component can add additional functionality, styling, or layout to the wrapped component while keeping the wrapped component simple and reusable." },
  { q: "২৪৩. useEffect ও useLayoutEffect-এর মধ্যে পার্থক্য কী?", qEn: "243. What are the differences between useEffect and useLayoutEffect hooks?", a: "| useEffect | useLayoutEffect |\n| ব্রাউজার পেইন্টের পরে চলে | ব্রাউজার পেইন্টের আগে চলে |\n| বেশিরভাগ ক্ষেত্রে | DOM মাপা, সিঙ্ক্রোনাস আপডেট |\n\nউদাহরণ:\n```javascript\nuseEffect(() => {\n  // side effect\n  return () => cleanup();\n}, [deps]);\n```", aEn: "useEffect and useLayoutEffect are both React hooks that can be used to synchronize a component with an external system, such as a browser API or a third-party library. However, there are some key differences between the two:\n\n - Timing: useEffect runs after the browser has finished painting, while useLayoutEffect runs synchronously before the browser paints. This means that useLayoutEffect can be used to measure and update layout in a way that feels more synchronous to the user.\n\n - Browser Paint: useEffect allows browser to paint the changes before running the effect, hence it may cause some visual flicker. useLayoutEffect synchronously runs the effect before browser paints and hence it will avoid visual flicker.\n\n - Execution Order: The order in which multiple useEffect hooks are executed is determined by React and may not be predictable. However, the order in which multiple useLayoutEffect hooks are executed is determined by the order in which they were called.\n\n - Error handling: useEffect has a built-in mechanism for handling errors that occur during the execution of the effect, so that it does not crash the entire application. useLayoutEffect does not have this mechanism, and errors that occur during the execution of the effect will crash the entire application.\n\n In general, it's recommended to use useEffect as much as possible, because it is more performant and less prone to errors. useLayoutEffect should only be used when you need to measure or update layout, and you can't achieve the same result using useEffect." },
  { q: "২৪৪. ফাংশনাল ও ক্লাস কম্পোনেন্টের মধ্যে পার্থক্য কী?", qEn: "244. What are the differences between Functional and Class Components?", a: "| ফাংশনাল | ক্লাস |\n| কম কোড | বেশি কোড |\n| হুকস | লাইফসাইকেল মেথড |\n| রি-রেন্ডার অপটিমাইজেশনে React.memo | PureComponent |\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "There are two different ways to create components in ReactJS. The main differences are listed down as below,\n\n ## 1. Syntax:\n\n The class components uses ES6 classes to create the components. It uses `render` function to display the HTML content in the webpage.\n\n The syntax for class component looks like as below.\n\n     \n```javascript\n     class App extends React.Component {\n       render() {\n         return <h1>This is a class component</h1>;\n       }\n     }\n```\n\n Note: The Pascal Case is the recommended approach to provide naming to a component.\n\n Functional component has been improved over the years with some added features like Hooks. Here is a syntax for functional component.\n\n     \n```javascript\n     function App() {\n       return (\n         <div className=\"App\">\n           <h1>Hello, I'm a function component</h1>\n         </div>\n       );\n     }\n```\n\n ## 2. State:\n\n State contains information or data about a component which may change over time.\n\n In class component, you can update the state when a user interacts with it or server updates the data using the `setState()` method. The initial state is going to be assigned in the `Constructor()` method using the `this.state` object and it is possible to assign different data types such as string, boolean, numbers, etc.\n\n A simple example showing how we use the setState() and constructor():\n\n     \n```javascript\n     class App extends Component {\n       constructor() {\n         super();\n         this.state = {\n           message: \"This is a class component\",\n         };\n       }\n       updateMessage() {\n         this.setState({\n           message: \"Updating the class component\",\n         });\n       }\n       render() {\n         return (\n           <>\n             <h1>{this.state.message}</h1>\n             <button\n               onClick={() => {\n                 this.updateMessage();\n               }}>\n               Click!!\n             </button>\n           </>\n         );\n       }\n     }\n```\n\n You didn't use state in functional components because it was only supported in class components. But over the years hooks have been implemented in functional components which enables to use state too.\n\n The `useState()` hook can used to implement state in functional components. It returns an array with two items: the first item is current state and the next one is a function (setState) that updates the value of the current state.\n\n Let's see an example to demonstrate the state in functional components,\n\n     \n```javascript\n     function App() {\n       const [message, setMessage] = useState(\"This is a functional component\");\n       const updateMessage = () => {\n         setMessage(\"Updating the functional component\");\n       };\n       return (\n         <div className=\"App\">\n           <h1>{message} </h1>\n           <button onClick={updateMessage}>Click me!!</button>\n         </div>\n       );\n     }\n```\n\n ## 3. Props:\n\n Props are referred to as \"properties\". The props are passed into React component just like arguments passed to a function. In other words, they are similar to HTML attributes.\n\n The props are accessible in child class component using `this.props` as shown in below example,\n\n     \n```javascript\n     class Child extends React.Component {\n       render() {\n         return (\n           <h1>\n             {\" \"}\n             This is a functional component and component name is {\n               this.props.name\n             }{\" \"}\n           </h1>\n         );\n       }\n     }\n\n     class Parent extends React.Component {\n       render() {\n         return (\n           <div className=\"Parent\">\n             <Child name=\"First child component\" />\n             <Child name=\"Second child component\" />\n           </div>\n         );\n       }\n     }\n```\n\n Props in functional components are similar to that of the class components but the difference is the absence of 'this' keyword.\n\n     \n```javascript\n     function Child(props) {\n       return (\n         <h1>\n           This is a child component and the component name is{props.name}\n         </h1>\n       );\n     }\n\n     function Parent() {\n       return (\n         <div className=\"Parent\">\n           <Child name=\"First child component\" />\n           <Child name=\"Second child component\" />\n         </div>\n       );\n     }\n```" },
  { q: "২৪৫. রিয়্যাক্টে স্ট্রিক্ট মোড কী?", qEn: "245. What is strict mode in React?", a: "ডেভেলপমেন্টে অতিরিক্ত চেক ও ওয়ার্নিং দেয়ার টুল। কম্পোনেন্টকে <React.StrictMode> দিয়ে র‍্যাপ করুন।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "`React.StrictMode` is a useful component for highlighting potential problems in an application. Just like ` `, ` ` does not render any extra DOM elements. It activates additional checks and warnings for its descendants. These checks apply for _development mode_ only.\n\n     ```jsx harmony\n     import { StrictMode } from \"react\";\n\n     function App() {\n       return (\n         <div>\n           <Header />\n           <StrictMode>\n             <div>\n               <ComponentOne />\n               <ComponentTwo />\n             </div>\n           </StrictMode>\n           <Header />\n         </div>\n       );\n     }\n     ```\n\n In the example above, the _strict mode_ checks apply to ` ` and ` ` components only. i.e., Part of the application only.\n\n Note: Frameworks such as NextJS has this flag enabled by default." },
  { q: "২৪৬. স্ট্রিক্ট মোডের সুবিধা কী কী?", qEn: "246. What is the benefit of strict mode?", a: "বিপজ্জনক লাইফসাইকেল সনাক্তকরণ\n\nলিগ্যাসি রেফ API ওয়ার্নিং\n\nঅপ্রত্যাশিত পার্শ্বপ্রতিক্রিয়া সনাক্তকরণ\n\nউদাহরণ:\n```javascript\nconst ref = useRef(null);\n```", aEn: "The will be helpful in the below cases,\n\n 1. To find the bugs caused by impure rendering where the components will re-render twice.\n 2. To find the bugs caused by missing cleanup of effects where the components will re-run effects one more extra time.\n 3. Identifying components with unsafe lifecycle methods.\n 4. Warning about legacy string ref API usage.\n 5. Detecting unexpected side effects.\n 6. Detecting legacy context API.\n 7. Warning about deprecated findDOMNode usage" },
  { q: "২৪৭. স্ট্রিক্ট মোড কেন দুবার রেন্ডার করে?", qEn: "247. Why does strict mode render twice in React?", a: "অপবিত্র রিডিউসার ও সাইড ইফেক্ট সনাক্ত করতে। প্রোডাকশনে একবারই রেন্ডার হয়।\n\nউদাহরণ:\n```javascript\nuseEffect(() => {\n  // side effect\n  return () => cleanup();\n}, [deps]);\n```", aEn: "StrictMode renders components twice in development mode(not production) in order to detect any problems with your code and warn you about those problems. This is used to detect accidental side effects in the render phase. If you used `create-react-app` development tool then it automatically enables StrictMode by default.\n\n     \n```javascript\n     const root = createRoot(document.getElementById(\"root\"));\n     root.render(\n       <StrictMode>\n         <App />\n       </StrictMode>\n     );\n```\n\n If you want to disable this behavior then you can simply remove `strict` mode.\n\n     \n```javascript\n     const root = createRoot(document.getElementById(\"root\"));\n     root.render(<App />);\n```\n\n To detect side effects the following functions are invoked twice:\n\n 1. Function component bodies, excluding the code inside event handlers.\n 2. Functions passed to `useState`, `useMemo`, or `useReducer` (any other Hook)\n 3. Class component's `constructor`, `render`, and `shouldComponentUpdate` methods\n 4. Class component static `getDerivedStateFromProps` method\n 5. State updater functions" },
  { q: "২৪৮. JSX-এর নিয়মগুলো কী কী?", qEn: "248. What are the rules of JSX?", a: "একটি রুট এলিমেন্ট লাগে (ফ্র্যাগমেন্ট ব্যবহার করতে পারেন)\n\nসব ট্যাগ বন্ধ করতে হবে\n\ncamelCase অ্যাট্রিবিউট\n\nclassName ব্যবহার করুন\n\nউদাহরণ:\n```javascript\nconst el = <div className=\"box\">Hi</div>;\n```", aEn: "The below 3 rules needs to be followed while using JSX in a react application.\n\n 1. Return a single root element:\n If you are returning multiple elements from a component, wrap them in a single parent element. Otherwise you will receive the below error in your browser console.\n\n `html Adjacent JSX elements must be wrapped in an enclosing tag.`\n\n 2. All the tags needs to be closed:\n Unlike HTML, all tags needs to closed explicitly with in JSX. This rule applies for self-closing tags(like hr, br and img tags) as well.\n 3. Use camelCase naming:\n It is suggested to use camelCase naming for attributes in JSX. For example, the common attributes of HTML elements such as `class`, `tabindex` will be used as `className` and `tabIndex`. \n Note: There is an exception for `aria-` and `data-` attributes which should be lower cased all the time." },
  { q: "২৪৯. একাধিক JSX ট্যাগ কেন র‍্যাপ করতে হয়?", qEn: "249. What is the reason behind multiple JSX tags to be wrapped?", a: "কারণ JSX শুধু একটি এক্সপ্রেশন রিটার্ন করতে পারে। ফ্র্যাগমেন্ট বা div দিয়ে র‍্যাপ করলে একটি এক্সপ্রেশন হয়।\n\nউদাহরণ:\n```javascript\nconst el = <div className=\"box\">Hi</div>;\n```", aEn: "Behind the scenes, JSX is transformed into plain javascript objects. It is not possible to return two or more objects from a function without wrapping into an array. This is the reason you can't simply return two or more JSX tags from a function without\n wrapping them into a single parent tag or a Fragment." },
  { q: "২৫০. অ্যারে ভেরিয়েবল মিউটেশন কীভাবে প্রতিরোধ করবেন?", qEn: "250. How do you prevent mutating array variables?", a: "স্প্রেড অপারেটর ([...arr]), concat(), filter(), map() ব্যবহার করুন (এরা নতুন অ্যারে রিটার্ন করে)।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "The preexisting variables outside of the function scope including state, props and context leads to a mutation and they result in unpredictable bugs during the rendering stage. The below points should be taken care while working with arrays variables.\n\n 1. You need to take copy of the original array and perform array operations on it for the rendering purpose. This is called local mutation.\n 2. Avoid triggering mutation methods such as push, pop, sort and reverse methods on original array. It is safe to use filter, map and slice method because they create a new array." },
  { q: "২৫১. ক্যাপচার ফেজ ইভেন্ট কী?", qEn: "251. What are capture phase events?", a: "DOM ইভেন্টের ক্যাপচার ফেজে ইভেন্ট হ্যান্ডলার চালাতে ইভেন্ট নামের শেষে Capture যোগ করুন: onClickCapture।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "The `onClickCapture` React event is helpful to catch all the events of child elements irrespective of event propagation logic or even if the events propagation stopped. This is useful if you need to log every click events for analytics purpose.\n\n For example, the below code triggers the click event of parent first followed by second level child eventhough leaf child button elements stops the propagation.\n\n     \n```javascript\n     <div onClickCapture={() => alert(\"parent\")}>\n       <div onClickCapture={() => alert(\"child\")}>\n         <button onClick={(e) => e.stopPropagation()} />\n         <button onClick={(e) => e.stopPropagation()} />\n       </div>\n     </div>\n```\n\n The event propagation for the above code snippet happens in the following order:\n\n 1. It travels downwards in the DOM tree by calling all `onClickCapture` event handlers.\n 2. It executes `onClick` event handler on the target element.\n 3. It travels upwards in the DOM tree by call all `onClick` event handlers above to it." },
  { q: "২৫২. রিয়্যাক্ট কীভাবে স্ক্রিন আপডেট করে?", qEn: "252. How does React updates screen in an application?", a: "স্টেট পরিবর্তন → ভার্চুয়াল DOM ডিফ → রিকনসিলিয়েশন → শুধু পরিবর্তিত অংশ রিয়েল DOM-এ কমিট।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "React updates UI in three steps,\n\n 1. Triggering or initiating a render: The component is going to triggered for render in two ways.\n\n 1. Initial render: When the app starts, you can trigger the initial render by calling `creatRoot` with the target DOM node followed by invoking component's `render` method. For example, the following code snippet renders `App` component on root DOM node.\n\n        \n```javascript\n        import { createRoot } from \"react-dom/client\";\n\n        const root = createRoot(document.getElementById(\"root\"));\n        root.render(<App />);\n```\n\n 2. Re-render when the state updated: When you update the component state using the state setter function, the componen't state automatically queues for a render.\n\n 2. Rendering components: After triggering a render, React will call your components to display them on the screen. React will call the root component for initial render and call the function component whose state update triggered the render. This is a recursive process for all nested components of the target component.\n\n 3. Commit changes to DOM: After calling components, React will modify the DOM for initial render using `appendChild()` DOM API and apply minimal necessary DOM updates for re-renders based on differences between rerenders." },
  { q: "২৫৩. রিয়্যাক্ট কীভাবে একাধিক স্টেট আপডেট ব্যাচ করে?", qEn: "253. How does React batch multiple state updates?", a: "এক ইভেন্ট হ্যান্ডলারের ভেতরের সব setState একত্র করে একবারে রি-রেন্ডার করে।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "React prevents component from re-rendering for each and every state update by grouping multiple state updates within an event handler. This strategy improves the application performance and this process known as batching. The older version of React only supported batching for browser events whereas React18 supported for asynchronous actions, timeouts and intervals along with native events. This improved version of batching is called automatic batching.\n\n Let's demonstrate this automatic batching feature with a below example.\n\n      \n```javascript\n      import { useState } from \"react\";\n\n      export default function BatchingState() {\n        const [count, setCount] = useState(0);\n        const [message, setMessage] = useState(\"batching\");\n\n        console.log(\"Application Rendered\");\n\n        const handleAsyncFetch = () => {\n          fetch(\"https://jsonplaceholder.typicode.com/users/1\").then(() => {\n            // Automatic Batching re-render only once\n            setCount(count + 1);\n            setMessage(\"users fetched\");\n          });\n        };\n\n        return (\n          <>\n            <h1>{count}</h1>\n            <button onClick={handleAsyncFetch}>Click Me!</button>\n          </>\n        );\n      }\n```\n\n The preceding code updated two state variables with in an event handler. However, React will perform automatic batching feature and the component will be re-rendered only once for better performance." },
  { q: "২৫৪. স্বয়ংক্রিয় ব্যাচিং প্রতিরোধ করা সম্ভব?", qEn: "254. Is it possible to prevent automatic batching?", a: "হাঁ। flushSync ব্যবহার করে: flushSync(() => setCount(c => c+1))\n\nউদাহরণ:\n```javascript\nহাঁ। flushSync ব্যবহার করে: flushSync(() => setCount(c => c+1))\n```", aEn: "Yes, it is possible to prevent automatic batching default behavior. There might be cases where you need to re-render your component after each state update or updating one state depends on another state variable. Considering this situation, React introduced `flushSync` method from `react-dom` API for the usecases where you need to flush state updates to DOM immediately.\n\n The usage of `flushSync` method within an `onClick` event handler will be looking like as below,\n\n      \n```javascript\n      import { flushSync } from \"react-dom\";\n\n      const handleClick = () => {\n        flushSync(() => {\n          setClicked(!clicked); //Component will create a re-render here\n        });\n\n        setCount(count + 1); // Component will create a re-render again here\n      };\n```\n\n In the above click handler, React will update DOM at first using flushSync and second time updates DOM because of the counter setter function by avoiding automatic batching." },
  { q: "২৫৫. রিয়্যাক্ট হাইড্রেশন কী?", qEn: "255. What is React hydration?", a: "SSR-এ সার্ভার থেকে আসা HTML-এর সাথে রিয়্যাক্ট ইভেন্ট লিসেনার অ্যাটাচ করার প্রক্রিয়া।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "React hydration is used to add client-side JavaScript interactivity to pre-rendered static HTML generated by the server. It is used only for server-side rendering(SSR) to enhance the initial rendering time and make it SEO friendly application. This hydration acts as a bridge to reduce the gap between server side and client-side rendering.\n\n After the page loaded with generated static HTML, React will add application state and interactivity by attaching all event handlers for the respective elements. Let's demonstrate this with an example.\n\n Consider that React DOM API(using `renderToString`) generated HTML for ` ` component which contains ` ` element to increment the counter.\n\n      \n```javascript\n      import {useState} from 'react';\n      import { renderToString } from 'react-dom/server';\n\n      export default function App() {\n        const [count, setCount] = React.useState(0);\n\n        return (\n          <h1>Counter</h1>\n          <button onClick={() => setCount(prevCount => prevCount + 1)}>\n            {count} times\n          </button>\n          );\n      }\n\n      const html = renderToString(<App />);\n```\n\n The above code generates the below HTML with a header text and button component without any interactivity.\n\n      \n```html\n      <h1>Counter</h1>\n      <button>\n        <!-- -->0<!-- -->\n        times\n      </button>\n```\n\n At this stage `hydrateRoot` API can be used to perform hydration by attaching `onClick` event handler.\n\n      \n```javascript\n      import { hydrateRoot } from \"react-dom/client\";\n      import App from \"./App.js\";\n\n      hydrateRoot(document.getElementById(\"root\"), <App />);\n```\n\n After this step, you are able to run React application on server-side and hydrating the javascript bundle on client-side for smooth user experience and SEO purposes." },
  { q: "২৫৬. স্টেটের ভেতর অবজেক্ট কীভাবে আপডেট করবেন?", qEn: "256. How do you update objects inside state?", a: "স্প্রেড অপারেটর: setUser({...user, name: 'নতুন নাম'})\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "You cannot update the objects which exists in the state directly. Instead, you should create a fresh new object (or copy from the existing object) and update the latest state using the newly created object. Eventhough JavaScript objects are mutable, you need to treat objects inside state as read-only while updating the state.\n\n Let's see this comparison with an example. The issue with regular object mutation approach can be described by updating the user details fields of `Profile` component. The properties of `Profile` component such as firstName, lastName and age details mutated in an event handler as shown below.\n\n      \n```javascript\n      import { useState } from \"react\";\n\n      export default function Profile() {\n        const [user, setUser] = useState({\n          firstName: \"John\",\n          lastName: \"Abraham\",\n          age: 30,\n        });\n\n        function handleFirstNameChange(e) {\n          user.firstName = e.target.value;\n        }\n\n        function handleLastNameChange(e) {\n          user.lastName = e.target.value;\n        }\n\n        function handleAgeChange(e) {\n          user.age = e.target.value;\n        }\n\n        return (\n          <>\n            <label>\n              First name:\n              <input value={user.firstName} onChange={handleFirstNameChange} />\n            </label>\n            <label>\n              Last name:\n              <input value={user.lastName} onChange={handleLastNameChange} />\n            </label>\n            <label>\n              Age:\n              <input value={user.age} onChange={handleAgeChange} />\n            </label>\n            <p>\n              Profile:\n              {person.firstName} {person.lastName} ({person.age})\n            </p>\n          </>\n        );\n      }\n```\n\n Once you run the application with above user profile component, you can observe that user profile details won't be update upon entering the input fields.\n This issue can be fixed by creating a new copy of object which includes existing properties through spread syntax(...obj) and add changed values in a single event handler itself as shown below.\n\n      \n```javascript\n      handleProfileChange(e) {\n        setUser({\n        ...user,\n          [e.target.name]: e.target.value\n        });\n      }\n```\n\n The above event handler is concise instead of maintaining separate event handler for each field. Now, UI displays the updated field values as expected without an issue." },
  { q: "২৫৭. স্টেটের ভেতর নেস্টেড অবজেক্ট কীভাবে আপডেট করবেন?", qEn: "257. How do you update nested objects inside state?", a: "প্রতিটি স্তরে স্প্রেড করুন: setState({...state, address: {...state.address, city: 'ঢাকা'}})\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "You cannot simply use spread syntax for all kinds of objects inside state. Because spread syntax is shallow and it copies properties for one level deep only. If the object has nested object structure, UI doesn't work as expected with regular JavaScript nested property mutation. Let's demonstrate this behavior with an example of User object which has address nested object inside of it.\n\n      \n```javascript\n      const user = {\n        name: \"John\",\n        age: 32,\n        address: {\n          country: \"Singapore\",\n          postalCode: 440004,\n        },\n      };\n```\n\n If you try to update the country nested field in a regular javascript fashion(as shown below) then user profile screen won't be updated with latest value.\n\n      \n```javascript\n      user.address.country = \"Germany\";\n```\n\n This issue can be fixed by flattening all the fields into a top-level object or create a new object for each nested object and point it to it's parent object. In this example, first you need to create copy of address object and update it with the latest value. Later, the address object should be linked to parent user object something like below.\n\n      \n```javascript\n      setUser({\n        ...user,\n        address: {\n          ...user.address,\n          country: \"Germany\",\n        },\n      });\n```\n\n This approach is bit verbose and not easy for deep hierarchical state updates. But this workaround can be used for few levels of nested objects without much hassle." },
  { q: "২৫৮. স্টেটের ভেতর অ্যারে কীভাবে আপডেট করবেন?", qEn: "258. How do you update arrays inside state?", a: "যোগ: [...arr, newItem]\n\nমুছ: arr.filter(i => i !== id)\n\nআপডেট: arr.map(i => i.id === id ? {...i, name} : i)\n\nউদাহরণ:\n```javascript\nমুছ: arr.filter(i => i !== id)\nআপডেট: arr.map(i => i.id === id ? {...i, name} : i)\n```", aEn: "Eventhough arrays in JavaScript are mutable in nature, you need to treat them as immutable while storing them in a state. That means, similar to objects, the arrays cannot be updated directly inside state. Instead, you need to create a copy of the existing array and then set the state to use newly copied array.\n\n To ensure that arrays are not mutated, the mutation operations like direct direct assignment(arr[1]='one'), push, pop, shift, unshift, splice etc methods should be avoided on original array. Instead, you can create a copy of existing array with help of array operations such as filter, map, slice, spread syntax etc.\n\n For example, the below push operation doesn't add the new todo to the total todo's list in an event handler.\n\n      \n```javascript\n      onClick = {\n        todos.push({\n          id: id+1,\n          name: name\n        })\n      }\n```\n\n This issue is fixed by replacing push operation with spread syntax where it will create a new array and the UI updated with new todo.\n\n      \n```javascript\n      onClick = {\n        [\n          ...todos,\n          { id: id+1, name: name }\n        ]\n      }\n```" },
  { q: "২৫৯. স্টেট আপডেটের জন্য ইমার লাইব্রেরি কীভাবে ব্যবহার করবেন?", qEn: "259. How do you use immer library for state updates?", a: "produce ফাংশন দিয়ে ড্রাফটে মিউটেট করুন:\n\nউদাহরণ:\n\n```javascript\nsetState(produce(draft => { draft.name = 'নতুন' }))\n```", aEn: "Immer library enforces the immutability of state based on copy-on-write mechanism. It uses JavaScript proxy to keep track of updates to immutable states. Immer has 3 main states as below,\n\n 1. Current state: It refers to actual state\n 2. Draft state: All new changes will be applied to this state. In this state, draft is just a proxy of the current state.\n 3. Next state: It is formed after all mutations applied to the draft state\n\n Immer can be used by following below instructions,\n\n 1. Install the dependency using `npm install use-immer` command\n 2. Replace `useState` hook with `useImmer` hook by importing at the top\n 3. The setter function of `useImmer` hook can be used to update the state.\n\n For example, the mutation syntax of immer library simplifies the nested address object of user state as follows,\n\n      \n```javascript\n      import { useImmer } from \"use-immer\";\n      const [user, setUser] = useImmer({\n        name: \"John\",\n        age: 32,\n        address: {\n          country: \"Singapore\",\n          postalCode: 440004,\n        },\n      });\n\n      //Update user details upon any event\n      setUser((draft) => {\n        draft.address.country = \"Germany\";\n      });\n```\n\n The preceding code enables you to update nested objects with a conceise mutation syntax." },
  { q: "২৬০. সরাসরি স্টেট মিউটেশন প্রতিরোধের সুবিধাগুলো কী কী?", qEn: "260. What are the benefits of preventing the direct state mutations?", a: "টাইম ট্রাভেল ডিবাগিং\n\nরি-রেন্ডার অপটিমাইজেশন\n\nবাগ কমায়\n\nপ্রেডিক্টেবিলিটি\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```" },
  { q: "২৬১. স্টেট আপডেটের জন্য পছন্দনীয় ও অ-পছন্দনীয় অ্যারে অপারেশনগুলো কী কী?", qEn: "261. What are the preferred and non-preferred array operations for updating the state?", a: "| পছন্দনীয় | অ-পছন্দনীয় |\n| map, filter, concat, spread | push, pop, shift, unshift, splice |\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "The below table represent preferred and non-preferred array operations for updating the component state.\n\n | Action | Preferred | Non-preferred |\n | --------- | -------------------- | -------------------------- |\n | Adding | concat, [...arr] | push, unshift |\n | Removing | filter, slice | pop, shift, splice |\n | Replacing | map | splice, arr[i] = someValue |\n | sorting | copying to new array | reverse, sort |\n\n If you use Immer library then you can able to use all array methods without any problem." },
  { q: "২৬২. নেস্টেড ফাংশন কম্পোনেন্ট ডিফাইন করলে কী হবে?", qEn: "262. What will happen by defining nested function components?", a: "প্রতি রি-রেন্ডারে ফাংশন রি-ক্রিয়েট হয়। পারফরম্যান্স খারাপ হয় এবং স্টেট রিসেট হয়।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "Technically it is possible to write nested function components but it is not suggested to write nested function definitions. Because it leads to unexpected bugs and performance issues." },
  { q: "২৬৩. নন-লিস্ট আইটেমের জন্য কী ব্যবহার করতে পারি?", qEn: "263. Can I use keys for non-list items?", a: "হাঁ। কী যেকোনো জায়গায় ব্যবহার করা যায়, বিশেষ করে অ্যানিমেশন বা ফর্ম ক্ষেত্র চিহ্নিত করতে।\n\nউদাহরণ:\n```javascript\n// সংক্ষিপ্ত বলুন, তারপর ছোট কোড দেখান\nfunction Demo() { return <p>Example</p>; }\n```", aEn: "Keys are primarily used for rendering list items but they are not just for list items. You can also use them React to distinguish components. By default, React uses order of the components in" },
  { q: "২৬৪. রিডিউসার লেখার জন্য নির্দেশিকাগুলো কী কী?", qEn: "264. What are the guidelines to be followed for writing reducers?", a: "স্টেট ও অ্যাকশনের উপর ভিত্তি করে নতুন স্টেট রিটার্ন করুন\n\nকখনো মিউটেট করবেন না\n\nসাইড ইফেক্ট করবেন না (API কল, ডেট ফাংশন)\n\nউদাহরণ:\n```javascript\nuseEffect(() => {\n  // side effect\n  return () => cleanup();\n}, [deps]);\n```", aEn: "There are two guidelines to be taken care while writing reducers in your code.\n\n 1. Reducers must be pure without mutating the state. That means, same input always returns the same output. These reducers run during rendering time similar to state updater functions. So these functions should not send any requests, schedule time outs and any other side effects.\n\n 2. Each action should describe a single user interaction even though there are multiple changes applied to data. For example, if you \"reset\" registration form which has many user input fields managed by a reducer, it is suggested to send one \"reset\" action instead of creating separate action for each fields. The proper ordering of actions should reflect the user interactions in the browser and it helps a lot for debugging purpose." },
  { q: "২৬৫. useReducer হুক কী? এর ব্যবহার বর্ণনা করতে পারেন?", qEn: "265. How does ReactJS work behind the scenes?", a: "জটিল স্টেট লজিকের জন্য useState-এর বিকল্প। একটি রিডিউসার ফাংশন নেয় এবং বর্তমান স্টেট ও ডিস্প্যাচ ফাংশন রিটার্ন করে।\n\nউদাহরণ:\n```javascript\nconst [state, dispatch] = useReducer(reducer, { count: 0 });\n```", aEn: "ReactJS is a powerful JavaScript library for building user interfaces. While it appears simple on the surface, React performs a lot of complex operations behind the scenes to efficiently update the UI. Here's an overview of how it works internally:\n\n #### 1. Virtual DOM & Component Rendering\n\n React doesn't manipulate the real DOM directly. Instead, it uses a Virtual DOM — a lightweight JavaScript representation of the UI.\n\n When a component renders (e.g., ` `):\n\n  React executes the component function (e.g., `App()`).\n  Hooks like `useState` are registered and tracked in order.\n  React builds a Virtual DOM tree from the returned JSX.\n  This virtual DOM is a plain JS object that describes the desired UI.\n\n This process ensures fast and efficient rendering before React decides how to update the real DOM.\n\n #### 2. React Fiber Architecture\n\n React’s core engine is called Fiber, introduced in React 16. Fiber is a reimplementation of the React reconciliation algorithm with the following capabilities:\n\n  Breaks rendering work into units of work (fiber nodes).\n  Enables interruptible rendering (important for responsiveness).\n  Supports priority scheduling and concurrent rendering.\n\n Each Fiber node represents a component and stores:\n\n  The component type (function/class).\n  Props, state, and effects.\n  Links to parent, child, and sibling fibers.\n\n #### 3. Reconciliation (Diffing Algorithm)\n\n When state or props change:\n\n  React re-executes the component to produce a new virtual DOM.\n  It compares the new virtual DOM to the previous one using an efficient diffing algorithm.\n  React determines the minimal set of DOM changes required.\n\n This process is known as reconciliation.\n\n #### 4. Commit Phase (Real DOM Updates)\n\n Once reconciliation is done:\n\n  React enters the commit phase.\n  It applies calculated changes to the real DOM.\n  It also runs side effects like `useEffect` or `useLayoutEffect`.\n\n This is the only time React interacts directly with the browser DOM.\n\n #### 5. Hooks and State Management\n\n With Hooks (like `useState`, `useEffect`):\n\n  React keeps an internal list of hooks per component.\n  Hooks are identified by their order in the function.\n  When state updates occur, React re-renders the component and re-runs the hooks in the same order.\n\n #### 6. React Scheduler\n\n React uses an internal Scheduler to control how updates are prioritized:\n\n  Urgent tasks like clicks and inputs are processed immediately.\n  Non-urgent tasks (like data fetching) can be delayed or paused.\n  This improves responsiveness and allows for time slicing in Concurrent Mode." },
  { q: "২৬৬. useState ও useReducer কীভাবে তুলনা করবেন?", qEn: "266. How is `useReducer` Different from `useState`?", a: "| useState | useReducer |\n| সরল (বুলিয়ান, নাম্বার, স্ট্রিং) | জটিল (অবজেক্ট, অ্যারে) |\n| নিকটবর্তী স্টেট | পরবর্তী স্টেট পূর্ববর্তীর উপর নির্ভরশীল |\n\nউদাহরণ:\n```javascript\nconst [value, setValue] = useState(initial);\n```", aEn: "There are notable differences between `useState` and `useReducer` hooks.\n \n | Feature | `useState` | `useReducer` |\n |-----------------------|--------------------------------------|---------------------------------------|\n | State complexity | Simple (one variable or flat object) | Complex, multi-part or deeply nested |\n | Update style | Direct (e.g. `setState(x)`) | Through actions (e.g. `dispatch({})`) |\n | Update logic | In component | In reducer function |\n | Reusability & testing | Less reusable | Highly reusable & testable |" },
  { q: "২৬৭. useContext হুকের সাথে কনটেক্সট কীভাবে কাজ করে?", qEn: "267. What is useContext? What are the steps to follow for useContext?", a: "কনটেক্সটের বর্তমান মান পড়তে useContext(MyContext) ব্যবহার করুন। কনটেক্সট পরিবর্তন হলে কম্পোনেন্ট রি-রেন্ডার হয়।\n\nউদাহরণ:\n```javascript\nconst theme = useContext(ThemeContext);\n```", aEn: "The `useContext` hook is a built-in React Hook that lets you access the value of a context inside a functional component without needing to wrap it in a component.\n\n It helps you avoid prop drilling (passing props through multiple levels) by allowing components to access shared data like themes, authentication status, or user preferences.\n\n The usage of useContext involves three main steps:\n #### Step 1 : Create the Context\n \n Use `React.createContext()` to create a context object.\n \n        \n```javascript\n        import React, { createContext } from 'react'; \n    \n        const ThemeContext = createContext(); // default value optional\n```\n \n You typically export this so other components can import it.\n\n #### Step 2: Provide the Context Value\n \n Wrap your component tree (or a part of it) with the `Context.Provider` and pass a `value` prop.\n \n        \n```javascript\n        function App() {\n            return ( \n                <ThemeContext.Provider value=\"dark\">\n                   <MyComponent />\n                </ThemeContext.Provider>\n            ); \n        }\n```\n \n Now any component inside ` ` can access the context value.\n\n #### Step 3: Consume the Context with `useContext`\n \n In any functional component inside the Provider, use the `useContext` hook:\n \n        \n```javascript\n        import { useContext } from 'react'; \n        function MyComponent() {\n            const theme = useContext(ThemeContext); // theme = \"dark\"\n            return <p>Current Theme: {theme}</p>; \n        }\n```" },
  { q: "২৬৮. useContext হুকের ব্যবহারের ক্ষেত্রগুলো কী কী?", qEn: "268. What are the use cases of useContext hook?", a: "থিম (ডার্ক/লাইট)\n\nভাষা (i18n)\n\nপ্রমাণীকরণ (ইউজার ডেটা)\n\nগ্লোবাল কনফিগারেশন\n\nউদাহরণ:\n```javascript\nconst value = useContext(MyContext);\n```", aEn: "The `useContext` hook in React is used to share data across components without having to pass props manually through each level. Here are some common and effective use cases:\n\n 1. Theme Customization \n `useContext` can be used to manage application-wide themes, such as light and dark modes, ensuring consistent styling and enabling user-driven customization.\n 2. Localization and Internationalization \n It supports localization by providing translated strings or locale-specific content to components, adapting the application for users in different regions.\n 3. User Authentication and Session Management \n `useContext` allows global access to authentication status and user data. This enables conditional rendering of components and helps manage protected routes or user-specific UI elements.\n 4. Shared Modal or Sidebar Visibility \n It's ideal for managing the visibility of shared UI components like modals, drawers, or sidebars, especially when their state needs to be controlled from various parts of the app.\n 5. Combining with `useReducer` for Global State Management \n When combined with `useReducer`, `useContext` becomes a powerful tool for managing more complex global state logic. This pattern helps maintain cleaner, scalable state logic without introducing external libraries like Redux.\n Some of the common use cases of useContext are listed below," },
  { q: "২৬৯. কখন ক্লায়েন্ট ও সার্ভার কম্পোনেন্ট ব্যবহার করবেন?", qEn: "269. When to use client and server components?", a: "সার্ভার কম্পোনেন্ট: স্ট্যাটিক কনটেন্ট, ডাটাবেস অ্যাক্সেস\nক্লায়েন্ট কম্পোনেন্ট: ইন্টারঅ্যাকটিভ UI, হুকস, ইভেন্ট লিসেনার\n\nউদাহরণ:\n```javascript\n// Hooks — ছোট working example দেখান\n```", aEn: "You can efficiently build nextjs application if you are aware about which part of the application needs to use client components and which other parts needs to use server components. The common cases of both client and server components are listed below:\n\n Client components:\n 1. Whenever your need to add interactivity and event listeners such as onClick(), onChange(), etc to the pages\n 2. If you need to use State and Lifecycle Effects like useState(), useReducer(), useEffect() etc.\n 3. If there is a requirement to use browser-only APIs.\n 4. If you need to implement custom hooks that depend on state, effects, or browser-only APIs.\n 5. There are React Class components in the pages.\n\n Server components:\n 1. If the component logic is about data fetching.\n 2. If you need to access backend resources directly.\n 3. When you need to keep sensitive information((access tokens, API keys, etc) ) on the server.\n 4. If you want reduce client-side JavaScript and placing large dependencies on the server." },
  { q: "২৭০. নেক্সট.জেএস-এর পেজ রাউটার ও অ্যাপ রাউটারের মধ্যে পার্থক্যগুলো কী কী?", qEn: "270. What are the differences between page router and app router in nextjs?", a: "| পেজ রাউটার | অ্যাপ রাউটার |\n| পেজ ডিরেক্টরি | অ্যাপ ডিরেক্টরি |\n| getServerSideProps | সার্ভার কম্পোনেন্ট ডিফল্ট |\n| ঐতিহ্যবাহী | রিয়্যাক্ট ১৮+ ফিচার |\n\nউদাহরণ:\n```javascript\n<Link to=\"/about\">About</Link>\n```", aEn: "Next.js provides two different routing systems: the Page Router (traditional) and the App Router (introduced in Next.js 13). The App Router is built on React Server Components and offers more powerful features for modern web applications.\n\n Here are the main differences between them:\n\n | Feature | Page Router | App Router |\n |---------|-------------|------------|\n | Directory | Uses `pages/` directory | Uses `app/` directory |\n | Routing | File-based routing with files like `pages/about.js` | File-based routing with folders and special files like `app/about/page.js` |\n | Components | All components are Client Components by default | All components are Server Components by default |\n | Layouts | Custom `_app.js` and `_document.js` for shared layouts | Native nested layouts using `layout.js` files |\n | Data Fetching | Uses `getServerSideProps`, `getStaticProps`, and `getInitialProps` | Uses `async/await` in Server Components with native `fetch` |\n | Loading States | Manual implementation required | Built-in `loading.js` for streaming and suspense |\n | Error Handling | Custom `_error.js` page | Built-in `error.js` for error boundaries at any level |\n | Streaming | Limited support | Built-in support for streaming with Suspense |\n | Server Actions | Not available | Native support for server-side mutations |\n | Metadata | Using `Head` component from `next/head` | Native Metadata API with `metadata` object or `generateMetadata` function |\n | Rendering | SSR, SSG, ISR, and CSR | SSR, SSG, ISR, CSR plus React Server Components |\n\n Example of Page Router structure:\n     \n```javascript\n     pages/\n     ├── index.js          // Home page (/)\n     ├── about.js          // About page (/about)\n     ├── _app.js           // Custom App component\n     ├── _document.js      // Custom Document\n     └── posts/\n         └── [id].js       // Dynamic route (/posts/:id)\n```\n\n Example of App Router structure:\n     \n```javascript\n     app/\n     ├── page.js           // Home page (/)\n     ├── layout.js         // Root layout\n     ├── loading.js        // Loading UI\n     ├── error.js          // Error UI\n     ├── about/\n     │   └── page.js       // About page (/about)\n     └── posts/\n         └── [id]/\n             └── page.js   // Dynamic route (/posts/:id)\n```\n\n Note: The App Router is recommended for new Next.js applications as it provides better performance, simpler data fetching patterns, and improved developer experience with React Server Components." },
  { q: "২৭১. useMemo() হুক বর্ণনা করতে পারেন?", qEn: "271. Can you describe the useMemo() Hook?", a: "ব্যয়বহুল গণনার ফলাফল মেমোয়েজ করে। নির্ভরশীলতা পরিবর্তিত হলেই শুধু পুনঃগণনা করে।\n\nউদাহরণ:\n```javascript\nconst expensive = useMemo(() => compute(a, b), [a, b]);\n```", aEn: "The `useMemo()` Hook in React is used to optimize performance by memoizing the result of expensive calculations. It ensures that a function is only re-executed when its dependencies change, preventing unnecessary computations on every re-render.\n\n #### Syntax\n\n     \n```javascript\n      const memoizedValue = useMemo(() => computeExpensiveValue(arg), [dependencies]);\n```\n - `computeExpensiveValue`: \n A function that returns the computed result.\n\n - `dependencies`: \n An array of values that, when changed, will cause the memoized function to re-run.\n\n If the dependencies haven’t changed since the last render, React returns the cached result instead of re-running the function.\n\n Let's exaplain the usage of `useMemo` hook with an example of user search and its respective filtered users list.\n\n #### Example: Memoizing a Filtered List\n      \n```javascript\n      import React, { useState, useMemo } from 'react';\n\n      const users = [\n        { id: 1, name: 'Sudheer' },\n        { id: 2, name: 'Brendon' },\n        { id: 3, name: 'Charlie' },\n        { id: 4, name: 'Dary' },\n        { id: 5, name: 'Eden' }\n      ];\n\n      export default function UserSearch({ users }) {\n        const [searchTerm, setSearchTerm] = useState('');\n        const [counter, setCounter] = useState(0);\n\n        // Memoize the filtered user list based on the search term\n        const filteredUsers = useMemo(() => {\n          console.log(\"Filtering users...\");\n          return users.filter(user =>\n            user.name.toLowerCase().includes(searchTerm.toLowerCase())\n          );\n        }, [searchTerm]);\n\n        return (\n          <div>\n            <h2>Counter: {counter}</h2>\n            <button onClick={() => setCounter(prev => prev + 1)}>Increment Counter</button>\n\n            <h2>Search Users</h2>\n            <input\n              type=\"text\"\n              value={searchTerm}\n              onChange={(e) => setSearchTerm(e.target.value)}\n              placeholder=\"Enter name\"\n            />\n\n            <ul>\n              {filteredUsers.map(user => (\n                <li key={user.id}>{user.name}</li>\n              ))}\n            </ul>\n          </div>\n        );\n      }\n```\n\n In the above example:\n - The filteredUsers list is only recomputed when searchTerm changes.\n - Pressing the \"Increment Counter\" button does not trigger the filtering logic again, as it's not a dependency.\n - The console will only log \"Filtering users...\" when the search term updates." },
  { q: "২৭২. হুকস কি ক্লাস কম্পোনেন্টে ব্যবহার করা যায়?", qEn: "272. Can Hooks be used in class components?", a: "না। হুকস শুধুমাত্র ফাংশনাল কম্পোনেন্ট বা কাস্টম হুকসে ব্যবহার করা যায়।\n\nউদাহরণ:\n```javascript\n// Hooks — ছোট working example দেখান\n```", aEn: "No, Hooks cannot be used inside class components. They are specially designed for function components. This is because hooks depend on the sequence in which they are called during a component’s render, something that's only guaranteed in functional components. However, both class and function components can coexist in the same application." },
  { q: "২৭৩. আপডেটার ফাংশন কী? সব ক্ষেত্রে কি আপডেটার ফাংশন ব্যবহার করা উচিত?", qEn: "273. What is an updater function? Should an updater function be used in all cases?", a: "setCount(c => c + 1) - আপডেটার ফাংশন। পূর্ববর্তী স্টেটের উপর নির্ভরশীল আপডেটের জন্য ব্যবহার করবেন।\n\nউদাহরণ:\n```javascript\nsetCount(c => c + 1) - আপডেটার ফাংশন। পূর্ববর্তী স্টেটের উপর নির্ভরশীল আপডেটের জন্য ব্যবহার করবেন।\n```", aEn: "An updater function is a form of `setState` where you pass a function instead of a direct value. This function receives the previous state as an argument and returns the next state.\n \n The updater function expression looks like below,\n     \n```javascript\n     setCount(prevCount => prevCount + 1); // Safe and predictable\n```\n Here, `prevCount => prevCount + 1` is the updater function.\n\n In the React community, there's often a recommendation to use updater functions when updating state that depends on its previous value. This helps prevent unexpected behaviors that can arise from working with outdated or \"stale\" state.\n\n While using an updater function is a good habit, it's not always necessary. In most cases, React batches updates and ensures that the state is up-to-date at the beginning of the event handler, so you typically don’t run into stale state issues during a single synchronous event.\n However, if you’re doing multiple updates to the same state variable within a single handler, using the updater form ensures that each update correctly uses the latest state value, rather than a potentially outdated one.\n\n Example: Multiple Updates in One Handler\n     \n```javascript\n     function handleCount() {\n        setCounter(a => a + 1);\n        setCounter(a => a + 1);\n        setCounter(a => a + 1);\n     }\n```\n\n In this example, `a => a + 1` is an updater function. React queues these updater functions and applies them sequentially, each using the most recent state value. As a result, the counter will correctly increment by 3.\n\n In many cases, such as setting state based on user input or assigning static values, you don’t need the updater function:\n     \n```javascript\n     setName('Sudheer');\n```" },
  { q: "২৭৪. useState কি ফাংশন ইনিশিয়াল ভ্যালু নিতে পারে?", qEn: "274. Can useState take a function as an initial value?", a: "হাঁ। লেজি ইনিশিয়ালাইজেশন: useState(() => expensiveComputation())\n\nউদাহরণ:\n```javascript\nconst [n] = useState(() => JSON.parse(localStorage.getItem('x')));\n```", aEn: "Yes, `useState` can take a function as an initial value, and this is a useful feature in React called lazy initialization. This function is also known as initializer function.\n\n When you call useState(initialValue), you normally pass in a value directly:\n \n     \n```javascript\n     const [count, setCount] = useState(0);  // initial value is 0\n```\n\n But if calculating that initial value is expensive or involves logic, you can pass a function that returns the value:\n     \n```javascript\n        const [count, setCount] = useState(() => {\n        // This function only runs once — when the component first renders\n        return expensiveComputation();\n        });\n```\n \n This function avoids doing heavy computation on every render. If you don't use this function form and invokes it directly, the function will run everytime the component renders and impact the performance.\n For example, the below usage is not recommended. \n     \n```javascript\n     const [count, setCount] = useState(expensiveComputation());\n```" },
  { q: "২৭৫. useState কী কী ধরনের মান ধারণ করতে পারে?", qEn: "275. What types of values can `useState` hold?", a: "যেকোনো জাভাস্ক্রিপ্ট টাইপ: নাম্বার, স্ট্রিং, বুলিয়ান, অ্যারে, অবজেক্ট, এমনকি ফাংশন।\n\nউদাহরণ:\n```javascript\nconst [value, setValue] = useState(initial);\n```", aEn: "The `useState` hook accepts different types of values.\n\n  Primitives: `number`, `string`, `boolean`\n  Arrays\n  Objects\n  Functions\n  `null` or `undefined`\n\n But you needs to be cautious with reference types (objects/arrays) because React compares old and new values by reference, so direct mutations won't trigger a re-render.\n For example, the correct and wrong ways of state updates as shown below, \n     \n```javascript\n     user.name = \"Sudheer\"; //wrong way\n     setUser(prev => ({ ...prev, name: 'Sudheer' })); //correct way\n```" },
  { q: "২৭৬. useState কে শর্তসাপেক্ষে কল করলে কী হবে?", qEn: "276. What happens if you call `useState` conditionally?", a: "হুকসের নিয়ম ভঙ্গ হবে। রিয়্যাক্ট ওয়ার্নিং দেবে এবং আচরণ অনির্ধারিত হবে।\n\nউদাহরণ:\n```javascript\nconst [value, setValue] = useState(initial);\n```", aEn: "As per rules of React Hooks, hooks must be called unconditionally. For example, if you conditionally call it:\n     \n```javascript\n     if (someCondition) { \n        const [state, setState] = useState(0); \n     }\n```\n\n React will throw a runtime error because it relies on the order of Hook calls, and conditional logic breaks that order." },
  { q: "২৭৭. useState কি সিঙ্ক্রোনাস নাকি অ্যাসিঙ্ক্রোনাস?", qEn: "277. Is useState Synchronous or Asynchronous?", a: "আপডেট ব্যাচিংয়ের কারণে অ্যাসিঙ্ক্রোনাস। সঙ্গে সঙ্গেই মান পাওয়া যাবে না।\n\nউদাহরণ:\n```javascript\nconst [value, setValue] = useState(initial);\n```", aEn: "The `useState` hook is synchronous, but state updates are asynchronous. When you call `useState()`, it runs synchronously and returns the state variable and setter function as tuple.\n     \n```javascript\n     const [count, setCount] = useState(0);\n```\n This happens immediately during rendering.\n However, the state update function (setState) is asynchronous in the sense that it doesn't update the state immediately.\n React batches updates and applies them before the next render. You won’t see the updated value immediately after calling `setState`.\n \n Example:\n     \n```javascript\n     const [count, setCount] = useState(0);\n    \n     function handleClick() {\n       setCount(count + 1);\n       console.log(count); // ❗️Still logs the old value\n     }\n```\n The > `console.log(count)` prints the old value, because the update hasn’t happened yet.\n \n To see the updated state value, you can use `useEffect()` hook. It runs after the component has re-rendered.  By the time `useEffect` runs:\n\n  The component has been updated.\n  The state contains the new value.\n \n        \n```javascript\n        import React, { useState, useEffect } from 'react';\n\n        function Counter() {\n        const [count, setCount] = useState(0);\n        \n        const handleClick = () => {\n        setCount(count + 1);\n        console.log('Clicked count (old):', count); // Old value\n        };\n        \n        useEffect(() => {\n        console.log('Updated count:', count); // New value\n        }, [count]); // Only runs when `count` changes\n        \n        return <button onClick={handleClick}>Count: {count}</button>;\n        }\n```" },
  { q: "২৭৮. useState কীভাবে ভিতরে কাজ করে ব্যাখ্যা করতে পারেন?", qEn: "278. Can you explain how useState works internally?", a: "প্রতিটি কম্পোনেন্টের জন্য রিয়্যাক্ট একটি \"মেমোরি সেল\" রাখে। ক্রম অনুযায়ী হুক কল সংরক্ষণ করে।\n\nউদাহরণ:\n```javascript\nconst [value, setValue] = useState(initial);\n```", aEn: "React’s hooks, including `useState`, rely on some internal machinery that keeps track of state per component and per hook call during rendering. Here's a simplified explanation of the internal mechanics:\n\n #### 1. Hook List / Linked List\n\n  React maintains a linked list or array of \"hook states\" for each component.\n  When a component renders, React keeps track of which hook it is currently processing via a cursor/index.\n  Each call to `useState()` corresponds to one \"slot\" in this list.\n\n #### 2. State Storage\n\n  Each slot stores:\n  The current state value.\n  A queue of pending state updates.\n\n #### 3. Initial Render\n \n  When the component first renders, React:\n  Creates a new slot for `useState` with the initial state (e.g., `0`).\n  Returns `[state, updaterFunction]`.\n\n #### 4. Updater Function\n \n  The updater function (`setCount`) is a closure that, when called:\n  Enqueues a state update to React's internal queue.\n  Schedules a re-render of the component.\n \n #### 5. Re-render and State Update\n \n  On the next render:\n  React processes all queued updates for each hook slot.\n  Updates the stored state value accordingly.\n  Returns the new state to the component.\n\n #### 6. Important: Hook Order\n\n  Hooks must be called in the same order on every render so React can match hook calls to their internal slots.\n  That’s why you can’t call hooks conditionally.\n \n The pseudocode for internal implementation of `useState` looks like below,\n      \n```javascript\n        let hookIndex = 0;\n        const hooks = [];\n        \n        function useState(initialValue) {\n            const currentIndex = hookIndex;\n        \n            if (!hooks[currentIndex]) {\n                // First render: initialize state\n                hooks[currentIndex] = {\n                    state: initialValue,\n                    queue: [],\n                };\n            }\n        \n            const hook = hooks[currentIndex];\n        \n            // Process queued updates\n            hook.queue.forEach(update => {\n                hook.state = update(hook.state);\n            });\n            hook.queue = [];\n        \n            // Define updater function\n            function setState(action) {\n                // action can be new state or function(state) => new state\n                hook.queue.push(typeof action === 'function' ? action : () => action);\n                scheduleRender(); // triggers React re-render\n            }\n        \n            hookIndex++;\n            return [hook.state, setState];\n        }\n```" },
  { q: "২৭৯. useReducer কী? কেন useReducer ব্যবহার করবেন?", qEn: "279. What is `useReducer`? Why do you use useReducer?", a: "একটি হুক যা রিডিউসার প্যাটার্ন ইমপ্লিমেন্ট করে। জটিল স্টেট ট্রানজিশন (একাধিক সাব-ভ্যালু) থাকলে ব্যবহার করুন।\n\nউদাহরণ:\n```javascript\nconst [state, dispatch] = useReducer(reducer, init);\n```", aEn: "The `useReducer` hook is a React hook used to manage complex state logic inside functional components. It is conceptually similar to Redux. i.e, Instead of directly updating state like with `useState`, you dispatch an action to a reducer function, and the reducer returns the new state.\n\n The `useReducer` hook takes three arguments:\n\n        \n```javascript\n        const [state, dispatch] = useReducer(reducer, initialState, initFunction);\n```\n\n  `reducer`: A function `(state, action) => newState` that handles how state should change based on the action.\n  `initialState`: The starting state.\n  `dispatch`: A function you call to trigger an update by passing an action.\n\n The `useReducer` hook is used when:\n\n  The state is complex, such as nested structures or multiple related values.\n  State updates depend on the previous state and logic.\n  You want to separate state update logic from UI code to make it cleaner and testable.\n  You’re managing features like:\n  Forms\n  Wizards / Multi-step flows\n  Undo/Redo functionality\n  Shopping cart logic\n  Toggle & conditional UI logic" },
  { q: "২৮০. useReducer কীভাবে কাজ করে? উদাহরণসহ ব্যাখ্যা করুন?", qEn: "280. How does `useReducer` works? Explain with an example", a: "উদাহরণ:\n\n```javascript\nconst reducer = (state, action) => {\n  switch(action.type) {\n    case 'increment': return {count: state.count + 1};\n    default: return state;\n  }\n};\n```\nconst [state, dispatch] = useReducer(reducer, {count: 0});", aEn: "The `useReducer` hooks works similarly to Redux, where:\n\n  You define a reducer function to handle state transitions.\n  You dispatch actions to update the state.\n \n Counter Example with Increment, Decrement, and Reset:\n 1. Reducer function:\n\n Define a counter reducer function that takes the current state and an action object with a type, and returns a new state based on that type.\n \n         \n```javascript\n         function counterReducer(state, action) {\n            switch (action.type) {\n              case 'increment':\n                return { count: state.count + 1 };\n              case 'decrement':\n                return { count: state.count - 1 };\n              case 'reset':\n                return { count: 0 };\n              default:\n                return state;\n            }\n          }\n```\n 2. Using `useReducer`:\n Invoke `useReducer` with above reducer function along with initial state. Thereafter, you can attach dispatch actions for respective button handlers.\n      \n```javascript\n      import React, { useReducer } from 'react';\n\n        function Counter() {\n          const initialState = { count: 0 };\n          const [state, dispatch] = useReducer(counterReducer, initialState);\n\n          return (\n            <div style={{ textAlign: 'center' }}>\n              <h2>Count: {state.count}</h2>\n              <button onClick={() => dispatch({ type: 'increment' })}>Increment</button>\n              <button onClick={() => dispatch({ type: 'decrement' })}>Decrement</button>\n              <button onClick={() => dispatch({ type: 'reset' })}>Reset</button>\n            </div>\n          );\n        }\n\n      export default Counter;\n```\n Once the new state has been returned, React re-renders the component with the updated `state.count`." },
  { q: "২৮১. useReducer কি useContext এর সাথে একত্রিত করতে পারেন?", qEn: "281. Can you combine **useReducer** with **useContext**?", a: "হাঁ। রিডিউসার স্টেট ও ডিস্প্যাচ কনটেক্সটে রেখে ডিপ কম্পোনেন্টে অ্যাক্সেস দেওয়া যায়।\n\nউদাহরণ:\n```javascript\nconst [state, dispatch] = useReducer(reducer, init);\n```", aEn: "Yes, it's common to combine useReducer with useContext to build a lightweight state management system similar to Redux:\n\n      \n```javascript\n      const AppContext = React.createContext();\n\n      function AppProvider({ children }) {\n        const [state, dispatch] = useReducer(reducer, initialState);\n        return (\n          <AppContext.Provider value={{ state, dispatch }}>\n            {children}\n          </AppContext.Provider>\n        );\n      }\n```" },
  { q: "২৮২. useReducer দিয়ে কি একের পর এক একাধিক অ্যাকশন ডিস্প্যাচ করতে পারেন?", qEn: "282. Can you dispatch multiple actions in a row with useReducer?", a: "হাঁ। প্রতিটি ডিস্প্যাচের জন্য রিডিউসার চালাবে এবং শেষে ব্যাচ আপডেট হবে।\n\nউদাহরণ:\n```javascript\nconst [state, dispatch] = useReducer(reducer, init);\n```", aEn: "Yes, you can dispatch multiple actions in a row using `useReducer` but not directly in one call. You'd have to call dispatch multiple times or create a composite action in your reducer that performs multiple updates based on the action type.\n \n Example: Dispatching Multiple Actions\n You can define a custom function with dispatching actions one by one.\n     \n```javascript\n     function handleMultipleActions(dispatch) {\n       dispatch({ type: 'increment' });\n       dispatch({ type: 'increment' });\n       dispatch({ type: 'reset' });\n     }\n```\n After that, you need to invoke it through event handler\n     \n```javascript\n     <button onClick={() => handleMultipleActions(dispatch)}>\n       Run Multiple Actions\n     </button>\n```\n Note: You can also define a custom action type If you want multiple state changes to be handled in one reducer call.\n     \n```javascript\n     case 'increment_twice':\n       return { count: state.count + 2 };\n```\n Then dispatch\n     \n```javascript\n     dispatch({ type: 'increment_twice' });\n```" },
  { q: "২৮৩. useReducer থেকে ডিস্প্যাচ কি অ্যাসিঙ্ক্রোনাস এবং তাৎক্ষণিক স্টেট আপডেট করে?", qEn: "283. Is dispatch from useReducer asynchronous and does it update state immediately?", a: "ডিস্প্যাচ কল স্টেট আপডেটের জন্য অনুরোধ করে। আপডেট ব্যাচিংয়ের কারণে স্টেট অবিলম্বে পরিবর্তন হয় না।\n\nউদাহরণ:\n```javascript\nconst [state, dispatch] = useReducer(reducer, init);\n```", aEn: "The `dispatch` function returned by `useReducer` is not asynchronous — it is a synchronous function call. When you call `dispatch(action)`, React synchronously invokes your reducer with the current state and the action, computes the new state, and schedules a re-render. However, the state variable does not update immediately within the same render cycle. The updated state is only available in the next render.\n\n This behavior is similar to `useState`'s `setState` — React batches state updates for performance optimization, meaning the component does not re-render immediately after each `dispatch` call. Instead, React processes all dispatched actions and re-renders once with the final state.\n\n #### Key Points\n\n 1. `dispatch` is synchronous: The reducer runs immediately when `dispatch` is called.\n 2. State update is not immediate in the current render: The state variable still holds the old value until the next render.\n 3. React batches updates: Multiple `dispatch` calls within the same event handler result in a single re-render.\n 4. Reducer is a pure function: It computes the new state without side effects.\n\n #### Example demonstrating that state does not update immediately\n\n     \n```javascript\n     import React, { useReducer } from 'react';\n\n     function reducer(state, action) {\n       switch (action.type) {\n         case 'increment':\n           return { count: state.count + 1 };\n         default:\n           return state;\n       }\n     }\n\n     function Counter() {\n       const [state, dispatch] = useReducer(reducer, { count: 0 });\n\n       const handleClick = () => {\n         dispatch({ type: 'increment' });\n         console.log(state.count); // Still logs the OLD value (e.g., 0), not 1\n         dispatch({ type: 'increment' });\n         console.log(state.count); // Still logs the OLD value (e.g., 0), not 2\n       };\n\n       // After re-render, state.count will be 2 (both dispatches are processed)\n       return (\n         <div>\n           <p>Count: {state.count}</p>\n           <button onClick={handleClick}>Increment Twice</button>\n         </div>\n       );\n     }\n```\n\n In the above example, even though `dispatch` is called twice, `state.count` still reflects the previous value inside the event handler. React batches both dispatches and re-renders the component once with `count: 2`.\n\n #### How to read updated state after dispatch\n\n If you need the updated value right after dispatching, you have several options:\n\n 1. Use `useEffect` to react to state changes:\n        \n```javascript\n        useEffect(() => {\n          console.log('Updated count:', state.count);\n        }, [state.count]);\n```\n\n 2. Compute the next state manually:\n        \n```javascript\n        const handleClick = () => {\n          const nextState = reducer(state, { type: 'increment' });\n          console.log('Next state will be:', nextState.count);\n          dispatch({ type: 'increment' });\n        };\n```\n\n 3. Use `useRef` to track the latest state:\n        \n```javascript\n        const stateRef = useRef(state);\n        useEffect(() => {\n          stateRef.current = state;\n        }, [state]);\n```\n\n Note: This behavior is by design in React. The `dispatch` function itself has a stable identity (it doesn't change between re-renders), which makes it safe to omit from `useEffect` dependency arrays." },
  { q: "২৮৪. useContext কীভাবে কাজ করে? উদাহরণসহ ব্যাখ্যা করুন?", qEn: "284. How does useContext works? Explain with an example", a: "উদাহরণ:\n\n```javascript\nconst ThemeContext = React.createContext('light');\n```\nconst theme = useContext(ThemeContext); // 'light' বা প্রোভাইডার থেকে মান", aEn: "The `useContext` hook can be used for authentication state management across multiple components and pages in a React application.\n \n Let's build a simple authentication flow with:\n\n  Login and Logout buttons\n  Global `AuthContext` to share state\n  Components that can access and update auth status\n \n 1. Create the Auth Context:\n\n You can define `AuthProvider` which holds and provides `user`, `login()`, and `logout()` via context.\n        \n```javascript\n        // AuthContext.js\n        import React, { createContext, useContext, useState } from 'react';\n        \n        const AuthContext = createContext();\n        \n        export function AuthProvider({ children }) {\n          const [user, setUser] = useState(null);\n        \n          const login = (username) => setUser({ name: username });\n          const logout = () => setUser(null);\n        \n          return (\n            <AuthContext.Provider value={{ user, login, logout }}>\n              {children}\n            </AuthContext.Provider>\n          );\n        }\n        \n        // Custom hook for cleaner usage\n        export const useAuth = () => useContext(AuthContext);\n```\n 2. Wrap Your App with the Provider:\n \n Wrap the above created provider in main `App.js` file \n        \n```javascript\n        // App.js\n        import React from 'react';\n        import { AuthProvider } from './AuthContext';\n        import HomePage from './HomePage';\n        import Dashboard from './Dashboard';\n        \n        function App() {\n          return (\n            <AuthProvider>\n              <HomePage />\n              <Dashboard />\n            </AuthProvider>\n          );\n        }\n        \n        export default App;\n```\n 3. Home page with login:\n Read or access user and login details through custom useAuth hook and use it inside home page.\n\n        \n```javascript\n         // HomePage.js\n         import React from 'react';\n         import { useAuth } from './AuthContext';\n    \n         function HomePage() {\n           const { user, login } = useAuth();\n    \n           return (\n             <div>\n               <h1>Home</h1>\n               {user ? (\n                 <p>Welcome back, {user.name}!</p>\n               ) : (\n                 <button onClick={() => login('Alice')}>Login</button>\n               )}\n             </div>\n           );\n         }\n    \n         export default HomePage;\n```\n \n 4. Dashboard with logout:\n Read or access user and logout details from `useAuth` custom hook and use it inside dashboard page.\n\n      \n```javascript\n        // Dashboard.js\n        import React from 'react';\n        import { useAuth } from './AuthContext';\n        \n        function Dashboard() {\n          const { user, logout } = useAuth();\n        \n          if (!user) {\n            return <p>Please login to view the dashboard.</p>;\n          }\n        \n          return (\n            <div>\n              <h2>Dashboard</h2>\n              <p>Logged in as: {user.name}</p>\n              <button onClick={logout}>Logout</button>\n            </div>\n          );\n        }\n        \n        export default Dashboard;\n```" },
  { q: "২৮৫. এক কম্পোনেন্টে কি একাধিক কনটেক্সট ব্যবহার করতে পারেন?", qEn: "285. Can You Use Multiple Contexts in One Component?", a: "হাঁ। একাধিকবার useContext কল করতে পারেন, ভিন্ন ভিন্ন কনটেক্সটের জন্য।\n\nউদাহরণ:\n```javascript\nconst value = useContext(MyContext);\n```", aEn: "Yes, it is possible. You can use multiple contexts inside the same component by calling useContext multiple times, once for each context.\n\n It can be achieved with below steps,\n\n  Create multiple contexts using `createContext()`.\n  Wrap your component tree with multiple ` `s.\n  Call `useContext()` separately for each context in the same component.\n \n Example: Using `ThemeContext` and `UserContext` Together\n     \n```javascript\n     import React, { createContext, useContext } from 'react';\n\n      // Step 1: Create two contexts\n      const ThemeContext = createContext();\n      const UserContext = createContext();\n\n      function Dashboard() {\n        // Step 2: Use both contexts\n        const theme = useContext(ThemeContext);\n        const user = useContext(UserContext);\n\n        return (\n          <div style={{ background: theme === 'dark' ? '#333' : '#fff' }}>\n            <h1>Welcome, {user.name}</h1>\n            <p>Current theme: {theme}</p>\n          </div>\n        );\n      }\n\n      // Step 3: Provide both contexts\n      function App() {\n        return (\n          <ThemeContext.Provider value=\"dark\">\n            <UserContext.Provider value={{ name: 'Sudheer' }}>\n              <Dashboard />\n            </UserContext.Provider>\n          </ThemeContext.Provider>\n        );\n      }\n\n      export default App;\n```" },
  { q: "২৮৬. অবজেক্টের সাথে useContext ব্যবহারের একটি সাধারণ ফাঁদ কী কী?", qEn: "286. What's a common pitfall when using useContext with objects?", a: "কনটেক্সট মান একটি অবজেক্ট হলে, প্রোভাইডারের মান পরিবর্তন না করলেও, প্যারেন্ট রি-রেন্ডারে সব কনজিউমার রি-রেন্ডার হয়। মেমোাইজেশন ব্যবহার করুন।\n\nউদাহরণ:\n```javascript\nconst value = useContext(MyContext);\n```", aEn: "A common pitfall when using `useContext` with objects is triggering unnecessary re-renders across all consuming components — even when only part of the context value changes.\n\n When you provide an object as the context value, React compares the entire object reference. If the object changes (even slightly), React assumes the whole context has changed, and all components using `useContext(MyContext)` will re-render, regardless of whether they use the part that changed.\n\n Example:\n     \n```javascript\n        const MyContext = React.createContext();\n\n        function MyProvider({ children }) {\n          const [user, setUser] = useState(null);\n          const [theme, setTheme] = useState('light');\n\n          // This causes all consumers to re-render on any state change\n          const contextValue = { user, setUser, theme, setTheme };\n\n          return (\n            <MyContext.Provider value={contextValue}>\n              {children}\n            </MyContext.Provider>\n          );\n        }\n```\n In this case, a change in `theme` will also trigger a re-render in components that only care about `user`.\n\n This issue can be fixed in two ways,\n\n 1. Split Contexts \n Create separate contexts for unrelated pieces of state:\n\n     \n```javascript\n     const UserContext = React.createContext(); \n     const ThemeContext = React.createContext();\n```\n\n 2. Memoize Context Value \n Use `useMemo` to prevent unnecessary re-renders:\n\n     \n```javascript\n       const contextValue = useMemo(() => ({ user, setUser, theme, setTheme }), [user, theme]);\n```\n\n However, this only helps if the object structure and dependencies are well controlled." },
  { q: "২৮৭. কোনো ম্যাচিং প্রোভাইডার না থাকলে কনটেক্সট ভ্যালু কী হবে?", qEn: "287. What would the context value be for no matching provider?", a: "createContext()-এ দেওয়া ডিফল্ট ভ্যালু।\n\nউদাহরণ:\n```javascript\n// Hooks — ছোট working example দেখান\n```", aEn: "When a component calls `useContext(SomeContext)` but no matching ` ` is present higher up in the component tree, the default value passed to `React.createContext(defaultValue)` is returned.\n \n     \n```javascript\n     const ThemeContext = React.createContext('light'); // 'light' is the default value\n    \n     function ThemedComponent() {\n       const theme = useContext(ThemeContext);\n       return <div>Current theme: {theme}</div>;\n     }\n    \n     // No ThemeContext.Provider anywhere in the tree\n```\n In this case, `theme` will be 'light'. It's the default value you provided when you created the context.\n \n Note: If you don’t specify a default value, the context value will be undefined when used without a provider:\n \n     \n```javascript\n     const AuthContext = React.createContext(); // No default\n    \n     function Profile() {\n       const auth = useContext(AuthContext);\n       // auth will be undefined if there's no AuthContext.Provider\n     }\n```" },
  { q: "২৮৮. useEffect ডিপেন্ডেন্সি অ্যারেতে রিঅ্যাকটিভ ডিপেন্ডেন্সি কীভাবে এক্সিকিউশন আচরণ প্রভাবিত করে?", qEn: "288. How do reactive dependencies in the useEffect dependency array affect its execution behavior?", a: "ডিপেন্ডেন্সিগুলোর মধ্যে যে কোনো একটি পরিবর্তিত হলে ইফেক্ট পুনরায় চলে। খালি অ্যারে দিলে শুধু মাউন্টে একবার চলে।\n\nউদাহরণ:\n```javascript\nuseEffect(() => { /* runs when dep changes */ }, [userId]);\n```", aEn: "The `useEffect` hook accepts an optional dependencies argument that accepts an array of reactive values. The dependency array determines when the effect runs. i.e, It makes `useEffect` _reactive_ to changes in specified values.\n\n #### How Dependency Array Affects Behavior\n\n 1. Empty Dependency Array: `[]`\n\n     \n```css\n     useEffect(() => {\n       // runs once after the initial render\n     }, []);\n```\n\n  Effect runs only once (like `componentDidMount`).\n  Ignores all state/prop changes.\n\n 2. With Specific Dependencies: `[count, user]`\n\n     \n```css\n     useEffect(() => {\n       // runs after initial render\n       // AND whenever `count` or `user` changes\n     }, [count, user]);\n```\n\n  Effect runs on first render, and\n  Again every time any dependency value changes.\n\n 3. No Dependency Array (Omitted)\n\n          \n```css\n          useEffect(() => {\n            // runs after every render\n          });\n```\n\n  Effect runs after every render, regardless of what changed.\n  Can lead to performance issues if not used carefully.\n\n React uses shallow comparison of the dependencies. If any value has changed (!==), the effect will re-run.\n \n Note: This hook works well when dependencies are primitives or memoized objects/functions." },
  { q: "২৮৯. কখন এবং কতবার React useEffect-এর ভেতরের সেটআপ ও ক্লিনআপ ফাংশন ডাকে?", qEn: "289. When and how often does React invoke the setup and cleanup functions inside a useEffect hook?", a: "প্রতি রেন্ডারে ডিপেন্ডেন্সি তুলনা করে। পরিবর্তন পেলে আগের ক্লিনআপ, তারপর নতুন সেটআপ চালায়।\n\nউদাহরণ:\n```javascript\nuseEffect(() => {\n  // side effect\n  return () => cleanup();\n}, [deps]);\n```", aEn: "1. Setup Function Execution (`useEffect`)\n\n The setup function (or the main function) you pass to `useEffect` runs at specific points:\n\n 1. After the component is mounted (if the dependency array is empty `[]`)\n 2. After every render (if no dependency array is provided)\n 3. After a dependency value changes (if the dependency array contains variables)\n\n 2. Cleanup Function Execution (Returned function from `useEffect`)\n\n The cleanup function is called before the effect is re-executed and when the component unmounts." },
  { q: "২৯০. useEffect থেকে Promise রিটার্ন করলে কী হবে?", qEn: "290. What happens if you return a Promise from useEffect??", a: "এরর দেবে। ক্লিনআপ ফাংশন একটি ফাংশন রিটার্ন করবে, প্রমিস নয়।\n\nউদাহরণ:\n```javascript\nuseEffect(() => {\n  // side effect\n  return () => cleanup();\n}, [deps]);\n```", aEn: "You should NOT return a Promise from useEffect. React expects the function passed to useEffect to return either nothing (undefined) or a cleanup function (synchronous function). i.e, It does not expect or handle a returned Promise. If you still return a Promise, React will ignore it silently, and it may lead to bugs or warnings in strict mode.\n\n Incorrect:\n      \n```javascript\n      useEffect(async () => {\n        await fetchData(); // ❌ useEffect shouldn't be async\n      }, []);\n```\n Correct:\n      \n```javascript\n      useEffect(() => {\n        const fetchData = async () => {\n          const res = await fetch('/api');\n          const data = await res.json();\n          setData(data);\n        };\n\n        fetchData();\n      }, []);\n```" },
  { q: "২৯১. একটি কম্পোনেন্টে কি একাধিক useEffect থাকতে পারে?", qEn: "291. How to prevent infinite loops with useEffect?", a: "হাঁ। যুক্তি অনুযায়ী ভাগ করে নিন। এরা ক্রমান্বয়ে চলে।\n\nউদাহরণ:\n```javascript\nuseEffect(() => {\n  // side effect\n  return () => cleanup();\n}, [deps]);\n```", aEn: "Infinite loops happen when the effect updates state that’s listed in its own dependency array, which causes the effect to re-run, updating state again and so on.\n \n Infinite loop scenario:\n        \n```javascript\n        useEffect(() => {\n          setCount(count + 1);\n        }, [count]); // Triggers again every time count updates\n```\n You need to ensure that setState calls do not depend on values that cause the effect to rerun, or isolate them with a guard.\n        \n```javascript\n        useEffect(() => {\n          if (count < 5) {\n            setCount(count + 1);\n          }\n        }, [count]);\n```" },
  { q: "২৯২. useEffect দিয়ে কীভাবে ইনফিনিট লুপ প্রতিরোধ করবেন?", qEn: "292. What are the usecases of useLayoutEffect?", a: "ডিপেন্ডেন্সি অ্যারে সঠিক দিন এবং ইফেক্টের ভেতর স্টেট আপডেট করলে শর্তসাপেক্ষে করুন।\n\nউদাহরণ:\n```javascript\nuseEffect(() => {\n  // side effect\n  return () => cleanup();\n}, [deps]);\n```", aEn: "You need to use `useLayoutEffect` when your effect must run before the browser paints, such as:\n\n  Reading layout measurements (e.g., element size, scroll position)\n  Synchronously applying DOM styles to prevent visual flicker\n  Animating layout or transitions\n  Integrating with third-party libraries that require DOM manipulation\n\n If there's no visual or layout dependency, prefer `useEffect` — it's more performance-friendly.\n\n      \n```javascript\n      useLayoutEffect(() => {\n        const width = divRef.current.offsetWidth;\n        if (width < 400) {\n          divRef.current.style.background = 'blue'; // prevents flicker\n        }\n      }, []);\n```" },
  { q: "২৯৩. useLayoutEffect-এর ব্যবহারের ক্ষেত্রগুলো কী কী?", qEn: "293. How does useLayoutEffect work during server-side rendering (SSR)?", a: "DOM এলিমেন্টের অবস্থান/সাইজ মাপা\n\nস্ক্রল পজিশন সামঞ্জস্য\n\nফ্লিকারিং প্রতিরোধ\n\nউদাহরণ:\n```javascript\n// Hooks — ছোট working example দেখান\n```", aEn: "The `useLayoutEffect` hook does not run on the server, because there is no DOM. React issues a warning in server environments like Next.js if `useLayoutEffect` is used directly.\n\n This can be mitigated using a conditional polyfill:\n\n      \n```javascript\n      const useIsomorphicLayoutEffect =\n        typeof window !== 'undefined' ? useLayoutEffect : useEffect;\n```\n\n i.e, Use `useIsomorphicLayoutEffect` in components that render both on client and server." },
  { q: "২৯৪. সার্ভার-সাইড রেন্ডারিংয়ে (SSR) useLayoutEffect কীভাবে কাজ করে?", qEn: "294. What happens if you use useLayoutEffect for non-layout logic?", a: "Warning দেয়। সার্ভারে চলে না, শুধু ক্লায়েন্টে চলে।\n\nউদাহরণ:\n```javascript\n// Hooks — ছোট working example দেখান\n```", aEn: "Using `useLayoutEffect` for logic unrelated to layout or visual DOM changes (such as logging, data fetching, or analytics) is not recommended. It can lead to performance issues or even unexpected behavior.\n\n Example: Anti-pattern\n      \n```javascript\n      useLayoutEffect(() => {\n        console.log(\"Tracking analytics\");\n        fetch('/log-page-view');\n      }, []);\n```\n The above usage delays the paint of the UI just to send a network request, which could (and should) be done after paint using useEffect." },
  { q: "২৯৫. নন-লেআউট লজিকের জন্য useLayoutEffect ব্যবহার করলে কী হবে?", qEn: "295. How does useLayoutEffect cause layout thrashing?", a: "অপ্রয়োজনীয় ব্লকিং হবে। ব্রাউজার পেইন্ট আটকে যাবে, পারফরম্যান্স খারাপ হবে।\n\nউদাহরণ:\n```javascript\n// Hooks — ছোট working example দেখান\n```", aEn: "The `useLayoutEffect` can cause layout thrashing when you repeatedly read and write to the DOM in ways that force the browser to recalculate layout multiple times per frame. This is because `useLayoutEffect` runs _before the browser paints_, these reflows happen _synchronously_, blocking rendering and degrading performance.\n\n Example:\n      \n```javascript\n      function ThrashingComponent() {\n        const ref = useRef();\n\n        useLayoutEffect(() => {\n          const height = ref.current.offsetHeight; //Read\n          ref.current.style.height = height + 20 + 'px'; //Write\n          const newHeight = ref.current.offsetHeight; //Read again — forces reflow\n        }, []);\n\n        return <div ref={ref}>Hello</div>;\n      }\n```\n In the above code, each read/write cycle triggers synchronous reflows, blocking the main thread and delays UI rendering.\n\n This issue can be avoided by batching your DOM reads and writes and prevent unnecessary reads after writes." },
  { q: "২৯৬. useLayoutEffect কীভাবে লেআউট থ্রাশিং সৃষ্টি করে?", qEn: "296. How Do You Use useRef to Access a DOM Element in React? Give an example.", a: "বারবার DOM মাপা ও সেট করার কারণে ব্রাউজার বারবার রি-ফ্লো করে।\n\nউদাহরণ:\n```javascript\n// Hooks — ছোট working example দেখান\n```", aEn: "The `useRef` hook is commonly used in React to directly reference and interact with DOM elements — like focusing an input, scrolling to a section, or controlling media elements.\n \n When you assign a ref to a DOM element using useRef, React gives you access to the underlying DOM node via the .current property of the ref object.\n \n Example: Focus an input\n\n        \n```javascript\n        import React, { useRef } from 'react';\n        \n        function FocusInput() {\n          const inputRef = useRef(null); // create the ref\n        \n          const handleFocus = () => {\n            inputRef.current.focus(); // access DOM element and focus it\n          };\n        \n          return (\n            <div>\n              <input type=\"text\" ref={inputRef} />\n              <button onClick={handleFocus}>Focus the input</button>\n            </div>\n          );\n        }\n```\n Note: The DOM reference is only available after the component has mounted — typically accessed in `useEffect` or event handlers." },
  { q: "২৯৭. DOM এলিমেন্ট অ্যাক্সেস করতে useRef কীভাবে ব্যবহার করবেন? উদাহরণ দিন?", qEn: "297. Can you use useRef to persist values across renders??", a: "উদাহরণ:\n\n```javascript\nconst inputRef = useRef();\n<input ref={inputRef} />\n```\ninputRef.current.focus();", aEn: "Yes, you can use `useRef` to persist values across renders in React. Unlike `useState`, changing `.current` does not cause re-renders, but the value is preserved across renders.\n \n Example:\n        \n```javascript\n        function Timer() {\n          const renderCount = useRef(0);\n          useEffect(() => {\n            renderCount.current++;\n            console.log(\"Render count:\", renderCount.current);\n          });\n        \n          return <div>Check console for render count.</div>;\n        }\n```" },
  { q: "২৯৮. useRef কি রেন্ডার জুড়ে মান ধরে রাখতে পারে?", qEn: "298. Can useRef be used to store previous values?", a: "হাঁ। স্টেটের মতো কিন্তু পরিবর্তন করলে রি-রেন্ডার হয় না।\n\nউদাহরণ:\n```javascript\nconst ref = useRef(null);\n```", aEn: "Yes, `useRef` is a common pattern when you want to compare current and previous props or state without causing re-renders.\n \n Example: Storing previous state value\n        \n```javascript\n        import { useEffect, useRef, useState } from 'react';\n        \n        function PreviousValueExample() {\n          const [count, setCount] = useState(0);\n          const prevCountRef = useRef();\n        \n          useEffect(() => {\n            prevCountRef.current = count;\n          }, [count]);\n        \n          const prevCount = prevCountRef.current;\n        \n          return (\n            <div>\n              <p>Current: {count}</p>\n              <p>Previous: {prevCount}</p>\n              <button onClick={() => setCount(c => c + 1)}>Increment</button>\n            </div>\n          );\n        }\n```" },
  { q: "২৯৯. useRef কি পূর্বের মান সংরক্ষণ করতে পারে?", qEn: "299. Is it possible to access a ref in the render method?", a: "হাঁ। useRef দিয়ে পূর্বের প্রপস/স্টেট সংরক্ষণ করে তুলনা করতে পারেন।\n\nউদাহরণ:\n```javascript\nconst ref = useRef(null);\n```", aEn: "Yes, you can access a ref in the render method, but what you get from it depends on how you're using the ref and when in the component lifecycle you're rendering.\n \n For example, when using ref to access a DOM node (e.g., divRef.current), it's not immediately available on the first render.\n        \n```javascript\n        const divRef = useRef(null);\n        \n        console.log(divRef.current); // ❌ null on initial render\n        return <div ref={divRef}>Hello</div>;\n```" },
  { q: "৩০০. রেন্ডার মেথডে কি রেফ অ্যাক্সেস করা সম্ভব?", qEn: "300. What are the common usecases of useRef hook?", a: "না। রেন্ডারের সময় DOM এখনও তৈরি হয়নি। useEffect বা ইভেন্ট হ্যান্ডলারে অ্যাক্সেস করুন।\n\nউদাহরণ:\n```javascript\nuseEffect(() => {\n  // side effect\n  return () => cleanup();\n}, [deps]);\n```", aEn: "Some of the common cases are:\n  Automatically focus an input when a component mounts.\n  Scroll to a specific element.\n  Measure element dimensions (`offsetWidth`, `clientHeight`).\n  Control video/audio playback.\n  Integrate with non-React libraries (like D3 or jQuery)." },
  { q: "৩০১. useRef হুকের সাধারণ ব্যবহারের ক্ষেত্রগুলো কী কী?", qEn: "301. What is useImperativeHandle Hook? Give an example.", a: "DOM এলিমেন্টে ফোকাস\n\nটাইমার আইডি সংরক্ষণ\n\nপূর্বের মান ট্র্যাকিং\n\nইম্পেরেটিভ মেথড কল\n\nউদাহরণ:\n```javascript\nconst ref = useRef(null);\n```", aEn: "`useImperativeHandle` is a React Hook that allows a child component to expose custom functions or properties to its parent component, when using `ref`.\n It is typically used with `forwardRef` and is very useful in cases like modals, dialogs, custom inputs, etc., where the parent needs to control behavior imperatively (e.g., open, close, reset).\n\n Example: Dialog component\n      \n```javascript\n      import React, {\n        useRef,\n        useState,\n        useImperativeHandle,\n        forwardRef,\n      } from 'react';\n      import './Dialog.css'; \n\n      const Dialog = forwardRef((props, ref) => {\n        const [isOpen, setIsOpen] = useState(false);\n        const [formData, setFormData] = useState('');\n\n        useImperativeHandle(ref, () => ({\n          open: () => setIsOpen(true),\n          close: () => setIsOpen(false),\n          reset: () => setFormData(''),\n        }));\n\n        if (!isOpen) return null;\n\n        return (\n          <div className=\"dialog\"> \n            <h2>Dialog</h2>\n            <input\n              type=\"text\"\n              value={formData}\n              placeholder=\"Type something...\"\n              onChange={(e) => setFormData(e.target.value)}\n            />\n            <br />\n            <button onClick={() => setIsOpen(false)}>Close</button>\n          </div>\n        );\n      });\n\n      function Parent() {\n        const dialogRef = useRef();\n\n        return (\n          <div>\n            <h1>useImperativeHandle Dialog Example</h1>\n            <button onClick={() => dialogRef.current.open()}>Open Dialog</button>\n            <button onClick={() => dialogRef.current.reset()}>Reset Dialog</button>\n            <button onClick={() => dialogRef.current.close()}>Close Dialog</button>\n\n            <Dialog ref={dialogRef} />\n          </div>\n        );\n      }\n\n      export default Parent;\n```" },
  { q: "৩০২. useImperativeHandle হুক কী? উদাহরণ দিন?", qEn: "302. When should you use useImperativeHandle?", a: "প্যারেন্ট কম্পোনেন্টকে চাইল্ডের ইম্পেরেটিভ মেথড অ্যাক্সেস দিতে forwardRef-এর সাথে ব্যবহার হয়।\n\nউদাহরণ:\n\n```javascript\nuseImperativeHandle(ref, () => ({ focus: () => inputRef.current.focus() }));\n```", aEn: "The useImperativeHandler hook will be used in below cases:\n\n  You want to expose imperative methods from a child component \n - Custom input controls exposing `focus`, `clear`, or `validate` methods\n - Modal components exposing `open()` and `close()` methods\n - Scroll containers exposing `scrollToTop()` or `scrollToBottom()` methods\n  You want to hide internal implementation but provide controlled external access.\n  You're building reusable component libraries (e.g., inputs, modals, form controls)." },
  { q: "৩০৩. কখন useImperativeHandle ব্যবহার করবেন?", qEn: "303. Is that possible to use useImperativeHandle without forwardRef?", a: "থার্ড-পার্টি লাইব্রেরি ইন্টিগ্রেশন, অ্যানিমেশন ট্রিগার, ফাংশনাল কম্পোনেন্টে মেথড এক্সপোজ করতে।\n\nউদাহরণ:\n```javascript\n// Hooks — ছোট working example দেখান\n```", aEn: "No. `useImperativeHandle` only works when the component is wrapped in `forwardRef`. It's the combination that allows parent components to use a `ref` on a function component." },
  { q: "৩০৪. forwardRef ছাড়া কি useImperativeHandle ব্যবহার করা যায়?", qEn: "304. How is useMemo different from useCallback?", a: "না। useImperativeHandle-কে একটি ref দরকার যা forwardRef থেকে আসে।\n\nউদাহরণ:\n```javascript\n// Hooks — ছোট working example দেখান\n```", aEn: "The following table compares both useMemo and useCallback:\n\n | Feature | `useMemo` | `useCallback` |\n | --- | --- | --- |\n | Purpose | Memoizes the result of a computation | Memoizes a function reference |\n | Returns | A value (e.g., result of a function) | A function |\n | Usage | `useMemo(() => computeValue(), [deps])` | `useCallback(() => doSomething(), [deps])` |\n | Primary Use Case | Avoid expensive recalculations | Prevent unnecessary re-creations of functions |\n | Common Scenario | Filtering, sorting, calculating derived data | Passing callbacks to child components |\n | When It's Useful | When the value is expensive to compute | When referential equality matters (e.g., props) |\n | Recomputed When | Dependencies change | Dependencies change |\n | Returned Value Type | Any (number, object, array, etc.) | Always a function |\n | Overhead | Slight (evaluates a function and caches result) | Slight (caches a function reference) |" },
  { q: "৩০৫. useMemo কীভাবে useCallback থেকে আলাদা?", qEn: "305. Does useMemo prevent re-rendering of child components?", a: "| useMemo | useCallback |\n| মান মেমোয়েজ করে | ফাংশন মেমোয়েজ করে |\n| useMemo(() => value, deps) | useCallback(fn, deps) |\n\nউদাহরণ:\n```javascript\nconst v = useMemo(() => heavy(a), [a]);\n```", aEn: "The `useMemo` hook does not directly prevent re-rendering of child components. Its main purpose is to memoize the result of an expensive computation so that it doesn’t get recalculated unless its dependencies change. While this can improve performance, it doesn’t inherently control whether a child component re-renders.\n \n However, `useMemo` can help prevent re-renders when the memoized value is passed as a prop to a child component that is wrapped in `React.memo`. In that case, if the memoized value doesn’t change between renders (i.e., it has the same reference), React.memo can skip re-rendering the child. So, while `useMemo` doesn’t stop renders on its own, it works in combination with tools like `React.memo` to optimize rendering behavior." },
  { q: "৩০৬. useMemo কি চাইল্ড কম্পোনেন্টের রি-রেন্ডার প্রতিরোধ করে?", qEn: "306. useMemo কি চাইল্ড কম্পোনেন্টের রি-রেন্ডার প্রতিরোধ করে?", a: "পরোক্ষভাবে করে। যদি মেমোয়েজড মান প্রপস হিসেবে যায় এবং তা পরিবর্তন না হয়, তবে চাইল্ড রি-রেন্ডার হয় না।\n\nউদাহরণ:\n```javascript\nconst v = useMemo(() => heavy(a), [a]);\n```" },
  { q: "৩০৭. useCallback কী এবং কেন ব্যবহার করা হয়?", qEn: "307. What is `useCallback` and why is it used?", a: "ফাংশন মেমোয়েজ করে, যাতে ডিপেন্ডেন্সি পরিবর্তন না হলে একই ফাংশন রেফারেন্স থাকে। চাইল্ড কম্পোনেন্টে অপ্রয়োজনীয় রি-রেন্ডার বাধা দেয়।\n\nউদাহরণ:\n```javascript\nconst onClick = useCallback(() => doSomething(id), [id]);\n```", aEn: "The `useCallback` is a React Hook used to memoize function definitions between renders. It returns the same function reference unless its dependencies change. This is especially useful when passing callbacks to optimized child components (e.g. those wrapped in `React.memo`) to prevent unnecessary re-renders.\n \n Example:\n \n        \n```css\n        const handleClick = useCallback(() => {\n          console.log('Button clicked');\n        }, []);\n```\n \n Without `useCallback`, a new function is created on every render, potentially causing child components to re-render unnecessarily." },
  { q: "৩০৮. কাস্টম রিয়্যাক্ট হুকস কী এবং কীভাবে তৈরি করবেন?", qEn: "308. What are Custom React Hooks, and How Can You Develop One?", a: "রিইউজেবল লজিকের ফাংশন যার নাম use দিয়ে শুরু হয়। যেমন:\n\nউদাহরণ:\n\n```javascript\nfunction useWindowWidth() {\n  const [width, setWidth] = useState(window.innerWidth);\n  // ...\n  return width;\n}\n```", aEn: "Custom Hooks in React are JavaScript functions that allow you to extract and reuse component logic using React’s built-in Hooks like `useState`, `useEffect`, etc.\n\n They start with the word \"use\" and let you encapsulate logic that multiple components might share—such as fetching data, handling forms, or managing timers—without repeating code.\n\n Let's explain the custom hook usage with `useFetchData` example. The `useFetchData` custom Hook is a reusable function in React that simplifies the process of fetching data from an API. It encapsulates common logic such as initiating the fetch request, managing loading and error states, and storing the fetched data. By using built-in Hooks like `useState` and `useEffect`, `useFetchData` provides a clean interface that returns the `data`, `loading`, and `error` values, which can be directly used in components.\n\n      \n```javascript\n      import { useState, useEffect } from 'react';\n\n      function useFetchData(url) {\n        const [data, setData] = useState(null);     // Holds the response\n        const [loading, setLoading] = useState(true); // Loading state\n        const [error, setError] = useState(null);     // Error state\n\n        useEffect(() => {\n          let isMounted = true; // Prevent setting state on unmounted component\n          setLoading(true);\n\n          fetch(url)\n            .then((response) => {\n              if (!response.ok) throw new Error('Network response was not ok');\n              return response.json();\n            })\n            .then((json) => {\n              if (isMounted) {\n                setData(json);\n                setLoading(false);\n              }\n            })\n            .catch((err) => {\n              if (isMounted) {\n                setError(err.message);\n                setLoading(false);\n              }\n            });\n\n          return () => {\n            isMounted = false; // Clean-up function to avoid memory leaks\n          };\n        }, [url]);\n\n        return { data, loading, error };\n      }\n```\n\n The above custom hook can be used to retrieve users data for `AuthorList`, `ReviewerList` components.\n\n Example: AuthorList component\n      \n```javascript\n      function AuthorList() {\n        const { data, loading, error } = useFetchData('https://api.example.com/authors');\n\n        if (loading) return <p>Loading authors...</p>;\n        if (error) return <p>Error: {error}</p>;\n\n        return (\n          <ul>\n            {data.map((author) => (\n              <li key={author.id}>{author.name}</li>\n            ))}\n          </ul>\n        );\n      }\n```\n \n Some of the benefits of custom hooks are:\n  Promotes code reuse\n  Keeps components clean and focused\n  Makes complex logic easier to test and maintain" },
  { q: "৩০৯. রিয়্যাক্ট ফাইবার কীভাবে কাজ করে? বিস্তারিত ব্যাখ্যা দিন?", qEn: "309. How does React Fiber works? Explain in detail.", a: "ফাইবার একটি ভির্চুয়াল DOM নোড। ফাইবার আর্কিটেকচার কাজকে ছোট ইউনিটে ভাগ করে, প্রাধান্য দেয়, থামাতে ও পুনরায় শুরু করতে পারে। এটি কাজের একটি লিংকড লিস্ট মেইনটেইন করে।\n\nউদাহরণ:\n```javascript\n// Hooks — ছোট working example দেখান\n```", aEn: "React Fiber is the core engine that enables advanced features like concurrent rendering, prioritization, and interruptibility in React. Here's how it works:\n \n ### 1. Fiber Tree Structure\n \n Each component in your app is represented by a Fiber node in a tree structure. A Fiber node contains:\n  Component type\n  Props & state\n  Pointers to parent, child, and sibling nodes\n  Effect tags to track changes (e.g., update, placement)\n  This forms the Fiber Tree, a data structure React uses instead of the traditional call stack.\n \n ### 2. Two Phases of Rendering\n \n #### A. Render Phase (work-in-progress)\n \n  React builds a work-in-progress Fiber tree.\n  It walks through each component (begin phase), calculates what needs to change, and collects side effects (complete phase).\n  This phase is interruptible—React can pause it and resume later.\n #### B. Commit Phase\n \n  React applies changes to the Real DOM.\n  Runs lifecycle methods (e.g., `componentDidMount`, `useEffect`).\n  This phase is non-interruptible but fast.\n \n ### 3. Work Units and Scheduling\n \n  React breaks rendering into units of work (small tasks).\n  These units are scheduled based on priority using the React Scheduler.\n  If time runs out (e.g., user starts typing), React can pause and yield control back to the browser.\n \n ### 4. Double Buffering with Two Trees\n \n  React maintains two trees:\n  Current Tree – what's visible on the screen.\n  Work-In-Progress Tree – the next version being built in memory.\n  Only after the new tree is fully ready, React commits it, making it the new current tree.\n \n ### 5. Concurrency and Prioritization\n \n  React can prepare multiple versions of UI at once (e.g., during slow data loading).\n  Updates can be assigned priorities, so urgent updates (like clicks) are handled faster than background work." },
  { q: "৩১০. useId হুক কী এবং কখন ব্যবহার করবেন?", qEn: "310. What is the useId hook and when should you use it?", a: "সার্ভার ও ক্লায়েন্টের মধ্যে কনসিস্টেন্ট ইউনিক আইডি জেনারেট করে। অ্যাক্সেসিবিলিটি অ্যাট্রিবিউটের (যেমন aria-labelledby) জন্য ব্যবহার করুন।\n\nউদাহরণ:\n```javascript\n// Hooks — ছোট working example দেখান\n```", aEn: "The `useId` hook is a React hook introduced in React 18 that generates unique IDs that are stable across server and client renders. It's primarily used for accessibility attributes like linking form labels to inputs.\n\n #### Syntax\n     \n```javascript\n     const id = useId();\n```\n\n #### Example: Accessible Form Input\n     \n```javascript\n     import { useId } from 'react';\n\n     function EmailField() {\n       const id = useId();\n       \n       return (\n         <div>\n           <label htmlFor={id}>Email:</label>\n           <input id={id} type=\"email\" />\n         </div>\n       );\n     }\n```\n\n #### When to Use\n - Generating unique IDs for form elements (`htmlFor`, `aria-describedby`, `aria-labelledby`)\n - Creating stable IDs in server-side rendering (SSR) applications\n - Avoiding ID collisions when the same component is rendered multiple times\n\n #### When NOT to Use\n - As keys in a list (use data-based keys instead)\n - As CSS selectors or query selectors\n - For any purpose that requires the ID to be predictable\n\n Note: The IDs generated by `useId` contain colons (`:`) which may not work in CSS selectors. For multiple related IDs, you can use the same `id` as a prefix: `${id}-firstName`, `${id}-lastName`." },
  { q: "৩১১. useDeferredValue হুক কী?", qEn: "311. What is the useDeferredValue hook?", a: "UI-তে একটি ডিফারড (বিলম্বিত) সংস্করণ দেখায়। নন-আরজেন্ট আপডেটকে পিছিয়ে দেয়, যেমন ফিল্টারিং।\n\nউদাহরণ:\n```javascript\n// Hooks — ছোট working example দেখান\n```", aEn: "The `useDeferredValue` hook is used to defer updating a part of the UI to keep other parts responsive. It accepts a value and returns a \"deferred\" version of that value that may lag behind. This is useful for optimizing performance when rendering expensive components.\n\n #### Syntax\n     \n```javascript\n     const deferredValue = useDeferredValue(value);\n```\n\n #### Example: Search with Deferred Results\n     \n```javascript\n     import { useState, useDeferredValue, useMemo } from 'react';\n\n     function SearchResults({ query }) {\n       // Expensive computation or large list filtering\n       const results = useMemo(() => {\n         return largeDataSet.filter(item => \n           item.name.toLowerCase().includes(query.toLowerCase())\n         );\n       }, [query]);\n\n       return (\n         <ul>\n           {results.map(item => <li key={item.id}>{item.name}</li>)}\n         </ul>\n       );\n     }\n\n     function SearchPage() {\n       const [query, setQuery] = useState('');\n       const deferredQuery = useDeferredValue(query);\n       const isStale = query !== deferredQuery;\n\n       return (\n         <div>\n           <input \n             value={query} \n             onChange={(e) => setQuery(e.target.value)}\n             placeholder=\"Search...\"\n           />\n           <div style={{ opacity: isStale ? 0.5 : 1 }}>\n             <SearchResults query={deferredQuery} />\n           </div>\n         </div>\n       );\n     }\n```\n\n The input stays responsive while the expensive `SearchResults` component re-renders with a slight delay using the deferred value." },
  { q: "৩১২. useTransition হুক কী এবং useDeferredValue থেকে কীভাবে আলাদা?", qEn: "312. What is the useTransition hook and how does it differ from useDeferredValue?", a: "useTransition একটি isPending ফ্ল্যাগ দেয়। আলাদা:\n\nuseTransition: সেটস্টেট ফাংশনকে ট্রানজিশনে র‍্যাপ করে\n\nuseDeferredValue: মানকে ডিফার করে\n\nউদাহরণ:\n```javascript\nuseTransition একটি isPending ফ্ল্যাগ দেয়। আলাদা:\nuseTransition: সেটস্টেট ফাংশনকে ট্রানজিশনে র‍্যাপ করে\nuseDeferredValue: মানকে ডিফার করে\n```", aEn: "The `useTransition` hook allows you to mark certain state updates as non-urgent transitions, keeping the UI responsive during expensive re-renders. It returns a `isPending` flag and a `startTransition` function.\n\n #### Syntax\n     \n```javascript\n     const [isPending, startTransition] = useTransition();\n```\n\n #### Example: Tab Switching\n     \n```javascript\n     import { useState, useTransition } from 'react';\n\n     function TabContainer() {\n       const [isPending, startTransition] = useTransition();\n       const [tab, setTab] = useState('home');\n\n       function selectTab(nextTab) {\n         startTransition(() => {\n           setTab(nextTab);\n         });\n       }\n\n       return (\n         <div>\n           <button onClick={() => selectTab('home')}>Home</button>\n           <button onClick={() => selectTab('posts')}>Posts (slow)</button>\n           <button onClick={() => selectTab('contact')}>Contact</button>\n           \n           {isPending && <Spinner />}\n           \n           {tab === 'home' && <HomeTab />}\n           {tab === 'posts' && <PostsTab />}  {/ Expensive component /}\n           {tab === 'contact' && <ContactTab />}\n         </div>\n       );\n     }\n```\n\n #### Differences from useDeferredValue\n\n | Feature | useTransition | useDeferredValue |\n |---------|--------------|------------------|\n | Controls | State updates (wraps `setState`) | Values (wraps a value) |\n | Use case | When you control the state update | When you receive a value from props or other hooks |\n | Returns | `[isPending, startTransition]` | Deferred value |\n | Pending state | Built-in `isPending` flag | Manual comparison needed |" },
  { q: "৩১৩. useSyncExternalStore হুক কী?", qEn: "313. What is the useSyncExternalStore hook?", a: "বাহ্যিক স্টোর (যেমন Redux, Zustand) থেকে সিঙ্ক্রোনাসভাবে মান পড়ার হুক।\n\nউদাহরণ:\n```javascript\ndispatch({ type: 'ACTION', payload: data });\n```", aEn: "The `useSyncExternalStore` hook is designed to subscribe to external stores (non-React state sources) in a way that's compatible with concurrent rendering. It's primarily used by library authors for state management libraries.\n\n #### Syntax\n     \n```javascript\n     const state = useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot?);\n```\n\n - subscribe: Function to subscribe to the store, returns an unsubscribe function\n - getSnapshot: Function that returns the current store value\n - getServerSnapshot: Optional function for SSR that returns the initial server snapshot\n\n #### Example: Browser Online Status\n     \n```javascript\n     import { useSyncExternalStore } from 'react';\n\n     function getSnapshot() {\n       return navigator.onLine;\n     }\n\n     function subscribe(callback) {\n       window.addEventListener('online', callback);\n       window.addEventListener('offline', callback);\n       return () => {\n         window.removeEventListener('online', callback);\n         window.removeEventListener('offline', callback);\n       };\n     }\n\n     function useOnlineStatus() {\n       return useSyncExternalStore(subscribe, getSnapshot, () => true);\n     }\n\n     function StatusBar() {\n       const isOnline = useOnlineStatus();\n       return <h1>{isOnline ? '✅ Online' : '❌ Disconnected'}</h1>;\n     }\n```\n\n This hook ensures that when the external store changes, React re-renders consistently without tearing (showing inconsistent data)." },
  { q: "৩১৪. useInsertionEffect হুক কী?", qEn: "314. What is the useInsertionEffect hook?", a: "CSS-in-JS লাইব্রেরির জন্য। DOM মিউটেশনের আগে স্টাইল ইনজেক্ট করে। লেআউট ইফেক্টের পর চলে।\n\nউদাহরণ:\n```javascript\nuseEffect(() => {\n  // side effect\n  return () => cleanup();\n}, [deps]);\n```", aEn: "The `useInsertionEffect` hook is designed for CSS-in-JS library authors to inject styles into the DOM before any layout effects run. It fires synchronously before DOM mutations.\n\n #### Syntax\n     \n```javascript\n     useInsertionEffect(() => {\n       // Insert styles here\n       return () => {\n         // Cleanup\n       };\n     }, [dependencies]);\n```\n\n #### Execution Order\n     \n```javascript\n     1. useInsertionEffect  → Inject styles\n     2. DOM mutations       → React updates DOM\n     3. useLayoutEffect     → Read layout, synchronously re-render if needed\n     4. Browser paint       → User sees the result\n     5. useEffect           → Side effects run\n```\n\n #### Example: Dynamic Style Injection\n     \n```javascript\n     import { useInsertionEffect } from 'react';\n\n     let isInserted = new Set();\n\n     function useCSS(rule) {\n       useInsertionEffect(() => {\n         if (!isInserted.has(rule)) {\n           isInserted.add(rule);\n           const style = document.createElement('style');\n           style.textContent = rule;\n           document.head.appendChild(style);\n         }\n       }, [rule]);\n     }\n\n     function Button() {\n       useCSS('.dynamic-btn { background: blue; color: white; }');\n       return <button className=\"dynamic-btn\">Click me</button>;\n     }\n```\n\n Note: This hook is not intended for application code. It's specifically for CSS-in-JS libraries like styled-components or Emotion to prevent style flickering." },
  { q: "৩১৫. কীভাবে কাস্টম হুক ব্যবহার করে কম্পোনেন্টের মধ্যে স্টেট লজিক শেয়ার করবেন?", qEn: "315. How do you share state logic between components using custom hooks?", a: "স্টেট, ইফেক্ট, রেফ ইত্যাদি কাস্টম হুকের ভেতর রেখে তা একাধিক কম্পোনেন্টে ব্যবহার করুন।\n\nউদাহরণ:\n```javascript\nuseEffect(() => {\n  // side effect\n  return () => cleanup();\n}, [deps]);\n```", aEn: "Custom hooks allow you to extract and share stateful logic between components without changing their hierarchy. The state itself is not shared—each component using the hook gets its own isolated state.\n\n #### Example: useLocalStorage Hook\n     \n```javascript\n     import { useState, useEffect } from 'react';\n\n     function useLocalStorage(key, initialValue) {\n       // Get stored value or use initial value\n       const [storedValue, setStoredValue] = useState(() => {\n         try {\n           const item = window.localStorage.getItem(key);\n           return item ? JSON.parse(item) : initialValue;\n         } catch (error) {\n           console.error(error);\n           return initialValue;\n         }\n       });\n\n       // Update localStorage when state changes\n       useEffect(() => {\n         try {\n           window.localStorage.setItem(key, JSON.stringify(storedValue));\n         } catch (error) {\n           console.error(error);\n         }\n       }, [key, storedValue]);\n\n       return [storedValue, setStoredValue];\n     }\n\n     // Usage in multiple components\n     function ThemeToggle() {\n       const [theme, setTheme] = useLocalStorage('theme', 'light');\n       return (\n         <button onClick={() => setTheme(theme === 'light' ? 'dark' : 'light')}>\n           Current: {theme}\n         </button>\n       );\n     }\n\n     function FontSizeSelector() {\n       const [fontSize, setFontSize] = useLocalStorage('fontSize', 16);\n       return (\n         <input \n           type=\"range\" \n           value={fontSize} \n           onChange={(e) => setFontSize(Number(e.target.value))} \n         />\n       );\n     }\n```\n\n Both components use `useLocalStorage`, but each has its own independent state that persists to localStorage." },
  { q: "৩১৬. useDebugValue হুক কী?", qEn: "316. What is the useDebugValue hook?", a: "ডেভ টুলসে কাস্টম হুকের লেবেল প্রদর্শন করতে।\n\nউদাহরণ:\n```javascript\n// Hooks — ছোট working example দেখান\n```", aEn: "The `useDebugValue` hook is used to display a label for custom hooks in React DevTools. It helps developers debug custom hooks by showing meaningful information.\n\n #### Syntax\n     \n```javascript\n     useDebugValue(value);\n     useDebugValue(value, formatFn); // With optional formatter\n```\n\n #### Example: Custom Hook with Debug Value\n     \n```javascript\n     import { useState, useEffect, useDebugValue } from 'react';\n\n     function useOnlineStatus() {\n       const [isOnline, setIsOnline] = useState(true);\n\n       useEffect(() => {\n         const handleOnline = () => setIsOnline(true);\n         const handleOffline = () => setIsOnline(false);\n         \n         window.addEventListener('online', handleOnline);\n         window.addEventListener('offline', handleOffline);\n         \n         return () => {\n           window.removeEventListener('online', handleOnline);\n           window.removeEventListener('offline', handleOffline);\n         };\n       }, []);\n\n       // Shows \"OnlineStatus: Online\" or \"OnlineStatus: Offline\" in DevTools\n       useDebugValue(isOnline ? 'Online' : 'Offline');\n\n       return isOnline;\n     }\n```\n\n #### With Formatting Function (for expensive computations)\n     \n```javascript\n     function useUser(userId) {\n       const [user, setUser] = useState(null);\n       \n       // The format function only runs when DevTools is open\n       useDebugValue(user, (user) => user ? `User: ${user.name}` : 'Loading...');\n       \n       return user;\n     }\n```\n\n Note: Only use `useDebugValue` in custom hooks that are part of shared libraries. It's not necessary for every custom hook in application code." },
  { q: "৩১৭. useEffect-এ কীভাবে ক্লিনআপ হ্যান্ডেল করবেন?", qEn: "317. How do you handle cleanup in useEffect?", a: "রিটার্ন একটি ফাংশন করুন:\n\nউদাহরণ:\n\n```javascript\nuseEffect(() => {\n  const timer = setInterval(...);\n  return () => clearInterval(timer);\n}, []);\n```", aEn: "The cleanup function in `useEffect` is used to clean up side effects before the component unmounts or before the effect runs again. This prevents memory leaks, stale data, and unexpected behavior.\n\n #### Syntax\n     \n```javascript\n     useEffect(() => {\n       // Setup code\n       \n       return () => {\n         // Cleanup code\n       };\n     }, [dependencies]);\n```\n\n #### Common Cleanup Scenarios\n\n 1. Event Listeners\n     \n```javascript\n     useEffect(() => {\n       const handleResize = () => setWidth(window.innerWidth);\n       window.addEventListener('resize', handleResize);\n       \n       return () => window.removeEventListener('resize', handleResize);\n     }, []);\n```\n\n 2. Timers and Intervals\n     \n```javascript\n     useEffect(() => {\n       const intervalId = setInterval(() => {\n         setCount(c => c + 1);\n       }, 1000);\n       \n       return () => clearInterval(intervalId);\n     }, []);\n```\n\n 3. Subscriptions\n     \n```javascript\n     useEffect(() => {\n       const subscription = dataSource.subscribe(handleChange);\n       \n       return () => subscription.unsubscribe();\n     }, [dataSource]);\n```\n\n 4. Abort Fetch Requests\n     \n```javascript\n     useEffect(() => {\n       const controller = new AbortController();\n       \n       fetch(url, { signal: controller.signal })\n         .then(response => response.json())\n         .then(data => setData(data))\n         .catch(err => {\n           if (err.name !== 'AbortError') {\n             setError(err);\n           }\n         });\n       \n       return () => controller.abort();\n     }, [url]);\n```\n\n When Cleanup Runs:\n - Before the component unmounts\n - Before re-running the effect when dependencies change" },
  { q: "৩১৮. useEffect ও experimental useEvent-এর মধ্যে পার্থক্য কী?", qEn: "318. What are the differences between useEffect and useEvent (experimental)?", a: "useEvent ডিপেন্ডেন্সি পরিবর্তন ছাড়াই সর্বশেষ প্রপস/স্টেট অ্যাক্সেস করে। এটি কখনো পরিবর্তিত হয় না।\n\nউদাহরণ:\n```javascript\nuseEffect(() => {\n  // side effect\n  return () => cleanup();\n}, [deps]);\n```", aEn: "`useEvent` is an experimental hook (not yet stable in React) designed to solve the problem of creating stable event handlers that always access the latest props and state without causing re-renders or needing to be in dependency arrays.\n\n #### The Problem useEvent Solves\n     \n```javascript\n     // Problem: onTick changes on every render, causing interval to reset\n     function Timer({ onTick }) {\n       useEffect(() => {\n         const id = setInterval(() => {\n           onTick(); // Uses stale closure if onTick is not in deps\n         }, 1000);\n         return () => clearInterval(id);\n       }, [onTick]); // Adding onTick causes interval to reset frequently\n     }\n```\n\n #### Solution with useEvent (Experimental)\n     \n```javascript\n     import { useEvent } from 'react'; // Experimental\n\n     function Timer({ onTick }) {\n       const stableOnTick = useEvent(onTick);\n\n       useEffect(() => {\n         const id = setInterval(() => {\n           stableOnTick(); // Always calls latest onTick\n         }, 1000);\n         return () => clearInterval(id);\n       }, []); // No dependency needed!\n     }\n```\n\n #### Key Differences\n\n | Feature | useEffect | useEvent (experimental) |\n |---------|-----------|------------------------|\n | Purpose | Run side effects | Create stable callbacks |\n | Runs | After render | During render (creates function) |\n | Returns | Cleanup function | Stable event handler |\n | Closure | Captures values at render time | Always accesses latest values |\n | Dependencies | Must list all used values | Not needed in other hooks' deps |\n\n Note: Until `useEvent` is stable, you can use `useCallback` with `useRef` as a workaround for stable callbacks." },
  { q: "৩১৯. রিয়্যাক্ট হুকস ব্যবহারের জন্য সেরা অভ্যাসগুলো কী কী?", qEn: "319. What are the best practices for using React Hooks?", a: "সব সময় টপ-লেভেলে কল করুন\n\nশুধুমাত্র রিয়্যাক্ট ফাংশনে কল করুন\n\nডিপেন্ডেন্সি অ্যারে সঠিক দিন\n\nকাস্টম হুকে লজিক রিইউজ করুন\n\neslint-plugin-react-hooks ব্যবহার করুন\n\nউদাহরণ:\nTop-level only; React functions only; eslint-plugin-react-hooks চালু রাখুন।", aEn: "Following best practices ensures your hooks are predictable, maintainable, and bug-free.\n\n #### 1. Follow the Rules of Hooks\n - Only call hooks at the top level (not inside loops, conditions, or nested functions)\n - Only call hooks from React functions (components or custom hooks)\n\n #### 2. Use the ESLint Plugin\n     \n```bash\n     npm install eslint-plugin-react-hooks --save-dev\n```\n     \n```json\n     {\n       \"plugins\": [\"react-hooks\"],\n       \"rules\": {\n         \"react-hooks/rules-of-hooks\": \"error\",\n         \"react-hooks/exhaustive-deps\": \"warn\"\n       }\n     }\n```\n\n #### 3. Keep Hooks Focused and Simple\n     \n```javascript\n     // ❌ Bad: One hook doing too much\n     function useEverything() {\n       const [user, setUser] = useState(null);\n       const [posts, setPosts] = useState([]);\n       const [theme, setTheme] = useState('light');\n       // ... lots of unrelated logic\n     }\n\n     // ✅ Good: Separate concerns\n     function useUser() { / user logic / }\n     function usePosts() { / posts logic / }\n     function useTheme() { / theme logic / }\n```\n\n #### 4. Use Descriptive Names for Custom Hooks\n     \n```javascript\n     // ❌ Bad\n     function useData() { }\n\n     // ✅ Good\n     function useUserAuthentication() { }\n     function useFetchProducts() { }\n     function useFormValidation() { }\n```\n\n #### 5. Properly Manage Dependencies\n     \n```javascript\n     // ❌ Bad: Missing dependency\n     useEffect(() => {\n       fetchUser(userId);\n     }, []); // userId is missing\n\n     // ✅ Good: All dependencies listed\n     useEffect(() => {\n       fetchUser(userId);\n     }, [userId]);\n```\n\n #### 6. Avoid Inline Object/Function Dependencies\n     \n```javascript\n     // ❌ Bad: New object on every render\n     useEffect(() => {\n       doSomething(options);\n     }, [{ page: 1, limit: 10 }]); // Always different reference\n\n     // ✅ Good: Memoize or extract\n     const options = useMemo(() => ({ page: 1, limit: 10 }), []);\n     useEffect(() => {\n       doSomething(options);\n     }, [options]);\n```\n\n #### 7. Clean Up Side Effects\n Always return a cleanup function when subscribing to events, timers, or external data sources." },
  { q: "৩২০. কেন সরাসরি state আপডেট করা উচিত নয়?", qEn: "320. Why should we not update the state directly?", a: "সরাসরি `this.state.message = 'Hello'` লিখলে React re-render ট্রিগার করে না। `this.setState({ message: 'Hello' })` ব্যবহার করুন—এটি আপডেট শিডিউল করে। constructor বা class field syntax-এ সরাসরি assign করা যায়।", aEn: "If you try to update the state directly then it won't re-render the component.\n\n   \n```javascript\n   //Wrong\n   this.state.message = \"Hello world\";\n```\n\n Instead use `setState()` method. It schedules an update to a component's state object. When state changes, the component responds by re-rendering.\n\n   \n```javascript\n   //Correct\n   this.setState({ message: \"Hello World\" });\n```\n\n Note: You can directly assign to the state object either in _constructor_ or using latest javascript's class field declaration syntax." },
  { q: "৩২১. setState()-এ callback ফাংশনের উদ্দেশ্য কী?", qEn: "321. What is the purpose of callback function as an argument of `setState()`?", a: "setState অ্যাসিঙ্ক্রোনাস; আপডেটের ঠিক পরেই নতুন state নির্ভর কাজের জন্য দ্বিতীয় আর্গুমেন্ট হিসেবে callback দিন। ফাংশন কম্পোনেন্টে `useEffect` দিয়ে একই ধরনের কাজ করা যায়।", aEn: "The callback function provided as the second argument to `setState` is executed after the state has been updated and the component has re-rendered. Because `setState()` is asynchronous, you cannot reliably perform actions that require the updated state immediately after calling `setState`. The callback ensures your code runs only after the update and re-render are complete.\n\n #### Example\n\n    \n```javascript\n    this.setState({ name: \"Sudheer\" }, () => {\n      console.log(\"The name has been updated and the component has re-rendered.\");\n    });\n```\n\n #### When to use the callback?\n\n Use the `setState` callback when you need to perform an action immediately after the DOM has been updated in response to a state change. i.e, The callback is a reliable way to perform actions after a state update and re-render, especially when the timing is critical due to the asynchronous nature of state updates in React. For example, if you need to interact with the updated DOM, trigger analytics, or perform further computations that depend on the new state or rendered output.\n\n #### Note\n\n - In modern React (with function components), you can achieve similar effects using the `useEffect` hook to respond to state changes.\n - In class components, you can also use lifecycle methods like `componentDidUpdate` for broader post-update logic.\n - The `setState` callback is still useful for one-off actions that directly follow a specific state change." },
  { q: "৩২২. JSX callback-এ মেথড বা ইভেন্ট হ্যান্ডলার কীভাবে bind করবেন?", qEn: "322. How to bind methods or event handlers in JSX callbacks?", a: "ক্লাস কম্পোনেন্টে তিন উপায়: (১) constructor-এ `.bind(this)`, (২) public class fields (`handleClick = () => {}`), (৩) JSX-এ arrow `onClick={() => this.handleClick()}`। child-এ prop হিসেবে পাস করলে arrow বেশি re-render করতে পারে—bind/fields ভালো।", aEn: "There are 3 possible ways to achieve this in class components:\n\n 1. Binding in Constructor: In JavaScript classes, the methods are not bound by default. The same rule applies for React event handlers defined as class methods. Normally we bind them in constructor.\n\n      \n```javascript\n      class User extends Component {\n        constructor(props) {\n          super(props);\n          this.handleClick = this.handleClick.bind(this);\n        }\n        handleClick() {\n          console.log(\"SingOut triggered\");\n        }\n        render() {\n          return <button onClick={this.handleClick}>SingOut</button>;\n        }\n      }\n```\n\n 2. Public class fields syntax: If you don't like to use bind approach then _public class fields syntax_ can be used to correctly bind callbacks. The Create React App enables this syntax by default.\n\n      ```jsx harmony\n      handleClick = () => {\n        console.log(\"SingOut triggered\", this);\n      };\n      \n```javascript\n\n```jsx harmony\n      <button onClick={this.handleClick}>SingOut</button>\n      \n```javascript\n\n 3. Arrow functions in callbacks: It is possible to use _arrow functions_ directly in the callbacks.\n```jsx harmony\n      handleClick() {\n          console.log('SingOut triggered');\n      }\n      render() {\n          return <button onClick={() => this.handleClick()}>SignOut</button>;\n      }\n      ```\n\n Note: If the callback is passed as prop to child components, those components might do an extra re-rendering. In those cases, it is preferred to go with `.bind()` or _public class fields syntax_ approach considering performance." },
  { q: "৩২৩. ইভেন্ট হ্যান্ডলার বা callback-এ প্যারামিটার কীভাবে পাস করবেন?", qEn: "323. How to pass a parameter to an event handler or callback?", a: "`<button onClick={() => this.handleClick(id)} />` অথবা `onClick={this.handleClick.bind(this, id)}`। curried arrow: `handleClick = (id) => () => { ... }`।", aEn: "You can use an _arrow function_ to wrap around an _event handler_ and pass parameters:\n\n   ```jsx harmony\n   <button onClick={() => this.handleClick(id)} />\n   \n```javascript\n\n This is an equivalent to calling `.bind`:\n```jsx harmony\n   <button onClick={this.handleClick.bind(this, id)} />\n   \n```javascript\n\n Apart from these two approaches, you can also pass arguments to a function which is defined as arrow function\n```jsx harmony\n   <button onClick={this.handleClick(id)} />;\n   handleClick = (id) => () => {\n     console.log(\"Hello, your ticket number is\", id);\n   };\n   ```" },
  { q: "৩২৪. refs-এর ব্যবহার কী?", qEn: "324. What is the use of refs?", a: "ref DOM বা ক্লাস ইনস্ট্যান্সে সরাসরি অ্যাক্সেস দেয়। বেশিরভাগ ক্ষেত্রে এড়িয়ে চলুন; focus, scroll, third-party ইন্টিগ্রেশনে দরকার হতে পারে।", aEn: "The _ref_ is used to return a reference to the element. They _should be avoided_ in most cases, however, they can be useful when you need a direct access to the DOM element or an instance of a component." },
  { q: "৩২৫. refs কীভাবে তৈরি করবেন?", qEn: "325. How to create refs?", a: "`React.createRef()` + `ref={this.myRef}` অথবা callback ref `(el) => { this.txt = el }`। ফাংশন কম্পোনেন্টে `useRef`।", aEn: "There are two approaches\n\n 1. This is a recently added approach. _Refs_ are created using `React.createRef()` method and attached to React elements via the `ref` attribute. In order to use _refs_ throughout the component, just assign the _ref_ to the instance property within constructor.\n\n      ```jsx harmony\n      class MyComponent extends React.Component {\n        constructor(props) {\n          super(props);\n          this.myRef = React.createRef();\n        }\n        render() {\n          return <div ref={this.myRef} />;\n        }\n      }\n      \n```javascript\n\n 2. You can also use ref callbacks approach regardless of React version. For example, the search bar component's input element is accessed as follows,\n```jsx harmony\n      class SearchBar extends Component {\n        constructor(props) {\n          super(props);\n          this.txtSearch = null;\n          this.state = { term: \"\" };\n          this.setInputSearchRef = (e) => {\n            this.txtSearch = e;\n          };\n        }\n        onInputChange(event) {\n          this.setState({ term: this.txtSearch.value });\n        }\n        render() {\n          return (\n            <input\n              value={this.state.term}\n              onChange={this.onInputChange.bind(this)}\n              ref={this.setInputSearchRef}\n            />\n          );\n        }\n      }\n      ```\n\n You can also use _refs_ in function components using closures.\n Note: You can also use inline ref callbacks even though it is not a recommended approach." },
  { q: "৩২৬. forward refs কী?", qEn: "326. What are forward refs?", a: "`React.forwardRef((props, ref) => <button ref={ref} />)` child-এ ref পাঠায়।", aEn: "_Ref forwarding_ is a feature that lets some components take a _ref_ they receive, and pass it further down to a child.\n\n   ```jsx harmony\n   const ButtonElement = React.forwardRef((props, ref) => (\n     <button ref={ref} className=\"CustomButton\">\n       {props.children}\n     </button>\n   ));\n\n   // Create ref to the DOM button:\n   const ref = React.createRef();\n   <ButtonElement ref={ref}>{\"Forward Ref\"}</ButtonElement>;\n   ```" },
  { q: "৩২৭. callback refs ও findDOMNode()-এর মধ্যে কোনটি ভালো?", qEn: "327. Which is preferred option with in callback refs and findDOMNode()?", a: "callback refs বা `createRef` ব্যবহার করুন; `findDOMNode()` এড়ান—ভবিষ্যৎ React অপ্টিমাইজেশনে বাধা দেয়।", aEn: "It is preferred to use _callback refs_ over `findDOMNode()` API. Because `findDOMNode()` prevents certain improvements in React in the future.\n\n The legacy approach of using `findDOMNode`:\n\n   \n```javascript\n   class MyComponent extends Component {\n     componentDidMount() {\n       findDOMNode(this).scrollIntoView();\n     }\n\n     render() {\n       return <div />;\n     }\n   }\n```\n\n The recommended approach is:\n\n   \n```javascript\n   class MyComponent extends Component {\n     constructor(props) {\n       super(props);\n       this.node = createRef();\n     }\n     componentDidMount() {\n       this.node.current.scrollIntoView();\n     }\n\n     render() {\n       return <div ref={this.node} />;\n     }\n   }\n```" },
  { q: "৩২৮. String Refs কেন legacy?", qEn: "328. Why are String Refs legacy?", a: "String refs (`ref='x'`, `this.refs.x`) legacy: React stateful রাখে, composable নয়, static analysis-এ খারাপ; React 16-এ সরানো হয়েছে।", aEn: "If you worked with React before, you might be familiar with an older API where the `ref` attribute is a string, like `ref={'textInput'}`, and the DOM node is accessed as `this.refs.textInput`. We advise against it because _string refs have below issues_, and are considered legacy. String refs were removed in React v16.\n\n 1. They _force React to keep track of currently executing component_. This is problematic because it makes react module stateful, and thus causes weird errors when react module is duplicated in the bundle.\n 2. They are _not composable_ — if a library puts a ref on the passed child, the user can't put another ref on it. Callback refs are perfectly composable.\n 3. They _don't work with static analysis_ like Flow. Flow can't guess the magic that framework does to make the string ref appear on `this.refs`, as well as its type (which could be different). Callback refs are friendlier to static analysis.\n 4. It doesn't work as most people would expect with the \"render callback\" pattern (e.g.)\n\n      ```jsx harmony\n      class MyComponent extends Component {\n        renderRow = (index) => {\n          // This won't work. Ref will get attached to DataTable rather than MyComponent:\n          return <input ref={\"input-\" + index} />;\n\n          // This would work though! Callback refs are awesome.\n          return <input ref={(input) => (this[\"input-\" + index] = input)} />;\n        };\n\n        render() {\n          return (\n            <DataTable data={this.props.data} renderRow={this.renderRow} />\n          );\n        }\n      }\n      ```" },
  { q: "৩২৯. কম্পোনেন্ট lifecycle-এর বিভিন্ন ধাপ কী কী?", qEn: "329. What are the different phases of component lifecycle?", a: "তিন ধাপ: Mounting (constructor → getDerivedStateFromProps → render → componentDidMount), Updating (shouldComponentUpdate, render, getSnapshotBeforeUpdate, componentDidUpdate), Unmounting (componentWillUnmount)। React-এর Render/Pre-commit/Commit ফেজও আছে।", aEn: "The component lifecycle has three distinct lifecycle phases:\n\n 1. Mounting: The component is ready to mount in the browser DOM. This phase covers initialization from `constructor()`, `getDerivedStateFromProps()`, `render()`, and `componentDidMount()` lifecycle methods.\n\n 2. Updating: In this phase, the component gets updated in two ways, sending the new props and updating the state either from `setState()` or `forceUpdate()`. This phase covers `getDerivedStateFromProps()`, `shouldComponentUpdate()`, `render()`, `getSnapshotBeforeUpdate()` and `componentDidUpdate()` lifecycle methods.\n\n 3. Unmounting: In this last phase, the component is not needed and gets unmounted from the browser DOM. This phase includes `componentWillUnmount()` lifecycle method.\n\n It's worth mentioning that React internally has a concept of phases when applying changes to the DOM. They are separated as follows\n\n 4. Render The component will render without any side effects. This applies to Pure components and in this phase, React can pause, abort, or restart the render.\n\n 5. Pre-commit Before the component actually applies the changes to the DOM, there is a moment that allows React to read from the DOM through the `getSnapshotBeforeUpdate()`.\n\n 6. Commit React works with the DOM and executes the final lifecycles respectively `componentDidMount()` for mounting, `componentDidUpdate()` for updating, and `componentWillUnmount()` for unmounting.\n\n React 16.3+ Phases (or an interactive version)\n\n !phases 16.4+\n\n Before React 16.3\n\n !phases 16.2" },
  { q: "৩৩০. React-এর lifecycle methods কী কী?", qEn: "330. What are the lifecycle methods of React?", a: "16.3-এর আগে: componentWillMount, componentDidMount, componentWillReceiveProps, shouldComponentUpdate, componentWillUpdate, componentDidUpdate, componentWillUnmount। 16.3+: getDerivedStateFromProps, componentDidMount, shouldComponentUpdate, getSnapshotBeforeUpdate, componentDidUpdate, componentWillUnmount।", aEn: "Before React 16.3\n\n - componentWillMount: Executed before rendering and is used for App level configuration in your root component.\n - componentDidMount: Executed after first rendering and here all AJAX requests, DOM or state updates, and set up event listeners should occur.\n - componentWillReceiveProps: Executed when particular prop updates to trigger state transitions.\n - shouldComponentUpdate: Determines if the component will be updated or not. By default it returns `true`. If you are sure that the component doesn't need to render after state or props are updated, you can return false value. It is a great place to improve performance as it allows you to prevent a re-render if component receives new prop.\n - componentWillUpdate: Executed before re-rendering the component when there are props & state changes confirmed by `shouldComponentUpdate()` which returns true.\n - componentDidUpdate: Mostly it is used to update the DOM in response to prop or state changes.\n - componentWillUnmount: It will be used to cancel any outgoing network requests, or remove all event listeners associated with the component.\n\n React 16.3+\n\n - getDerivedStateFromProps: Invoked right before calling `render()` and is invoked on _every_ render. This exists for rare use cases where you need a derived state. Worth reading if you need derived state.\n - componentDidMount: Executed after first rendering and where all AJAX requests, DOM or state updates, and set up event listeners should occur.\n - shouldComponentUpdate: Determines if the component will be updated or not. By default, it returns `true`. If you are sure that the component doesn't need to render after the state or props are updated, you can return a false value. It is a great place to improve performance as it allows you to prevent a re-render if component receives a new prop.\n - getSnapshotBeforeUpdate: Executed right before rendered output is committed to the DOM. Any value returned by this will be passed into `componentDidUpdate()`. This is useful to capture information from the DOM i.e. scroll position.\n - componentDidUpdate: Mostly it is used to update the DOM in response to prop or state changes. This will not fire if `shouldComponentUpdate()` returns `false`.\n - componentWillUnmount It will be used to cancel any outgoing network requests, or remove all event listeners associated with the component." },
  { q: "৩৩১. HOC কম্পোনেন্টে props proxy কীভাবে তৈরি করবেন?", qEn: "331. How to create props proxy for HOC component?", a: "HOC render-এ নতুন props মার্জ করে wrapped কম্পোনেন্টে পাঠান: `<WrappedComponent {...this.props} {...newProps} />`।", aEn: "You can add/edit props passed to the component using _props proxy_ pattern like this:\n\n    ```jsx harmony\n    function HOC(WrappedComponent) {\n      return class Test extends Component {\n        render() {\n          const newProps = {\n            title: \"New Header\",\n            footer: false,\n            showFeatureX: false,\n            showFeatureY: true,\n          };\n\n          return <WrappedComponent {...this.props} {...newProps} />;\n        }\n      };\n    }\n    ```" },
  { q: "৩৩২. context কী?", qEn: "332. What is context?", a: "Context ট্রিতে props ছাড়াই ডেটা শেয়ার করে (theme, auth, locale)। `React.createContext(defaultValue)` → Provider/Consumer।", aEn: "_Context_ provides a way to pass data through the component tree without having to pass props down manually at every level.\n\n For example, authenticated users, locale preferences, UI themes need to be accessed in the application by many components.\n\n    \n```javascript\n    const { Provider, Consumer } = React.createContext(defaultValue);\n```" },
  { q: "৩৩৩. super constructor-এ props আর্গুমেন্ট ব্যবহারের উদ্দেশ্য কী?", qEn: "333. What is the purpose of using super constructor with props argument?", a: "child constructor-এ `super(props)` না হলে `this.props` undefined থাকে; constructor-এর বাইরে পার্থক্য নেই। `props` প্যারামিটার সবসময় পাওয়া যায়।", aEn: "A child class constructor cannot make use of `this` reference until the `super()` method has been called. The same applies to ES6 sub-classes as well. The main reason for passing props parameter to `super()` call is to access `this.props` in your child constructors.\n\n Passing props:\n\n    \n```javascript\n    class MyComponent extends React.Component {\n      constructor(props) {\n        super(props);\n\n        console.log(this.props); // prints { name: 'John', age: 42 }\n      }\n    }\n```\n\n Not passing props:\n\n    \n```javascript\n    class MyComponent extends React.Component {\n      constructor(props) {\n        super();\n\n        console.log(this.props); // prints undefined\n\n        // but props parameter is still available\n        console.log(props); // prints { name: 'John', age: 42 }\n      }\n\n      render() {\n        // no difference outside constructor\n        console.log(this.props); // prints { name: 'John', age: 42 }\n      }\n    }\n```\n\n The above code snippets reveals that `this.props` is different only within the constructor. It would be the same outside the constructor." },
  { q: "৩৩৪. ডাইনামিক key নাম দিয়ে state কীভাবে সেট করবেন?", qEn: "334. How to set state with a dynamic key name?", a: "computed property: `this.setState({ [event.target.id]: event.target.value })`।", aEn: "If you are using ES6 or the Babel transpiler to transform your JSX code then you can accomplish this with _computed property names_.\n\n    \n```javascript\n    handleInputChange(event) {\n      this.setState({ [event.target.id]: event.target.value })\n    }\n```" },
  { q: "৩৩৫. রেন্ডারে ফাংশন প্রতিবার কল হওয়ার সাধারণ ভুল কী?", qEn: "335. What would be the common mistake of function being called every time the component renders?", a: "ভুল: `onClick={this.handleClick()}` (প্রতি render-এ কল)। সঠিক: `onClick={this.handleClick}` বা arrow wrapper।", aEn: "You need to make sure that function is not being called while passing the function as a parameter.\n\n    ```jsx harmony\n    render() {\n      // Wrong: handleClick is called instead of passed as a reference!\n      return <button onClick={this.handleClick()}>{'Click Me'}</button>\n    }\n    \n```javascript\n\n Instead, pass the function itself without parenthesis:\n```jsx harmony\n    render() {\n      // Correct: handleClick is passed as a reference!\n      return <button onClick={this.handleClick}>{'Click Me'}</button>\n    }\n    ```" },
  { q: "৩৩৬. React v16-এ error boundaries কী?", qEn: "336. What are error boundaries in React v16?", a: "Error boundary child tree-এর JS error ধরে fallback UI দেখায়। `componentDidCatch` বা `static getDerivedStateFromError` সহ class component।", aEn: "_Error boundaries_ are components that catch JavaScript errors anywhere in their child component tree, log those errors, and display a fallback UI instead of the component tree that crashed.\n\n A class component becomes an error boundary if it defines a new lifecycle method called `componentDidCatch(error, info)` or `static getDerivedStateFromError() `:\n\n    ```jsx harmony\n    class ErrorBoundary extends React.Component {\n      constructor(props) {\n        super(props);\n        this.state = { hasError: false };\n      }\n\n      componentDidCatch(error, info) {\n        // You can also log the error to an error reporting service\n        logErrorToMyService(error, info);\n      }\n\n      static getDerivedStateFromError(error) {\n        // Update state so the next render will show the fallback UI.\n        return { hasError: true };\n      }\n\n      render() {\n        if (this.state.hasError) {\n          // You can render any custom fallback UI\n          return <h1>{\"Something went wrong.\"}</h1>;\n        }\n        return this.props.children;\n      }\n    }\n    \n```javascript\n\n After that use it as a regular component:\n```jsx harmony\n    <ErrorBoundary>\n      <MyWidget />\n    </ErrorBoundary>\n    ```" },
  { q: "৩৩৭. React v15-তে error boundaries কীভাবে handle করা হয়?", qEn: "337. How are error boundaries handled in React v15?", a: "React 15-এ `unstable_handleError`; v16-এ `componentDidCatch`।", aEn: "React v15 provided very basic support for _error boundaries_ using `unstable_handleError` method. It has been renamed to `componentDidCatch` in React v16." },
  { q: "৩৩৮. react-dom-এর render মেথডের উদ্দেশ্য কী?", qEn: "338. What is the purpose of render method of `react-dom`?", a: "`ReactDOM.render(element, container, callback)` DOM-এ রেন্ডার/আপডেট করে; optional callback render/update-এর পর চলে।", aEn: "This method is used to render a React element into the DOM in the supplied container and return a reference to the component. If the React element was previously rendered into container, it will perform an update on it and only mutate the DOM as necessary to reflect the latest changes.\n\n    \n```javascript\n    ReactDOM.render(element, container, [callback])\n```\n\n If the optional callback is provided, it will be executed after the component is rendered or updated." },
  { q: "৩৩৯. constructor-এ setState() ব্যবহার করলে কী হবে?", qEn: "339. What will happen if you use `setState()` in constructor?", a: "constructor-এ setState re-render চায় কিন্তু কম্পোনেন্ট এখনো mount হয়নি—তাই `this.state = {...}` দিয়ে initialize করুন।", aEn: "When you use `setState()`, then apart from assigning to the object state React also re-renders the component and all its children. You would get error like this: _Can only update a mounted or mounting component._ So we need to use `this.state` to initialize variables inside constructor." },
  { q: "৩৪০. componentWillMount()-এ setState() ব্যবহার করা ভালো?", qEn: "340. Is it good to use `setState()` in `componentWillMount()` method?", a: "componentWillMount-এ setState নিরাপদ কিন্তু async/side-effect এড়ান; ডেটা fetch `componentDidMount`-এ করুন।", aEn: "Yes, it is safe to use `setState()` inside `componentWillMount()` method. But at the same it is recommended to avoid async initialization in `componentWillMount()` lifecycle method. `componentWillMount()` is invoked immediately before mounting occurs. It is called before `render()`, therefore setting state in this method will not trigger a re-render. Avoid introducing any side-effects or subscriptions in this method. We need to make sure async calls for component initialization happened in `componentDidMount()` instead of `componentWillMount()`.\n\n    ```jsx harmony\n    componentDidMount() {\n      axios.get(`api/todos`)\n        .then((result) => {\n          this.setState({\n            messages: [...result.data]\n          })\n        })\n    }\n    ```" },
  { q: "৩৪১. initial state-এ props ব্যবহার করলে কী হবে?", qEn: "341. What will happen if you use props in initial state?", a: "constructor-এ props থেকে state একবারই সেট হয়; props পরে বদলালে state আপডেট হয় না—controlled হলে render-এ `this.props` ব্যবহার করুন।", aEn: "If the props on the component are changed without the component being refreshed, the new prop value will never be displayed because the constructor function will never update the current state of the component. The initialization of state from props only runs when the component is first created.\n\n The below component won't display the updated input value:\n\n    ```jsx harmony\n    class MyComponent extends React.Component {\n      constructor(props) {\n        super(props);\n\n        this.state = {\n          records: [],\n          inputValue: this.props.inputValue,\n        };\n      }\n\n      render() {\n        return <div>{this.state.inputValue}</div>;\n      }\n    }\n    \n```javascript\n\n Using props inside render method will update the value:\n```jsx harmony\n    class MyComponent extends React.Component {\n      constructor(props) {\n        super(props);\n\n        this.state = {\n          record: [],\n        };\n      }\n\n      render() {\n        return <div>{this.props.inputValue}</div>;\n      }\n    }\n    ```" },
  { q: "৩৪২. React-এ decorators কীভাবে ব্যবহার করবেন?", qEn: "342. How you use decorators in React?", a: "Decorator HOC-এর syntactic sugar (`@setTitle('Profile')`)—class wrap করে `componentDidMount`-এ title ইত্যাদি সেট করে।", aEn: "You can _decorate_ your _class_ components, which is the same as passing the component into a function. Decorators are flexible and readable way of modifying component functionality.\n\n    ```jsx harmony\n    @setTitle(\"Profile\")\n    class Profile extends React.Component {\n      //....\n    }\n\n    /\n      title is a string that will be set as a document title\n      WrappedComponent is what our decorator will receive when\n      put directly above a component class as seen in the example above\n    /\n    const setTitle = (title) => (WrappedComponent) => {\n      return class extends React.Component {\n        componentDidMount() {\n          document.title = title;\n        }\n\n        render() {\n          return <WrappedComponent {...this.props} />;\n        }\n      };\n    };\n    ```\n\n Note: Decorators are a feature that didn't make it into ES7, but are currently a _stage 2 proposal_." },
  { q: "৩৪৩. CRA কী এবং এর সুবিধা কী?", qEn: "343. What is CRA and its benefits?", a: "Create React App: zero-config React, JSX, ES6, test runner, dev server, production build। `npx create-react-app my-app`।", aEn: "The `create-react-app` CLI tool allows you to quickly create & run React applications with no configuration step.\n\n Let's create Todo App using _CRA_:\n\n    \n```console\n    # Installation\n    $ npm install -g create-react-app\n\n    # Create new project\n    $ create-react-app todo-app\n    $ cd todo-app\n\n    # Build, test and run\n    $ npm run build\n    $ npm run test\n    $ npm start\n```\n\n It includes everything we need to build a React app:\n\n 1. React, JSX, ES6, and Flow syntax support.\n 2. Language extras beyond ES6 like the object spread operator.\n 3. Autoprefixed CSS, so you don’t need -webkit- or other prefixes.\n 4. A fast interactive unit test runner with built-in support for coverage reporting.\n 5. A live development server that warns about common mistakes.\n 6. A build script to bundle JS, CSS, and images for production, with hashes and sourcemaps." },
  { q: "৩৪৪. mounting-এ lifecycle methods-এর ক্রম কী?", qEn: "344. What is the lifecycle methods order in mounting?", a: "Mounting ক্রম: constructor() → static getDerivedStateFromProps() → render() → componentDidMount()।", aEn: "The lifecycle methods are called in the following order when an instance of a component is being created and inserted into the DOM.\n\n 1. `constructor()`\n 2. `static getDerivedStateFromProps()`\n 3. `render()`\n 4. `componentDidMount()`" },
  { q: "৩৪৫. React v16-এ কোন lifecycle methods deprecated হবে?", qEn: "345. What are the lifecycle methods going to be deprecated in React v16?", a: "componentWillMount, componentWillReceiveProps, componentWillUpdate unsafe; 16.3+ থেকে `UNSAFE_` prefix, v17-এ সরানোর পরিকল্পনা।", aEn: "The following lifecycle methods going to be unsafe coding practices and will be more problematic with async rendering.\n\n 1. `componentWillMount()`\n 2. `componentWillReceiveProps()`\n 3. `componentWillUpdate()`\n\n Starting with React v16.3 these methods are aliased with `UNSAFE_` prefix, and the unprefixed version will be removed in React v17." },
  { q: "৩৪৬. getDerivedStateFromProps() lifecycle method-এর উদ্দেশ্য কী?", qEn: "346. What is the purpose of `getDerivedStateFromProps()` lifecycle method?", a: "render-এর আগে props থেকে state derive; object return করলে state আপডেট, null মানে আপডেট দরকার নেই। componentWillReceiveProps-এর বিকল্প।", aEn: "The new static `getDerivedStateFromProps()` lifecycle method is invoked after a component is instantiated as well as before it is re-rendered. It can return an object to update state, or `null` to indicate that the new props do not require any state updates.\n\n    \n```javascript\n    class MyComponent extends React.Component {\n      static getDerivedStateFromProps(props, state) {\n        // ...\n      }\n    }\n```\n\n This lifecycle method along with `componentDidUpdate()` covers all the use cases of `componentWillReceiveProps()`." },
  { q: "৩৪৭. getSnapshotBeforeUpdate() lifecycle method-এর উদ্দেশ্য কী?", qEn: "347. What is the purpose of `getSnapshotBeforeUpdate()` lifecycle method?", a: "DOM commit-এর ঠিক আগে snapshot (scroll position); মান componentDidUpdate-এর তৃতীয় আর্গুমেন্ট।", aEn: "The new `getSnapshotBeforeUpdate()` lifecycle method is called right before DOM updates. The return value from this method will be passed as the third parameter to `componentDidUpdate()`.\n\n    \n```javascript\n    class MyComponent extends React.Component {\n      getSnapshotBeforeUpdate(prevProps, prevState) {\n        // ...\n      }\n    }\n```\n\n This lifecycle method along with `componentDidUpdate()` covers all the use cases of `componentWillUpdate()`." },
  { q: "৩৪৮. কম্পোনেন্ট নামকরণের recommended উপায় কী?", qEn: "348. What is the recommended way for naming components?", a: "displayName-এর বদলে class/function reference দিয়ে নাম দিন (`export default class TodoApp`)।", aEn: "It is recommended to name the component by reference instead of using `displayName`.\n\n Using `displayName` for naming component:\n\n    \n```javascript\n    export default React.createClass({\n      displayName: \"TodoApp\",\n      // ...\n    });\n```\n\n The recommended approach:\n\n    \n```javascript\n    export default class TodoApp extends React.Component {\n      // ...\n    }\n```\n\n also\n\n    \n```javascript\n    const TodoApp = () => {\n      //...\n    };\n    export default TodoApp;\n```" },
  { q: "৩৪৯. class component-এ methods-এর recommended order কী?", qEn: "349. What is the recommended ordering of methods in component class?", a: "ক্রম: static → constructor → lifecycle (mount/update/unmount) → handlers → getters → optional render helpers → render()।", aEn: "_Recommended_ ordering of methods from _mounting_ to _render stage_:\n\n 1. `static` methods\n 2. `constructor()`\n 3. `getChildContext()`\n 4. `componentWillMount()`\n 5. `componentDidMount()`\n 6. `componentWillReceiveProps()`\n 7. `shouldComponentUpdate()`\n 8. `componentWillUpdate()`\n 9. `componentDidUpdate()`\n 10. `componentWillUnmount()`\n 11. click handlers or event handlers like `onClickSubmit()` or `onChangeDescription()`\n 12. getter methods for render like `getSelectReason()` or `getFooterContent()`\n 13. optional render methods like `renderNavigation()` or `renderProfilePicture()`\n 14. `render()`" },
  { q: "৩৫০. কেন setState()-এ ফাংশন পাস করতে হয়?", qEn: "350. Why we need to pass a function to setState()?", a: "setState batch করে; একাধিক `setState({ count: this.state.count+1 })` একবারই যোগ হতে পারে। ফাংশন ফর্ম: `setState((prev, props) => ({ count: prev.count + 1 }))`।", aEn: "The reason behind for this is that `setState()` is an asynchronous operation. React batches state changes for performance reasons, so the state may not change immediately after `setState()` is called. That means you should not rely on the current state when calling `setState()` since you can't be sure what that state will be. The solution is to pass a function to `setState()`, with the previous state as an argument. By doing this you can avoid issues with the user getting the old state value on access due to the asynchronous nature of `setState()`.\n\n Let's say the initial count value is zero. After three consecutive increment operations, the value is going to be incremented only by one.\n\n    \n```javascript\n    // assuming this.state.count === 0\n    this.setState({ count: this.state.count + 1 });\n    this.setState({ count: this.state.count + 1 });\n    this.setState({ count: this.state.count + 1 });\n    // this.state.count === 1, not 3\n```\n\n If we pass a function to `setState()`, the count gets incremented correctly.\n\n    \n```javascript\n    this.setState((prevState, props) => ({\n      count: prevState.count + props.increment,\n    }));\n    // this.state.count === 3 as expected\n```\n\n (OR)\n\n ### Why function is preferred over object for `setState()`?\n\n React may batch multiple `setState()` calls into a single update for performance. Because `this.props` and `this.state` may be updated asynchronously, you should not rely on their values for calculating the next state.\n\n This counter example will fail to update as expected:\n\n    \n```javascript\n    // Wrong\n    this.setState({\n      counter: this.state.counter + this.props.increment,\n    });\n```\n\n The preferred approach is to call `setState()` with function rather than object. That function will receive the previous state as the first argument, and the props at the time the update is applied as the second argument.\n\n    \n```javascript\n    // Correct\n    this.setState((prevState, props) => ({\n      counter: prevState.counter + props.increment,\n    }));\n```" },
  { q: "৩৫১. isMounted() কেন anti-pattern এবং সমাধান কী?", qEn: "351. Why is `isMounted()` an anti-pattern and what is the proper solution?", a: "isMounted() warning লুকায় কিন্তু unmount-পর setState ঠিক করে না। callback cancel করুন `componentWillUnmount`-এ।", aEn: "The primary use case for `isMounted()` is to avoid calling `setState()` after a component has been unmounted, because it will emit a warning.\n\n    \n```javascript\n    if (this.isMounted()) {\n      this.setState({...})\n    }\n```\n\n Checking `isMounted()` before calling `setState()` does eliminate the warning, but it also defeats the purpose of the warning. Using `isMounted()` is a code smell because the only reason you would check is because you think you might be holding a reference after the component has unmounted.\n\n An optimal solution would be to find places where `setState()` might be called after a component has unmounted, and fix them. Such situations most commonly occur due to callbacks, when a component is waiting for some data and gets unmounted before the data arrives. Ideally, any callbacks should be canceled in `componentWillUnmount()`, prior to unmounting." },
  { q: "৩৫২. constructor ও getInitialState()-এর পার্থক্য কী?", qEn: "352. What is the difference between constructor and getInitialState?", a: "ES6 class: constructor-এ `this.state`। `React.createClass`: `getInitialState()` (deprecated v16+)।", aEn: "You should initialize state in the constructor when using ES6 classes, and `getInitialState()` method when using `React.createClass()`.\n\n Using ES6 classes:\n\n    \n```javascript\n    class MyComponent extends React.Component {\n      constructor(props) {\n        super(props);\n        this.state = {\n          / initial state /\n        };\n      }\n    }\n```\n\n Using `React.createClass()`:\n\n    \n```javascript\n    const MyComponent = React.createClass({\n      getInitialState() {\n        return {\n          / initial state /\n        };\n      },\n    });\n```\n\n Note: `React.createClass()` is deprecated and removed in React v16. Use plain JavaScript classes instead." },
  { q: "৩৫৩. setState ছাড়া re-render চাপানো যায়?", qEn: "353. Can you force a component to re-render without calling setState?", a: "`forceUpdate(callback)` re-render চাপায়; props/state ছাড়া ডেটা থাকলে—তবু এড়িয়ে চলুন।", aEn: "By default, when your component's state or props change, your component will re-render. If your `render()` method depends on some other data, you can tell React that the component needs re-rendering by calling `forceUpdate()`.\n\n    \n```javascript\n    component.forceUpdate(callback);\n```\n\n It is recommended to avoid all uses of `forceUpdate()` and only read from `this.props` and `this.state` in `render()`." },
  { q: "৩৫৪. ES6 class-এ super() ও super(props)-এর পার্থক্য কী?", qEn: "354. What is the difference between `super()` and `super(props)` in React using ES6 classes?", a: "constructor-এ `this.props` চাইলে `super(props)`; শুধু `super()` হলে constructor-এ `this.props` undefined।", aEn: "When you want to access `this.props` in `constructor()` then you should pass props to `super()` method.\n\n Using `super(props)`:\n\n    \n```javascript\n    class MyComponent extends React.Component {\n      constructor(props) {\n        super(props);\n        console.log(this.props); // { name: 'John', ... }\n      }\n    }\n```\n\n Using `super()`:\n\n    \n```javascript\n    class MyComponent extends React.Component {\n      constructor(props) {\n        super();\n        console.log(this.props); // undefined\n      }\n    }\n```\n\n Outside `constructor()` both will display same value for `this.props`." },
  { q: "৩৫৫. setState() ও replaceState()-এর পার্থক্য কী?", qEn: "355. What is the difference between `setState()` and `replaceState()` methods?", a: "setState merge করে; replaceState পুরো state প্রতিস্থাপন করে (বিরল)।", aEn: "When you use `setState()` the current and previous states are merged. `replaceState()` throws out the current state, and replaces it with only what you provide. Usually `setState()` is used unless you really need to remove all previous keys for some reason. You can also set state to `false`/`null` in `setState()` instead of using `replaceState()`." },
  { q: "৩৫৬. state পরিবর্তন কীভাবে শুনবেন?", qEn: "356. How to listen to state changes?", a: "`componentDidUpdate(prevProps, prevState)`-এ তুলনা করে side-effect চালান।", aEn: "The `componentDidUpdate` lifecycle method will be called when state changes. You can compare provided state and props values with current state and props to determine if something meaningful changed.\n\n    \n```javascript\n    componentDidUpdate(object prevProps, object prevState)\n```\n\n Note: The previous releases of ReactJS also uses `componentWillUpdate(object nextProps, object nextState)` for state changes. It has been deprecated in latest releases." },
  { q: "৩৫৭. React state থেকে array element সরানোর recommended উপায় কী?", qEn: "357. What is the recommended approach of removing an array element in React state?", a: "`filter` দিয়ে নতুন array: `this.setState({ data: this.state.data.filter((_, i) => i !== index) })`—মিউটেট করবেন না।", aEn: "The better approach is to use `Array.prototype.filter()` method.\n\n For example, let's create a `removeItem()` method for updating the state.\n\n    \n```javascript\n    removeItem(index) {\n      this.setState({\n        data: this.state.data.filter((item, i) => i !== index)\n      })\n    }\n```" },
  { q: "৩৫৮. HTML রেন্ডার ছাড়া React ব্যবহার করা যায়?", qEn: "358. Is it possible to use React without rendering HTML?", a: "হ্যাঁ: `return null`, `false`, `[]` (16+), `Fragment` (16.2+), `undefined` (18+)।", aEn: "It is possible. Below are the possible options:\n\n    ```jsx harmony\n    render() {\n      return false\n    }\n    \n```javascript\n\n```jsx harmony\n    render() {\n      return true\n    }\n    \n```javascript\n\n```jsx harmony\n    render() {\n      return null\n    }\n    \n```javascript\n\n React version >=16.0.0:\n```jsx harmony\n    render() {\n      return []\n    }\n    \n```javascript\n\n```jsx harmony\n    render() {\n      return \"\"\n    }\n    \n```javascript\n\n React version >=16.2.0:\n```jsx harmony\n    render() {\n      return <React.Fragment></React.Fragment>\n    }\n    \n```javascript\n\n```jsx harmony\n    render() {\n      return <></>\n    }\n    \n```javascript\n\n React version >=18.0.0:\n```jsx harmony\n    render() {\n      return undefined\n    }\n    ```" },
  { q: "৩৫৯. state-এ object আপডেটের উপায় কী কী?", qEn: "359. What are the possible ways of updating objects in state?", a: "Object.assign বা spread দিয়ে copy, তারপর setState; বা functional setState: `setState(prev => ({ user: { ...prev.user, age: 42 } }))`।", aEn: "1. Calling `setState()` with an object to merge with state:\n\n - Using `Object.assign()` to create a copy of the object:\n\n          \n```javascript\n          const user = Object.assign({}, this.state.user, { age: 42 });\n          this.setState({ user });\n```\n\n - Using _spread operator_:\n\n          \n```javascript\n          const user = { ...this.state.user, age: 42 };\n          this.setState({ user });\n```\n\n 2. Calling `setState()` with a function:\n\n        \n```javascript\n        this.setState((prevState) => ({\n          user: {\n            ...prevState.user,\n            age: 42,\n          },\n        }));\n```" },
  { q: "৩৬০. create-react-app-এ polyfills যোগ করার উপায় কী?", qEn: "360. What are the approaches to include polyfills in your `create-react-app`?", a: "core-js manual import অথবা polyfill.io CDN `index.html`-এ।", aEn: "There are approaches to include polyfills in create-react-app,\n\n 1. Manual import from `core-js`:\n\n Create a file called (something like) `polyfills.js` and import it into root `index.js` file. Run `npm install core-js` or `yarn add core-js` and import your specific required features.\n\n        \n```javascript\n        import \"core-js/fn/array/find\";\n        import \"core-js/fn/array/includes\";\n        import \"core-js/fn/number/is-nan\";\n```\n\n 2. Using Polyfill service:\n\n Use the polyfill.io CDN to retrieve custom, browser-specific polyfills by adding this line to `index.html`:\n\n        \n```html\n        <script src=\"https://cdn.polyfill.io/v2/polyfill.min.js?features=default,Array.prototype.includes\"></script>\n```\n\n In the above script we had to explicitly request the `Array.prototype.includes` feature as it is not included in the default feature set." },
  { q: "৩৬১. create-react-app-এ https কীভাবে ব্যবহার করবেন?", qEn: "361. How to use https instead of http in create-react-app?", a: "HTTPS=true env: package.json start script-এ set HTTPS=true (Windows) বা HTTPS=true npm start।", aEn: "You just need to use `HTTPS=true` configuration. You can edit your `package.json` scripts section:\n\n    \n```json\n    \"scripts\": {\n      \"start\": \"set HTTPS=true && react-scripts start\"\n    }\n```\n\n or just run `set HTTPS=true && npm start`" },
  { q: "৩৬২. create-react-app-এ relative import এড়ানোর উপায় কী?", qEn: "362. How to avoid using relative path imports in create-react-app?", a: "root `.env`-এ `NODE_PATH=src/app`—dev server restart।", aEn: "Create a file called `.env` in the project root and write the import path:\n\n    \n```javascript\n    NODE_PATH=src/app\n```\n\n After that restart the development server. Now you should be able to import anything inside `src/app` without relative paths." },
  { q: "৩৬৩. প্রতি সেকেন্ডে কম্পোনেন্ট আপডেট কীভাবে করবেন?", qEn: "363. How to update a component every second?", a: "`componentDidMount`-এ `setInterval`, `componentWillUnmount`-এ `clearInterval`।", aEn: "You need to use `setInterval()` to trigger the change, but you also need to clear the timer when the component unmounts to prevent errors and memory leaks.\n\n    \n```javascript\n    componentDidMount() {\n      this.interval = setInterval(() => this.setState({ time: Date.now() }), 1000)\n    }\n\n    componentWillUnmount() {\n      clearInterval(this.interval)\n    }\n```" },
  { q: "৩৬৪. constructor কেন শুধু একবার কল হয়?", qEn: "364. Why is a component constructor called only once?", a: "reconciliation একই জায়গায় একই টাইপের কম্পোনেন্টকে একই instance ধরে—constructor আবার চলে না।", aEn: "React's _reconciliation_ algorithm assumes that without any information to the contrary, if a custom component appears in the same place on subsequent renders, it's the same component as before, so reuses the previous instance rather than creating a new one." },
  { q: "৩৬৫. React-এ constants কীভাবে define করবেন?", qEn: "365. How to define constants in React?", a: "static class field: `static DEFAULT_PAGINATION = 10;`।", aEn: "You can use ES7 `static` field to define constant.\n\n    \n```javascript\n    class MyComponent extends React.Component {\n      static DEFAULT_PAGINATION = 10;\n    }\n```" },
  { q: "৩৬৬. React-এ programmatically click event কীভাবে trigger করবেন?", qEn: "366. How to programmatically trigger click event in React?", a: "ref সংরক্ষণ করে `this.inputElement.click()`।", aEn: "You could use the ref prop to acquire a reference to the underlying `HTMLInputElement` object through a callback, store the reference as a class property, then use that reference to later trigger a click from your event handlers using the `HTMLElement.click` method.\n\n This can be done in two steps:\n\n 1. Create ref in render method:\n\n        ```jsx harmony\n        <input ref={(input) => (this.inputElement = input)} />\n        \n```javascript\n\n 2. Apply click event in your event handler:\n```javascript\n        this.inputElement.click();\n        ```" },
  { q: "৩৬৭. কোন lifecycle-এ AJAX call করবেন?", qEn: "367. How to make AJAX call and in which component lifecycle methods should I make an AJAX call?", a: "Axios/fetch `componentDidMount`-এ; ডেটা এলে setState।", aEn: "You can use AJAX libraries such as Axios, jQuery AJAX, and the browser built-in `fetch`. You should fetch data in the `componentDidMount()` lifecycle method. This is so you can use `setState()` to update your component when the data is retrieved.\n\n For example, the employees list fetched from API and set local state:\n\n    ```jsx harmony\n    class MyComponent extends React.Component {\n      constructor(props) {\n        super(props);\n        this.state = {\n          employees: [],\n          error: null,\n        };\n      }\n\n      componentDidMount() {\n        fetch(\"https://api.example.com/items\")\n          .then((res) => res.json())\n          .then(\n            (result) => {\n              this.setState({\n                employees: result.employees,\n              });\n            },\n            (error) => {\n              this.setState({ error });\n            }\n          );\n      }\n\n      render() {\n        const { error, employees } = this.state;\n        if (error) {\n          return <div>Error: {error.message}</div>;\n        } else {\n          return (\n            <ul>\n              {employees.map((employee) => (\n                <li key={employee.name}>\n                  {employee.name}-{employee.experience}\n                </li>\n              ))}\n            </ul>\n          );\n        }\n      }\n    }\n    ```" },
  { q: "৩৬৮. render props কী?", qEn: "368. What are render props?", a: "render prop: `value` হিসেবে ফাংশন prop যা React element return করে—কোড শেয়ারিং।", aEn: "Render Props is a simple technique for sharing code between components using a prop whose value is a function. The below component uses render prop which returns a React element.\n\n    ```jsx harmony\n    <DataProvider render={(data) => <h1>{`Hello ${data.target}`}</h1>} />\n    ```\n\n Libraries such as React Router and DownShift are using this pattern." },
  { q: "৩৬৯. load-এ action কীভাবে dispatch করবেন?", qEn: "369. How to dispatch an action on load?", a: "`componentDidMount`-এ `dispatch(fetchData())`; render-এ loading state দেখান।", aEn: "You can dispatch an action in `componentDidMount()` method and in `render()` method you can verify the data.\n\n    \n```javascript\n    class App extends Component {\n      componentDidMount() {\n        this.props.fetchData();\n      }\n\n      render() {\n        return this.props.isLoaded ? (\n          <div>{\"Loaded\"}</div>\n        ) : (\n          <div>{\"Not Loaded\"}</div>\n        );\n      }\n    }\n\n    const mapStateToProps = (state) => ({\n      isLoaded: state.isLoaded,\n    });\n\n    const mapDispatchToProps = { fetchData };\n\n    export default connect(mapStateToProps, mapDispatchToProps)(App);\n```" },
  { q: "৩৭০. React Redux-এ connect() কীভাবে ব্যবহার করবেন?", qEn: "370. How to use `connect()` from React Redux?", a: "`connect(mapStateToProps, mapDispatchToProps)(App)`—state props-এ, actions bind।", aEn: "You need to follow two steps to use your store in your container:\n\n 1. Use `mapStateToProps()`: It maps the state variables from your store to the props that you specify.\n 2. Connect the above props to your container: The object returned by the `mapStateToProps` function is connected to the container. You can import `connect()` from `react-redux`.\n\n        ```jsx harmony\n        import React from \"react\";\n        import { connect } from \"react-redux\";\n\n        class App extends React.Component {\n          render() {\n            return <div>{this.props.containerData}</div>;\n          }\n        }\n\n        function mapStateToProps(state) {\n          return { containerData: state.data };\n        }\n\n        export default connect(mapStateToProps)(App);\n        ```" },
  { q: "৩৭১. Redux connect decorator-এ @ symbol-এর উদ্দেশ্য কী?", qEn: "371. Whats the purpose of `at` symbol in the Redux connect decorator?", a: "`@connect(...)` decorator syntax—experimental; babel plugin লাগে।", aEn: "The @ symbol is in fact a JavaScript expression used to signify decorators. _Decorators_ make it possible to annotate and modify classes and properties at design time.\n\n Let's take an example setting up Redux without and with a decorator.\n\n - Without decorator:\n\n      \n```javascript\n      import React from \"react\";\n      import  as actionCreators from \"./actionCreators\";\n      import { bindActionCreators } from \"redux\";\n      import { connect } from \"react-redux\";\n\n      function mapStateToProps(state) {\n        return { todos: state.todos };\n      }\n\n      function mapDispatchToProps(dispatch) {\n        return { actions: bindActionCreators(actionCreators, dispatch) };\n      }\n\n      class MyApp extends React.Component {\n        // ...define your main app here\n      }\n\n      export default connect(mapStateToProps, mapDispatchToProps)(MyApp);\n```\n\n - With decorator:\n\n      \n```javascript\n      import React from \"react\";\n      import  as actionCreators from \"./actionCreators\";\n      import { bindActionCreators } from \"redux\";\n      import { connect } from \"react-redux\";\n\n      function mapStateToProps(state) {\n        return { todos: state.todos };\n      }\n\n      function mapDispatchToProps(dispatch) {\n        return { actions: bindActionCreators(actionCreators, dispatch) };\n      }\n\n      @connect(mapStateToProps, mapDispatchToProps)\n      export default class MyApp extends React.Component {\n        // ...define your main app here\n      }\n```\n\n The above examples are almost similar except the usage of decorator. The decorator syntax isn't built into any JavaScript runtimes yet, and is still experimental and subject to change. You can use babel for the decorators support." },
  { q: "৩৭২. create-react-app-এ TypeScript কীভাবে ব্যবহার করবেন?", qEn: "372. How to use TypeScript in `create-react-app` application?", a: "`npx create-react-app my-app --template typescript` (react-scripts 3.3+); পুরনোতে `--typescript` বা `react-scripts-ts`।", aEn: "Starting from react-scripts@3.3.0+ releases onwards, you can now optionally start a new app from a template by appending `--template [template-name]` to the creation command. If you don't select a template, it will create your project with base template. Remember that templates are always named in the format `cra-template-[template-name]`, here you only need to fill the `[template-name]` section.\n\n The typeScript can be used in your project by appending `--template typescript` to the creation command.\n\n         \n```bash\n         npx create-react-app my-app --template typescript\n```\n\n But if you are using React Scripting between react-scripts@2.1.0 and react-scripts@3.2.x , there is a built-in support for TypeScript. i.e, `create-react-app` now supports TypeScript natively. You can just pass `--typescript` option as below\n\n         \n```bash\n         npx create-react-app my-app --typescript\n\n         # or\n\n         yarn create react-app my-app --typescript\n```\n\n Whereas for lower versions of react scripts, just supply `--scripts-version` option as `react-scripts-ts` while you create a new project. `react-scripts-ts` is a set of adjustments to take the standard `create-react-app` project pipeline and bring TypeScript into the mix.\n\n Now the project layout should look like the following:\n\n         \n```javascript\n         my-app/\n         ├─ .gitignore\n         ├─ images.d.ts\n         ├─ node_modules/\n         ├─ public/\n         ├─ src/\n         │  └─ ...\n         ├─ package.json\n         ├─ tsconfig.json\n         ├─ tsconfig.prod.json\n         ├─ tsconfig.test.json\n         └─ tslint.json\n```" },
  { q: "৩৭৩. ES6 class-এ statics object কাজ করে?", qEn: "373. Does the statics object work with ES6 classes in React?", a: "না—`statics` শুধু createClass-এ; ES6-এ `static propTypes`, class বাইরে `Component.x = ...`।", aEn: "No, `statics` only works with `React.createClass()`:\n\n    \n```javascript\n    someComponent = React.createClass({\n      statics: {\n        someMethod: function () {\n          // ..\n        },\n      },\n    });\n```\n\n But you can write statics inside ES6+ classes as below,\n\n    \n```javascript\n    class Component extends React.Component {\n      static propTypes = {\n        // ...\n      };\n\n      static someMethod() {\n        // ...\n      }\n    }\n```\n\n or writing them outside class as below,\n\n    \n```javascript\n    class Component extends React.Component {\n       ....\n    }\n\n    Component.propTypes = {...}\n    Component.someMethod = function(){....}\n```" },
  { q: "৩৭৪. inline ref callbacks কেন recommended নয়?", qEn: "374. Why are inline ref callbacks or functions not recommended?", a: "inline callback ref প্রতি render-এ নতুন ফাংশন—null তারপর element দুবার কল। class field method stable রাখুন।", aEn: "If the ref callback is defined as an inline function, it will get called twice during updates, first with null and then again with the DOM element. This is because a new instance of the function is created with each render, so React needs to clear the old ref and set up the new one.\n\n    \n```javascript\n    class UserForm extends Component {\n      handleSubmit = () => {\n        console.log(\"Input Value is: \", this.input.value);\n      };\n\n      render() {\n        return (\n          <form onSubmit={this.handleSubmit}>\n            <input type=\"text\" ref={(input) => (this.input = input)} /> //\n            Access DOM input in handle submit\n            <button type=\"submit\">Submit</button>\n          </form>\n        );\n      }\n    }\n```\n\n But our expectation is for the ref callback to get called once, when the component mounts. One quick fix is to use the ES7 class property syntax to define the function\n\n    \n```javascript\n    class UserForm extends Component {\n      handleSubmit = () => {\n        console.log(\"Input Value is: \", this.input.value);\n      };\n\n      setSearchInput = (input) => {\n        this.input = input;\n      };\n\n      render() {\n        return (\n          <form onSubmit={this.handleSubmit}>\n            <input type=\"text\" ref={this.setSearchInput} /> // Access DOM input\n            in handle submit\n            <button type=\"submit\">Submit</button>\n          </form>\n        );\n      }\n    }\n```" },
  { q: "৩৭৫. HOC factory implementations কী?", qEn: "375. What are HOC factory implementations?", a: "Props Proxy (wrapped-এ props pass) ও Inheritance Inversion (Enhancer extends Wrapped)।", aEn: "There are two main ways of implementing HOCs in React.\n\n 1. Props Proxy (PP) and\n 2. Inheritance Inversion (II).\n\n But they follow different approaches for manipulating the _WrappedComponent_.\n\n Props Proxy\n\n In this approach, the render method of the HOC returns a React Element of the type of the WrappedComponent. We also pass through the props that the HOC receives, hence the name Props Proxy.\n\n    \n```javascript\n    function ppHOC(WrappedComponent) {\n      return class PP extends React.Component {\n        render() {\n          return <WrappedComponent {...this.props} />;\n        }\n      };\n    }\n```\n\n Inheritance Inversion\n\n In this approach, the returned HOC class (Enhancer) extends the WrappedComponent. It is called Inheritance Inversion because instead of the WrappedComponent extending some Enhancer class, it is passively extended by the Enhancer. In this way the relationship between them seems inverse.\n\n    \n```javascript\n    function iiHOC(WrappedComponent) {\n      return class Enhancer extends WrappedComponent {\n        render() {\n          return super.render();\n        }\n      };\n    }\n```" },
  { q: "৩৭৬. class field declarations syntax কীভাবে ব্যবহার করবেন?", qEn: "376. How to use class field declarations syntax in React classes?", a: "state = {}, arrow handlers—constructor/bind ছাড়াই concise class components।", aEn: "React Class Components can be made much more concise using the class field declarations. You can initialize the local state without using the constructor and declare class methods by using arrow functions without the extra need to bind them.\n\n Let's take a counter example to demonstrate class field declarations for state without using constructor and methods without binding,\n\n    \n```javascript\n    class Counter extends Component {\n      state = { value: 0 };\n\n      handleIncrement = () => {\n        this.setState((prevState) => ({\n          value: prevState.value + 1,\n        }));\n      };\n\n      handleDecrement = () => {\n        this.setState((prevState) => ({\n          value: prevState.value - 1,\n        }));\n      };\n\n      render() {\n        return (\n          <div>\n            {this.state.value}\n\n            <button onClick={this.handleIncrement}>+</button>\n            <button onClick={this.handleDecrement}>-</button>\n          </div>\n        );\n      }\n    }\n```" },
  { q: "৩৭৭. event handlers-এ error boundaries দরকার নেই কেন?", qEn: "377. Why do you not need error boundaries for event handlers?", a: "event handler render phase-এর বাইরে; error boundary লাগে না—try/catch ব্যবহার করুন।", aEn: "Error boundaries do not catch errors inside event handlers.\n\n React doesn’t need error boundaries to recover from errors in event handlers. Unlike the render method and lifecycle methods, the event handlers don’t happen during rendering. So if they throw, React still knows what to display on the screen.\n\n If you need to catch an error inside an event handler, use the regular JavaScript try / catch statement:\n\n    \n```javascript\n    class MyComponent extends React.Component {\n      constructor(props) {\n        super(props);\n        this.state = { error: null };\n        this.handleClick = this.handleClick.bind(this);\n      }\n\n      handleClick() {\n        try {\n          // Do something that could throw\n        } catch (error) {\n          this.setState({ error });\n        }\n      }\n\n      render() {\n        if (this.state.error) {\n          return <h1>Caught an error.</h1>;\n        }\n        return <button onClick={this.handleClick}>Click Me</button>;\n      }\n    }\n```\n\n Note that the above example is demonstrating regular JavaScript behavior and doesn’t use error boundaries." },
  { q: "৩৭৮. try/catch ও error boundaries-এর পার্থক্য কী?", qEn: "378. What is the difference between try catch block and error boundaries?", a: "try/catch imperative কোডে; error boundary declarative render/lifecycle error-এর জন্য।", aEn: "Try catch block works with imperative code whereas error boundaries are meant for declarative code to render on the screen.\n\n For example, the try catch block used for below imperative code\n\n    \n```javascript\n    try {\n      showButton();\n    } catch (error) {\n      // ...\n    }\n```\n\n Whereas error boundaries wrap declarative code as below,\n\n    \n```javascript\n    <ErrorBoundary>\n      <MyComponent />\n    </ErrorBoundary>\n```\n\n So if an error occurs in a componentDidUpdate method caused by a setState somewhere deep in the tree, it will still correctly propagate to the closest error boundary." },
  { q: "৩৭৯. class component-এ required method কোনটি?", qEn: "379. What is the required method to be defined for a class component?", a: "শুধু `render()` বাধ্যতামূলক।", aEn: "The `render()` method is the only required method in a class component. i.e, All methods other than render method are optional for a class component." },
  { q: "৩৮০. render method-এর সম্ভাব্য return types কী?", qEn: "380. What are the possible return types of render method?", a: "elements, array/fragment, portal, string/number, boolean/null (কিছু render নয়)।", aEn: "Below are the list of following types used and return from render method,\n\n 1. React elements: Elements that instruct React to render a DOM node. It includes html elements such as ` ` and user defined elements.\n 2. Arrays and fragments: Return multiple elements to render as Arrays and Fragments to wrap multiple elements\n 3. Portals: Render children into a different DOM subtree.\n 4. String and numbers: Render both Strings and Numbers as text nodes in the DOM\n 5. Booleans or null: Doesn't render anything but these types are used to conditionally render content." },
  { q: "৩৮১. constructor-এর মূল উদ্দেশ্য কী?", qEn: "381. What is the main purpose of constructor?", a: "state initialize ও event handler bind (constructor-এ setState নয়)।", aEn: "The constructor is mainly used for two purposes,\n\n 1. To initialize local state by assigning object to this.state\n 2. For binding event handler methods to the instance\n For example, the below code covers both the above cases,\n\n    \n```javascript\n    constructor(props) {\n      super(props);\n      // Don't call this.setState() here!\n      this.state = { counter: 0 };\n      this.handleClick = this.handleClick.bind(this);\n    }\n```" },
  { q: "৩৮২. React component-এ constructor বাধ্যতামূলক?", qEn: "382. Is it mandatory to define constructor for React component?", a: "না—state/handlers না থাকলে constructor লাগবে না।", aEn: "No, it is not mandatory. i.e, If you don’t initialize state and you don’t bind methods, you don’t need to implement a constructor for your React component." },
  { q: "৩৮৩. componentWillUnmount-এ setState কেন ডাকবেন না?", qEn: "383. Why should not call setState in componentWillUnmount?", a: "unmount-পর আর mount হবে না—setState অর্থহীন।", aEn: "You should not call `setState()` in `componentWillUnmount()` because once a component instance is unmounted, it will never be mounted again." },
  { q: "৩৮৪. getDerivedStateFromError-এর উদ্দেশ্য কী?", qEn: "384. What is the purpose of getDerivedStateFromError?", a: "error থেকে state আপডেট করে fallback UI (`return { hasError: true }`)।", aEn: "This lifecycle method is invoked after an error has been thrown by a descendant component. It receives the error that was thrown as a parameter and should return a value to update state.\n\n The signature of the lifecycle method is as follows,\n\n    \n```javascript\n    static getDerivedStateFromError(error)\n```\n\n Let us take error boundary use case with the above lifecycle method for demonstration purpose,\n\n    \n```javascript\n    class ErrorBoundary extends React.Component {\n      constructor(props) {\n        super(props);\n        this.state = { hasError: false };\n      }\n\n      static getDerivedStateFromError(error) {\n        // Update state so the next render will show the fallback UI.\n        return { hasError: true };\n      }\n\n      render() {\n        if (this.state.hasError) {\n          // You can render any custom fallback UI\n          return <h1>Something went wrong.</h1>;\n        }\n\n        return this.props.children;\n      }\n    }\n```" },
  { q: "৩৮৫. re-render-এ methods-এর order কী?", qEn: "385. What is the methods order when component re-rendered?", a: "getDerivedStateFromProps → shouldComponentUpdate → render → getSnapshotBeforeUpdate → componentDidUpdate।", aEn: "An update can be caused by changes to props or state. The below methods are called in the following order when a component is being re-rendered.\n\n 1. static getDerivedStateFromProps()\n 2. shouldComponentUpdate()\n 3. render()\n 4. getSnapshotBeforeUpdate()\n 5. componentDidUpdate()" },
  { q: "৩৮৬. error handling-এ কোন methods invoke হয়?", qEn: "386. What are the methods invoked during error handling?", a: "getDerivedStateFromError, componentDidCatch।", aEn: "Below methods are called when there is an error during rendering, in a lifecycle method, or in the constructor of any child component.\n\n 1. static getDerivedStateFromError()\n 2. componentDidCatch()" },
  { q: "৩৮৭. unmountComponentAtNode method-এর উদ্দেশ্য কী?", qEn: "387. What is the purpose of unmountComponentAtNode method?", a: "`ReactDOM.unmountComponentAtNode(container)`—DOM থেকে সরায়, listeners/state cleanup।", aEn: "This method is available from react-dom package and it removes a mounted React component from the DOM and clean up its event handlers and state. If no component was mounted in the container, calling this function does nothing. Returns true if a component was unmounted and false if there was no component to unmount.\n\n The method signature would be as follows,\n\n    \n```javascript\n    ReactDOM.unmountComponentAtNode(container);\n```" },
  { q: "৩৮৮. HOCs-এর সীমাবদ্ধতা কী?", qEn: "388. What are the limitations with HOCs?", a: "render-এ HOC তৈরি করবেন না; static methods copy; refs `forwardRef` দরকার।", aEn: "Higher-order components come with a few caveats apart from its benefits. Below are the few listed in an order,\n\n 1. Don’t use HOCs inside the render method:\n It is not recommended to apply a HOC to a component within the render method of a component.\n\n        \n```javascript\n        render() {\n          // A new version of EnhancedComponent is created on every render\n          // EnhancedComponent1 !== EnhancedComponent2\n          const EnhancedComponent = enhance(MyComponent);\n          // That causes the entire subtree to unmount/remount each time!\n          return <EnhancedComponent />;\n        }\n```\n\n The above code impacts on performance by remounting a component that causes the state of that component and all of its children to be lost. Instead, apply HOCs outside the component definition so that the resulting component is created only once.\n\n 2. Static methods must be copied over:\n When you apply a HOC to a component the new component does not have any of the static methods of the original component\n\n        \n```javascript\n        // Define a static method\n        WrappedComponent.staticMethod = function () {\n          /.../\n        };\n        // Now apply a HOC\n        const EnhancedComponent = enhance(WrappedComponent);\n\n        // The enhanced component has no static method\n        typeof EnhancedComponent.staticMethod === \"undefined\"; // true\n```\n\n You can overcome this by copying the methods onto the container before returning it,\n\n        \n```javascript\n        function enhance(WrappedComponent) {\n          class Enhance extends React.Component {\n            /.../\n          }\n          // Must know exactly which method(s) to copy :(\n          Enhance.staticMethod = WrappedComponent.staticMethod;\n          return Enhance;\n        }\n```\n\n 3. Refs aren’t passed through:\n For HOCs you need to pass through all props to the wrapped component but this does not work for refs. This is because ref is not really a prop similar to key. In this case you need to use the React.forwardRef API" },
  { q: "৩৮৯. DevTools-এ forwardRefs কীভাবে debug করবেন?", qEn: "389. How to debug forwardRefs in DevTools?", a: "forwardRef render function-এ নাম/displayName দিন DevTools-এ স্পষ্টতার জন্য।", aEn: "React.forwardRef accepts a render function as parameter and DevTools uses this function to determine what to display for the ref forwarding component.\n\n For example, If you don't name the render function or not using displayName property then it will appear as ”ForwardRef” in the DevTools,\n\n    \n```javascript\n    const WrappedComponent = React.forwardRef((props, ref) => {\n      return <LogProps {...props} forwardedRef={ref} />;\n    });\n```\n\n But If you name the render function then it will appear as ”ForwardRef(myFunction)”\n\n    \n```javascript\n    const WrappedComponent = React.forwardRef(function myFunction(props, ref) {\n      return <LogProps {...props} forwardedRef={ref} />;\n    });\n```\n\n As an alternative, You can also set displayName property for forwardRef function,\n\n    \n```javascript\n    function logProps(Component) {\n      class LogProps extends React.Component {\n        // ...\n      }\n\n      function forwardRef(props, ref) {\n        return <LogProps {...props} forwardedRef={ref} />;\n      }\n\n      // Give this component a more helpful display name in DevTools.\n      // e.g. \"ForwardRef(logProps(MyComponent))\"\n      const name = Component.displayName || Component.name;\n      forwardRef.displayName = `logProps(${name})`;\n\n      return React.forwardRef(forwardRef);\n    }\n```" },
  { q: "৩৯০. render methods-এ arrow functions ব্যবহার করা ভালো?", qEn: "390. Is it good to use arrow functions in render methods?", a: "হ্যাঁ, প্যারামিটার পাসে সহজ; প্রতি render নতুন ফাংশন—পারফরম্যান্স খেয়াল।", aEn: "Yes, You can use. It is often the easiest way to pass parameters to callback functions. But you need to optimize the performance while using it.\n\n    \n```javascript\n    class Foo extends Component {\n      handleClick() {\n        console.log(\"Click happened\");\n      }\n      render() {\n        return <button onClick={() => this.handleClick()}>Click Me</button>;\n      }\n    }\n```\n\n Note: Using an arrow function in render method creates a new function each time the component renders, which may have performance implications" },
  { q: "৩৯১. state updates merged হয় বলতে কী বোঝায়?", qEn: "391. How do you say that state updates are merged?", a: "setState shallow merge—`setState({ comments })` posts অপরিবর্তিত থাকতে পারে।", aEn: "When you call setState() in the component, React merges the object you provide into the current state.\n\n For example, let us take a facebook user with posts and comments details as state variables,\n\n    \n```javascript\n      constructor(props) {\n        super(props);\n        this.state = {\n          posts: [],\n          comments: []\n        };\n      }\n```\n\n Now you can update them independently with separate `setState()` calls as below,\n\n    \n```javascript\n     componentDidMount() {\n        fetchPosts().then(response => {\n          this.setState({\n            posts: response.posts\n          });\n        });\n\n        fetchComments().then(response => {\n          this.setState({\n            comments: response.comments\n          });\n        });\n      }\n```\n\n As mentioned in the above code snippets, `this.setState({comments})` updates only comments variable without modifying or replacing `posts` variable." },
  { q: "৩৯২. event handler-এ arguments কীভাবে পাস করবেন?", qEn: "392. How do you pass arguments to an event handler?", a: "arrow `(e) => this.update(id, e)` বা `bind(this, id)`—synthetic event দ্বিতীয় আর্গুমেন্ট।", aEn: "During iterations or loops, it is common to pass an extra parameter to an event handler. This can be achieved through arrow functions or bind method.\n\n Let us take an example of user details updated in a grid,\n\n    \n```javascript\n    <button onClick={(e) => this.updateUser(userId, e)}>Update User details</button>\n    <button onClick={this.updateUser.bind(this, userId)}>Update User details</button>\n```\n\n In the both approaches, the synthetic argument `e` is passed as a second argument. You need to pass it explicitly for arrow functions and it will be passed automatically for `bind` method." },
  { q: "৩৯৩. কম্পোনেন্ট রেন্ডার প্রতিরোধ কীভাবে করবেন?", qEn: "393. How to prevent component from rendering?", a: "শর্তে `return null` (যেমন loggedIn না হলে Greeting না দেখানো)।", aEn: "You can prevent component from rendering by returning null based on specific condition. This way it can conditionally render component.\n\n    \n```javascript\n    function Greeting(props) {\n      if (!props.loggedIn) {\n        return null;\n      }\n\n      return <div className=\"greeting\">welcome, {props.name}</div>;\n    }\n```\n\n    \n```javascript\n    class User extends React.Component {\n      constructor(props) {\n        super(props);\n        this.state = {loggedIn: false, name: 'John'};\n      }\n\n      render() {\n       return (\n           <div>\n             //Prevent component render if it is not loggedIn\n             <Greeting loggedIn={this.state.loggedIn} />\n             <UserDetails name={this.state.name}>\n           </div>\n       );\n      }\n```\n\n In the above example, the `greeting` component skips its rendering section by applying condition and returning null value." },
  { q: "৩৯৪. context ব্যবহারের উদাহরণ দিন?", qEn: "394. Give an example on How to use context?", a: "ThemeContext.Provider value পাঠান; ThemedButton `static contextType` বা Consumer দিয়ে পড়ে।", aEn: "Context is designed to share data that can be considered global for a tree of React components.\n\n For example, in the code below lets manually thread through a “theme” prop in order to style the Button component.\n\n    \n```javascript\n    //Lets create a context with a default theme value \"luna\"\n    const ThemeContext = React.createContext(\"luna\");\n    // Create App component where it uses provider to pass theme value in the tree\n    class App extends React.Component {\n      render() {\n        return (\n          <ThemeContext.Provider value=\"nova\">\n            <Toolbar />\n          </ThemeContext.Provider>\n        );\n      }\n    }\n    // A middle component where you don't need to pass theme prop anymore\n    function Toolbar(props) {\n      return (\n        <div>\n          <ThemedButton />\n        </div>\n      );\n    }\n    // Lets read theme value in the button component to use\n    class ThemedButton extends React.Component {\n      static contextType = ThemeContext;\n      render() {\n        return <Button theme={this.context} />;\n      }\n    }\n```" },
  { q: "৩৯৫. contextType কীভাবে ব্যবহার করবেন?", qEn: "395. How do you use contextType?", a: "class-এ `MyClass.contextType = MyContext` বা `static contextType = MyContext`।", aEn: "ContextType is used to consume the context object. The contextType property can be used in two ways,\n\n 1. contextType as property of class:\n The contextType property on a class can be assigned a Context object created by React.createContext(). After that, you can consume the nearest current value of that Context type using this.context in any of the lifecycle methods and render function.\n\n Lets assign contextType property on MyClass as below,\n\n        \n```javascript\n        class MyClass extends React.Component {\n          componentDidMount() {\n            let value = this.context;\n            / perform a side-effect at mount using the value of MyContext /\n          }\n          componentDidUpdate() {\n            let value = this.context;\n            / ... /\n          }\n          componentWillUnmount() {\n            let value = this.context;\n            / ... /\n          }\n          render() {\n            let value = this.context;\n            / render something based on the value of MyContext /\n          }\n        }\n        MyClass.contextType = MyContext;\n```\n\n 2. Static field\n You can use a static class field to initialize your contextType using public class field syntax.\n\n        \n```javascript\n        class MyClass extends React.Component {\n          static contextType = MyContext;\n          render() {\n            let value = this.context;\n            / render something based on the value /\n          }\n        }\n```" },
  { q: "৩৯৬. consumer কী?", qEn: "396. What is a consumer?", a: "`<MyContext.Consumer>{value => ...}</MyContext.Consumer>`—function child।", aEn: "A Consumer is a React component that subscribes to context changes. It requires a function as a child which receives current context value as argument and returns a react node. The value argument passed to the function will be equal to the value prop of the closest Provider for this context above in the tree.\n\n Lets take a simple example,\n\n    \n```javascript\n    <MyContext.Consumer>\n      {value => / render something based on the context value /}\n    </MyContext.Consumer>\n```" },
  { q: "৩৯৭. context-এ performance corner cases কীভাবে সমাধান করবেন?", qEn: "397. How do you solve performance corner cases while using context?", a: "Provider `value`-কে state-এ রাখুন—inline `{ }` object প্রতি render নতুন reference।", aEn: "The context uses reference identity to determine when to re-render, there are some gotchas that could trigger unintentional renders in consumers when a provider’s parent re-renders.\n\n For example, the code below will re-render all consumers every time the Provider re-renders because a new object is always created for value.\n\n    \n```javascript\n    class App extends React.Component {\n      render() {\n        return (\n          <Provider value={{ something: \"something\" }}>\n            <Toolbar />\n          </Provider>\n        );\n      }\n    }\n```\n\n This can be solved by lifting up the value to parent state,\n\n    \n```javascript\n    class App extends React.Component {\n      constructor(props) {\n        super(props);\n        this.state = {\n          value: { something: \"something\" },\n        };\n      }\n\n      render() {\n        return (\n          <Provider value={this.state.value}>\n            <Toolbar />\n          </Provider>\n        );\n      }\n    }\n```" },
  { q: "৩৯৮. HOCs-এ forward ref-এর উদ্দেশ্য কী?", qEn: "398. What is the purpose of forward ref in HOCs?", a: "HOC refs pass করে না—`React.forwardRef` + `forwardedRef` prop pattern।", aEn: "Refs will not get passed through because ref is not a prop. It is handled differently by React just like key. If you add a ref to a HOC, the ref will refer to the outermost container component, not the wrapped component. In this case, you can use Forward Ref API. For example, we can explicitly forward refs to the inner FancyButton component using the React.forwardRef API.\n\n The below HOC logs all props,\n\n    \n```javascript\n    function logProps(Component) {\n      class LogProps extends React.Component {\n        componentDidUpdate(prevProps) {\n          console.log(\"old props:\", prevProps);\n          console.log(\"new props:\", this.props);\n        }\n\n        render() {\n          const { forwardedRef, ...rest } = this.props;\n\n          // Assign the custom prop \"forwardedRef\" as a ref\n          return <Component ref={forwardedRef} {...rest} />;\n        }\n      }\n\n      return React.forwardRef((props, ref) => {\n        return <LogProps {...props} forwardedRef={ref} />;\n      });\n    }\n```\n\n Let's use this HOC to log all props that get passed to our “fancy button” component,\n\n    \n```javascript\n    class FancyButton extends React.Component {\n      focus() {\n        // ...\n      }\n\n      // ...\n    }\n    export default logProps(FancyButton);\n```\n\n Now let's create a ref and pass it to FancyButton component. In this case, you can set focus to button element.\n\n    \n```javascript\n    import FancyButton from \"./FancyButton\";\n\n    const ref = React.createRef();\n    ref.current.focus();\n    <FancyButton label=\"Click Me\" handleClick={handleClick} ref={ref} />;\n```" },
  { q: "৩৯৯. সব function/class component-এ ref argument পাওয়া যায়?", qEn: "399. Is ref argument available for all functions or class components?", a: "শুধু `React.forwardRef` কম্পোনেন্টে দ্বিতীয় ref argument।", aEn: "Regular function or class components don’t receive the ref argument, and ref is not available in props either. The second ref argument only exists when you define a component with React.forwardRef call." },
  { q: "৪০০. forward refs-এ component library-তে extra care কেন?", qEn: "400. Why do you need additional care for component libraries while using forward refs?", a: "forwardRef API পরিবর্তন breaking change—library-তে major version।", aEn: "When you start using forwardRef in a component library, you should treat it as a breaking change and release a new major version of your library. This is because your library likely has a different behavior such as what refs get assigned to, and what types are exported. These changes can break apps and other libraries that depend on the old behavior." },
  { q: "৪০১. ES6 ছাড়া React class component কীভাবে তৈরি করবেন?", qEn: "401. How to create react class components without ES6?", a: "`create-react-class`: getDefaultProps, getInitialState; auto-binding।", aEn: "If you don’t use ES6 then you may need to use the create-react-class module instead. For default props, you need to define getDefaultProps() as a function on the passed object. Whereas for initial state, you have to provide a separate getInitialState method that returns the initial state.\n\n    \n```javascript\n    var Greeting = createReactClass({\n      getDefaultProps: function () {\n        return {\n          name: \"Jhohn\",\n        };\n      },\n      getInitialState: function () {\n        return { message: this.props.message };\n      },\n      handleClick: function () {\n        console.log(this.state.message);\n      },\n      render: function () {\n        return <h1>Hello, {this.props.name}</h1>;\n      },\n    });\n```\n\n Note: If you use createReactClass then auto binding is available for all methods. i.e, You don't need to use `.bind(this)` with in constructor for event handlers." },
  { q: "৪০২. JSX ছাড়া React ব্যবহার করা যায়?", qEn: "402. Is it possible to use react without JSX?", a: "হ্যাঁ—JSX `React.createElement`-এর syntactic sugar।", aEn: "Yes, JSX is not mandatory for using React. Actually it is convenient when you don’t want to set up compilation in your build environment. Each JSX element is just syntactic sugar for calling `React.createElement(component, props, ...children)`.\n\n For example, let us take a greeting example with JSX,\n\n    \n```javascript\n    class Greeting extends React.Component {\n      render() {\n        return <div>Hello {this.props.message}</div>;\n      }\n    }\n\n    ReactDOM.render(\n      <Greeting message=\"World\" />,\n      document.getElementById(\"root\")\n    );\n```\n\n You can write the same code without JSX as below,\n\n    \n```javascript\n    class Greeting extends React.Component {\n      render() {\n        return React.createElement(\"div\", null, `Hello ${this.props.message}`);\n      }\n    }\n\n    ReactDOM.render(\n      React.createElement(Greeting, { message: \"World\" }, null),\n      document.getElementById(\"root\")\n    );\n```" },
  { q: "৪০৩. render props দিয়ে HOC কীভাবে তৈরি করবেন?", qEn: "403. How do you create HOC using render props?", a: "render prop দিয়ে `<Mouse render={mouse => <Component mouse={mouse} />} />` HOC-এর মতো।", aEn: "You can implement most higher-order components (HOC) using a regular component with a render prop. For example, if you would prefer to have a withMouse HOC instead of a component, you could easily create one using a regular with a render prop.\n\n    \n```javascript\n    function withMouse(Component) {\n      return class extends React.Component {\n        render() {\n          return (\n            <Mouse\n              render={(mouse) => <Component {...this.props} mouse={mouse} />}\n            />\n          );\n        }\n      };\n    }\n```\n\n This way render props gives the flexibility of using either pattern." },
  { q: "৪০৪. react-scripts কী?", qEn: "404. What is react scripts?", a: "create-react-app-এর scripts—dev server, HMR, build, test।", aEn: "The `react-scripts` package is a set of scripts from the create-react-app starter pack which helps you kick off projects without configuring. The `react-scripts start` command sets up the development environment and starts a server, as well as hot module reloading." },
  { q: "৪০৫. create react app-এর features কী?", qEn: "405. What are the features of create react app?", a: "React/JSX/TS, autoprefix CSS, dev server, tests, production bundle, PWA optional।", aEn: "Below are the list of some of the features provided by create react app.\n\n 1. React, JSX, ES6, Typescript and Flow syntax support.\n 2. Autoprefixed CSS\n 3. CSS Reset/Normalize\n 4. A live development server\n 5. A fast interactive unit test runner with built-in support for coverage reporting\n 6. A build script to bundle JS, CSS, and images for production, with hashes and sourcemaps\n 7. An offline-first service worker and a web app manifest, meeting all the Progressive Web App criteria." },
  { q: "৪০৬. renderToNodeStream method-এর উদ্দেশ্য কী?", qEn: "406. What is the purpose of renderToNodeStream method?", a: "SSR: `ReactDOMServer.renderToNodeStream`—HTML stream; শুধু server।", aEn: "The `ReactDOMServer#renderToNodeStream` method is used to generate HTML on the server and send the markup down on the initial request for faster page loads. It also helps search engines to crawl your pages easily for SEO purposes.\n Note: Remember this method is not available in the browser but only server." },
  { q: "৪০৭. create-react-app-এ redux scaffolding কীভাবে পাবেন?", qEn: "407. How do you get redux scaffolding using create-react-app?", a: "`npx create-react-app my-app --template redux` বা `redux-typescript`।", aEn: "Redux team has provided official redux+js or redux+typescript templates for create-react-app project. The generated project setup includes,\n 1. Redux Toolkit and React-Redux dependencies\n 2. Create and configure Redux store\n 3. React-Redux ` ` passing the store to React components\n 4. Small \"counter\" example to demo how to add redux logic and React-Redux hooks API to interact with the store from components\n The below commands need to be executed along with template option as below,\n 5. Javascript template:\n    \n```javascript\n    npx create-react-app my-app --template redux\n```\n 2. Typescript template:\n    \n```javascript\n    npx create-react-app my-app --template redux-typescript\n```" },
  { q: "৪০৮. state mutation কী এবং কীভাবে প্রতিরোধ করবেন?", qEn: "408. What is state mutation and how to prevent it?", a: "setState ছাড়া state মিউটেট করলে React জানে না—সবসময় immutable update + setState; Immutable.js optional।", aEn: "`State mutation` happens when you try to update the state of a component without actually using `setState` function. This can happen when you are trying to do some computations using a state variable and unknowingly save the result in the same state variable. This is the main reason why it is advised to return new instances of state variables from the reducers by using Object.assign({}, ...) or spread syntax.\n\n This can cause unknown issues in the UI as the value of the state variable got updated without telling React to check what all components were being affected from this update and it can cause UI bugs.\n\n Ex:\n\n    \n```javascript\n    class A extends React.component {\n      constructor(props) {\n        super(props);\n        this.state = {\n          loading: false\n        }\n     }\n\n    componentDidMount() {\n      let { loading } = this.state;\n      loading = (() => true)(); // Trying to perform an operation and directly saving in a state variable\n    }\n```\n\n How to prevent it: Make sure your state variables are immutable by either enforcing immutability by using plugins like Immutable.js, always using `setState` to make updates, and returning new instances in reducers when sending updated state values." },
];
